return {
  ["00:2815"] = "Evento de objeto.",
  ["03:4d42"] = "¡{STRBUF}\nusó FUERZA!",
  ["03:4d47"] = "{STRBUF}\npuede mover\vlas piedras.",
  ["03:4d6a"] = "Un POKéMON\npodría moverla.\f¿Quieres usar\nFUERZA?",
  ["03:4d6f"] = "¡Ahora se pueden\nmover las piedras!",
  ["03:4d74"] = "Un POKéMON\npodría moverla.",
  ["03:4f59"] = "¡{STRBUF}\nusó GOLPE ROCA!",
  ["03:4f73"] = "Un POKéMON\npodría romperla.",
  ["03:4f78"] = "Esta roca se\npuede romper.\f¿Quieres usar el\nGOLPE ROCA?",
  ["09:716e"] = "MAPA del PUEBLO.",
  ["09:7176"] = "Un póster de un\nsimpático PIKACHU.",
  ["09:717e"] = "Un póster de un\ngracioso CLEFAIRY.",
  ["09:7186"] = "Un póster de un\nbonito JIGGLYPUFF.",
  ["09:71ab"] = "Un/a formidable\n{STRBUF}.",
  ["09:71b9"] = "¡Un muñeco de\npeluche muy mono!",
  ["21:6514"] = "¡Nuevo Hall Fama!",
  ["21:66db"] = "¡Maestro HdF!",
  ["21:66eb"] = "    vez/veces HdF",
  ["24:4244"] = "¿Eh? Perdona,\nnº equivocado.",
  ["24:462a"] = "Ese número no es\nde esta zona.",
  ["24:4633"] = "¡Habla con esa\npersona!",
  ["40:4615"] = "¡Bienvenido a\nnuestro CENTRO\vPOKéMON!",
  ["40:4640"] = "¡Hola! ¡Bienvenido\na nuestro CENTRO\vPOKéMON!",
  ["40:4664"] = "¡Buenas noches!\nBienvenido a\fnuestro CENTRO\nPOKéMON.",
  ["40:469f"] = "Nosotros curamos\na tus POKéMON.\f¿Quieres curar a\ntus POKéMON?",
  ["40:46e2"] = "Muy bien, déjame\ntus POKéMON.",
  ["40:46fc"] = "¡Gracias por\nesperar!\fTus POKéMON están\nen plena forma.",
  ["40:4730"] = "¡Vuelve siempre\nque quieras!",
  ["40:4766"] = "Tus POKéMON\ntienen minúsculas\fformas de vida\nunidas a ellos.\fTus POKéMON están\nsanos y parecen\vcontentos.\fPero no podemos\ndarte más\finformación en un\nCENTRO POKéMON.",
  ["40:4801"] = "Está llena de\nlibros complejos.",
  ["40:481f"] = "¡Una colección de\nlibros ilustrados\vde POKéMON!",
  ["40:484a"] = "Revistas POKéMON…\nTELEVISOR POKéMON,\fMANUAL POKéMON,\nGRÁFICA POKéMON…",
  ["40:4880"] = "VOTOS TEAM ROCKET\fRobar POKéMON para\nenriquecernos.\fExplotarlos para\nenriquecernos.\f¡Todo POKéMON\nexiste para gloria\vdel TEAM ROCKET!",
  ["40:48ef"] = "¿Qué es esto?\f¡Oh! ¡Es un\npebetero!",
  ["40:4919"] = "¡Cantidad de\nartículos POKéMON!",
  ["40:4934"] = "MAPA del PUEBLO.",
  ["40:4947"] = "¡Mi reflejo!\n¡Qué guapo!",
  ["40:4965"] = "Es una TV.",
  ["40:4970"] = "PÁGINA DE INICIO\nREVISTA POKéMON.\fNo ha sido\nactualizada…",
  ["40:49cd"] = "Aquí dentro no\nhay nada…",
  ["40:4a26"] = "Cura a tus POKéMON\nCENTRO POKéMON",
  ["40:4a43"] = "Todo lo necesario\npara tus POKéMON\fTIENDA POKéMON",
  ["40:4a66"] = "Vamos a evaluar\na tus POKéMON.\f……\n……\f¡Hemos elegido a\nlos ganadores!\f¿Estás preparado?",
  ["40:4ac8"] = "¡Uauu! ¡Eres\nbastante fuerte!\f¿Me das tu número\nde teléfono?\fTe llamaré para\nvolver a pelear.",
  ["40:4b1d"] = "¿Grabar el número\nde teléfono?",
  ["40:4b39"] = "{PLAYER} grabó el\nNº de {STRBUF}.",
  ["40:4b56"] = "Te llamaré si\nsurge algo.",
  ["40:4b7a"] = "¡Ah! ¡Vale…!\nPues habla conmigo\fcuando quieras\nmi número.",
  ["40:4bb7"] = "En tu teléfono\nno tienes espacio\vpara más números.",
  ["40:4bef"] = "Te esperaba.\n¡Luchemos!",
  ["40:4c14"] = "¡Uauu! Peleas\nmuy bien.\f¿Me das tu número\nde teléfono?\fTe llamaré para\nvolver a pelear.",
  ["40:4c77"] = "¿Grabar el número\nde teléfono?",
  ["40:4c93"] = "{PLAYER} grabó el\nNº de {STRBUF}.",
  ["40:4cb0"] = "Te llamaré si\nsurge algo.",
  ["40:4cd0"] = "De acuerdo.\nCuando quieras\fmi número de\nteléfono, dímelo.",
  ["40:4d12"] = "En tu teléfono\nno tienes espacio\vpara más números.",
  ["40:4d4a"] = "Te esperaba.\n¡Luchemos!",
  ["40:4d6a"] = "{PLAYER} gana el\npremio Nº{STRBUF}:\v¡una {STRBUF}!",
  ["40:4d90"] = "{PLAYER} recibió\n{STRBUF}.",
  ["40:4da3"] = "¡Participa en el\npróximo concurso!",
  ["40:4dc9"] = "¡Todos los demás\nreciben una BAYA\vcomo consolación!",
  ["40:4dff"] = "A ver si mejoras\nla próxima vez.",
  ["40:4e21"] = "Aquí tienes los\nPOKéMON que\fte estábamos\ncuidando.",
  ["40:4e55"] = "¡Equipo completo!\nEl POKéMON fue\fenviado a tu CAJA\nen el PC de BILL.",
  ["40:4e96"] = "GIMNASIO POKéMON\nDE {STRBUF}",
  ["40:4ea4"] = "LÍDER: {STRBUF}\fGANADORES:\n{PLAYER}",
  ["40:4ec7"] = "Bienvenido al\nCASINO.",
  ["40:4ee4"] = "¿Necesitas fichas\nde juego?\f¡Oh! No tienes\nun MONEDERO\vpara tus fichas.",
  ["40:4f2b"] = "¿Necesitas fichas\nde juego?\n50 fichas por\n1000¥. ¿Quieres\vcomprar?",
  ["40:4f78"] = "¡Gracias! Aquí\ntienes 50 fichas.",
  ["40:4f97"] = "¡Gracias! Aquí\ntienes 500 fichas.",
  ["40:4fb7"] = "No tienes\nbastante dinero.",
  ["40:4fd4"] = "¡Uups! Tu MONEDERO\nestá lleno.",
  ["40:4ff5"] = "¿No quieres\nfichas?\fVuelve cuando\nquieras.",
  ["40:5014"] = "¡Oh! Tu MOCHILA\nestá llena.\fTe guardaremos\nesto. Vuelve\fcuando tengas\nsitio.",
  ["40:5072"] = "¡Uauu! ¡Tú y tus\nPOKéMON estáis\vmuy unidos!",
  ["40:509c"] = "Cuanto más tiempo\npases con los\fPOKéMON, más\nte querrán.",
  ["40:50d1"] = "No has domesticado\na tu POKéMON.\fSi no eres amable,\néste se enfadará.",
  ["41:4a8a"] = "Buenos días.",
  ["41:4a99"] = "¿Dígame?\f¡Hola, {PLAYER}!\n¿Trabajando duro?",
  ["41:4aba"] = "Así que estás en\n{STRBUF}.\f¿No está ahí\n{STRBUF}?\f¿Has ido a echar\nun vistazo?",
  ["41:4b04"] = "¿Sí? ¿Estás en\n{STRBUF}?\fNunca he estado\nallí. ¡Genial,\v{PLAYER}!",
  ["41:4b4a"] = "¿Qué? ¿Estás en\n{STRBUF}?\f¡Ven a verme\ncuando quieras!",
  ["41:4b7d"] = "¿Estás visitando a\n{STRBUF}?\f¿Por qué no vienes\nun rato a casa?",
  ["41:4bb5"] = "¡Uau! ¿Estás en\n{STRBUF}?\f¡Suerte en tu\naventura POKéMON!",
  ["41:4be9"] = "Eso parece\nbastante duro.\fPero, {PLAYER}, sé\nque estás decidido\fy que te irá bien,\n¿de acuerdo?",
  ["41:4c40"] = "Por cierto, has\nahorrado {STRBUF}¥.\f¿Quieres seguir\nahorrando dinero?",
  ["41:4c83"] = "Es importante que\nahorres dinero.",
  ["41:4ca6"] = "¡Oh, {PLAYER}!\nNo estás ahorrando\fdinero. ¿Quieres\nahorrar?",
  ["41:4ce2"] = "Por cierto, has\nahorrado {STRBUF}¥.\f¿Quieres seguir\nahorrando?",
  ["41:4d22"] = "Vale. Te guardaré\nel dinero.",
  ["41:4d3c"] = "Vale. Dejaré de\nguardarte dinero.",
  ["41:4d5d"] = "¡Sigue así,\n{PLAYER}!\v¡Estoy contigo!",
  ["41:4d87"] = "¿Dígame?\f¡Hola, {PLAYER}!\n¿No te esperaba\vel PROF. ELM?",
  ["41:4dba"] = "¿Dígame?\f¡Hola, {PLAYER}!\n¿Tienes una misión\fimportante del\nPROF. ELM? ¡Bien!",
  ["41:4dfc"] = "¿Dígame?\f¡Hola, {PLAYER}!\nCuando termines\ftu misión, vuelve\na casa.",
  ["41:4e3e"] = "¿Dígame?\f¿{PLAYER}…?\nMe dijo el PROF.\fELM que saliste\nde viaje.\fOjalá me lo\nhubieras dicho…\f¿Y el dinero? ¿Te\nlo guardo?",
  ["41:4ec4"] = "¡Buenos días!\fSERVICIO de\nADMÓN. del SISTEMA\fde ALMACENAMIENTO\nde los POKéMON.",
  ["41:4f0d"] = "¡Buenos días!\fSERVICIO de\nADMÓN. del SISTEMA\fde ALMACENAMIENTO\nde los POKéMON.",
  ["41:4f52"] = "¡Buenas noches!\fSERVICIO de\nADMÓN. del SISTEMA\fde ALMACENAMIENTO\nde los POKéMON.",
  ["41:4f9b"] = "¿Quién llama?\f{PLAYER}, ¿eres tú?\nEspera un segundo.\f……\n……",
  ["41:4fc7"] = "¡Gracias por\nesperar!\f{PLAYER}, en tu\nCAJA cabe/n {STRBUF}\vPOKéMON más.\f¡Adelante!\n¡Llénala!",
  ["41:5024"] = "¡Gracias por\nesperar!\f{PLAYER}, en tu\nCAJA sólo cabe/n\v{STRBUF} POKéMON más.\fQuizá deberías\ncambiar de CAJA.",
  ["41:508a"] = "¡Gracias por\nesperar!\f¡{PLAYER}, tu\nCAJA está llena!\fSi quieres atrapar\nmás POKéMON,\ftendrás que\ncambiar de CAJA.",
  ["41:50ef"] = "Hola, ¿{PLAYER}?\n¡Soy yo, BILL!\fGracias por usar\nmi SISTEMA de\vALMACENAMIENTO.\fTu CAJA se llenó\ncon el último\fPOKéMON que\nenviaste.\fSi quieres atrapar\nmás POKéMON,\ftendrás que\ncambiar de CAJA.\f¡Hasta luego!",
  ["41:5199"] = "Hola, ¿{PLAYER}?\fNo te\nexcedas.\fNo olvides curar\na tus POKéMON\vsi están heridos.\n",
  ["41:51e6"] = "Hola, ¿{PLAYER}?\f¿Viste al SR.\nPOKéMON? ¡Genial!\v¡Vuelve ileso!",
  ["41:5221"] = "¿{PLAYER}? Ahora\nestoy muy triste.\fNos han robado un\nPOKéMON. ¿Cómo\fhan podido\nhacerlo?",
  ["41:5272"] = "Hola, ¿{PLAYER}?\fEstamos analizando\nel HUEVO. Parece\fser un HUEVO de\nPOKéMON.",
  ["41:52b9"] = "Hola, ¿{PLAYER}?\f¿Has visto a mi\nayudante? Está en\fel CENTRO POKéMON\nde CIUDAD MALVA.",
  ["41:5305"] = "Hola, ¿{PLAYER}?\f¿Qué tal el HUEVO?\n¿Ha cambiado algo?\fSi pasa algo, por\nfavor llámame.",
  ["41:5358"] = "Hola, ¿{PLAYER}?\n¿Qué tal el HUEVO?\f¿Qué? ¿Se ha\nabierto? ¡Uau!\v¿Qué POKéMON es?\f¡Por favor, ven\na enseñármelo!",
  ["41:53bc"] = "Hola, ¿{PLAYER}?\fAcabo de hacer un\ndescubrimiento.\fEl tiempo que\ntarda un HUEVO en\fabrirse depende\ndel POKéMON.",
  ["41:541f"] = "Hola, ¿{PLAYER}?\fLos movimientos de\nun POKéMON recién\fnacido son\nun misterio.\fAhora estamos\ninvestigando eso.",
  ["41:5484"] = "Hola, ¿{PLAYER}?\fHe descubierto\nalgo extraño.\fParece haber algo\nllamado POKéRUS\fque infecta\na los POKéMON.\f¡Sí! Es como un\nvirus, por eso se\vllama POKéRUS.\fSe multiplica\nrápido e infecta\fa otros POKéMON.\nPero eso es todo.\fParece que no\nhace nada y que\fdesaparece con\nel tiempo.\fCreo que no hay\nde qué preocuparse\v¡Adiós!",
  ["41:55b4"] = "¿Hola? ¿{PLAYER}?\n¡Qué desastre!\f¡Ee…, ee…, es\nterrible!\f¿Qué hacer?\n¡Oh, no…!\f¡Vuelve aquí\nahora mismo!",
  ["41:5624"] = "Hola, ¿{PLAYER}?\n¡Hemos descubierto\falgo sobre el\nHUEVO!\fMi ayudante está\nen el CENTRO\fPOKéMON de CIUDAD\nMALVA. ¿Podrías\vhablar con él?",
  ["41:56a3"] = "{PLAYER}, ¿qué tal\nvan las cosas?\fTe llamo porque\npasó algo raro\fcon las emisiones\nde radio.\fHablaban del\nTEAM ROCKET.\f{PLAYER}, ¿sabes\nalgo sobre\vesto?\fQuizá ha vuelto\nel TEAM ROCKET.\fNo, no puede\nser cierto.\fSiento molestarte.\n¡Cuídate!",
  ["41:57a6"] = "Hola, ¿{PLAYER}?\fTengo algo para\nti aquí.\f¿Puedes venir\nal LABORATORIO?\f¡Hasta luego!",
  ["41:5862"] = "Hola. Soy\n{STRBUF}…\f¡Buenos días,\n{PLAYER}!",
  ["41:588a"] = "Hola. Soy\n{STRBUF}…\f¿Qué tal,\n{PLAYER}?",
  ["41:58b3"] = "Hola. Soy\n{STRBUF}…\f¡Buenas noches,\n{PLAYER}!",
  ["41:58db"] = "Hola. Soy\n{STRBUF}.\f¡Hola, {PLAYER}!\nBuenos días.",
  ["41:5904"] = "Hola. Soy\n{STRBUF}.\f¡Hola, {PLAYER}!\n¿Cómo estás?",
  ["41:592c"] = "Hola. Soy\n{STRBUF}.\f¡Hola, {PLAYER}!\nBuenas noches.",
  ["41:5955"] = "¡Buenos días,\n{PLAYER}!\fSoy yo, {STRBUF}.\n¿Qué tal estás?",
  ["41:5989"] = "Hola, {PLAYER}.\fSoy yo, {STRBUF}.\n¿Qué tal va todo?",
  ["41:59b5"] = "¡Buenas noches,\n{PLAYER}!\fSoy yo, {STRBUF}.\n¿Tienes un minuto?",
  ["41:59e4"] = "Buenos días,\n{PLAYER}.\fSoy {STRBUF}.\n¿Te he despertado?",
  ["41:5a15"] = "Hola, {PLAYER}.\fSoy {STRBUF}.\n¿Qué tal todo?",
  ["41:5a3f"] = "Buenas noches,\n{PLAYER}.\fSoy {STRBUF}.\n¿Estabas dormido?",
  ["41:5a70"] = "¿Qué tal están\ntus POKéMON?\fMi {STRBUF}\ntiene mucha\venergía. ¡Genial!",
  ["41:5ab5"] = "¿Qué tal están\ntus POKéMON?\fMi {STRBUF}\nestá en forma\fporque lo llevo al\nCENTRO POKéMON.",
  ["41:5b0d"] = "Mi {STRBUF}\ntiene un aspecto\fincreíble. Ojalá\npudieras verlo.",
  ["41:5b42"] = "He vestido a mi\n{STRBUF}.\fTiene mucho mejor\naspecto que antes.",
  ["41:5b7b"] = "¡Sí! He ganado\na un fuerte\v{STRBUF}.\fDebo fortalecer\na mi equipo.",
  ["41:5bcb"] = "¡Tienes que oír\nesto! El otro día\fderroté a\n{STRBUF}.\f¡Fue sencillo!\nTuve ventaja.",
  ["41:5c27"] = "¡Eh, escucha!\nCasi atrapo a\f{STRBUF} el\notro día.\f¡Oh, estuve\nmuy cerca!",
  ["41:5c76"] = "¿Sabes lo que me\npasó el otro día?\fSe me volvió\na escapar\f{STRBUF}.\nQuizá no sea tan\vguay en esto…",
  ["41:5cdb"] = "¿Quieres luchar?\nNo volverá a\focurrir lo de la\núltima vez.\fEstaré por\n{STRBUF}.",
  ["41:5d37"] = "¿Quieres luchar?\n¡Esta vez ganaré!\fTe estaré\nesperando por\f{STRBUF}.\nBúscame, ¿vale?",
  ["41:5da0"] = "¿Hola? Soy\n{STRBUF}…\f¡Oh, oh…! ¡Tú no\neres MATEO! ¡Vaya,\vme he equivocado!",
  ["41:5de2"] = "Hola, soy\n{STRBUF}. ¿Cómo\vestás, ARIADNA?\f¿Eh? ¿{PLAYER}?\n¡Me he equivocado!",
  ["41:5e2e"] = "¡Hasta luego!",
  ["41:5e3e"] = "¡Adiós!",
  ["41:5e48"] = "¡Tienes que ver\nesto! ¡Es salvaje!\f¡Ha aparecido\nun grupo de\f{STRBUF}\nalrededor de\v{STRBUF}!",
  ["41:5e9c"] = "¡Es increíble!\fEn {STRBUF},\nestán picando\f{STRBUF} como si\nno hubiera mañana.\f¡{PLAYER}, trae\ntu CAÑA, tío!",
  ["41:5efa"] = "Un amigo me lo\nacaba de decir.\fHa visto muchos\n{STRBUF} en\v{STRBUF}.\f{PLAYER}, deberías\nir a verlo.",
  ["41:5f50"] = "Hoy se celebra el\nConcurso de\fCaptura de Bichos\nen el PARQUE.\f¿Vas a ir,\n{PLAYER}?",
  ["41:5fa4"] = "¿Sabes qué,\n{PLAYER}?\fDicen que el TEAM\nROCKET ha asaltado\fla TORRE de RADIO\nde CIUDAD TRIGAL.\f¿Pero qué es el\nTEAM ROCKET?",
  ["41:6014"] = "¿{PLAYER}, has\noído las noticias?\fEl TEAM ROCKET ha\nasaltado la TORRE\fde RADIO de\nCIUDAD TRIGAL.\f¿Estarán bien\nlos trabajadores?",
  ["41:608d"] = "¡Hola, {PLAYER}!\n¡Las ventas de\fBICIS han subido\nespectacularmente!\fY todo gracias a\nla publicidad\fque has hecho\ncon nuestra BICI.\fQuédate con esa\nBICI como\fagradecimiento.\n¡Gracias de nuevo!",
  ["42:4027"] = "Montamos guardia\nen esta torre.\fAsí expresamos\nnuestra gratitud a\vtodos los POKéMON.",
  ["42:4078"] = "¡Gra-Gracias!",
  ["42:4087"] = "Todos los seres\nvivos coexisten\ven cooperación.\fDeberíamos\nestar agradecidos.",
  ["42:40dc"] = "Sólo obtendrás\nuna MO si llegas\varriba.",
  ["42:410e"] = "La TORRE\nBELLSPROUT fue\fconstruida para\nentrenar POKéMON.",
  ["42:414d"] = "Un BELLSPROUT de\n30 m de altura.\fDice la gente que\nse convirtió en la\vcolumna central.",
  ["42:41a1"] = "¿Ves cómo se\nmueve la columna?\fArriba hay gente\nentrenando.",
  ["42:41da"] = "Estatua POKéMON…\fParece muy\nilustre.",
  ["42:42ad"] = "Por mucho que\nluchemos, la TORRE\vseguirá en pie.",
  ["42:42e3"] = "Luché con fuerza\npero estoy débil.",
  ["42:4303"] = "La columna\nflexible protege\fla TORRE hasta\nde los terremotos.",
  ["42:4345"] = "Se mueve como las\nhojas al viento…",
  ["42:4365"] = "¡Oh, estoy débil!",
  ["42:4373"] = "Quería imitar los\nsuaves movimientos\fde BELLSPROUT\npara pelear…\fPero no me\nentrené bastante.",
  ["42:43cc"] = "Estatua POKéMON…\fParece muy\nilustre.",
  ["42:452b"] = "ANCIANO: Eres\nun entrenador\vmuy hábil.\fComo te prometí,\naquí tienes tu MO.\fPero déjame que te\ndiga que deberías\ftratar mejor a\ntus POKéMON.\fLuchas de forma\nmuy violenta.\fLos POKéMON no son\narmas de guerra.",
  ["42:45f0"] = "…\n¡Bah!\fAfirma ser el\nANCIANO, pero\ves muy débil.\fEs evidente.\fJamás perdería\nante quienes dicen\fque hay que ser\nbuenos con\vlos POKéMON.\fSólo me interesan\nlos POKéMON\vganadores.\fPaso de los\nPOKéMON\vdébiles.",
  ["42:46cc"] = "¡{RIVAL}\nusó\vCUERDA HUIDA!",
  ["42:46e4"] = "¡Encantado de\nverte por aquí!\fTORRE BELLSPROUT\nes un lugar de\ventrenamiento.\fLa gente y los\nPOKéMON evalúan\fsus vínculos para\nconstruir juntos\vun futuro mejor.\fYo soy la prueba\nfinal.\f¡Déjame evaluar\ntus vínculos con\vlos POKéMON!",
  ["42:47b6"] = "¡Ah, excelente!",
  ["42:47c6"] = "Tú y tus POKéMON\nno deberíais tener\fproblemas con\neste movimiento.\fToma esta MO.\nEs DESTELLO.",
  ["42:4817"] = "DESTELLO ilumina\nhasta el lugar\vmás oscuro.\fY con la MEDALLA\nde CIUDAD MALVA,\fpodrás usarlo\nfuera del combate.",
  ["42:488c"] = "¡Ojalá aprendas y\nmadures con\vtu viaje!",
  ["42:48ba"] = "¡Entreno para\nsaberlo todo\vsobre los POKéMON!",
  ["42:48e2"] = "¡Derrotado por\nun mocoso!",
  ["42:48fb"] = "Cuanto más fuerte\nsea el POKéMON,\fmás fuerte será\nsu entrenador.\fNo, espera. Cuanto\nmás fuerte sea el\fentrenador, más\nfuerte el POKéMON.",
  ["42:4961"] = "A ver cuánto\nconfías en tus\vPOKéMON.",
  ["42:498b"] = "¡Sí, tu confianza\nes auténtica!",
  ["42:49a5"] = "No estás lejos\ndel ANCIANO.",
  ["42:49c2"] = "La MO del ANCIANO\nalumbra hasta\vlo más oscuro.",
  ["42:49f4"] = "¡Mi cerebro sí\nque es brillante!",
  ["42:4a13"] = "¡Que haya luz\nen tus viajes!",
  ["42:4a38"] = "Es un bonito\ncuadro de un\vBELLSPROUT.",
  ["42:4a62"] = "Estatua POKéMON…\fParece muy\nilustre.",
  ["42:4b20"] = "Intento desvelar\nel secreto del\fPOKéMON legendario\nque, en teoría,\vdescansa aquí.\fDicen que este\nPOKéMON no ha\fdejado de volar\ndesde que se quemó\vla TORRE Oeste.\fPor eso pensé que\nsi tuviera algo\fde ese POKéMON,\néste se sentiría\vatraído por mí.\fCreo que ese\nobjeto es…\f¡Un ALA ARCOIRIS!\fPero, ¿dónde\nencontrar una?",
  ["42:4f24"] = "…… …… ……\f¡Ah, eres tú!\fQuerías ser más\nfuerte y por eso\fhas venido a por\nel POKéMON\flegendario que\nvive aquí. Ésa es\vtu historia, ¿no?\fPues ya te puedes\nir olvidando.\f¡Porque ese\nPOKéMON será mío!\fQuiero ser el\nmejor entrenador\fdel mundo y ese\nPOKéMON legendario\fsería perfecto\npara mí.\fDe todos modos,\nya estoy harto de\fver a un mocoso\ncomo tú siempre\vpor aquí.",
  ["42:5093"] = "¡Bah!\f¡Por eso no me\ngusta luchar\fcontra memos!\n¡Son tan malos!",
  ["42:50da"] = "¡Que más da!\fJamás podrías\natrapar un\fPOKéMON\nlegendario.",
  ["42:5124"] = "¡Bah!\f¡Por eso no me\ngusta luchar\fcontra memos! ¡Qué\npérdida de tiempo!",
  ["42:516d"] = "Estoy entrenándome\nen secreto.\f¡Me da vergüenza\nque mires!",
  ["42:51ac"] = "¡Terminé\nhecho cenizas…!",
  ["42:51cb"] = "Estaba tan ocupado\nentrenándome que\fcaí por este\nagujero.",
  ["42:5202"] = "¡Mi alma está\nardiendo! ¡Déjame\fque te enseñe\ncómo quema!",
  ["42:5236"] = "Aún no hace\nbastante calor…",
  ["42:524d"] = "En el pasado\nexistían POKéMON\fque corrían\npor la hierba a\vgran velocidad.\fDicen que corren\ncomo el viento.\fSi te encuentras\ncon uno de ellos,\vpuede que escape.",
  ["42:552a"] = "Del suelo salieron\nun montón de\fDIGLETT.\n¡Qué susto!",
  ["42:562d"] = "…… …… ……\f¡Cuánto tiempo,\n{PLAYER}!\fTras haber sido\nderrotado por\fti, estuve\npensando en mis\vPOKéMON…\fY llegué a una\nconclusión.\f¡Ahora verás,\n{PLAYER}!",
  ["42:56c5"] = "…… …… ……\fCreía haber\nentrenado muy\fbien a mis\nPOKéMON…\fPero estaba\nequivocado…",
  ["42:5722"] = "…… …… ……\fHas ganado\njustamente.\fLo admito. Pero\nesto no termina\vaquí.\fVoy a ser el mejor\nentrenador POKéMON\vdel mundo.\fYa que estos\nchicos me apoyan.\fMira, {PLAYER}.\fUno de estos días\nte demostraré lo\fbueno que soy,\nderrotándote.",
  ["42:5808"] = "…… …… ……\fYa te he pagado\nmi deuda.\fCon mis POKéMON\nganaré al CAMPEÓN\fy seré el mejor\nentrenador\vdel mundo.",
  ["42:5a87"] = "Espera.\f¿Vas a\nparticipar en la\vLIGA POKéMON?\fNo me hagas reír.\nEres mucho más\fdébil que yo,\nporque ya no\fsoy el mismo\nde antes.\f¡Ahora tengo los\nPOKéMON mejores\fy más fuertes!\n¡Soy invencible!\f¡{PLAYER}!\n¡Yo te desafío!",
  ["42:5b65"] = "He perdido…\fHice todo lo\nque pude…\fLo que tú tienes\ny yo no tengo…\fEmpiezo a entender\nlo que me dijo\faquel maestro\nde dragones…",
  ["42:5bf6"] = "Sigo queriendo\nser el mejor\ventrenador…\fDescubriré por qué\nno puedo ganar\fy ser más\nfuerte…\fTe desafiaré en\ncuanto lo sepa.\fY te aplastaré\ncon todo\vmi poder.\fHasta entonces,\n¡sigue entrenando!",
  ["42:5cd2"] = "¡Bah!\fDespués de todo,\nnada mejor que\vel poder.\fNo necesito\nnada más.",
  ["43:4196"] = "¡Eh! ¡Mira mi\nmochila!\fImprimí de la\nPOKéDEX mis\fPOKéMON favoritos\ny los pegué\ven ella.",
  ["43:41f1"] = "Es una CARTA\nde mi hija.\v¡Me da ánimos!",
  ["43:4228"] = "¡Presta atención,\npor favor!\f¡Ups! A ver si\ndejo de hablar\fcomo si fuera\nuna maestra.\fEres un entrenador\nPOKéMON.\fComo estás\ntrabajando tan\fduro, te voy\na dar esto.",
  ["43:42d0"] = "Dale a un POKéMON\nesa GARRA RÁPIDA.\fY a veces atacará\nel primero\ven combate.",
  ["43:4320"] = "Estoy jugando con\nlas pegatinas de\vmi POKéDEX.",
  ["43:4352"] = "La pegatina de la\nPOKéDEX del otro\fchico será mía,\nsi gano.",
  ["43:437f"] = "Doy paseos por\nel PARQUE, pero\fnunca entro en\nla hierba.\fLos entrenadores\nsiempre luchan…",
  ["43:43d9"] = "PERSIAN: ¡Persiia!",
  ["43:43ed"] = "Estoy imprimiendo\nmi POKéDEX.\fTambién puedes\nimprimir las\fCARTAS y\nCAJAS de tu PC.",
  ["43:4441"] = "El mundo POKéMON\nes muy amplio.\fY sigue habiendo\nmuchas cosas que\vignoramos.\f¡Pero yo sé\nmás que tú!",
  ["43:44a7"] = "¿Qué, qué, qué?",
  ["43:44b6"] = "Hay muchas cosas\nque aprender.\fPor ejemplo…\fHay 50 tipos de\nMT.\fLos POKéMON\nintercambiados\fsuben antes\nde nivel.",
  ["43:4514"] = "Mis POKéMON son\nmuy monos. Te los\vvoy a enseñar.",
  ["43:4547"] = "Quizá no pueda\nvencerte…\fPero los míos son\nmucho más bonitos.",
  ["43:4584"] = "Un amigo mío tiene\nun MARILL. ¡Es\fprecioso! ¡Ojalá\ntuviera un MARILL!",
  ["43:45c1"] = "Queremos a\nnuestros POKéMON,\faunque ellos\nno nos quieran.\fEso significa ser\nun FAN POKéMON.",
  ["43:4611"] = "¡M-mi POKéMON!",
  ["43:461d"] = "Perdí el combate,\npero mis POKéMON\fson más adorables\nque los tuyos.",
  ["43:4662"] = "¿Hola?\n¿Y tú que miras?\f¿Quieres luchar?",
  ["43:4693"] = "¡Mmmm…!",
  ["43:469b"] = "Por como me\nmirabas, pensé\vque te gustaba.\fAl fin y al cabo,\nsoy tan guapa…",
  ["43:46e4"] = "PLAZA DEL DESCANSO\nPARQUE NACIONAL",
  ["43:4705"] = "¿Qué dice\neste cartel?\fPor favor, lucha\nsólo en la hierba.\fPUESTO DEL GUARDA\nPARQUE NACIONAL",
  ["43:475a"] = "PISTAS ENTRENADOR\fImprime una CARTA\nabriéndola y\vpulsando START.",
  ["43:48e0"] = "RAFA: ¡Voy a\nganar! No me\vmolestes.",
  ["43:4907"] = "SAM: Mi PARASECT\nduerme a los\fPOKéMON con\nESPORA.",
  ["43:4937"] = "NANO: Entreno a\nPOKéMON rápidos\vpara luchar.",
  ["43:4960"] = "GUILLE: No me\nimporta ganar.\fSólo busco\nPOKéMON raros.",
  ["43:49a9"] = "TINO: ¡Ssh! Vas a\nasustar a SCYTHER.\fHablaré contigo\ndespués.",
  ["43:49e6"] = "BENITO: Debilita a\nlos POKéMON\fbicho y lánzales\nuna PARQUE BALL.",
  ["43:4a25"] = "CINDY: ¿Qué pasa?\f¿Te parece\ngracioso que\funa chica atrape\nPOKéMON bicho?",
  ["43:4a70"] = "KAI: Colecciono\nPOKéMON bicho\fdesde que era\nsólo un niño.\f¡Es imposible\nque pueda perder!",
  ["43:4acd"] = "SAMUEL: Si tienes\ntiempo para\fconversar, busca\nPOKéMON bicho.",
  ["43:4b0c"] = "KOLDO: Soy un gran\nestudioso de los\vPOKéMON bicho.\fSeguro que\ngano.",
  ["43:4b4f"] = "PLAZA DEL DESCANSO\nPARQUE NACIONAL",
  ["43:4b70"] = "¿Qué dice\neste cartel?\fPor favor, lucha\nsólo en la hierba.\fPUESTO DEL GUARDA\nPARQUE NACIONAL",
  ["43:4bc5"] = "PISTAS ENTRENADOR\fImprime una CARTA\nabriéndola y\vpulsando START.",
  ["43:4e1f"] = "¡Bienvenido!",
  ["43:4e29"] = "Hola. Lo siento\npero hoy no\fse admiten\nvisitas.",
  ["43:4e62"] = "¿Quieres probar\nen el NÚMERO DE\vLA SUERTE?\f¿Compruebo los\nnúmeros ID de\vtus POKéMON?\fSi tienes suerte,\nganarás un premio.",
  ["43:4ee2"] = "El número de esta\nsemana es {STRBUF}.",
  ["43:4f02"] = "A ver si coincide\ncon tu número.",
  ["43:4f21"] = "……\n……",
  ["43:4f26"] = "Vuelve la próxima\nsemana y participa\fotra vez en el\nNº DE LA SUERTE.",
  ["43:4f5d"] = "¡Uauu! ¡Tus cinco\nnúmeros coinciden!\f¡Ya tenemos un\nganador!\f¡Has ganado una\nMASTER BALL!",
  ["43:4fcb"] = "¡Oye! ¡Tus tres\núltimos números\vcoinciden!\f¡Ganaste el\nsegundo premio:\vREPARTIR EXP!",
  ["43:501e"] = "¡Ooh! ¡Tus dos\núltimos números\vcoinciden!\fGanaste el tercer\npremio: MÁS PP.",
  ["43:5068"] = "¡No! Tus números\nID no coinciden.",
  ["43:508e"] = "No tienes sitio\npara tu premio.\fHazle sitio y\nvuelve enseguida.",
  ["43:50d5"] = "Ahora tenemos\nuna promoción\vespecial.\fAcierta estas 5\npreguntas y gana\vuna TARJETA RADIO.\fIntrodúcela en tu\nPOKéGEAR para oír\fla radio siempre\nque quieras.\f¿Quieres\nparticipar?",
  ["43:519a"] = "Pregunta 1:\f¿Se puede ver el\nMAPA del PUEBLO\ven el POKéGEAR?",
  ["43:51d1"] = "¡Correcto!\nPregunta 2:\f¿NIDORINA es\nsiempre hembra?",
  ["43:5204"] = "¡Perfecto!\nPregunta 3:\f¿Utiliza BONTURI\nCÉSAR, el artesano\vde las POKé BALL?",
  ["43:524d"] = "¡Por ahora bien!\nPregunta 4:\f¿Es cierto que\nMAGIKARP no puede\faprender ningún\nmovimiento de MT?",
  ["43:528b"] = "¡Otro acierto!\nY ahora la última\vpregunta:\fLa HORA POKéMON\ndel PROF. OAK es\vmuy popular.\f¿Es ROSI la\nco-presentadora?",
  ["43:530b"] = "¡Bingo!\n¡Enhorabuena!\fÉste es tu premio:\n¡la TARJETA RADIO!",
  ["43:5350"] = "¡El POKéGEAR de\n{PLAYER} se puede\vusar como radio!",
  ["43:5375"] = "Sintoniza nuestros\nprogramas.",
  ["43:5399"] = "Lo siento mucho,\npero te has\fequivocado.\n¡Vuelve a probar!",
  ["43:53d3"] = "¡Ah! Entiendo.\nVuelve a probar si\vcambias de idea.",
  ["43:5403"] = "NARDO es un DJ\nfabuloso.\f¡Su dulce voz\nme derrite!",
  ["43:5439"] = "Me gusta ROSA, de\nla HORA POKéMON.\fAunque sólo\nconozca su voz.",
  ["43:5481"] = "¡Por fin nos hemos\napoderado de la\vTORRE de RADIO!\f¡Ahora todos\nexperimentarán el\fverdadero terror\ndel TEAM ROCKET!\f¡Ya veréis qué\nhorribles somos!",
  ["43:550f"] = "¡Demasiado fuerte!\nTe vigilaremos…",
  ["43:552f"] = "Eres muy fuerte.\fArruinarías\nnuestros planes.\fMejor alertar a\nlos otros…",
  ["43:5574"] = "PB RECEPCIÓN\nP1 VENTAS\fP2 PERSONAL\nP3 PRODUCCIÓN\fP4 OFICINA DEL\n   DIRECTOR",
  ["43:55be"] = "¡CANAL SUERTE!\f¡Gana con los ID\nde los POKéMON!\f¡Cambia POKéMON\ny reúne diferentes\vnúmeros ID!",
  ["43:570e"] = "Puedes escuchar la\nradio en cualquier\vlugar. ¡Sintoniza!",
  ["43:5740"] = "Las nanas de la\nradio duermen\va los POKéMON.",
  ["43:576d"] = "¿Por qué querrían\napoderarse de la\vTORRE de RADIO?",
  ["43:57a0"] = "JIGGLYPUFF:\nJiggly…",
  ["43:57b5"] = "¡Aviso!\nProhibido entrar\vsin autorización.\fAntes no\nera así.\fDebe de haber\nalgún problema con\vel DIRECTOR…",
  ["43:582e"] = "Puedes mirar por\ntodas partes.\fEl DIRECTOR ya\nno está enfadado.",
  ["43:5885"] = "Hace tres años, el\nTEAM ROCKET tuvo\vque separarse.\f¡Pero nos estamos\nvolviendo a\vreunir aquí!",
  ["43:58db"] = "¡Bah! ¡No te\nhagas el chulo!",
  ["43:58f1"] = "¡No permitiremos\nque arruines\vnuestros planes!",
  ["43:5923"] = "¡Somos el\nTEAM ROCKET,\fexplotadores de\nlos POKéMON!\f¡Nos gusta ser\nmalos! ¿Asustado?",
  ["43:596a"] = "¿Te crees\nun héroe?",
  ["43:5983"] = "No siempre somos\nmalos. Hacemos\vlo que queremos.",
  ["43:59b7"] = "¡Oye! ¡Fuera de\nnuestro camino!",
  ["43:59d7"] = "¡Argg! Me rindo.",
  ["43:59ea"] = "Nuestros\nEJECUTIVOS\fquieren hacerse\ncon este lugar.\fTienen grandes\nplanes. ¿Cuáles\vserán?",
  ["43:5a4e"] = "¡Jajaja!\f¡Qué aburrimiento!\n¡Fue tan sencillo\fapoderarse de\neste lugar!\f¡Venga,\nentretenme!",
  ["43:5aa9"] = "¿Quién eres tú?",
  ["43:5aba"] = "¡Me venciste y no\npienso olvidarlo!",
  ["43:5ade"] = "P1 VENTAS",
  ["43:5ae8"] = "La HORA POKéMON\ndel PROF. OAK.\f¡El mejor programa\nde la radio!",
  ["43:5b1b"] = "Radio POKéMON.\nA cualquier hora\vy en todas partes.",
  ["43:5cbf"] = "Hemos grabado los\ngritos de todos\flos POKéMON\ndescubiertos.\fDebemos de tener\nunos 200 tipos.",
  ["43:5d20"] = "Los POKéMON son\nmuy queridos por\vsus entrenadores.\fEs horrible ver\ncómo trata el\fTEAM ROCKET\na los POKéMON.",
  ["43:5d89"] = "Emitimos programas\nde entretenimiento\flas 24 horas\ndel día.\f¡Intentaremos\nhacerlo lo mejor\vposible!",
  ["43:5df2"] = "El jefe del TEAM\nROCKET se ha\vencerrado.\fPero el DIRECTOR\npuede abrirle.\fEstá en el\ncuarto piso.\f¡Sálvale!",
  ["43:5e69"] = "¿Está a salvo\nel DIRECTOR?",
  ["43:5e80"] = "¡Gracias!\n¡Eres mi héroe!\fToma esto como\nagradecimiento.",
  ["43:5ebf"] = "¡Es DÍA SOLEADO!\nMejora movimientos\fdel tipo fuego\ndurante un tiempo.",
  ["43:5efa"] = "¡Estuviste\ngenial!",
  ["43:5f16"] = "He recibido\nórdenes.\f¡Aplastaré a todo\naquél que desafíe\val TEAM ROCKET!",
  ["43:5f66"] = "¿¡Qué!?",
  ["43:5f6e"] = "No he cumplido\ncon mi deber…\fY me van a\nbajar el sueldo…",
  ["43:5fa2"] = "Me encanta ordenar\na los POKéMON que\vcometan delitos.",
  ["43:5fd2"] = "¿Bromeas?",
  ["43:5fe2"] = "¡No me gusta\nperder!\f¡Odio a los\nPOKéMON inútiles!",
  ["43:601b"] = "¿Por qué se\nabrió la puerta?\f¿Acaso eres tú\nel responsable?",
  ["43:6060"] = "¡Es mi fin!",
  ["43:606e"] = "¿Qué? ¿Esquivaste\na nuestros hombres\vdel SUBTERRÁNEO?\f¿Cómo lo hiciste?",
  ["43:60b2"] = "¿Un niño que\nmerodea por aquí?\f¿Quién eres?",
  ["43:60e1"] = "¡Vaya! ¡No te tomé\nmuy en serio!",
  ["43:60ff"] = "¡Jajajajaja…!\fDesde aquí puedo\ntransmitir todo\vtipo de señales.",
  ["43:6142"] = "Es la ranura de la\nLLAVE MAGNÉTICA.",
  ["43:615a"] = "{PLAYER}\nusó la\vLLAVE MAGNÉTICA.",
  ["43:6174"] = "P2 PERSONAL",
  ["43:6182"] = "MÚSICA POKéMON\ncon el DJ NARDO",
  ["43:62b0"] = "Mientras estaba\nen las RUINAS\voía la radio.\fY escuché una\nextraña emisión.",
  ["43:6306"] = "ROSA: ¿Por qué?\n¿Por qué debo\vsufrir?\f¡MEOWTH, ayúdame!",
  ["43:6349"] = "ROSA: ¡Oh! ¡Eres\nmi salvador!\f¿Aceptas esto como\nagradecimiento?",
  ["43:638d"] = "ROSA: Es para los\nPOKéMON que\fsaben movimientos\nnormales.",
  ["43:63ca"] = "ROSA: Sintoniza\nconmigo en la\fHORA POKéMON\ndel PROF. OAK.",
  ["43:6404"] = "MEOWTH: Meowth…",
  ["43:6415"] = "¿Quieres rescatar\nal DIRECTOR?\f¡Pues ya te puedes\nir olvidando de\feso, porque te\nvoy a ganar!",
  ["43:646d"] = "¡No! ¡Increíble!",
  ["43:6480"] = "¡Increíble!\n¡He perdido!",
  ["43:64a2"] = "¡Alto ahí!\n¡Me llaman la\ffortaleza del\nTEAM ROCKET!\f¡No des un\npaso más!",
  ["43:64ee"] = "¡La fortaleza\nse derrumbó!",
  ["43:6507"] = "Te has ganado mi\nrespeto. ¡Te daré\vun consejo!\fAún estás a\ntiempo de darte\vla vuelta.",
  ["43:6562"] = "¿Son buenos mis\nPOKéMON?\f¡Creeré que mis\nPOKéMON son buenos\fcuando derroten\na los tuyos!",
  ["43:65b3"] = "¡Oh, no! ¡Son\ntan inútiles!",
  ["43:65cf"] = "¡Me gusta mi\npersonalidad!\f¿Qué importan\nlos POKéMON?",
  ["43:6600"] = "¡Extraordinario!\fEsta TORRE de\nRADIO completará\vnuestro gran plan.",
  ["43:6641"] = "¡Mmmm…!\fTodo gran plan\ntiene sus pegas.",
  ["43:6669"] = "¿De verdad crees\nque puedes detener\val TEAM ROCKET?",
  ["43:669c"] = "P3 PRODUCCIÓN",
  ["43:66ab"] = "P3 ESTUDIO 2",
  ["43:686a"] = "¡Tú! ¿Has venido\na rescatarme?",
  ["43:6889"] = "¿Es eso lo que\nestabas esperando?\f¡Pues no!\n¡Soy un impostor!\fMe hice pasar por\nel director para\fpreparar nuestra\ninvasión.\f¿Quieres saber\ndónde escondimos\val DIRECTOR?\fTe lo diré,\n¡pero sólo si eres\vcapaz de vencerme!",
  ["43:6965"] = "Muy bien. Te diré\ndónde está.",
  ["43:6988"] = "Escondimos al\nauténtico DIRECTOR\fen el ALMACÉN\nSUBTERRÁNEO.\fEstá al otro\nextremo del\vSUBTERRÁNEO.\fPero dudo que\nllegues tan lejos.",
  ["43:6a0d"] = "Hola, jovencito.\n¿Me recuerdas de\fla GUARIDA de\nPUEBLO CAOBA?\fEntonces perdí,\npero ahora no.",
  ["43:6a70"] = "¡Esto no me puede\nestar pasando!\fHe luchado y\nhe perdido…",
  ["43:6aaa"] = "{PLAYER}, ¿verdad?\fUn mocoso como tú\nno puede apreciar\fla grandeza del\nTEAM ROCKET.\f¡Qué lástima!\nTendrías futuro\vcon nosotros.",
  ["43:6b23"] = "¿Cómo has logrado\nllegar tan lejos?\fDebes de ser un\nbuen entrenador.\fQueremos hacernos\ncon esta EMISORA\fde RADIO para\nanunciar nuestra\vvuelta.\fEso debería\nhacer regresar a\fGIOVANNI de su\nentrenamiento.\fVamos a recuperar\nla gloria\vperdida.\fY no voy a\npermitir que\finterfieras en\nnuestros planes.",
  ["43:6c45"] = "¡No! ¡Perdóname,\nGIOVANNI!",
  ["43:6c60"] = "¿Qué ha pasado?\fNuestros sueños\nhechos añicos.\fNo estaba listo\npara la tarea.\fComo ya hiciera\nGIOVANNI, hoy\fabandonaré yo el\nTEAM ROCKET.\f¡Adiós!",
  ["43:6d04"] = "DIRECTOR: Gracias,\n{PLAYER}.\fTu valiente\nacción ha salvado\fa los POKéMON\nde todo el país.\fSé que no es\nmucho, pero\vacepta esto.",
  ["43:6d7e"] = "En CIUDAD TRIGAL\nhabía una\vtorre.\fPero era vieja\ne inestable.\fY la sustituimos\npor nuestra\vTORRE de RADIO.\fAl demolerla,\nencontramos eso en\vla parte superior.\fDicen que antes\nvolaban enormes\fPOKéMON sobre\nCIUDAD TRIGAL.\fPodría ser de\nun POKéMON.\fComo el que\naparece en la\fTORRE HOJALATA\nde CIUDAD IRIS.\fMejor que vuelva\na mi OFICINA.",
  ["43:6ee3"] = "En CIUDAD TRIGAL\nhabía una\vtorre.\fPero era vieja\ne inestable.\fY la sustituimos\npor nuestra\vTORRE de RADIO.\fAl demolerla,\nencontramos eso en\vla parte superior.\fDicen que antes\nvolaban enormes\fPOKéMON sobre\nCIUDAD TRIGAL.\fPodría ser de\nun POKéMON.\fComo el que\naparece en ISLAS\fREMOLINO, cerca de\nCIUDAD ORQUÍDEA.\fMejor que vuelva\na mi OFICINA.",
  ["43:7049"] = "DIRECTOR: ¡Hola,\n{PLAYER}!\fYa sabes que amo\na los POKéMON.\fConstruí la TORRE\nde RADIO para\fexpresar mi amor\npor los POKéMON.\f¡Ojalá difrute la\ngente con nuestros\vprogramas!",
  ["43:70e3"] = "NARDO: ¿Escuchas\nnuestra música?",
  ["43:7105"] = "P4 OFICINA\n   DEL DIRECTOR",
  ["43:711e"] = "P4 ESTUDIO 1",
  ["44:409f"] = "¿Eh? Es una\nPOKéDEX, ¿verdad?\v¿Puedo verla?\fHay muchos tipos\nde POKéMON.\f¿Y esto qué es?\f¿Cuál es este\nPOKéMON?\fSe parece a las\nraras escrituras\fde las paredes\nde las RUINAS.\fSi esos dibujos\nson POKéMON,\fdebería haber\nmuchos más.\f¡Ya sé! Voy a\nactualizar tu\vPOKéDEX. Sígueme.",
  ["44:42c3"] = "¡Mmm…! ¡Qué\nlugar tan extraño!",
  ["44:42e3"] = "…",
  ["44:42e6"] = "Me gusta pensar\naquí.",
  ["44:42fd"] = "SALA DEL PANEL DE\nPIEDRA MISTERIOSO",
  ["44:431a"] = "RUINAS ALFA\n¡Bienvenidos!",
  ["44:433a"] = "C. INVESTIGACIÓN\nDE LAS RUINAS ALFA\fLa Autoridad en\nlas RUINAS ALFA",
  ["44:443c"] = "Es una réplica\nde un antiguo\vPOKéMON.",
  ["44:4461"] = "Un POKéMON que\nvuela elegante,\fcon alas de color\narcoiris.",
  ["44:4516"] = "¡Bienvenido a\nesta cámara!\fHay unos paneles\ncon el dibujo de\fun POKéMON, hecho\npor los antiguos.\fMueve los paneles\ny completa el\vdibujo.\fA la derecha verás\nuna descripción\vdel POKéMON.",
  ["44:45cb"] = "Es una réplica\nde un antiguo\vPOKéMON.",
  ["44:45f0"] = "Un POKéMON que se\noculta en el mar.\fCon sus ojos\nexplora la zona.",
  ["44:46bb"] = "Es una réplica\nde un antiguo\vPOKéMON.",
  ["44:46e0"] = "Este POKéMON\nflota a la deriva\fmoviendo sus\ndiez tentáculos.",
  ["44:4795"] = "Es una réplica\nde un antiguo\vPOKéMON.",
  ["44:47ba"] = "Este POKéMON\nvolador ataca a\fsu presa con sus\nfuertes colmillos.",
  ["44:484a"] = "Siento una\nrara presencia…",
  ["44:486d"] = "Esta habitación es\nmuy grande, pero\vaquí no hay nada.",
  ["44:489b"] = "Este lugar está\nimpregnado de\vmisticismo.\fParece hasta\netéreo.",
  ["44:48e5"] = "Los edificios\nantiguos suelen\fser tumbas\nde reyes.\fComo por ejemplo,\nlas pirámides.",
  ["44:4933"] = "Es una réplica\nde un antiguo\vPOKéMON.",
  ["44:4b1e"] = "¡Ya está!\fHe modificado\ntu POKéDEX.\fAñadí una\nPOKéDEX opcional\fpara guardar los\ndatos de UNOWN.\fLos registra en\nel orden en que\vson atrapados.",
  ["44:4ba0"] = "Mejorada POKéDEX\nde {PLAYER}.",
  ["44:4bb7"] = "Todos los UNOWN\nque atrapes serán\vregistrados aquí.\fA ver cuántos\ntipos existen.",
  ["44:4c05"] = "¿Atrapaste a todos\nlos UNOWN?\f¡Es un gran\nlogro!\fHe ajustado la\nimpresora para\vUNOWN.\fPuedes usarla\ncuando quieras.",
  ["44:4c93"] = "Las RUINAS datan\nde hace unos\t1.500 años.\fPero ignoramos\npor qué o por\fquién fueron\nconstruidas.",
  ["44:4ceb"] = "¿Cuántos tipos de\nPOKéMON habrá\ven las RUINAS?",
  ["44:4d1e"] = "¿Hay POKéMON\nen las RUINAS?\f¡Qué noticia\ntan increíble!\fTendremos que\ninvestigarlo.",
  ["44:4d71"] = "En las paredes de\nlas RUINAS hay\funos dibujos\nmuy raros.\fSon la clave\npara resolver\fel misterio\nde las RUINAS.",
  ["44:4ded"] = "¿Los POKéMON\nraros que viste\ven las RUINAS?\fSon muy parecidos\na los dibujos de\fesas paredes\nde ahí.\f¡Mmm…!\fDebe de significar\nque hay muchos\vtipos diferentes…",
  ["44:4e8b"] = "RUINAS ALFA\n10 Años\nde Exploración",
  ["44:4eae"] = "Nombre de POKéMON\nmisterioso: UNOWN\fEncontrados un\ntotal de 26 tipos.",
  ["44:4ee3"] = "Parece que esto\naún no funciona.",
  ["44:4f02"] = "Se puede imprimir\nUNOWN.",
  ["44:4f5b"] = "Hay muchos libros\nacadémicos.\fRuinas Antiguas…\nLos Misterios de\vlos Antiguos…",
  ["44:505c"] = "¿Te diriges a\nPUEBLO AZALEA?\fDemuestra a\nmis POKéMON que\vvales para luchar.",
  ["44:50b0"] = "¡Oh, oh, oh!",
  ["44:50bd"] = "¡Muy bien!\nYa lo he decidido.\f¡No me iré hasta\nque mis POKéMON\vse fortalezcan!",
  ["44:5106"] = "Merodeo por todas\npartes en busca\vde POKéMON.\f¿También tú vas en\nbusca de POKéMON?\f¡Pues entonces\neres mi rival\vcoleccionista!",
  ["44:516c"] = "¡Ugh! Mis pobres\nPOKéMON…",
  ["44:5182"] = "Todos los viernes\nse escucha a un\fPOKéMON que ruge\nen la cueva.",
  ["44:51c4"] = "¡Uauu!\n¡Qué sorpresa!\f¡No esperaba\nver a nadie!",
  ["44:51ff"] = "¡Uauu! ¡Me\nhan machacado!",
  ["44:521a"] = "Me obligaron a\ncomprar una COLA\vde SLOWPOKE.\fLo siento por\nel pobre POKéMON.",
  ["44:5266"] = "El SUPERSÓNICO de\nZUBAT confunde a\vmis POKéMON.\f¡Y eso me\npreocupa!",
  ["44:52b1"] = "¡Me inflamé!",
  ["44:52c0"] = "Los fines de\nsemana se oyen\fextraños rugidos\nen la cueva.",
  ["44:5300"] = "Si hay luz, no me\nasusta la cueva.\fSi eres fuerte,\nlos POKéMON no\vse asustarán.",
  ["44:5345"] = "¡DESTELLO!",
  ["44:534d"] = "El fuego de mi\nPOKéMON\vilumina la cueva.",
  ["44:546e"] = "Hace mucho\ntiempo que no\vveo a nadie.\fNo seas tímido.\n¡Luchemos!",
  ["44:54bb"] = "¡Uurggh…!",
  ["44:54c4"] = "Llevo perdido\nmucho tiempo…\fNo es que me\nimporte, ¡pero\vestoy hambriento!",
  ["44:5510"] = "¡Qué sabes tú!\n¡Un visitante!",
  ["44:552e"] = "¡Jajaja! ¡Eres\nmuy susceptible!",
  ["44:554c"] = "Vivo aquí abajo.\fY tú también\npodrías si\vquisieras.\fComo ves, hay\nmucho sitio.",
  ["44:559b"] = "¿Quién anda ahí?\f¡Déjame en paz,\na mí y a mis\vPOKéMON!",
  ["44:55c4"] = "¡Fuera…!\n¡Lárgate!",
  ["44:55d2"] = "Sólo yo y mis\nPOKéMON. ¡Me\vmuero de alegría!",
  ["44:5601"] = "He venido hasta\naquí para estudiar\va los POKéMON.\f¡Te demostraré\nmis hallazgos en\vun combate real!",
  ["44:5668"] = "¡Lo has demostrado\nconmigo!",
  ["44:5681"] = "Debería reunir\ny publicar mis\vhallazgos.\fPodría hacerme\ntan famoso como\vel PROF. ELM.",
  ["44:57bf"] = "Hay dos tipos\nde personas.\fLos que tienen\nestilo y los que\vno lo tienen.\f¿A qué tipo\nperteneces tú?",
  ["44:5826"] = "¡Tu estilo es\ndeslumbrante!",
  ["44:5841"] = "El estilo de tus\nPOKéMON es\vsorprendente.\f¡Seguirás\nmejorando!",
  ["44:5895"] = "Estoy entrenando.\n¿Quieres luchar?",
  ["44:58b8"] = "No, eres demasiado\nbueno para mí.",
  ["44:58d9"] = "Seguiré\nentrenándome\vhasta que mejore.",
  ["44:5907"] = "Si los POKéMON\nque me gustan\festuvieran ahí,\niría sin pensarlo.\fEso haría un\nbuen entrenador.",
  ["44:5958"] = "¡Preferiría cuidar\nde mis niños!",
  ["44:597c"] = "Cada semana viene\nun POKéMON hasta\vla orilla.\fQuería ver a ese\nPOKéMON…",
  ["44:5b06"] = "CÉSAR: ¡Hola,\n{PLAYER}!\fLos guardias de\narriba huyeron en\vcuanto les grité.\fPero entonces\nme caí por el\vPOZO.\fMe golpeé en la\nespalda y ahora\vno puedo moverme.\fSi estuviera bien,\nmis POKéMON\flos habrían\nmachacado…\f¡Bah! Pero no\npuedo hacer nada.\f¡{PLAYER},\ndemuéstrales lo\vque vales!",
  ["44:5c1d"] = "CÉSAR: ¡Muy bien,\n{PLAYER}!\fEl TEAM ROCKET\nha huido.\fY yo estoy mejor\nde mi espalda.\v¡Salgamos de aquí!",
  ["44:5c78"] = "¡Maldición! Estaba\nde guardia arriba\fcuando un viejo\nmemo me gritó.\fMe asusté tanto\nque me he caído\vaquí abajo.\f¡Creo que voy\na desahogar mi\fira luchando\ncontra ti!",
  ["44:5d1f"] = "¡Arrg! ¡Hoy NO\nes mi día!",
  ["44:5d3b"] = "Sí, hemos estado\ncortando las colas\fde los SLOWPOKE\ny vendiéndolas.\fLo hacemos sólo\npor dinero.\f¡Así es! Somos\nel TEAM ROCKET,\f¡y haríamos lo que\nfuera por dinero!",
  ["44:5dde"] = "¿Qué quieres?\f¡Si nos molestas,\nno esperes\vmisericordia!",
  ["44:5e23"] = "Lo hiciste bien,\nmocoso, pero ya\vverás la próxima.",
  ["44:5e54"] = "Sí, el TEAM ROCKET\nse separó hace\vtres años.\fPero seguimos\nclandestinamente\fcon nuestras\nactividades.\f¡Diviértete ahora\ncon nuestras\vfechorías!",
  ["44:5ee5"] = "¿Dejar de cortar\nlas COLAS de\vlos SLOWPOKE?\f¡Obedecerte\narruinaría la\freputación del\nTEAM ROCKET!",
  ["44:5f37"] = "Simplemente…\nMuy fuerte…",
  ["44:5f4a"] = "Necesitamos pasta,\n¿pero vendiendo\vCOLAS de SLOWPOKE?\f¡Es muy duro ser\nun SOLDADO ROCKET!",
  ["44:5f9b"] = "¿No más COLAS?\f¡Claro! ¡Intenta\nvencernos a todos!",
  ["44:5fd3"] = "¡Maldito lambrijo!",
  ["44:5fe5"] = "¡Las COLAS de los\nSLOWPOKE se\vregeneran rápido!\f¿Qué hay de malo\nen venderlas?",
  ["44:6023"] = "Un SLOWPOKE\nsin COLA…\f¿Qué? Tiene una\nCARTA. ¿Leerla?",
  ["44:6061"] = "{PLAYER} lee\nla CARTA.\fSé bueno y cuida\nla casa donde\festá el abuelo y\nSLOWPOKE.\fTe quiere, papá.",
  ["44:60b9"] = "Un SLOWPOKE\nsin COLA…",
  ["44:6182"] = "Me gustaría ver\ncómo evoluciona\vSLOWPOKE.\fObservándolos\nhe hecho un nuevo\vdescubrimiento.\fUn SLOWPOKE con\nuna ROCA DEL REY\fsuele ser mordido\npor un SHELLDER.\fToma, compartiré\nuna ROCA DEL REY\vcontigo.",
  ["44:624a"] = "Voy a ser como\nSLOWPOKE.\fTendré paciencia\ny a ver si\vevoluciona alguno.",
  ["44:62c5"] = "En este FARO se\nentrena la gente.\fNo es fácil subir\nporque hay muchos\ventrenadores.",
  ["44:631a"] = "Antes había unos\nPOKéMON que\filuminaban el mar\nque rodea OLIVO.\fEl FARO se\nconstruyó en honor\va esos POKéMON.",
  ["44:646b"] = "¡Los hombres de\nmar siempre\vquieren luchar!",
  ["44:64a1"] = "¡Urf!\n¡He perdido!",
  ["44:64af"] = "¡Qué poder!\n¿Te gustaría\fnavegar conmigo\npor estos mares?",
  ["44:64e9"] = "¿Qué? Aquí\nno se juega.",
  ["44:650c"] = "¡Ah! Ya veo que\nvas en serio.",
  ["44:652f"] = "Arriba hay un\nPOKéMON que\vilumina el FARO.\fPero dicen que\nestá enfermo y que\fla medicina normal\nno puede curarle.",
  ["44:6625"] = "¿Qué haces aquí?\n¿Sólo mirando?\f¡Pues mejor\nque te vayas!",
  ["44:666e"] = "Estás realmente\npreocupado…",
  ["44:6689"] = "¿Cómo diablos\nse sube?\fQuiero visitar\nal POKéMON\fenfermo, pero no\npuedo subir…",
  ["44:66dd"] = "Los marineros\nsomos fuertes y\vsimpáticos. ¿Y tú?",
  ["44:670f"] = "Eres fuerte y\nsimpático…",
  ["44:672e"] = "Siempre que vuelvo\na CIUDAD OLIVO\vvoy al GIMNASIO.\fEl tipo de POKéMON\nde su LÍDER ha\fcambiado sin\ndarme cuenta.",
  ["44:679e"] = "Viajo por el mundo\npara entrenar a\fmis POKéMON.\n¿Quieres luchar?",
  ["44:67e1"] = "(Suspiro…)\nDebo entrenar más.",
  ["44:6801"] = "YASMINA solía\nutilizar POKéMON\vroca como ONIX.",
  ["44:68bc"] = "YASMINA debe de\nestar preocupada\vpor este POKéMON.\fNi siquiera\nsonríe.",
  ["44:690f"] = "Yo tampoco puedo\nsonreír…",
  ["44:692e"] = "Hablando de\nenfermedades, hay\funa FARMACIA en\nCIUDAD ORQUÍDEA.",
  ["44:696f"] = "YASMINA es LÍDER\nde este GIMNASIO.\fQuería que viniera\nconmigo.\f¡No he encontrado\na nadie mejor!",
  ["44:69d5"] = "¡Ay! ¡Mi POKéMON!",
  ["44:69e6"] = "Cualquiera estaría\npreocupado si sus\fPOKéMON estuvieran\nenfermos.\fRezaré por este\nPOKéMON, para que\fYASMINA regrese\nal GIMNASIO.",
  ["44:6aef"] = "Quería luchar con\nYASMINA, pero no\festá disponible.\n¿Y tú, qué…?",
  ["44:6b3a"] = "¡Uauu! ¡Eres\nincreíble!",
  ["44:6b5b"] = "Ser LÍDER de un\nGIMNASIO no es\fsólo una cuestión\nde fuerza. Todo\fLÍDER también debe\nser compasivo.",
  ["44:6bb0"] = "Estamos bastante\naltos aquí. Mis\fPOKéMON pájaro\nestán en forma.",
  ["44:6beb"] = "¡Uups…!\n¡Se estrellaron!",
  ["44:6bff"] = "Mi POKéMON\naprendió VUELO en\vCIUDAD ORQUÍDEA.\fY como soy un\nperdedor, cruzaré\vel mar VOLANDO…",
  ["44:6dbd"] = "YASMINA: Este\nPOKéMON siempre\filuminaba el mar\npor la noche.\fPero de pronto\nenfermó… Le\vcuesta respirar…\fDicen que hay\nuna FARMACIA\festupenda en\nCIUDAD ORQUÍDEA…\fPero está al otro\nlado del mar…\fY no puedo dejar\nsolo a AMPHY…",
  ["44:6ea0"] = "¿Podrías traerme\nsu medicina?\v¿Por favor?",
  ["44:6ed5"] = "YASMINA: ¡Ah…!\n¿Le das a AMPHY\vesa medicina?",
  ["44:6eff"] = "{PLAYER} entregó\nla POCIÓN SECRETA\va YASMINA.",
  ["44:6f26"] = "YASMINA: ¡Mmm!\nPor favor, no te\vofendas…\fAMPHY no aceptaría\nnada de nadie,\vsólo confía en mí.",
  ["44:6f80"] = "YASMINA: …\fAMPHY, ¿cómo te\nsientes?",
  ["44:6fa8"] = "YASMINA: ¡Oh…!\n¡Qué alivio…!\fEs tan\nestupendo…\fMuchísimas\ngracias.\fRegresaré\nal GIMNASIO…",
  ["44:701b"] = "YASMINA: Ya veo.",
  ["44:702d"] = "¡AMPHY, aguanta!",
  ["44:703f"] = "AMPHY: ¡Am…\nAm… phyphy…!",
  ["44:7055"] = "Apenas puede\nrespirar…",
  ["44:7079"] = "AMPHY: ¡Amphy!\n¡Amphy!",
  ["45:4126"] = "¡Arrg…!\nHas encontrado la\vescalera secreta.",
  ["45:414f"] = "El experimento\nfuncionó a las mil\vmaravillas.\fLos MAGIKARP no\nvalen nada, pero\flos GYARADOS son\nmuy productivos.",
  ["45:41bc"] = "¡Urrg…!\fLos POKéMON dragón\nde ese chico\vson muy fuertes…",
  ["45:41e5"] = "LANCE: DRAGONITE,\nHÍPER RAYO.",
  ["45:4204"] = "¿Por qué tardaste\ntanto, {PLAYER}?\fComo pensaba,\nesa extraña señal\fde radio viene\nde aquí.",
  ["45:4259"] = "Las escaleras\nestán justo aquí.",
  ["45:4275"] = "LANCE: {PLAYER},\nseparémonos para\fregistrarlo todo.\nYo iré primero.",
  ["45:47cd"] = "¡Cuidado!\n¡Un intruso!",
  ["45:47e3"] = "¡Vaya…! Fallé…",
  ["45:47f4"] = "¡Me toca a mí!\n¡No puedes huir!",
  ["45:4814"] = "En las estatuas de\nlos POKéMON hay\fcámaras de\nvigilancia.\fSeguiremos\napareciendo hasta\fque pulses un\nbotón secreto.",
  ["45:4876"] = "Esto era una\nguarida ninja.\fHay trampas para\nconfundir a los\vintrusos como tú.",
  ["45:48c6"] = "Lo tengo…",
  ["45:48d1"] = "Bien. Te contaré\nun secreto sobre\vnuestra guarida.\fEso que hay en\nel suelo es un\vpanel deslizante.\fSi te colocas\nencima, te\fllevará de vuelta\na la entrada.",
  ["45:4972"] = "¡Je, je! ¿Te crees\nafortunado?\fAdelante, da\notro paso.\f¡El suelo está\nlleno de trampas!",
  ["45:49cd"] = "¡Kabum!",
  ["45:49d6"] = "Yo ni siquiera sé\ndónde están las\vtrampas.\fTendrás que\nser valiente\vy caminar.",
  ["45:4a37"] = "Es una estatua de\nPERSIAN…\fSus ojos tienen un\nbrillo extraño.",
  ["45:4a68"] = "¡Un botón secreto!\nMejor pulsarlo.",
  ["45:4a8b"] = "El interruptor\nestá apagado.",
  ["45:4f65"] = "¡Alto ahí!",
  ["45:4f7b"] = "No podemos dejar\nque un mocoso como\vtú nos toree.\fEs malo para el\norgullo del TEAM\vROCKET.\fPor muy fuerte que\nseas, no podrás\fderrotarnos al\nmismo tiempo.\fLo siento, chico.\n¡Prepárate para\vser aniquilado!",
  ["45:5044"] = "¡Oye! No seas tan\negoísta. Comparte\vla diversión.",
  ["45:5075"] = "¿Qué? ¿Tenías un\ncómplice? ¿Dónde\festá tu sentido\ndel honor?\fComo sustituto\nprovisional\fde GIOVANNI, ¡ya\nte enseñaré yo a\fno meterte con\nel TEAM ROCKET!",
  ["45:5114"] = "¡Uau! Eres muy\nfuerte.\f¡Qué lástima!\fSi te unieras al\nTEAM ROCKET,\fpodrías llegar a\nser un EJECUTIVO.",
  ["45:517e"] = "Esta guarida\nse acabó…\fPero no importa.\nEl experimento de\femisión fue\ntodo un éxito.\fQué más da lo que\npase ahora con\vesta guarida.\fTenemos planes más\nimportantes.\fMuy pronto\nconocerás el\fverdadero poder\ndel TEAM ROCKET.\fDisfruta mientras\npuedas…\f¡Fufufufu…!",
  ["45:5290"] = "LANCE: Funcionó.\nHemos derrotado\fa todos estos\nROCKETS.\fPero me preocupa\nese joven contra\vel que luché…",
  ["45:5306"] = "Perdona, {PLAYER}.\nComo lo estabas\fhaciendo tan bien,\nme retiré.\fLo único que hay\nque hacer ahora es\fapagar esa extraña\nseñal radiofónica.",
  ["45:5387"] = "Esta máquina está\ncausando todos\vlos problemas.\fPero no veo ningún\ninterruptor…\fNo tenemos\nelección. Hay que\fdebilitar a todos\nlos ELECTRODE.\fEso impedirá que\nesta máquina siga\ftransmitiendo esa\nextraña señal.\fLos POKéMON no\ntienen la culpa\fy por eso yo me\nsiento culpable.\f{PLAYER}, mejor\nque nos dividamos\vla tarea.",
  ["45:54a2"] = "LANCE: Déjame\neste lado.",
  ["45:54c1"] = "LANCE: Por fin\nha parado esa\vextraña señal.\fEl LAGO vuelve a\nla normalidad.\f¡Eres un héroe!\nMuchas gracias\fen nombre de\ntodos los POKéMON.\f¡Ah, sí! Toma\nesto.\fLo encontré aquí,\npero yo no lo\vnecesito.",
  ["45:55b0"] = "Es TORBELLINO.\nEnséñasela a\fun POKéMON y\npodrá cruzar\vtorbellinos.\fPero recuerda\nque…\fSólo podrás usarla\nfuera de los\fcombates con la\nMEDALLA del\vGIMNASIO CAOBA.",
  ["45:564c"] = "{PLAYER}…\fEl viaje para ser\nun MAESTRO\fPOKéMON es largo\ny difícil.\fY ya que lo sabes,\n¿quieres seguir?\f…\fEntiendo. No,\ntienes razón.\fSi te rindieras\ntan fácilmente,\fjamás habrías\nperseguido este\fmaravilloso\nsueño.\f¡Espero volver\na verte!",
  ["45:574f"] = "LANCE: ¿Estás\nbien?\fTus POKéMON están\nheridos, cansados.\fToma, dales un\npoco de mi\vmedicina.",
  ["45:57af"] = "LANCE: {PLAYER},\ntenemos que hacer\ftodo lo posible\npor los POKéMON.",
  ["45:57da"] = "¿No se abre\nla puerta?\fBueno, necesitas\nuna contraseña que\fsólo conoce el\nTEAM ROCKET.",
  ["45:5831"] = "¿Qué? ¿He perdido?",
  ["45:5840"] = "¿Qué? Soy sólo\nun SOLDADO.\fY no conozco la\ncontraseña. Lo\vsiento por ti.",
  ["45:5882"] = "¡Oh! ¿Un niño?\nNo me gusta,\fpero debo\neliminarte.",
  ["45:58c1"] = "Sabía que\nperdería…",
  ["45:58d2"] = "En mi última\nmisión también fui\fderrotado por\nun niño.\fCuando estábamos\nsecuestrando unos\fPOKéMON, un\nchico pelirrojo y\fde extraña mirada\nme machacó…",
  ["45:5968"] = "¡Tú! ¡Pequeño\nparásito podrido!",
  ["45:5981"] = "¡Grrrr…!",
  ["45:5989"] = "¡Oye! Sólo el jefe\nconoce la clave\vde esa puerta.\f¿Dónde está el\njefe? ¡Quién sabe!\vEncuéntralo tú.",
  ["45:59f1"] = "La puerta está\ncerrada…\fRequiere una\ncontraseña.",
  ["45:5a23"] = "La puerta está\ncerrada…\f{PLAYER} introdujo\nla contraseña.\f¡Puerta abierta!",
  ["45:5a5f"] = "La emisora de\nradio está\femitiendo una\nsiniestra señal.\fEstá funcionando a\nmáxima capacidad.",
  ["45:5abb"] = "Por fin la emisora\nde radio ha dejado\fde transmitir esa\nmaldita señal.",
  ["45:5e2f"] = "LANCE: Necesitas\ndos contraseñas\fpara entrar en el\ncuarto del jefe.\fY sólo conocen\nesas contraseñas\valgunos ROCKETS.\fMe lo ha contado\nese ROCKET que\vestá ahí.\f{PLAYER}, busquemos\nesas contraseñas.",
  ["45:5eeb"] = "¡Urrgg…! El\nchico de la capa\ves muy fuerte…",
  ["45:5f1d"] = "…\f¿No te había\ndicho que iba a\fdestruir al TEAM\nROCKET?\fDime, ¿quién\nera el chico de la\fcapa que usaba los\nPOKéMON dragón?\fMis POKéMON no\npudieron con él.\fNo me importa\nperder. Podría\fganarle con otros\nPOKéMON.\fLo que me molestó\nes lo que dijo…\fMe dijo que no\namo ni confío\fbastante en mis\nPOKéMON.\fMe enfurece haber\nperdido contra un\vmemo como él.\f¡Humph! ¡No tengo\ntiempo para\vgente como tú!",
  ["45:60b6"] = "¿Qué? ¿Quién eres?\nÉsta es la oficina\fde nuestro líder,\nGIOVANNI.\fLleva entrenándose\ndesde que el TEAM\fROCKET se separó\nhace tres años.\fPero seguro que\nvolverá algún día\fpara retomar el\nmando.\fPor eso estamos\naquí de guardia.\f¡No permitiré que\nnadie perturbe\veste lugar!",
  ["45:61c7"] = "Yo…, no pude\nevitarlo…\fGIOVANNI,\nperdóname…",
  ["45:61fe"] = "No puedo dejar\nque me afecte.\fTengo que informar\na los otros…",
  ["45:623b"] = "MURKROW: La\ncontraseña es…\fVIVA GIOVANNI.",
  ["45:6265"] = "¿Conozco yo la\ncontraseña?\fA lo mejor.\f¡Pero no será de\nningún debilucho!",
  ["45:62a7"] = "Muy bien. Espera.\nTe la diré.",
  ["45:62c7"] = "La contraseña de\nla oficina del\vjefe es…\fCOLASLOWPOKE.\fPero no te servirá\nde nada si no\vtienes las dos.",
  ["45:6327"] = "¡Je, je, je!\f¿Me desafías a\nun combate? ¡Bah!\f¡Estás loco, pero\ntienes agallas!\f¡Eso me gusta!\f¡Si me vences, te\ndiré la contraseña\fde la oficina\ndel jefe!",
  ["45:63cd"] = "¡Ji, Ji, Ji!\n¡Eres bueno!",
  ["45:63ed"] = "¡Ji, Ji, Ji!\fLa contraseña\nde la oficina del\vjefe es…\f¡Eh…! Creo que\nes COLARATICATE.",
  ["45:6443"] = "Trabajaba para\nSILPH, pero ahora\finvestigo para el\nTEAM ROCKET.\fUn entrometido\ncomo tú debería\vser castigado.",
  ["45:64b8"] = "Un error táctico\nacabó conmigo…",
  ["45:64d8"] = "Una señal de radio\nque vuelve locos a\vlos POKéMON…\fMi experimento es\ntodo un éxito.\fMi ascenso está\nasegurado. Esta\fderrota no\nsignifica nada.",
  ["45:6562"] = "Me da igual que\nlos POKéMON sufran\fdebido a nuestros\nexperimentos.",
  ["45:6595"] = "Mi fuerte es\npensar, no pelear.",
  ["45:65c0"] = "Si enviáramos\nnuestra señal de\fradio por todo\nel país…\f¡Me emociono\nsólo de pensarlo!",
  ["45:6626"] = "La puerta está\ncerrada…\fNecesitas dos\ncontraseñas.",
  ["45:6659"] = "La puerta está\ncerrada…\f{PLAYER} introdujo\ndos contraseñas.\f¡Puerta abierta!",
  ["45:6a44"] = "¡Vaya…! Mi jefe\nse va a poner\vfurioso…\fSe me escapó el\nFARFETCH'D que\fCORTA árboles para\nconseguir carbón.\fNo puedo ir a\nbuscarlo al\vENCINAR.\fDemasiado grande y\noscuro para mí…",
  ["45:6b01"] = "¡Uauu! ¡Muchísimas\ngracias!\fEl POKéMON de\nmi jefe no me\fobedecía porque\nno tengo MEDALLAS.",
  ["45:6b57"] = "¡Es el POKéMON\nperdido!",
  ["45:6b6e"] = "FARFETCH'D: ¡Farf!",
  ["45:6b81"] = "¡Mi FARFETCH'D!\f¡Genial! ¡Lo has\nencontrado!\fSin él no podíamos\nCORTAR árboles\fpara conseguir\ncarbón.\f¡Gracias, chico!\f¿Cómo podría\nagradecértelo…?\f¡Ya sé! Toma\nesto.",
  ["45:6c29"] = "Es la MO CORTE.\n¡Enséñasela a un\fPOKéMON para\ncortar arbustos!\fPero necesitarás\nla MEDALLA del\fGIMNASIO AZALEA\npara usarla.",
  ["45:6ca8"] = "¿Quieres que te\nenseñe a trabajar\vcon el carbón?\f¡En diez años\nserás el mejor!",
  ["45:6d03"] = "¿Que qué hago?\fAgitar los árboles\ncon GOLPE CABEZA.\fEs muy divertido.\n¡Toma, pruébalo!",
  ["45:6d55"] = "Agita los árboles\ncon GOLPE CABEZA.\fA veces caen\nPOKéMON dormidos.",
  ["45:6d97"] = "Hay tantos árboles\nen el ENCINAR que\fno se ve ni\nel cielo.\fPor favor, busca\nobjetos que puedan\vhaber caído.",
  ["45:6e11"] = "SANTUARIO del\nENCINAR…\fConstruido en\nhonor del guardián\vdel encinar…",
  ["46:42dc"] = "Me echaron\ndel CASINO.\fIntentaba hacer\ntrampas usando\vmis POKéMON…",
  ["46:4329"] = "¡Caray…!",
  ["46:4334"] = "Supongo que\ndebería actuar\vhonradamente…",
  ["46:4362"] = "¿Tienes en cuenta\nlos tipos durante\vel combate?\fSi conoces bien\nlos distintos\ftipos, rendirás\nmás en combate.",
  ["46:43cb"] = "¡Oo, oo, oo!",
  ["46:43d8"] = "Conozco mis tipos\nde POKéMON.\fPero sólo uso un\ntipo de POKéMON.",
  ["46:441a"] = "¡Les corté el pelo\na mis POKéMON!\f¡Ahora verás lo\nfuertes que son!",
  ["46:4458"] = "¡Ayyyy!",
  ["46:4462"] = "Los POKéMON serán\nmás amigos tuyos\fsi los llevas a\ncortar el pelo.",
  ["46:449b"] = "Creo que tienes\nalgunos POKéMON\vmuy raros.\f¡Déjame verlos!",
  ["46:44d7"] = "¡Bah! ¡He perdido!\n¡Qué rabia me da!",
  ["46:44f9"] = "¿Tienes una\nPOKéDEX? Pues te\vdaré una pista.\fEl MONTAÑERO de\nla RUTA 33, LUIS,\ves un buen chico.\fTe telefoneará\nsi ve algún\vPOKéMON raro.",
  ["46:457a"] = "Puerta cerrada…",
  ["46:458d"] = "Puerta abierta.",
  ["46:45a0"] = "Puerta abierta con\nLLAVE del SÓTANO.",
  ["46:45c3"] = "¡Hola! ¡Yo dirijo\fla PELUQUERÍA\nPOKéMON!\fSoy el mayor y\nel mejor de los\fdos HERMANOS\nPELUQUEROS.\fPuedo poner guapos\na tus POKéMON por\vsólo 500¥.\f¿Quieres que les\ncorte el pelo?",
  ["46:4664"] = "¿A qué POKéMON\nle corto el pelo?",
  ["46:4682"] = "¡Vale! ¡Verás lo\nbien que queda!",
  ["46:46a2"] = "¡Bien! ¡Ya está!",
  ["46:46b4"] = "¿De verdad?\n¡Qué vergüenza!",
  ["46:46d3"] = "Necesitarás más\ndinero.",
  ["46:46f5"] = "Sólo corto el pelo\nuna vez al día.\vYa vale por hoy.",
  ["46:4726"] = "¡Bienvenido a la\nPELUQUERÍA!\fSoy el más joven y\nel más novato de\flos dos HERMANOS\nPELUQUEROS.\fPondré guapos a\ntus POKéMON por\vsólo 300¥.\f¿Qué dices?",
  ["46:47bb"] = "¿A qué POKéMON\nle corto el pelo?",
  ["46:47d8"] = "¡Vale! Ya verás lo\nbien que queda.",
  ["46:47f4"] = "¡Muy bien!\n¡Ya está!",
  ["46:480c"] = "¿No?\n¡Qué lástima!",
  ["46:4825"] = "No te queda\nmucho dinero.",
  ["46:4845"] = "Sólo corto el pelo\nuna vez al día.\fPerdona, pero hoy\nno trabajo más.",
  ["46:4889"] = "{STRBUF}\nparece un poco\vmás feliz.",
  ["46:48a6"] = "{STRBUF}\nparece feliz.",
  ["46:48b8"] = "¡{STRBUF}\nestá encantado!",
  ["46:48ce"] = "Lo siento,\nhemos cerrado.",
  ["46:48e4"] = "PROHIBIDO PASAR\nDE ESTE PUNTO",
  ["46:4e67"] = "¡Alto ahí!\fTe he visto y te\nhe seguido.\fNo quiero verte\ncerca mientras\fme ocupo del TEAM\nROCKET.\fEspera un segundo.\nMe venciste antes,\v¿verdad?\f¡Tuviste mucha\nsuerte!\f¡Pero yo pago\nmis deudas!",
  ["46:4f27"] = "¿Por qué? ¿Cómo\nhe podido perder?\fHe usado a mis\nmejores POKéMON.\fNo he bajado la\nguardia.\f¿Cómo he perdido?",
  ["46:4f8c"] = "No lo\nentiendo…\f¿Es verdad lo que\ndijo ese LANCE?\f¿Qué no cuido bien\na mis POKéMON?\fAmor…\fConfianza…\f¿Es eso lo que\nme falta?\f¿Es eso lo que me\nimpide ganar?\fYo… No lo\nentiendo.\fPero esto no\nacaba aquí.\fAhora no. No por\nesta razón.\f¡No renunciaré a\nmi sueño de ser el\fmejor entrenador\nPOKéMON del mundo!",
  ["46:50cc"] = "¡Bah! ¡Mira\nqué fuerte soy!\fDestruiré al\nTEAM ROCKET.\fY machacaré a\nese tal LANCE.",
  ["46:5140"] = "Me desafiaron a\nun combate en el\vpiso de abajo.\fAhí abajo son muy\nduros. Mejor que\vtengas cuidado.",
  ["46:519a"] = "Abajo hay algunas\ntiendas…\fPero también hay\nentrenadores.\fMe da miedo\nbajar ahí.",
  ["46:51f5"] = "Una puerta se abre\ny otra se cierra.\f¡Seguro que no\nconsigues llegar!",
  ["46:5239"] = "¡Caramba! ¡Perdí\npor mi indecisión!",
  ["46:525a"] = "Tampoco lo sé…\nPrimero hay que\fpulsar el último\nbotón, pero…",
  ["46:52a2"] = "¡Ajajaja!\f¿Confundido con\ntanta llave?\f¡Te contaré un\nsecreto si logras\vvencerme!",
  ["46:52ff"] = "¡Ohhh…!\nFallé.",
  ["46:5311"] = "Bien. ¡Una pista!\fCambia el orden al\npulsar botones.\fY cambiará la\nforma en que se\fabren y se cierran\nlas puertas.",
  ["46:5378"] = "¡Paga tus\ndeudas!",
  ["46:5391"] = "¡Misericordia!",
  ["46:5399"] = "¡Robar y vender!\n¡La base de todo\vacto criminal!",
  ["46:53c5"] = "Abandonaron este\nproyecto antes\vde terminarlo.\fEstoy buscando\nrestos.",
  ["46:5416"] = "¡Por encima!",
  ["46:5425"] = "¿Al ALMACÉN\nSUBTERRÁNEO?\f¿Para qué quieres\nir ahí?\fAhí abajo no\nhay nada.",
  ["46:547c"] = "¡Qué me importa si\nte has perdido!\fApareciste aquí,\n¡eres sólo una\vvíctima!",
  ["46:54c6"] = "¡Seguro! Te crees\ngenial, ¿verdad?",
  ["46:54e9"] = "Debes de tener\nhielo en las venas\fpara enfrentarte\nal TEAM ROCKET.",
  ["46:551e"] = "Viene marcado\ncomo BOTÓN 1.",
  ["46:5535"] = "¿Estás perdido?\nNo, es imposible.\fNo pareces\nasustado.\f¡Te daré algo\nque te\vasustará!",
  ["46:55a0"] = "¿Cómo ha sido?",
  ["46:55b0"] = "¡Ve a donde\nquieras! ¡Lárgate!\v¡No me importa!",
  ["46:55e1"] = "Está APAGADO.\n¿ENCENDERLO?",
  ["46:55f7"] = "Está ENCENDIDO.\n¿APAGARLO?",
  ["46:560d"] = "Viene marcado\ncomo BOTÓN 2.",
  ["46:5624"] = "Viene marcado\ncomo BOTÓN 3.",
  ["46:563b"] = "Viene marcado\ncomo EMERGENCIA.",
  ["46:5795"] = "¡Eh, chico! ¡Estás\ninterrumpiéndonos!\f¡Tenemos por\ncostumbre trabajar\fsin que nadie\nnos vea!",
  ["46:57f7"] = "Pierdo las ganas\nde trabajar si hay\valguien mirando.\f¡Venga, chaval,\nfuera de aquí!",
  ["46:5840"] = "¡Oohah! ¡Oohah!\fHay cosas tiradas\npor el suelo.\f¡Recógelas si\nquieres!",
  ["46:5886"] = "MACHOKE: ¡Machok!",
  ["46:59b3"] = "¿Cómo has llegado\nhasta aquí?\fSupongo que no\npudieron evitarlo.\v¡Acabaré contigo!",
  ["46:59fd"] = "Acabó conmigo…",
  ["46:5a11"] = "El TEAM ROCKET\nseguirá esperando\fel regreso de\nGIOVANNI.\fHaremos lo que\nsea necesario.",
  ["46:5a70"] = "¡No vas a ir\nmás lejos!\f¡Soy implacable\ncon mis enemigos\fy con cualquier\nmocoso!",
  ["46:5abf"] = "¡Maldición!",
  ["46:5aca"] = "He perdido…\f¡Perdóname,\nGIOVANNI!",
  ["46:5af0"] = "¡Ji, ji, ji!\n¡Te recuerdo!\f¡Me diste bien\nen la guarida!",
  ["46:5b34"] = "¡Ji, ji, ji!\n¿Así funcionas?",
  ["46:5b57"] = "¡Ji, ji, ji!\n¡Vaya combate!\v¡No te olvidaré!",
  ["46:5b8f"] = "DIRECTOR: ¿Quién?\n¿Qué? ¿Has venido\va rescatarme?\f¡Gracias!\fLa TORRE de RADIO.\f¿Qué está pasando\nahí dentro?\f¿Invadida por el\nTEAM ROCKET?\fMira. Toma esta\nLLAVE MAGNÉTICA.",
  ["46:5c24"] = "DIRECTOR: Úsala\npara abrir las\vpuertas de la P2.",
  ["46:5c56"] = "Te ruego que\nme ayudes.\f¡Quién sabe lo\nque harían si se\fapoderaran de la\nemisora!\f¡Podrían hasta\ncontrolar a los\fPOKéMON usando una\nseñal especial!\fSólo tú puedes\nayudarme.\fSalva la TORRE\nde RADIO…\f¡Y a todos los\nPOKéMON del mundo!",
  ["46:5f3d"] = "¡Hola!\f¡Soy el REY\ndel KARATE!\f¡Me entreno solo\nen la oscuridad!\f¡Tú!\n¡Lucha conmigo!\f¡Uaaarggh!",
  ["46:5f99"] = "¡Aaaargg!\n¡He perdido!",
  ["46:5fb0"] = "He… perdido…\fTendré que seguir\nentrenándome…\fPero una derrota\nes una derrota.\fComo prueba de tu\nvictoria, te voy\fa dar un raro\nPOKéMON de lucha.",
  ["46:6045"] = "{PLAYER} recibió\na TYROGUE.",
  ["46:605a"] = "TYROGUE es del\ntipo lucha.\fEvoluciona en\nun POKéMON\vmás fuerte.\fSigue así.\nYo también seguiré\ventrenándome.\f¡Adiós!",
  ["46:60cf"] = "¡No tienes sitio\nen tu equipo!",
  ["46:61cc"] = "La piedra cayó\npor el agujero.",
  ["46:6267"] = "Está empotrado\nen el hielo.",
  ["47:41c8"] = "¡Gyaaas!",
  ["47:4292"] = "…\n…",
  ["47:4297"] = "…",
  ["47:429a"] = "…\n…",
  ["47:438b"] = "¡Uauu! ¡Me has\nasustado!\fTenía puestas las\nGAFAS DE SOL y\fno me di cuenta\nde tu presencia.\f¿Que qué estoy\nhaciendo aquí?\fNo te preocupes\npor eso.\fTe daré unas GAFAS\nDE SOL si olvidas\fque me has\nvisto, ¿vale?",
  ["47:4458"] = "Las GAFAS DE SOL\naumentan el poder\fde los movimientos\nde tipo siniestro.",
  ["47:459c"] = "DÉBORA: Muy bien.\nReconozco tu\fverdadero poder.\nToma esta MEDALLA.",
  ["47:45e1"] = "{PLAYER} recibió\nla MEDALLA DRAGÓN.",
  ["47:45fa"] = "La MEDALLA DRAGÓN\npermitirá que tus\fPOKéMON usen el\nmovimiento para\vsubir cascadas.\fY los POKéMON\nte reconocerán\fcomo entrenador y\nobedecerán todas\ftus órdenes sin\nrechistar.\fAdemás, te voy\na dar esta MT.",
  ["47:46d6"] = "Esta MT contiene\nDRAGOALIENTO.\fNo, no tiene\nnada que ver\vcon mi aliento.\fSi no la quieres,\nno es necesario\vque la aceptes.",
  ["47:4754"] = "Así que has\nconseguido todas\vlas MEDALLAS.\fAhora debes\ndirigirte a la\fLIGA POKéMON\nde MESETA AÑIL.\f¿Sabes cómo llegar\nhasta allí?\fDesde aquí, ve a\nPUEBLO PRIMAVERA.\fLuego haz SURF\nhacia el Este.\vNo será fácil.\f¡Ni se te ocurra\nperder en la LIGA\vPOKéMON!\fSi pierdes, ¡me\nsentiré aún peor\fpor haber perdido\ncontra ti!",
  ["47:4881"] = "SANTUARIO DRAGÓN\fErigido en honor\nde los POKéMON\fdragón de la\nGUARIDA DRAGÓN",
  ["47:48d6"] = "…\n¿Qué? ¿{PLAYER}?\fNo, no lucharé\ncontra ti…\fMis POKéMON no\npueden ganarte.\fY ahora no puedo\npresionarles.\fLa disciplina es\nclave para ser el\fmejor entrenador\nPOKéMON.",
  ["47:4980"] = "…\f¡Vaya…!\fAprende a no\ncruzarte en\vmi camino.",
  ["47:49a6"] = "¡{PLAYER} encontró\n{STRBUF}!",
  ["47:49b8"] = "Pero {PLAYER} no\npuede llevar\vmás cosas.",
  ["48:4101"] = "¡Uau! ¡Tu POKéGEAR\nes impresionante!\f¿Te la ha dado\ntu madre?",
  ["48:413e"] = "¡Espera, {PLAYER}!",
  ["48:4148"] = "¿Qué crees que\nestás haciendo?",
  ["48:4168"] = "¡Es peligroso\nsalir sin\vun POKéMON!\fDe camino hacia la\nsiguiente ciudad\fte encontrarás\nPOKéMON salvajes.",
  ["48:41ce"] = "¡Oh, tu POKéMON es\nadorable! ¡Ojalá\vtuviera yo uno!",
  ["48:41fc"] = "¡Hola, {PLAYER}!\n¿Te vas otra vez?\fDeberías decirle\na tu madre que\vte vas.",
  ["48:4240"] = "Llama a tu madre\ncon la POKéGEAR\fy cuéntale cómo\nte va.",
  ["48:427e"] = "¡Hola, {PLAYER}!\fDicen que el PROF.\nELM ha descubierto\vnuevos POKéMON.",
  ["48:42b0"] = "……\fAsí que éste es el\nfamoso LABORATORIO\vPOKéMON de ELM…",
  ["48:42d7"] = "¿Qué estás\nmirando?",
  ["48:42f2"] = "PUEBLO PRIMAVERA\fEl pueblo donde\nsoplan vientos de\vun nuevo amanecer",
  ["48:4332"] = "CASA DE {PLAYER}",
  ["48:433c"] = "LABORATORIO DE ELM",
  ["48:434a"] = "CASA DE ELM",
  ["48:45ae"] = "Eres un entrenador\nnovato, ¿verdad?\v¡Estoy seguro!\f¡Está bien! ¡Todo\nel mundo es novato\valguna vez!\fSi quieres, te\npuedo enseñar\valgunas cosas.",
  ["48:463a"] = "¡De acuerdo!\n¡Sígueme!",
  ["48:4650"] = "Esto es un\nCENTRO POKéMON.\fAquí curan a\ntus POKéMON.\fVas a necesitar\nmucho de ellos,\fasí que mejor\nconocerlos.",
  ["48:46cf"] = "Esto es una TIENDA\nPOKéMON.\fHay POKé BALL para\ncapturar POKéMON\fsalvajes y otras\nmuchas cosas.",
  ["48:4724"] = "La RUTA 30 está\npor aquí.\fEn ella luchan\nlos entrenadores\fcon sus queridos\nPOKéMON.",
  ["48:4772"] = "Como puedes ver,\nesto es el mar.\fAlgunos POKéMON\nsólo viven en\vel agua.",
  ["48:47b7"] = "Y…\f¡Ésta es mi casa!\nGracias por\vacompañarme.\fDéjame darte\nun regalito.",
  ["48:4803"] = "¡Ahora el POKéGEAR\nde {PLAYER}\vtiene un MAPA!",
  ["48:481c"] = "El POKéGEAR será\nmás útil cuando\vañadas TARJETAS.\f¡Mucha suerte\nen tu aventura!",
  ["48:486a"] = "¡Oh…! Me\ngusta hacerlo…\fVale. Ven a verme\ncuando quieras.",
  ["48:48ad"] = "¿Qué…?\f¿Te han dado\nun POKéMON\ven el LABORATORIO?\f¡Qué desperdicio!\n¡Eres tan inútil!\f…\f¿No entiendes\nlo que digo?\fPues yo también\ntengo un buen\fPOKéMON. ¡Te\nlo demostraré!",
  ["48:4942"] = "¿Estás contento\nde haber ganado?",
  ["48:4961"] = "…\f¿Mi nombre?\fVoy a ser el\nmejor entrenador\fPOKéMON del\nmundo.",
  ["48:49a5"] = "¡Vaya pérdida\nde tiempo!",
  ["48:49c7"] = "…\f¿Mi nombre?\fVoy a ser el\nmejor entrenador\fPOKéMON del\nmundo.",
  ["48:4a0b"] = "¿Has hablado con\nel anciano que\festá cerca del\nCENTRO POKéMON?\fTe dará un MAPA\nde JOHTO para tu\vPOKéGEAR.",
  ["48:4a63"] = "Cuando vas con los\nPOKéMON, cualquier\vsitio está bien.",
  ["48:4a91"] = "La casa del SR.\nPOKéMON está\vmás adelante.",
  ["48:4abc"] = "He luchado contra\nlos entrenadores\vdel camino.\fMis POKéMON han\nperdido. ¡Están\ffatal! Los llevaré\nal CENTRO POKéMON.",
  ["48:4b21"] = "Atrapé un POKéMON\ncon un objeto.\fCreo que es\nAGUA MÍSTICA.\fNo lo necesito,\n¿lo quieres?",
  ["48:4b7c"] = "Pues yo me\nvoy a pescar.",
  ["48:4b9b"] = "CIUDAD CEREZO\fLa ciudad de las\nflores bonitas y\vfragantes",
  ["48:4bd0"] = "CASA DEL GUÍA",
  ["48:4d29"] = "¡Hola! ¿Eres un\nentrenador? ¿Has\fganado al LÍDER\ndel GIMNASIO?",
  ["48:4d62"] = "¡Oh la la!\n¡Muy bien!",
  ["48:4d81"] = "¿Es verdad? ¡Pues\ntú estudiarás!\v¡Sígueme!",
  ["48:4daf"] = "El profesor soy\nyo. ¡Bien está\vque aquí estudies!",
  ["48:4ddf"] = "Dicen que en la\nTORRE BELLSPROUT\vhay fantasmas.\fY dicen que los\nPOKéMON normales\fno afectan\na los fantasmas.",
  ["48:4e49"] = "¿Eres entrenador\nPOKéMON?\f¡Si ganas a este\nLÍDER de GIMNASIO,\festarás en el\ncamino del éxito!",
  ["48:4ea5"] = "¡PEGASO, del\nGIMNASIO POKéMON\fde CIUDAD MALVA,\nes magnífico!\fHeredó el\ngimnasio de su\fpadre y ha hecho\nun gran trabajo.",
  ["48:4f1b"] = "¡He visto un árbol\nque se mueve!\f¡Si lo tocas,\nse retuerce y\vbaila! ¡Es genial!",
  ["48:4f68"] = "CIUDAD MALVA\fLa ciudad de los\naromas nostálgicos",
  ["48:4f92"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\vMALVA: PEGASO\fEl elegante\nmaestro de los\vPOKéMON voladores",
  ["48:4fda"] = "TORRE BELLSPROUT\fVive la vida\nPOKéMON",
  ["48:5003"] = "ACADEMIA POKéMON\nDE PRIMO",
  ["48:51e7"] = "Dime una\ncosa…\f¿Es cierto que\nel TEAM ROCKET\vha vuelto?\f¿Qué? ¿Los has\nderrotado? ¡Anda!\v¡No me mientas!\f¿Bromeas?\nPues a ver lo\vbueno que eres.",
  ["48:5280"] = "¡Vaya!\n¡Inútiles POKéMON!\f¡Escúchame! ¡Has\nganado porque\fmis POKéMON\neran débiles!",
  ["48:52cd"] = "Odio a los\ndébiles.\fYa sean POKéMON\no entrenadores. Da\vigual quién o qué.\fSeré fuerte\ny acabaré con los\venclenques.\fEso también va por\nel TEAM ROCKET.\fSon fuertes cuando\nestán en grupo,\fpero si están\nsolos, son unos\vcobardes.\f¡Cuánto les odio!\f¡Fuera de mi\nvista! ¡Eres tan\finsignificante\ncomo el resto!",
  ["48:53f5"] = "¡Ja! Sabía\nque mentías.",
  ["48:5415"] = "Entrar ahí es muy\npeligroso, por eso\vestoy de guardia.\f¿A que soy un\nbuen samaritano?",
  ["48:5461"] = "¿Sabes algo sobre\nlas COLASLOWPOKE?\f¡Dicen que son\nmuy sabrosas!\f¿Contento de que\nte lo haya dicho?",
  ["48:54b5"] = "Los SLOWPOKE han\ndesaparecido del\vpueblo…\fDicen que venden\nsus COLAS en algún\vlugar.",
  ["48:550d"] = "Los SLOWPOKE\nhan vuelto.\fConociéndolos,\nquizá han estado\fremoloneando en\nalgún lugar.",
  ["48:5568"] = "¿Viste a CÉSAR\npara que te diera\valgunas BALL?\fMuchas personas\nlo hacen.",
  ["48:55b4"] = "Ataja por PUEBLO\nAZALEA y llegarás\val ENCINAR.\fPero estos\narbolitos te\vimpiden pasar.\fLos POKéMON del\nCARBONERO pueden\vCORTAR árboles.",
  ["48:564a"] = "SLOWPOKE: …\f…… …… ……",
  ["48:565d"] = "(bostezo)……",
  ["48:5679"] = "PUEBLO AZALEA\nDonde la gente y\flos POKéMON viven\nen feliz armonía",
  ["48:56b2"] = "CASA DE CÉSAR",
  ["48:56c0"] = "LÍDER DEL GIMNASIO\nPOKéMON DE PUEBLO\vAZALEA: ANTÓN\fLa enciclopedia\nandante de los\vPOKéMON bicho",
  ["48:5706"] = "POZO SLOWPOKE\fConocido también\ncomo POZO LLUVIA.\fLos nativos creen\nque el bostezo de\fSLOWPOKE invoca\nla lluvia.\fHace 400 años\nun bostezo de\fSLOWPOKE acabó\ncon una sequía.",
  ["48:57ac"] = "CASA DEL CARBONERO",
  ["48:57bb"] = "EL ENCINAR\fEntra por la\npuerta",
  ["48:5936"] = "¿Has cruzado el\nmar para llegar\fhasta aquí? ¡Habrá\nsido duro!\fTodo sería mucho\nmás fácil si tus\fPOKéMON supieran\nVUELO…",
  ["48:59a8"] = "Pero no puedes\nusar VUELO sin la\fMEDALLA de esta\nciudad.\fSi vences al LÍDER\nde este GIMNASIO,\vven a verme.\fTe daré un\nbonito regalo.",
  ["48:5a28"] = "¡Es la MEDALLA de\nCIUDAD ORQUÍDEA!\f¡Toma esta\nMO!",
  ["48:5a62"] = "Enseña VUELO a\ntus POKéMON.\fEn un instante\npodrás VOLAR a\fcualquier lugar al\nque ya hayas ido.",
  ["48:5abc"] = "Mi marido perdió\ncontra ti. Debería\ventrenarse más.\fMenos mal, porque\nya estaba\vengordando.",
  ["48:5b24"] = "Si usas VUELO,\npodrás volver a\fCIUDAD OLIVO\nenseguida.",
  ["48:5b5e"] = "Las piedras del\nnorte del pueblo\vse pueden romper.\fQuizá escondan\nalgo.\fTus POKéMON pueden\nusar el GOLPE ROCA\vpara romperlas.",
  ["48:5bd9"] = "ANÍBAL, el LÍDER\ndel GIMNASIO,\fpelea con sus\nPOKéMON de lucha.",
  ["48:5c78"] = "CIUDAD ORQUÍDEA\fUn puerto rodeado\nde agitadas aguas",
  ["48:5ca7"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\fORQUÍDEA: ANÍBAL\fSus puños\nhablan por él",
  ["48:5cee"] = "500 años de\ntradición\fFARMACIA DE\nCIUDAD ORQUÍDEA\fAceptamos\npedidos",
  ["48:5d3d"] = "ESTUD. FOTOGRÁFICO\nDE CIUDAD ORQUÍDEA\f¡Hazte una foto\nde recuerdo!",
  ["48:5ec6"] = "Han construido una\nTORRE RADIO nueva\fque sustituye a\nla antigua.",
  ["48:5f06"] = "Sé que hay una\nnueva TIENDA de\fBICIS, pero no\nla encuentro.",
  ["48:5f43"] = "¿Ese hombre de\nnegro se ha\fvestido como uno\ndel TEAM ROCKET?\v¡Qué tonto!",
  ["48:5f8a"] = "¿Pertenecía ese\nhombre de negro\fal TEAM ROCKET?\n¡Es increíble!",
  ["48:5fd0"] = "La TORRE de RADIO\nde CIUDAD TRIGAL\ves muy importante.\fAhora están en\nuna campaña\vpromocional.\fModificarán tu\nPOKéGEAR para\fque te sirva\ntambién de radio.",
  ["48:6071"] = "¡Oh, tu POKéGEAR\nsirve de radio!",
  ["48:6093"] = "¡Eh, eh, eh…!\fMe he metido en\nlíos por jugar en\fel sótano del\nCENTRO COMERCIAL.",
  ["48:60e0"] = "El hombre de esa\ncasa evalúa los\fnombres de\ntus POKéMON.\fY puede renombrar\na tus POKéMON.",
  ["48:612c"] = "¡Uau! Esta ciudad\nes muy grande.\fNo sé dónde\nestá nada.",
  ["48:616a"] = "Así que ésta es la\nTORRE de RADIO…",
  ["48:6187"] = "¿Qué quieres,\npesado? ¡Fuera!",
  ["48:61ab"] = "¡Fuera de mi\ncamino! ¡Pesado!",
  ["48:61ca"] = "Asaltemos la\nTORRE de RADIO…\f¿Qué? ¡Y a ti\nqué te importa!",
  ["48:6207"] = "¿Los POKéMON?\n¡Sólo son\fherramientas para\nganar dinero!",
  ["48:623f"] = "Nuestro sueño se\ncumplirá pronto…\fHa sido una lucha\ntan larga…",
  ["48:627c"] = "¡Eh, mocoso! ¡Tú\nno eres de aquí!\v¡Lárgate!",
  ["48:62a8"] = "¡Prueba el\nverdadero terror\vdel TEAM ROCKET!",
  ["48:62d4"] = "ESTACIÓN DE\nCIUDAD TRIGAL",
  ["48:62ec"] = "TORRE DE RADIO\nDE CIUDAD TRIGAL",
  ["48:6308"] = "¡Una gran gama de\nartículos POKéMON!\fCENTRO COMERCIAL\nDE CIUDAD TRIGAL",
  ["48:6341"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\vTRIGAL: BLANCA\f¡La increíble y\nbella señorita!",
  ["48:6386"] = "CIUDAD TRIGAL\fLa alegre ciudad\nde rico encanto",
  ["48:63b8"] = "¡El mundo es un\ncamino de bicis!\vTIENDA DE BICIS",
  ["48:63de"] = "¡Tu zona de juego!\fCASINO DE\nCIUDAD TRIGAL",
  ["48:640b"] = "INSPECTOR DE MOTES\fEvalúa los motes\nde tus POKéMON",
  ["48:6435"] = "ENTRADA\nSUBTERRÁNEA",
  ["48:644b"] = "ENTRADA\nSUBTERRÁNEA",
  ["49:40d7"] = "…\f¿Tú otra vez?\f¿Y a mí qué me\nimporta? No me\fasustan los\ncanijos como tú.\fY hablando de\ndebiluchos, la\fLÍDER del GIMNASIO\nno está aquí.\fSe supone que está\ncuidando a un\fPOKéMON enfermo\nen el FARO.\f¡Buuuu! ¡Fuera\nlos POKéMON\venfermos!\f¡Los POKéMON que\nno pueden luchar\vson unos inútiles!\f¿Por qué no vas\na entrenar al\vFARO?\f¿Quién sabe?\n¡A lo mejor\vte refuerza!",
  ["49:4235"] = "Las calles oscuras\nson muy peligrosas\vpor la noche.\fPero si es noche\ncerrada, ¡el mar\fes aún más\ntraicionero!\fSi no les guiara\nla luz del FARO,\flos barcos no\npodrían navegar.",
  ["49:42e1"] = "Eso que tienes\nes un POKéGEAR,\f¿verdad? ¡Uauu!\n¡Es genial!",
  ["49:431e"] = "¡Uauu, tienes una\nPOKéDEX! Es\frealmente\nincreíble.",
  ["49:434e"] = "¡Hola, chaval!\n¡Me gusta el mar!\f¡Canta conmigo!\n¡Yo jo!\v¡Yo jo…!",
  ["49:439a"] = "CIUDAD OLIVO\fEl puerto a\ntierras lejanas",
  ["49:43ca"] = "PUERTO OLIVO\nMUELLE DEL FERRY",
  ["49:43e7"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\vOLIVO: YASMINA\fLa chica\nde acero",
  ["49:442a"] = "FARO DE OLIVO\nTambién conocido\fcomo el FARO\nBRILLANTE.",
  ["49:4604"] = "En CIUDAD IRIS\nhabía dos torres:\funa en el Este y\notra en el Oeste.",
  ["49:4646"] = "¡Ah, chaval!\n¿Has aprendido a\fbailar como las\nCHICAS KIMONO?\fSi vas a su\nTEATRO de DANZA,\fun anciano raro te\ndará algo bonito.\vEso me han dicho.",
  ["49:46de"] = "Voy a practicar en\nel TEATRO de\fDANZA. ¿Vienes\nconmigo?",
  ["49:471d"] = "Esa torre era\nmucho más alta,\fpero se quemó\nen un incendio.",
  ["49:4761"] = "Tres POKéMON\nhuyeron en tres\fdirecciones.\n¿Qué eran?",
  ["49:47a4"] = "He oído un rumor\nsobre el FARO\vOLIVO.\fEl POKéMON que\nusan como luz\fha caído enfermo.\nParece que tienen\vproblemas.",
  ["49:481d"] = "El POKéMON de\nFARO OLIVO se\vha curado.\fLos barcos pueden\nvolver a navegar\vseguros de noche.",
  ["49:487e"] = "Los POKéMON están\ncausando estragos\fen el LAGO DE\nLA FURIA. Me\vencantaría verlo.",
  ["49:48c3"] = "CIUDAD IRIS\nUna ciudad donde\fconviven el pasado\ny el presente",
  ["49:4905"] = "TORRE HOJALATA\fAquí duerme un\nPOKéMON\vlegendario.",
  ["49:493a"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\vIRIS: MORTI\fEl místico adivino\ndel futuro",
  ["49:497e"] = "TEATRO DE DANZA\nDE CIUDAD IRIS",
  ["49:4996"] = "TORRE QUEMADA\fDestruida por\nun misterioso\vincendio.\f¡Atención!\n¡Peligro!",
  ["49:4b65"] = "¡Hola, hijito! Ya\nveo que eres nuevo\ven PUEBLO CAOBA.\f¡Ya que eres nuevo\ndeberías probar\fel delicioso\nCARAMELO FURIA!\f¡Puede ser tuyo\npor sólo 300¥!\v¿Quieres uno?",
  ["49:4c03"] = "¡Bien! ¡Saboréalo!",
  ["49:4c14"] = "No tienes\nbastante dinero.",
  ["49:4c31"] = "¡Oh, de acuerdo…!",
  ["49:4c41"] = "No tienes\nespacio para esto.",
  ["49:4c5f"] = "CARAMELOS FURIA\nagotados.\fEstoy haciendo las\nmaletas. No me\vmolestes, hijito.",
  ["49:4ca2"] = "¿Vas al LAGO a ver\na los violentos\vGYARADOS?",
  ["49:4cda"] = "MAGIKARP ha\nvuelto al LAGO\vDE LA FURIA.\fSon buenas\nnoticias para\vlos pescadores.",
  ["49:4d33"] = "Has venido de muy\nlejos. Tómate\ftiempo para ver\nel paisaje.\fDeberías ir hacia\nel Norte y ver lo\fque pasa en el\nLAGO DE LA FURIA.",
  ["49:4daf"] = "Visita la tienda\nde la Abuela. Hay\fcosas que sólo\nella tiene.",
  ["49:4deb"] = "PUEBLO CAOBA\fBienvenido al\nhogar de los Ninja",
  ["49:4e1b"] = "¡Si visitas PUEBLO\nCAOBA, prueba\vun CARAMELO FURIA!",
  ["49:4e4e"] = "LÍDER DEL GIMNASIO\nPOKéMON DE PUEBLO\vCAOBA: FREDO\fEl maestro del\ncrudo invierno",
  ["49:5063"] = "Este LAGO\nestá lleno de\vGYARADOS…\fAsí que los\nMAGIKARP\fdeben haber\nevolucionado.",
  ["49:50c0"] = "¿Has venido hasta\naquí por los\vrumores?\f¿Eres {PLAYER}?\nYo soy LANCE, un\ventrenador más.\fHe oído rumores\ny he venido a\vinvestigar…\fTe he visto\nluchar, {PLAYER}.\fCreo que como\nentrenador eres\vmuy bueno.\fSi no te importa,\n¿quieres ayudarme\va investigar?",
  ["49:51d2"] = "LANCE: ¡Excelente!\fParece que los\nMAGIKARP del LAGO\fse ven obligados a\nevolucionar.\fLa razón es una\nmisteriosa emisión\fde radio desde\nPUEBLO CAOBA.\fTe esperaré\nallí, {PLAYER}.",
  ["49:527d"] = "¡Oh…! Si\ncambias de opinión\fagradecería tu\nayuda.",
  ["49:52b1"] = "LANCE: ¿Qué?\n¿Me vas a ayudar?",
  ["49:52d7"] = "GYARADOS: ¡Gyaraa!",
  ["49:52eb"] = "{PLAYER} obtuvo\nuna ESCAMA ROJA.",
  ["49:5304"] = "¡Los GYARADOS\nestán enfadados!\f¡Mal presagio!",
  ["49:532d"] = "¡Ajaa! ¡Los\nMAGIKARP pican!",
  ["49:5350"] = "Dicen que este\nlago fue obra\fde violentos\nGYARADOS.\fMe pregunto si eso\nestará relacionado\fcon su actual\nrebelión.",
  ["49:53c7"] = "¿Me han engañado\nmis ojos? He visto\fun GYARADOS rojo\nen el LAGO…\fYo pensaba que\nlos GYARADOS eran\vsiempre azules.",
  ["49:542e"] = "¡Déjame luchar con\nel POKéMON que\vacabo de atrapar!",
  ["49:545a"] = "Puede que sea un\npescador experto,\fpero soy un mal\nentrenador…",
  ["49:549b"] = "¡No perderé como\npescador! Me paso\fel día capturando\nPOKéMON.",
  ["49:54cc"] = "Haga lo que haga,\nsiempre capturo\flos mismos\nPOKéMON…",
  ["49:5503"] = "Mi caña se ha\nenredado…",
  ["49:551d"] = "¿Por qué no atrapo\nbuenos POKéMON?",
  ["49:553e"] = "Si un entrenador\nse encuentra con\fotro entrenador,\ndebe desafiarle.\fÉse es nuestro\ndestino.",
  ["49:5594"] = "¡Uauu…!\nBuen combate.",
  ["49:55a8"] = "Los POKéMON y su\nentrenador se\fhacen más fuertes\ncuanto más luchan.",
  ["49:55eb"] = "¿Qué ocurrió con\nel GYARADOS rojo?\f¿Se ha ido?\f¡Maldición! ¿He\nvenido para nada?\fYa sé.\n¡Luchemos!",
  ["49:5651"] = "¡Muy bien!",
  ["49:565e"] = "Pensándolo bien,\ncreo que vi un\vBUTTERFREE rosa.",
  ["49:5690"] = "MIGUEL: Hola,\n¿qué tal estás?\fHoy es miércoles\ny yo soy MIGUEL,\fpor lo de\nmiércoles.",
  ["49:56e9"] = "Encantado de\nconocerte. Toma\vun recuerdo.",
  ["49:5717"] = "MIGUEL: CINTURÓN\nNEGRO potencia los\vataques de lucha.",
  ["49:5750"] = "MIGUEL: Como me\nhas encontrado,\fhabrás visto a\nmis hermanos.\f¿O es que has\ntenido suerte?",
  ["49:57b5"] = "MIGUEL: Hoy no\nes miércoles.\v¡Qué pena!",
  ["49:57e3"] = "LAGO DE LA FURIA,\nconocido como\vLAGO DE GYARADOS.",
  ["49:580f"] = "CASA DEL GURÚ\nPESCADOR",
  ["49:5994"] = "Lo siento.\fNuestro LÍDER de\nGIMNASIO está\fentrenando en una\ncueva aquí detrás.\fNo tengo ni idea\nde cuándo volverá.",
  ["49:5a01"] = "Te espera el LÍDER\ndel GIMNASIO.\fPero es imposible\nque le gane un\fentrenador del\nmontón.",
  ["49:5a6b"] = "¿Venciste al LÍDER\ndel GIMNASIO? ¡Es\vincreíble!\fCon tu poder,\nseguro que\ftriunfas en la\nLIGA POKéMON.",
  ["49:5ad0"] = "Aquí sólo pueden\nentrenar los que\fusan dragones.\nVete, por favor.",
  ["49:5b0e"] = "DÉBORA, la maestra\nde los dragones,\fda su permiso, así\nque puedes entrar.",
  ["49:5b4e"] = "¿Mi radio está\nrota? Sólo recibo\vesta rara señal.",
  ["49:5b87"] = "¡Auu! ¡Voces en\nmi cabeza! ¿Cómo?\f¡Estoy escuchando\nla radio!",
  ["49:5bc1"] = "¿Quieres que\ntus POKéMON\folviden algún\nmovimiento?",
  ["49:5bf5"] = "Voy a usar\ndragones como\vhace DÉBORA.",
  ["49:5c1f"] = "SABINO: …\fEs sábado…\fSoy SABINO, por\nsábado…",
  ["49:5c4f"] = "Toma esto…",
  ["49:5c63"] = "SABINO: …\fHECHIZO…\fMejora los\nmovimientos de\vtipo fantasma.\fTe voy a\nasustar…",
  ["49:5cae"] = "SABINO: …\fNos vemos otro\nsábado…\fPero ya no tendré\nmás regalos…",
  ["49:5cf8"] = "SABINO: Hoy no\nes sábado…",
  ["49:5d16"] = "¡Uau! ¿Has venido\npor la RUTA\vHELADA?\f¡Debes de ser un\nentrenador genial!",
  ["49:5d5f"] = "CIUDAD ENDRINO\fUn tranquilo\nrefugio de montaña",
  ["49:5d89"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\vENDRINO: DÉBORA\fLa gran experta en\nPOKéMON dragón",
  ["49:5dd1"] = "CASA DEL\nQUITA-MOVIMIENTOS",
  ["49:5de7"] = "HACIA LA GUARIDA\nDEL DRAGÓN",
  ["49:5dfb"] = "PISTAS ENTRENADOR\fTodo POKéMON que\nvaya equipado con\funa BAYA MILAGRO\nse curará a sí\vmismo en combate.",
  ["49:5f27"] = "MT. PLATEADO",
  ["4a:4175"] = "Estoy haciendo\nlos últimos\fpreparativos para\nla LIGA POKéMON.",
  ["4a:41ab"] = "¡Caramba!",
  ["4a:41b7"] = "Va a ser difícil\nganar en la\vLIGA.\fTengo que\nentrenar más.\fDicen que el ALTO\nMANDO es más duro\fque los LÍDERES\nde GIMNASIO.",
  ["4a:4246"] = "Es en estos duros\ncombates donde\vganas más poder.",
  ["4a:4276"] = "¡La vida es\naún más dura!",
  ["4a:4293"] = "Para llegar a la\nLIGA POKéMON,\fhay que pasar por\nla CALLE VICTORIA.\fPero la CALLE\nVICTORIA es dura.\f¡No va allí\ncasi nadie!",
  ["4a:430b"] = "Si has llegado tan\nlejos, debes de\vser muy bueno.\f¡Voy a dar todo\nlo que tengo en\veste combate!",
  ["4a:436c"] = "¡No! ¡No puedo\ncreerlo!",
  ["4a:4386"] = "Como había vencido\na ocho LÍDERES\fde GIMNASIO, me\nconfié demasiado.\fTendré que\nesforzarme más.",
  ["4a:43e5"] = "He perdido contra\n{RIVAL}.\fEra realmente\nfuerte, pero…\fParecía como si\ntuviera que ganar\va toda costa.\fMe dieron pena\nsus POKéMON.",
  ["4a:446e"] = "Los POKéMON no son\narmas de guerra.",
  ["4a:4488"] = "Los POKéMON son\nvaliosos amigos\vpara toda la vida.",
  ["4a:44b3"] = "¡Uau! ¡Cuántas\nMEDALLAS! Estoy\vimpresionado.\fPero no te basta\nsólo con\fcoleccionarlas,\n¿verdad?",
  ["4a:4519"] = "¡Buena batalla!",
  ["4a:4527"] = "Las personas y los\nPOKéMON se\fenriquecen con la\nexperiencia.\fNo seas vago\ny conformista.",
  ["4a:4573"] = "¡Hoy me siento\nmuy bien!\f¡Siento que podría\nvencer hasta al\vCAMPEÓN de LIGA!",
  ["4a:45bc"] = "¡No! ¡En esta\nbatalla, no!",
  ["4a:45d5"] = "Como en la pesca,\ncon los POKéMON\ftodo está perdido\nsi te rindes.",
  ["4a:4613"] = "RUTA 26\fRECEPCIÓN DE LA\nLIGA POKéMON",
  ["4a:486a"] = "¡Eh!",
  ["4a:4870"] = "¿Sabes lo que\nacabas de hacer?\fAcabas de\nentrar en\vKANTO.\fConsulta el MAPA\ndel POKéGEAR.",
  ["4a:48d8"] = "Pareces muy\nfuerte. ¡Déjame\vluchar contigo!",
  ["4a:4904"] = "¡Yau!",
  ["4a:490a"] = "Si continúas por\neste duro camino,\f¡conocerás la\nverdad!\fLo siento, pero me\napetecía decir\valgo chulo.",
  ["4a:497b"] = "¿Mmm? Eres bueno,\n¿verdad?",
  ["4a:4997"] = "¡Tal como pensaba!",
  ["4a:49ab"] = "Un buen entrenador\nsabe reconocer a\fotros buenos\nentrenadores.",
  ["4a:49de"] = "No deberías\nsubestimar a los\fPOKéMON salvajes\nde esta zona.",
  ["4a:4a18"] = "¡Oh! ¡Qué\nfuerte eres!",
  ["4a:4a34"] = "Eres sólo un niño,\npero tampoco\fse te puede\nsubestimar.",
  ["4a:4a72"] = "Es raro que venga\nalguien por aquí.\f¿Te estás\nentrenando solo?",
  ["4a:4ab3"] = "¡Oh! ¡Eres\nmuy fuerte!",
  ["4a:4acd"] = "Estoy investigando\nlos POKéMON antes\fy después de que\nevolucionen.\fLos POKéMON se\nhacen más fuertes\val evolucionar.\fPero aprenderán\nnuevos movimientos\fmucho más despacio\nque antes.",
  ["4a:4b54"] = "¡No digas nada!\fDéjame adivinar lo\nque piensas.\f¡Mmmmmmm…!\f¡Listo! ¡Estás\nen la LIGA\vPOKéMON!",
  ["4a:4bc0"] = "¡Eres demasiado!",
  ["4a:4bd1"] = "Con tus\nhabilidades,\fte irá bien\nen la LIGA.\fEso es lo que\npresiento.",
  ["4a:4c21"] = "¡Pío! ¡Pío!\n¡Píooo!",
  ["4a:4c39"] = "¡Pío!",
  ["4a:4c41"] = "Los ORNITÓLOGOS\nimitan el canto de\flos pájaros para\ncontrolar POKéMON.",
  ["4a:4c7e"] = "CATARATAS TOHJO\fLa conexión entre\nKANTO y JOHTO.",
  ["4a:4d53"] = "RUTA 28",
  ["4a:4ed2"] = "Los POKéMON se\nesconden en la\fhierba. Nadie sabe\ncuando salen…",
  ["4a:4f0a"] = "Te he visto un par\nde veces. ¿Cuántos\fPOKéMON has\natrapado?\f¿Quieres que te\nenseñe a atrapar\vPOKéMON?",
  ["4a:4f78"] = "Así es como\nse hace.\fSi los debilitas,\nlos POKéMON\fson más fáciles\nde atrapar.",
  ["4a:4fc2"] = "¡Ah! ¡Muy bien!\fPero si quieres\natrapar POKéMON,\ftendrás que\ncaminar mucho.",
  ["4a:500e"] = "¿Qué? ¿Quieres que\nte enseñe a\vatrapar POKéMON?",
  ["4a:503f"] = "¿Cómo están tus\nPOKéMON?\fSi están débiles y\nno pueden luchar,\fno entres en\nla hierba.",
  ["4a:5097"] = "¿Ves esos setos?\nDa miedo\vsaltarlos.\fPero puedes ir a\nPUEBLO PRIMAVERA\fsin pasar por\nla hierba.",
  ["4a:5104"] = "Quería descansar\nun poco, así que\fguardé la\npartida.",
  ["4a:5177"] = "Estoy esperando a\nlos POKéMON\fque aparecen sólo\npor la noche.",
  ["4a:51a7"] = "Estoy esperando a\nlos POKéMON\fque aparecen sólo\npor la mañana.",
  ["4a:51dd"] = "MARTA: Creo que\nes la primera\fvez que nos\nvemos.\fDéjame que me\npresente. Soy\fMARTA, por\nmartes.",
  ["4a:525a"] = "Como presentación,\npor favor, toma\feste regalo:\nun LAZO ROSA.",
  ["4a:529a"] = "MARTA: ¿No\ncrees que es\vadorable?\fFortalece los\nataques normales.\fSeguro que te\nserá muy útil.",
  ["4a:5312"] = "MARTA: ¿Has visto\na LUNA, mi hermana\vmayor?\f¿O a mi hermano\npequeño, MIGUEL?\fSoy la segunda de\nsiete hermanos.",
  ["4a:5384"] = "MARTA: Hoy no es\nmartes. ¡Qué\vpena…!",
  ["4a:53b9"] = "RUTA 29\fCIUDAD CEREZO -\nPUEBLO PRIMAVERA",
  ["4a:53e4"] = "RUTA 29\fCIUDAD CEREZO -\nPUEBLO PRIMAVERA",
  ["4a:55ad"] = "¡Ve, RATTATA!\f¡PLACAJE!",
  ["4a:55c3"] = "¿Qué? ¡Es un\ngran combate!\v¡Déjame en paz!",
  ["4a:55f0"] = "Acabo de perder\ny estoy buscando\vmás POKéMON.\f¡Espera! ¡Pareces\ndébil! ¡Venga,\vluchemos!",
  ["4a:5649"] = "¡Vaya! No tengo\nmás POKéMON.",
  ["4a:566a"] = "Necesito tener\nmás POKéMON\vpara luchar.\f¡Voy a atrapar\nunos cuantos más!",
  ["4a:56ae"] = "Eres un entrenador\nPOKéMON, ¿verdad?\f¡Pues entonces\nluchemos!",
  ["4a:56e5"] = "¡Qué extraño!\n¡Creí que ganaría!",
  ["4a:5703"] = "Es muy duro llegar\na ser un buen\ventrenador.\fTengo que luchar\ncontra más gente\vpara mejorar.",
  ["4a:575e"] = "¡En lugar de un\nPOKéMON bicho,\fhe encontrado\nun entrenador!",
  ["4a:5789"] = "¡Arg! ¡Eres\nmuy fuerte!",
  ["4a:57a2"] = "Me quedé sin\nPOKé BALL mientras\vatrapaba POKéMON.\fDebería haber\ncomprado más…",
  ["4a:57f0"] = "¿La casa del SR.\nPOKéMON? Está un\vpoco más adelante.",
  ["4a:581a"] = "¡Todo el mundo se\ndivierte luchando!\f¡Tú también\ndeberías hacerlo!",
  ["4a:584a"] = "No soy una\nentrenadora.\fPero si miras a\nuno a los ojos,\fprepárate\na luchar.",
  ["4a:5891"] = "RUTA 30\fCIUDAD MALVA -\nCIUDAD CEREZO",
  ["4a:58ba"] = "CASA SR. POKéMON\n¡Todo recto!",
  ["4a:58db"] = "CASA SR. POKéMON",
  ["4a:58ec"] = "PISTAS ENTRENADOR\f¡No robes los\nPOKéMON de otros!\f¡Las POKé BALL\nsólo se lanzan a\vPOKéMON salvajes!",
  ["4a:5b1e"] = "CUEVA OSCURA…\fSi los POKéMON\npudieran\filuminarla,\nla exploraría.",
  ["4a:5b54"] = "He atrapado un\nmontón de POKéMON.\v¡Luchemos!",
  ["4a:5b87"] = "¡Auuuu…!",
  ["4a:5b90"] = "Puedes atrapar\nPOKéMON aunque\fya lleves seis\ncontigo.\fSi atrapas alguno\nmás, será enviado\va la CAJA.",
  ["4a:5bf8"] = "¡Arg…! ¿Eh?\fHoy he caminado\nmucho buscando\vPOKéMON.\fMe duelen los pies\ny tengo sueño…\fSi fuera un\nPOKéMON salvaje,\fsería fácil\natraparme…\f¡Zzzz…!",
  ["4a:5c80"] = "Zzzz… ¿Eh?\f¿Qué es eso? ¿Una\nCARTA para mí?",
  ["4a:5caf"] = "{PLAYER} entregó\nel POKéMON que\vlleva la CARTA.",
  ["4a:5cd9"] = "Veamos…\fLa C. OSCURA lleva\na otro camino.\fEs bueno\nsaberlo.\fGracias por\ntraerme esto.\fMi amigo es un\nbuen chico. ¡Tú\ftambién eres\nincreíble!\f¡Me gustaría\ndevolverte el\vfavor!\f¡Ya sé!\n¡Toma esto!",
  ["4a:5dbb"] = "MT50 es PESADILLA.\fEs un movimiento\nterrible que\freduce los PS de\nun rival dormido.\f¡Ooooh…!\n¡Qué miedo…!\fNo me gustan las\npesadillas.",
  ["4a:5e46"] = "Esta CARTA no\nes para mí.",
  ["4a:5e5e"] = "¿Por qué es espe-\ncial este POKéMON?\fNo tiene ninguna\nCARTA.",
  ["4a:5e97"] = "¿Qué? ¿No\nquieres nada?",
  ["4a:5eb6"] = "Si te quito ese\nPOKéMON, ¿qué\fvas a usar en los\ncombates?",
  ["4a:5efa"] = "He encontrado un\nbuen POKéMON en\vla CUEVA OSCURA.\fVoy a criarlo\npara enfrentarme\va PEGASO.\fEs el líder del\nGIM. de C. MALVA.",
  ["4a:5f6a"] = "RUTA 31\fCIUDAD MALVA -\nCIUDAD CEREZO",
  ["4a:5f93"] = "CUEVA OSCURA",
  ["4b:42a5"] = "¡Espera!\n¿Por qué corres?",
  ["4b:42c0"] = "{PLAYER}, ¿verdad?\nUn tipo con\fgafas te estaba\nbuscando.\fCompruébalo tú\nmismo. Te está\fesperando en el\nCENTRO POKéMON.",
  ["4b:43c5"] = "¿Has ido al\nGIMNASIO POKéMON?\fAllí puedes probar\na tus POKéMON\vy a ti mismo.\f¡Es un rito para\ntodos los\ventrenadores!",
  ["4b:443a"] = "Tienes POKéMON\nmuy buenos.\fSeguro que es por\nhaberlos entrenado\fen los alrededores\nde CIUDAD MALVA.\fEl entrenamiento\nen el GIMNASIO ha\fdebido de ser de\ngran ayuda.\fToma esto como\nrecuerdo de\vCIUDAD MALVA.\fAumenta el poder\nde los movimientos\vde tipo planta.",
  ["4b:452a"] = "Tu experiencia en\nCIUDAD MALVA\fdebería ayudarte\nen tu viaje.",
  ["4b:456e"] = "¿Te gustaría tener\nesta sabrosa y\fnutritiva\nCOLASLOWPOKE?\f¡Sólo te costará\n1.000.000¥!\f¡Te gustará!",
  ["4b:45e4"] = "¡Vaya! Pensaba que\nlos niños de hoy\fen día estaban\nforrados…",
  ["4b:4611"] = "¿No la quieres?\nPues lárgate.",
  ["4b:4636"] = "¡Vaya!\f¡Se me escapó ese\npez por tu culpa!",
  ["4b:4659"] = "¡Splash!",
  ["4b:4663"] = "Paciencia… La\nbase de la pesca\fy de los POKéMON\nes la misma.",
  ["4b:46a4"] = "Soy un buen\npescador, pero\fcomo entrenador\nsoy aún mejor.",
  ["4b:46d3"] = "Intenté acelerar\nlas cosas…",
  ["4b:46f1"] = "¡Pescar es una\npasión eterna y\flos POKéMON son\namigos eternos!",
  ["4b:4863"] = "¿Mi POKéMON?\n¡Recién pescado!",
  ["4b:487d"] = "¡Splash!",
  ["4b:4886"] = "Los POKéMON\nrecién atrapados\fno son comparables\ncon los criados.",
  ["4b:48c2"] = "No te había\nvisto antes.\f¿Te crees\nmuy duro?",
  ["4b:4907"] = "¡Eres fuerte!",
  ["4b:4916"] = "Intentaré ser el\nmejor con mis\vfavoritos.\fNo uso los mismos\nPOKéMON que\vtodo el mundo.",
  ["4b:497c"] = "¡He encontrado\nPOKéMON muy buenos\ven la hierba!\f¡Creo que me\nservirán!",
  ["4b:49bf"] = "¡Maldición! Creía\nque podía ganar.",
  ["4b:49dd"] = "En la hierba hay\ncosas pegajosas.",
  ["4b:4a02"] = "Esa mirada…\nMe intriga.",
  ["4b:4a20"] = "¡Mmmm! ¡Qué\ndecepción!",
  ["4b:4a3e"] = "Si no quieres\nluchar, evita el\vcontacto visual.",
  ["4b:4a73"] = "Sí. Y sabes\nque…\f¿Luchar? ¡Estoy\nal teléfono!\fVale. Pero que\nsea rápido.",
  ["4b:4ad2"] = "¡Tranquilízate!\n¡Eso no está bien!",
  ["4b:4aed"] = "Yo también estaba\ncharlando.",
  ["4b:4b0c"] = "¡Esa MEDALLA! ¡Es\nde CIUDAD MALVA!\f¿Ganaste a PEGASO?",
  ["4b:4b41"] = "Conozco mis\ndebilidades.",
  ["4b:4b61"] = "Debería volver a\nentrenarme en el\fGIMNASIO de\nCIUDAD MALVA.",
  ["4b:4bc0"] = "¡GRRR!\n¡TODOS HUYEN\fCUANDO RUJO! ¡PERO\nTÚ HAS VENIDO!\f¡ESO ME GUSTA!\n¡TOMA ESTO!",
  ["4b:4c19"] = "¡GRRR!\n¡ES RUGIDO! HASTA\fLOS POKéMON HUYEN\nCON UN RUGIDO.",
  ["4b:4c4e"] = "VICKI: ¡Yuju!\n¡Es viernes!\fSoy VICKI, por\nviernes.\f¡Mucho gusto!",
  ["4b:4c91"] = "¡Toma una FLECHA\nVENENOSA!",
  ["4b:4caf"] = "VICKI: Dásela a un\nPOKéMON de tipo\vveneno.\f¡Oh!\f¡Es terrible!\f¡Te sorprenderá\nver cómo mejora\flos movimientos\nde tipo veneno!",
  ["4b:4d27"] = "VICKI: ¡Hola! ¿Qué\ndía prefieres?\fA mí me gusta el\nviernes. Sin duda.\f¿No crees que\nes genial?",
  ["4b:4d8c"] = "VICKI: ¿Hoy no\nes viernes?\f¡Me aburro cuando\nno lo es!",
  ["4b:4dc7"] = "RUTA 32\fCIUDAD MALVA -\nPUEBLO AZALEA",
  ["4b:4deb"] = "RUINAS ALFA\nENTRADA ESTE",
  ["4b:4e08"] = "Hacia la\nCUEVA UNIÓN",
  ["4b:4fad"] = "Crucé el túnel\ny todavía me\fqueda mucha\nenergía.",
  ["4b:4ff1"] = "¡Uauu, chico! ¡Qué\nmarcha tienes!",
  ["4b:5011"] = "Los MONTAÑEROS\nsomos felices en\vlas montañas.",
  ["4b:503e"] = "RUTA 33",
  ["4b:52ee"] = "¡Aquí es donde\nentreno!",
  ["4b:530f"] = "¿Qué ha pasado?",
  ["4b:531f"] = "Voy a entrenar\nmás aún.\fEstoy intentado\nconvertirme en un\vLÍDER de GIMNASIO.",
  ["4b:536c"] = "Soy el mejor de mi\nclase en POKéMON.",
  ["4b:538e"] = "¡No! Hay mejores\nentrenadores…",
  ["4b:53b0"] = "Estoy esforzándome\npara ser el mejor\vde mi clase.",
  ["4b:53e2"] = "Confío en mi\ncapacidad para\vcriar POKéMON.\f¿Quieres verlo?",
  ["4b:541a"] = "¿No lo hice lo\nbastante bien?",
  ["4b:5439"] = "Quizá debería\ndejar uno en la\fGUARDERÍA.\n¿Qué debo hacer?",
  ["4b:5473"] = "¿Eres entrenador?\fLibremos un\ncombate de prueba.",
  ["4b:54a4"] = "¡Oh, no! No\npuedo ganar…",
  ["4b:54be"] = "Eres demasiado\nfuerte para\vpracticar conmigo.",
  ["4b:54ea"] = "¿Quién anda ahí?\n¿Qué es lo que\vquieres?",
  ["4b:550f"] = "Eres un chaval\nmuy fuerte.",
  ["4b:552a"] = "Hoy no veo\nnada malo. Sé\fbueno y no te\nmetas en líos.",
  ["4b:5570"] = "Estoy buscando\nindividuos\vsospechosos.",
  ["4b:559c"] = "Acabo de recoger\nmi POKéMON de la\vGUARDERÍA.\f¡Veamos lo fuerte\nque es ahora!",
  ["4b:55e7"] = "¿Por qué acaba\nasí?",
  ["4b:5602"] = "Mi POKéMON sabía\nmovimientos que yo\vdesconocía.\f¡Eso me confundió\nmuchísimo!",
  ["4b:5649"] = "MAR: ¡Vaya, nos\nha visto un chico!",
  ["4b:5669"] = "MAR: ¡Ohhhh!\n¡Es muy fuerte!",
  ["4b:5688"] = "MAR: ¡Mi hermana\nLISA te lo hará\vpagar!",
  ["4b:56b6"] = "MAR: ¿No te parece\nuna playa genial?\f¡Es nuestro\npequeño refugio!",
  ["4b:56f4"] = "ILDA: ¡No puedes\nvencer a MAR e\virte sin más!",
  ["4b:5722"] = "ILDA: ¡Lo siento\nmucho, MAR!",
  ["4b:573f"] = "ILDA: ¡No seas\nchulo! ¡Mi hermana\vLISA es fuerte!",
  ["4b:576f"] = "ILDA: El sol\nfortalece tu\vcuerpo.",
  ["4b:5799"] = "LISA: ¡Seguro que\nhas sido malo con\vmis hermanitas!",
  ["4b:57c9"] = "LISA: ¡He perdido!\n¡Increíble!",
  ["4b:57eb"] = "LISA: Eres muy\nfuerte. No pude\vhacer nada.\fToma. Te lo\nmereces.",
  ["4b:5834"] = "LISA: Sentimos\nhaberte atacado.\fPensábamos que\naquí nadie nos\fencontraría. ¡Nos\nhas sorprendido!",
  ["4b:58b1"] = "RUTA 34\fCIUDAD TRIGAL -\nPUEBLO AZALEA\fEL ENCINAR\nEntre medias",
  ["4b:58f6"] = "PISTAS ENTRENADOR\fTodos los días\ncrecen BAYAS\ven los árboles.\fToma nota de los\ntipos de BAYAS que\vtiene cada árbol.",
  ["4b:595a"] = "GUARDERÍA\f¡Déjanos criar a\ntu POKéMON por ti!",
  ["4b:5c09"] = "He estado cogiendo\ndatos de POKéMON\fde mi radio. Creo\nque soy bueno.",
  ["4b:5c44"] = "¡Me rindo!",
  ["4b:5c4d"] = "La música de la\nradio cambia el\fánimo de los\nPOKéMON salvajes.",
  ["4b:5c81"] = "Le voy a demostrar\na mi novia lo\vbueno que soy.",
  ["4b:5cac"] = "Ojalá hubieras\nperdido por mí…",
  ["4b:5cd0"] = "Me humillaste\ndelante de mi\vnovia…",
  ["4b:5cfd"] = "Mi novio es débil.\nAsí que no puedo\vconfiar en él.",
  ["4b:5d29"] = "¡Cielos! ¡Eres tan\nfuerte!",
  ["4b:5d43"] = "Confío más en\nmis POKéMON\vque en mi novio.",
  ["4b:5d73"] = "¿Vas al GIMNASIO?\n¡Yo también!",
  ["4b:5d96"] = "¡Vaya! No pude\nganar…",
  ["4b:5daa"] = "Me gustan las\nMEDALLAS de\flos GIMNASIOS.\nLas colecciono.",
  ["4b:5dd6"] = "¿Qué tipo de\nPOKé BALL usas?",
  ["4b:5df8"] = "¡Vaya! ¡No lo\nbastante rápido!",
  ["4b:5e11"] = "Algunos POKéMON\nhuyen enseguida.\fIntenta atraparlos\ncon la RAPID BALL\vde CÉSAR.\fCuando encuentro\nun BONGURI BLA, se\vlo llevo a CÉSAR.\fÉl lo convierte en\nuna POKé BALL.",
  ["4b:5eaa"] = "¡Observa cómo uso\nlas POKé BALL!",
  ["4b:5ece"] = "¡Uauuu! ¡Vaya\nsacudida!",
  ["4b:5ee6"] = "Quería\nimpresionarte con\vmi premio POKéMON.\f¡Pero tu habilidad\nme ha electrizado!",
  ["4b:5f36"] = "Iré a cualquier\nlugar donde haya\vPOKéMON bicho.",
  ["4b:5f61"] = "Ya veo. Ésta es tu\nforma de luchar.",
  ["4b:5f81"] = "Mi VENONAT ganó\nel Concurso de\fCaptura de Bichos\ndel PARQUE\vNACIONAL.",
  ["4b:5fc3"] = "Practico mi\naliento de fuego.",
  ["4b:5fe5"] = "¡Me he quemado la\npunta de la nariz!",
  ["4b:6009"] = "La Marcha POKéMON\nde la radio atrae\vPOKéMON salvajes.",
  ["4b:6037"] = "¡El peligro acecha\npor la noche!",
  ["4b:6053"] = "¡Uy!",
  ["4b:605c"] = "Ya sabes, la noche\nes divertida a su\vmanera.\fPero no te pases,\n¿vale?",
  ["4b:60a3"] = "Tus POKéMON son\nbastante fuertes.\fEstarás seguro en\ncualquier parte.",
  ["4b:60e1"] = "RUTA 35",
  ["4b:6321"] = "Un árbol extraño.\n¿Usar REGADERA?",
  ["4b:6346"] = "{PLAYER} usó\nla REGADERA.",
  ["4b:6360"] = "¡Al árbol extraño\nno le gusta la\vREGADERA!\f¡El árbol extraño\natacó!",
  ["4b:63a7"] = "¡Cielos!\fIba a quitar\nese árbol con\fun gran\nderechazo.\fPero no pude.\n¡Soy un fracaso!",
  ["4b:6408"] = "¿Quitaste ese\npobre árbol?\f¡Estoy\nimpresionado! Toma\vesto.",
  ["4b:6464"] = "Se trata del\nGOLPE ROCA.\fPuedes destrozar\nrocas con un\fsimple golpe bien\ndirigido.\fSi encuentras una\nroca en tu camino,\v¡destrózala!",
  ["4b:64f0"] = "Un árbol extraño\nbloquea el camino\va CIUDAD TRIGAL.\fNo me permite\nir de compras.\fHabría que hacer\nalgo.",
  ["4b:6568"] = "Ese árbol extraño\ndesapareció sin\vdejar rastro.\f¡Oh! ¿Ese árbol\nera un POKéMON?",
  ["4b:65b7"] = "¡Te voy a leer\nel pensamiento!",
  ["4b:65d8"] = "¡Te malinterpreté!",
  ["4b:65e8"] = "Sería fuerte si\npudiera saber lo\fque está pensando\nmi rival.",
  ["4b:662a"] = "¡Gracias a mis\nestudios, estoy\fpreparado para\ncualquier POKéMON!",
  ["4b:665a"] = "¡Uups! ¿Error de\ncálculo?",
  ["4b:6674"] = "Yo también estudio\n5 horas al día.\fLeyendo libros\npuedes aprender\vmuchas cosas.",
  ["4b:66cc"] = "JOSUÉ: ¿Quién\neres tú?\fSoy JOSUÉ, por\njueves.",
  ["4b:66f9"] = "Toma. Coge\nesto.",
  ["4b:6713"] = "JOSUÉ: Debería\nusarlo un POKéMON\fcon habilidades\nde tipo roca.\fMejora los ataques\nde tipo roca.",
  ["4b:6776"] = "JOSUÉ: Soy JOSUÉ,\npor jueves. Soy\fel segundo de\nsiete hermanos.",
  ["4b:67bf"] = "JOSUÉ: Hoy no\nes jueves. ¡Qué\vdesilusión!",
  ["4b:67f0"] = "RUTA 36",
  ["4b:67fa"] = "RUINAS ALFA\nENTRADA NORTE",
  ["4b:6818"] = "PISTAS ENTRENADOR\fLas habilidades de\nlos POKéMON varían\fincluso dentro de\nuna misma especie.\fAl principio, sus\nhabilidades pueden\vparecerse.\fSin embargo, las\ndiferencias surgen\fa medida que el\nPOKéMON crece.",
  ["4b:68ba"] = "PISTAS ENTRENADOR\fUsa EXCAVAR para\nvolver a la\ventrada.\fEs útil para\nexplorar cuevas\fy otros\nlugares.",
  ["4c:4093"] = "ANA: ¡ANY y yo\nestamos en esto\vjuntas!",
  ["4c:40bc"] = "ANA-ANY: ¡Eres\nmuy malo!",
  ["4c:40d5"] = "ANA: Sé lo que\nestán pensando\fmi hermana y mis\nPOKéMON.",
  ["4c:410f"] = "ANY: ¡ANA y yo\nestamos en esto\vjuntas!",
  ["4c:4138"] = "ANA-ANY: ¡Eres\nmuy malo!",
  ["4c:4151"] = "ANY: Sentimos\nlo mismo que\vnuestros POKéMON.",
  ["4c:4180"] = "Los POKéMON no\npueden hacer nada\vdormidos.\f¡Yo te enseñaré el\nmiedo que da eso!",
  ["4c:41ca"] = "He perdido. ¡Qué\npena…!",
  ["4c:41e5"] = "Dormir o paralizar\na los POKéMON\fson buenas\ntécnicas de lucha.",
  ["4c:422d"] = "DOMINGO: ¡Hola!\fSoy DOMINGO, por\nel día. Es decir,\v¡hoy es domingo!",
  ["4c:4269"] = "¡Me dijeron que\nte diera esto si\vte veía!",
  ["4c:4294"] = "DOMINGO: Eso…\f¡Um…!\f¿Qué era…?\f…\f¡Ah! ¡Ahora lo\nrecuerdo!\fDebería llevarlo\nun POKéMON\fcon habilidades\neléctricas.\f¡Mi hermana LUNA\ndice que mejora\flas habilidades\neléctricas!",
  ["4c:4336"] = "DOMINGO: Mis\nhermanos son\vLUNA, MARTA,\vMIGUEL, JOSUÉ,\vVICKY y SABINO.\f¡Son todos\nmayores que yo!",
  ["4c:43a8"] = "DOMINGO: ¿Hoy no\nes domingo?\v¡Um…! ¡Lo olvidé!",
  ["4c:43d1"] = "RUTA 37",
  ["4c:45a8"] = "¡Vuela alto hacia\nel cielo, querido\vpájaro POKéMON!",
  ["4c:45d6"] = "¡Me apetece salir\nvolando ahora!",
  ["4c:45f9"] = "Pienso entrenar en\nCIUDAD ORQUÍDEA\fy enseñar a volar\na mis POKéMON.",
  ["4c:4638"] = "Déjame probar\nalgo que he\vaprendido hoy.",
  ["4c:4661"] = "Creo que no\nestudié bastante.",
  ["4c:4681"] = "Tengo que hacer\nmuchos exámenes y\fno tengo tiempo\npara los POKéMON.\fAsí que, cuando\npuedo jugar, me\vconcentro mucho.",
  ["4c:46f0"] = "¿Estás\nentrenándote?\fSi es así, ¿puedes\nenseñarme cómo?",
  ["4c:472e"] = "Ya veo. De modo\nque luchas así.",
  ["4c:4752"] = "¡Tengo una buena\nnoticia!\fLa leche de la\nGRANJA MUU-MUU\fes famosa por\nsu sabor.",
  ["4c:4796"] = "¡Hola! ¡Eres\nmuy guapo!\f¿Me dejas ver a\ntus POKéMON?",
  ["4c:47ca"] = "Encantada de\nhaber visto\va tus POKéMON.",
  ["4c:47eb"] = "Cuando veo\nPOKéMON me\vtranquilizo.",
  ["4c:481d"] = "He estado en el\nextranjero. ¡Así\fque conozco todo\ntipo de POKéMON!",
  ["4c:4856"] = "¡Tu destreza es de\ncategoría mundial!",
  ["4c:4872"] = "Gentes de todo el\nmundo viven\ffelices con\nlos POKéMON.",
  ["4c:48b2"] = "RUTA 38\fCIUDAD OLIVO -\nCIUDAD IRIS",
  ["4c:48d9"] = "PISTAS ENTRENADOR\fSi un POKéMON\nva a evolucionar,\vpuedes pararlo.\fPulsa el Botón B\nmientras intenta\vevolucionar.\fEsto asusta al\nPOKéMON y detiene\vsu evolución.",
  ["4c:4abc"] = "MUU-MUU: ¡Muu!",
  ["4c:4acc"] = "Acabo de volver\nde CIUDAD OLIVO.\f¿Te apetece luchar\ncon los POKéMON?",
  ["4c:4b05"] = "¡Awaaargh!",
  ["4c:4b10"] = "Mis POKéMON han\nsido atrapados y\fentrenados en el\nextranjero.\fSon mis compañeros\nde esos largos\vviajes.",
  ["4c:4b68"] = "¿Te importa si\npresumo de mis\vPOKéMON?",
  ["4c:4b94"] = "No puedo\npresumir…",
  ["4c:4bae"] = "¡No te estoy\nescuchando!\f¡Los POKéFANS\ntenemos la norma\fde no escuchar a\nlos presumidos!",
  ["4c:4c11"] = "¡Qué POKéMON\nmás encantadores!\fEnseñemos nuestros\nPOKéMON al\vmismo tiempo.",
  ["4c:4c53"] = "No me importa\nperder.",
  ["4c:4c68"] = "¿Sabes algo sobre\nlos POKéMON bebés?\f¡Seguro que\nson adorables!",
  ["4c:4ca2"] = "Déjame ver de qué\nson capaces tus\vPOKéMON.",
  ["4c:4ccd"] = "¡Ooh! Tus POKéMON\ntienen potencial.",
  ["4c:4ced"] = "¿Sabes que\nlos POKéMON\ftienen distintas\nhabilidades?\fSon como las\npersonas. Cada\funo tiene su\npropio potencial.",
  ["4c:4d5a"] = "RUTA 39\fCIUDAD OLIVO -\nCIUDAD IRIS",
  ["4c:4d81"] = "GRANJA MUU-MUU\fPrueba nuestra\nrica leche fresca",
  ["4c:4dad"] = "PISTAS ENTRENADOR\fUsa GOLPE CABEZA\nen los árboles\fpara que salgan\nPOKéMON.\fDe los árboles\npueden caer varios\vtipos de POKéMON.",
  ["4c:4f84"] = "Debes calentar\nantes de entrar\ven el agua.\fEs imprescindible.",
  ["4c:4fc3"] = "¡Vale! ¡Me rindo!",
  ["4c:4fd7"] = "CIUDAD ORQUÍDEA\nestá bastante\vlejos de aquí.",
  ["4c:5009"] = "Un joven como tú\ndebería nadar.\fNo hagas SURF\nsobre tus POKéMON.",
  ["4c:5044"] = "¡Oh, he perdido…!",
  ["4c:5054"] = "La natación\nfortalece tu\vcuerpo. Es sana.",
  ["4c:5087"] = "¿Vas a CIUDAD\nORQUÍDEA?\f¿Te apetece luchar\nantes?",
  ["4c:50c3"] = "¡He perdido!",
  ["4c:50d5"] = "Creo que nado\nmejor que tú.\v¡Sin duda!",
  ["4c:5103"] = "Yo no necesito\nflotador.\f¡Voy agarrada a\nun POKéMON de mar!",
  ["4c:5137"] = "¡Ooh, estoy\nmareada!",
  ["4c:514f"] = "Mientras flote\nasí, las olas\vme llevarán.",
  ["4c:5183"] = "Aunque no se ve\ndesde aquí, CIUDAD\fORQUÍDEA está al\notro lado del mar.",
  ["4c:51c4"] = "LUNA: Encantada de\nconocerte. Soy\fLUNA, por lunes.",
  ["4c:51f4"] = "¡Como prueba de\nnuestra amistad,\ftengo un regalo\npara ti!",
  ["4c:522a"] = "LUNA: Es un objeto\nque aumenta el\fpoder de los\nataques de vuelo.\fDeberías dar este\nobjeto a un\vPOKéMON pájaro.",
  ["4c:529a"] = "LUNA: Mis hermanos\ny hermanas están\fpor todas\npartes.\f¡A ver si los\nencuentras!",
  ["4c:52f5"] = "LUNA: No creo\nque hoy sea\vlunes. ¡Qué pena…!",
  ["4c:5325"] = "RUTA 40\fCIUDAD ORQUÍDEA -\nCIUDAD OLIVO",
  ["4c:54a1"] = "Aquí el agua está\ntemplada. Estoy\vmuy a gusto.\fPor supuesto,\n¡lucharé contigo!",
  ["4c:54e4"] = "¡Vaya! ¡Estoy\ncomo una pasa!",
  ["4c:5500"] = "¡Qué relajante\nes flotar\vasí!",
  ["4c:552b"] = "Estoy cansado. Si\ngano, ¿me prestas\vtus POKéMON?",
  ["4c:5559"] = "(jadeo…)",
  ["4c:5566"] = "CIUDAD ORQUÍDEA\nestá muy lejos.\fPero tampoco es\nfácil volver a\vCIUDAD OLIVO.\f¿Qué hacer?",
  ["4c:55c0"] = "¿Ves esas islas\naisladas por\vtorbellinos?\f¡Tiene que haber\nun secreto!",
  ["4c:5612"] = "¿Cuál es tu\nsecreto?",
  ["4c:5636"] = "Era de noche\ny llovía…\fVi un POKéMON\ngigante volando\vdesde las islas.\fDejaba caer las\nplumas de sus\valas plateadas.",
  ["4c:56b8"] = "Aquí hay mucho\noleaje.\fCuesta mucho\nnadar.",
  ["4c:56f4"] = "¡Me has vencido!",
  ["4c:56fe"] = "La corriente me\nimpide llegar\va las islas.",
  ["4c:572f"] = "¿Estás buscando\nel secreto de las\vISLAS REMOLINO?",
  ["4c:575e"] = "¡Ooh, tienes una\ngran resistencia!",
  ["4c:577f"] = "Un secreto sobre\nISLAS REMOLINO…\f¡Dentro está muy\noscuro!",
  ["4c:57b6"] = "Voy hacia las\nISLAS REMOLINO.\fVoy a explorarlas\ncon unos amigos.",
  ["4c:57f9"] = "¿Así es como\nlo haces?",
  ["4c:5811"] = "Dicen que hay un\ngran POKéMON\fbajo las\nISLAS REMOLINO.\fMe pregunto\ncómo será…",
  ["4c:586c"] = "Estás tan elegante\nmontado en tu\vPOKéMON.",
  ["4c:5896"] = "He perdido.",
  ["4c:58a3"] = "¿No había una\ncanción famosa\fsobre un niño que\nmontaba un LAPRAS?",
  ["4c:58d8"] = "¡Hace muy buen\ndía! ¡Estoy\vaturdida!",
  ["4c:5904"] = "¡Ohhh!",
  ["4c:590b"] = "El sol es muy malo\npara la piel.\fPero yo no uso\nprotección solar.\fNo quiero\nensuciar el agua.",
  ["4c:5962"] = "Si necesitas\ndescansar, ve por\vel agua.\fEl viento te\nempujará y podrás\fseguir siendo\nfuerte.",
  ["4c:59c5"] = "¡Oh! Tienes más\nenergía que yo.",
  ["4c:59ea"] = "He oído rugidos\nprocedentes de\vlas ISLAS.",
  ["4c:5a17"] = "Por la noche,\nlos STARYU se\freúnen cerca de la\nsuperficie.",
  ["4c:5a49"] = "¡Oh, querido…!",
  ["4c:5a54"] = "Los grupos de\nSTARYU se iluminan\val mismo tiempo.\fEs muy bonito,\npero da miedo.",
  ["4c:5c16"] = "¡Déjame que te\nenseñe el poder de\vmis POKéMON!",
  ["4c:5c4a"] = "¿Qué? Eso no está\nbien.",
  ["4c:5c62"] = "Quiero convertirme\nen un CAMPEÓN\fcon los POKéMON\nque he atrapado.\f¡Eso es lo mejor\nde la pesca!",
  ["4c:5cbf"] = "¡Ah! ¡Qué bien\nestar fuera! ¡Me\vsiento tan libre!",
  ["4c:5cec"] = "¡Gahahah!",
  ["4c:5cf6"] = "¡Perder no tiene\nimportancia si lo\fcomparas con el\ninmenso cielo!",
  ["4c:5d33"] = "¡OYE!\f¡Éste es mi lugar\nsecreto! ¡Fuera de\vaquí, intruso!",
  ["4c:5d6a"] = "Debí haber usado\nmi PIEDRA LUNAR…",
  ["4c:5d8d"] = "¿Tienes una\nPOKéDEX?\f¡Uau, habrás visto\nPOKéMON muy\vraros!\f¿Puedo verla,\npor favor?",
  ["4c:5dee"] = "RUTA 42\fCIUDAD IRIS -\nPUEBLO CAOBA",
  ["4c:5e16"] = "MONTE MORTERO\fCUEVA CASCADA\nInterior",
  ["4c:5e3a"] = "MONTE MORTERO\fCUEVA CASCADA\nInterior",
  ["4c:5e5e"] = "RUTA 42\fCIUDAD IRIS -\nPUEBLO CAOBA",
  ["4d:418e"] = "¡Me encantan\nlos POKéMON!\f¡Ésa es la razón\npor la que empecé\fa coleccionar\nPOKéMON!",
  ["4d:41d8"] = "¿Cómo me has\npodido hacer esto?",
  ["4d:41f6"] = "¿Que qué me gusta\nademás de los\vPOKéMON?\fOír a ROSA en la\nradio. ¡Seguro que\ves muy guapa!",
  ["4d:423d"] = "¡Eh! ¿Tienes algún\nPOKéMON raro?",
  ["4d:425e"] = "¡Oh, mis pobres\nPOKéMON!",
  ["4d:427d"] = "Sería feliz con\nsólo tener un\vPOKéMON raro.",
  ["4d:42aa"] = "¿Te lo puedes\ncreer?\f¡{RIVAL} se ha\nburlado de mi\vPOKéMON!\f¡Maldición! ¡Mi\nPOKéMON es genial!",
  ["4d:42fa"] = "¡Mi NIDOKING lo\nha hecho muy bien!",
  ["4d:431c"] = "Es bueno que a la\ngente le gusten\fdistintos tipos de\nPOKéMON.\fNo sólo se trata\nde tener el\vmás fuerte.",
  ["4d:4385"] = "No estoy de racha.\fQuizá sea por el\nequipo que uso.\fLuchemos. A ver si\ncambia mi suerte.",
  ["4d:43d4"] = "He perdido, pero\nme siento mejor.",
  ["4d:43f7"] = "Las CEBO BALL de\nCÉSAR son las\fmejores para\npescar POKéMON.\fSon mucho más\nefectivas que las\vULTRA BALL.",
  ["4d:4459"] = "Puedo hacer muchas\ncosas con mis\fPOKéMON.\n¡Es muy divertido!",
  ["4d:4489"] = "Perder no es nada\ndivertido…",
  ["4d:44a2"] = "¿Qué ocurre en el\nLAGO DE LA FURIA?\fTeníamos pensado\nacampar aquí.",
  ["4d:44e5"] = "¿Tú también vas al\nLAGO DE LA FURIA?\f¡Juguemos un\nratito!",
  ["4d:4528"] = "¡He jugado mucho!",
  ["4d:453c"] = "Voy a ir de picnic\ncon mis POKéMON.\f¿No te vienes?",
  ["4d:456f"] = "RUTA 43\fLAGO DE LA FURIA -\nPUEBLO CAOBA",
  ["4d:4596"] = "RUTA 43\fLAGO DE LA FURIA -\nPUEBLO CAOBA",
  ["4d:45bd"] = "PISTAS ENTRENADOR\fTodos los POKéMON\ntienen ventajas y\fdesventajas según\nel tipo.\fEntre dos POKéMON\nde distinto tipo,\fpuede perder el\nde nivel superior.\fAprende qué tipos\nson fuertes o\fdébiles contra tu\ntipo de POKéMON.",
  ["4d:488b"] = "¡Me has hecho\nperder a POLIWAG!\f¿Qué vas a hacer\npara remediarlo?",
  ["4d:48d1"] = "¡Simplemente,\nolvídalo!",
  ["4d:48e8"] = "Ese POLIWAG que\nescapó…\vEra enorme.\f¡Juraría que medía\nunos 5 metros!",
  ["4d:4937"] = "Pesco hasta que\nno puedo más.\fY lucho hasta\ndesfallecer.\fÉsta es la\nrelación que tengo\vcon mis POKéMON.",
  ["4d:4995"] = "¡Mmmmm…!\nEso no está bien.",
  ["4d:49af"] = "Son 100 victorias\ny 101 derrotas.\fNo lucharé\nen un rato.",
  ["4d:49ef"] = "¿Sabes algo sobre\nel POKéMON\vpájaro legendario?",
  ["4d:4a1b"] = "¡Uauu! Eres un\nhacha.",
  ["4d:4a33"] = "ARTICUNO, ZAPDOS y\nMOLTRES son los\fpájaros POKéMON\nlegendarios.\fAunque dicen que\nhay otros pájaros\vlegendarios.",
  ["4d:4aa7"] = "¡Voy a ganar!\n¡Seguro!",
  ["4d:4ac0"] = "¡Arrgh…! No\nesperaba perder.",
  ["4d:4adf"] = "Es importante\ntener confianza\ven uno mismo.",
  ["4d:4b0f"] = "¡Haré lo que sea\npara conseguir\vPOKéMON raros!",
  ["4d:4b3e"] = "Oooh, tus POKéMON\nson muy bonitos.",
  ["4d:4b61"] = "Los POKéMON\nde colores\fpoco habituales\ntienen más valor.\f¿Qué? ¿Insinúas\nque no es cierto?",
  ["4d:4bbf"] = "Con sólo mirarte\nsé si eres un\vbuen entrenador.\fYo soy bueno con\nlos POKéMON y veo\vque tú también.",
  ["4d:4c26"] = "¡Vaya! Ha sido una\nauténtica derrota.",
  ["4d:4c49"] = "¡Uauu! Tienes\nmuchas MEDALLAS.\fNo me extraña que\nseas tan fuerte.\fMe pregunto si\nMORTI, de GIMNASIO\fIRIS, estará\naún entrenándose.\fÉl sí que me\ndio una paliza.",
  ["4d:4cd0"] = "Pareces fuerte.\fLos buenos\nentrenadores\fsiempre buscan\nbuenos rivales.",
  ["4d:4d14"] = "¡No! Esto no\nservirá para nada.",
  ["4d:4d30"] = "Todos mejoramos\nluchando\vmuchas veces.\fHe luchado mucho\npara llegar a ser\flo que soy hoy:\nuna campeona.",
  ["4d:4d96"] = "RUTA 44\nHACIA RUTA HELADA",
  ["4d:4daf"] = "RUTA 44\fPUEBLO CAOBA -\nCIUDAD ENDRINO",
  ["4d:4feb"] = "¡Prepárate para\ncualquier cosa!\f¡Déjame ver si\nhas entrenado bien\va tus POKéMON!",
  ["4d:5039"] = "¡Oh, he perdido!",
  ["4d:504b"] = "Volveré a la RUTA\nHELADA de CIUDAD\fENDRINO y seguiré\nentrenándome.",
  ["4d:5087"] = "¡Eres valiente!\nPero…\f¿Sabes qué?\nPara valiente,\v¡yo!",
  ["4d:50dc"] = "¡A mis POKéMON les\nfaltaron agallas!",
  ["4d:50fb"] = "¡Cómo me gusta\nMÁS PS! ¡Mmmm!\f¡Me bebo la de mis\nPOKéMON!\fNo puedo evitarlo.",
  ["4d:5147"] = "¡Mis POKéMON son\nmuy poderosos!",
  ["4d:5162"] = "¡Buaaaaa! ¡Soy un\nperdedor!",
  ["4d:517e"] = "No se me da muy\nbien pensar.\f¡Así que utilizo\nsólo la fuerza!",
  ["4d:51c4"] = "¿Que por qué\nescalo montañas?\fPorque están\nahí.\f¿Que por qué\nentreno POKéMON?\f¡Porque están\nahí!",
  ["4d:5220"] = "Las derrotas…\n¡También están!",
  ["4d:523b"] = "Lo mejor que me ha\npasado nunca fue\fdescubrir a los\nPOKéMON.",
  ["4d:5276"] = "Estaba entrenando\naquí solo.\f¡Observa el fruto\nde mi trabajo!",
  ["4d:52b1"] = "¡Waaaargh!",
  ["4d:52bc"] = "Debo tomar\nmedidas extremas.\fDebo ir a los\nmontes y entrenar\vallí, en soledad.",
  ["4d:530e"] = "¿Qué piensas sobre\nla educación\vde los POKéMON?",
  ["4d:5339"] = "Te has ganado\nmi respeto.",
  ["4d:5350"] = "Veo que estás\neducando a tus\fPOKéMON\ncon cariño.\fEl vínculo que\nos une os salvará\fen las situaciones\ndifíciles.",
  ["4d:53b2"] = "¿Cuál es tu\nestrategia?\fEs de tontos usar\nataques fuertes\fde forma\nindiscriminada.",
  ["4d:5405"] = "Vale. He perdido.",
  ["4d:5414"] = "No soy partidaria\nde los ataques\vdemasiado fuertes.\fQuiero ganar, pero\nno quiero herir\va los POKéMON.",
  ["4d:5490"] = "RUTA 45\nCAMINO MONTAÑA",
  ["4d:561f"] = "De acuerdo. ¡Te\nenseñaré el poder\fde los POKéMON\nde montaña!",
  ["4d:5652"] = "¡Me has demostrado\ntu poder!",
  ["4d:5674"] = "Se acabó. Pero no\nme importa. \fLos MONTAÑEROS\nsomos así.",
  ["4d:56a5"] = "¡Yo también\nentreno POKéMON!\f¿Quieres luchar\ncontra mí?",
  ["4d:56d6"] = "¿Qué…?",
  ["4d:56dd"] = "Hice lo que pude\npero no sirvió.\fNo hay excusa que\nvalga. He perdido.",
  ["4d:571b"] = "¡Yo también\nentreno POKéMON!\f¡Luchemos!",
  ["4d:573b"] = "¡Oh, maldición!",
  ["4d:5749"] = "He estado en\nmuchos GIMNASIOS,\fpero mi favorito\nes el de TRIGAL.\f¡Está lleno de\npreciosas flores!",
  ["4d:57aa"] = "RUTA 46\nCAMINO MONTAÑA",
  ["4d:588a"] = "¿Has ido al GIM.\nde C. PLATEADA?\fEl LÍDER utiliza\nPOKéMON roca.",
  ["4d:58c8"] = "Por la noche,\nCLEFAIRY sale a\vjugar al MT. MOON.\fPero no todas\nlas noches.",
  ["4d:590e"] = "¡Vaya! ¿Vienes\nde JOHTO?\fMe trae muchos\nrecuerdos. Cuando\fera joven, fui a\nJOHTO a entrenar.\fTe pareces\nmucho a mí\fcuando yo\ntenía tu edad.\fMe gustaría darte\neste objeto que\vencontré en JOHTO.",
  ["4d:59f2"] = "Visitar nuevos\nsitios y conocer\vgente nueva…\fEso es lo\nbueno de viajar.",
  ["4d:5a47"] = "CIUDAD PLATEADA\nLa ciudad de\vpiedra grisácea",
  ["4d:5a66"] = "LÍDER POKéMON\nDEL GIMNASIO DE\vC. PLATEADA: BROCK\fEl Entrenador\nPOKéMON más\ffuerte que\nuna roca.",
  ["4d:5aa6"] = "Aquí hay una\nnota…\fMUSEO DE LA\nCIENCIA DE CIUDAD\fPLATEADA: Cerrado\npor obras…",
  ["4d:5af1"] = "Aquí hay una\nnota…\f¡TIENDA DE REGALOS\nMT. MOON abierta!",
  ["4d:5b24"] = "¡Bienvenido a\nCIUDAD PLATEADA!",
  ["4d:5c1a"] = "Mis POKéMON bicho\nson muy fuertes.\f¡Prepárate para\nperder!",
  ["4d:5c43"] = "Me vencieron…",
  ["4d:5c53"] = "Voy a buscar\nPOKéMON bichos\vmás fuertes.",
  ["4d:5c7c"] = "Si caminas por la\nhierba alta con\fpantalones cortos,\n¿no te arañas?",
  ["4d:5cc2"] = "¡Au, au, au!",
  ["4d:5cd5"] = "Seguro que te\npican si te\vbañas.",
  ["4d:5d00"] = "¿Por qué a las\nchicas no les\fgustan los\nPOKéMON bicho?",
  ["4d:5d1f"] = "¡Muy mal!",
  ["4d:5d29"] = "Los POKéMON bicho\nparecen muñecos\fde goma cuando les\naprietas la tripa.\f¡Me encanta\ntocarlos!",
  ["4d:5d80"] = "RUTA 2\fCIUDAD VERDE -\nCIUDAD PLATEADA",
  ["4d:5da5"] = "CUEVA DIGLETT",
  ["4e:4062"] = "¡Hola, chico! ¡Me\nacabo de tomar un\fcafé doble y estoy\ncomo una moto!\f¡Tengo que hablar\ncon alguien, así\vque te toca a ti!\fPuede que ahora no\nlo parezca, pero\fyo era un experto\natrapando POKéMON.\f¿Me crees?",
  ["4e:412c"] = "Muy bien. Sí, yo\nera algo fuera de\flo normal. ¡Déjame\ncontártelo!",
  ["4e:4174"] = "¿Qué? ¡Pequeño\nbribón!\fSi fuera un poco\nmás joven, te\fenseñaría un par\nde cosas. ¡Vaya!",
  ["4e:41ce"] = "Este GIMNASIO no\nha tenido LÍDER\vhasta hace poco.\fUn joven de\nPUEBLO PALETA se\fconvirtió en LÍDER\npero viaja mucho.",
  ["4e:423b"] = "¿Vas a enfrentarte\nal LÍDER?\f¡Buena suerte! ¡La\nvas a necesitar!",
  ["4e:4281"] = "¡Qué sueño!\fMe habré quedado\ndormido al sol.\fHe soñado que\nun DROWZEE se\fcomía mi sueño.\nEs raro, ¿verdad?\f¿Eh?\n¿Qué es esto?\f¿De dónde ha\nsalido esta MT?\f¡Esto es muy\nmisterioso! Aquí\vtienes esta MT.",
  ["4e:4343"] = "MT42 contiene\nCOME SUEÑOS…\f¡Zzzzz…!",
  ["4e:4367"] = "Dicen que en el\nsuelo del BOSQUE\fVERDE hay muchos\nobjetos.",
  ["4e:43ac"] = "CIUDAD VERDE\fEl Paraíso\nEternamente Verde",
  ["4e:43d8"] = "LÍDER DEL GIMNASIO\nPOKéMON DE\vCIUDAD VERDE:…\fEl resto del texto\nes ilegible…",
  ["4e:441d"] = "Bienvenido a\nCIUDAD VERDE,\fla entrada a\nla MESETA AÑIL",
  ["4e:4456"] = "CASA DE ENTRENADOR\fClub de Mejores\nEntrenadores",
  ["4e:44fc"] = "LIGA POKéMON\fENTRADA A\nCALLE VICTORIA",
  ["4e:455e"] = "Luchar es lo\nprimero que hacen\flos entrenadores\nsi se encuentran.",
  ["4e:4592"] = "Tengo el récord de\ncombates perdidos.",
  ["4e:45b2"] = "Es obvio que los\nentrenadores\fluchemos cuando\nnos encontremos.",
  ["4e:45f0"] = "¡Estás ahí!\n¿Quieres luchar?",
  ["4e:460c"] = "He perdido…",
  ["4e:461b"] = "Eres fuerte.\fSeguro que te has\nentrenado mucho.",
  ["4e:4650"] = "RUTA 1\fPUEBLO PALETA -\nCIUDAD VERDE",
  ["4e:46c2"] = "Yo también entreno\nPOKéMON. Son\fmis guardaespaldas\npersonales.",
  ["4e:46fb"] = "¡La tecnología es\nincreíble!\fAhora puedes\ncambiar POKéMON\fcon el pasado,\ncomo un e-mail.",
  ["4e:4746"] = "PUEBLO PALETA\fUn tranquilo lugar\nde paz y pureza",
  ["4e:4778"] = "CASA DE ROJO",
  ["4e:4785"] = "LABORATORIO DE\nINVESTIGACIÓN\vPOKéMON DE OAK",
  ["4e:479c"] = "CASA DE AZUL",
  ["4e:482b"] = "Tierra a la vista.\n¡Sigamos adelante!",
  ["4e:4847"] = "¡Glup…!",
  ["4e:484e"] = "Ese chico tan\narrogante estaba\fen el volcán de\nISLA CANELA.",
  ["4e:487b"] = "¡Hola!\fMe iba a poner\nun poco de\vprotección solar.",
  ["4e:48ab"] = "No quiero\nquemarme…",
  ["4e:48c6"] = "Debería tener\ncuidado con las\fmanchas causadas\npor el sol.",
  ["4e:48fc"] = "Estoy aburrido de\npescar. ¡Luchemos!",
  ["4e:4921"] = "Un fracaso…",
  ["4e:4931"] = "Seguiré\npescando…",
  ["4e:49a7"] = "¿Quién eres tú?\fEs evidente\nque eres un\ventrenador…\fMe llamo AZUL.\fY una vez fui el\nCAMPEÓN, pero sólo\fdurante poco\ntiempo…\fEl entrometido de\nROJO me ganó…\f¡Pero qué más da!\n¿Y tú qué quieres?\f¿Has venido a\ndesafiarme?\fLo siento, pero\nno, ahora no\ftengo ganas\nde luchar.\fEcha un vistazo a\ntu alrededor…\fUn volcán entra\nen erupción y una\fciudad entera\ndesaparece.\fEn POKéMON se\npuede ganar y\fperder, pero si\nse tuercen las\fcosas, se puede\nperder enseguida.\f…\fAsí son las\ncosas…\fSin embargo, sigo\nsiendo entrenador.\fY encontrarme con\nun rival fuerte me\vanima a luchar.\fSi quieres luchar\ncontra mí, ven\fal GIMNASIO de\nla CIUDAD VERDE.\fY aceptaré\ntu desafío…",
  ["4e:4c48"] = "Aquí hay una\nnota…\fEl GIMNASIO DE\nISLA CANELA se ha\ftrasladado a ISLAS\nESPUMA.\fBLAINE",
  ["4e:4c97"] = "ISLA CANELA\fLa abrasadora isla\ndel ardiente deseo",
  ["4e:4d3d"] = "Me siento más\nligera en el agua.",
  ["4e:4d5f"] = "¡Oh, no!",
  ["4e:4d68"] = "La natación\nfortalece todo el\fcuerpo. ¡Es muy\nbuena!",
  ["4e:4da5"] = "¡Vaya colección\nde MEDALLAS\fde GIMNASIO!\n¡Luchemos!",
  ["4e:4de5"] = "¡No!",
  ["4e:4dea"] = "SURF ya no es el\núnico movimiento\fque se utiliza\nen el agua.",
  ["4e:4e20"] = "Supongo que es\nimposible ir\fnadando hasta\nJOHTO.",
  ["4e:4e58"] = "¡Aiyaa!",
  ["4e:4e60"] = "Además de nadar\nen el mar, puedo\fnadar en estanques\ny ríos.",
  ["4e:4e97"] = "¿Qué pone en\neste letrero?\fLÍDER del GIMNASIO\nde ISLA CANELA:\vBLAINE",
  ["4e:4fa6"] = "¿Has nadado alguna\nvez en el mar por\vla noche?",
  ["4e:4fd8"] = "¡Glup…!",
  ["4e:4fdf"] = "De noche, el mar\nestá oscuro. Da la\fimpresión de que\nte va a tragar.",
  ["4e:5025"] = "(Resoplido)…\nUn… poco más…\fy… llegaré…\na CIUDAD FUCSIA…",
  ["4e:5058"] = "¡Me ahogo!",
  ["4e:5066"] = "Le… pedí a mi\nnovia que nadara\va CIUDAD FUCSIA…",
  ["4e:509a"] = "¡No me gustan los\ncanijos!",
  ["4e:50b9"] = "Podría ganarte\nnadando…",
  ["4e:50d8"] = "No hay que nadar\nmucho desde CIUDAD\fFUCSIA a las ISLAS\nESPUMA…\f¡Mi novio es un\ngrandullón!\f¡Qué canijo!",
  ["4e:5144"] = "Soy malísimo\nnadando.\fSólo estoy\nchapoteando por\festas aguas poco\nprofundas.",
  ["4e:5191"] = "Creía que podía\nganar.",
  ["4e:51a9"] = "Puede que no nade\nmuy bien, pero me\vencanta el mar.",
  ["4e:51da"] = "Lo siento. La\ncarretera está\vcortada por obras.\fSi quieres llegar\na ISLA CANELA, ve\fpor el Sur, desde\nPUEBLO PALETA.",
  ["4e:524f"] = "Estoy sudando.\n¡Voy a bañarme!",
  ["4e:5270"] = "A saber cuánto se\ntardaría en mover\vesta roca…",
  ["4e:52a8"] = "Las obras de la\ncarretera ya han\vterminado.\fYa puedo volver a\npescar.",
  ["4e:52e7"] = "RUTA 19\fCIUDAD FUCSIA -\nISLAS ESPUMA",
  ["4e:5310"] = "Por favor, ten\ncuidado si vas\fnadando hasta las\nISLAS ESPUMA\fPOLICÍA C. FUCSIA",
  ["4e:53eb"] = "Un miembro del\nALTO MANDO era el\fLÍDER del GIMNASIO\nde CIUDAD FUCSIA.",
  ["4e:5429"] = "La hija de KOGA le\nha sucedido como\fLÍDER del GIMNASIO\ncuando él se unió\val ALTO MANDO.",
  ["4e:5479"] = "La ZONA SAFARI\nestá cerrada. Da\fpena, ya que es\nla mayor atracción\vde CIUDAD FUCSIA.",
  ["4e:54c8"] = "CIUDAD FUCSIA\f¡Mirad la CIUDAD\nFUCSIA! ¡La pasión\vrosa!",
  ["4e:54f0"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\vFUCSIA: SACHIKO\fLa venenosa\nmaestra ninja.",
  ["4e:5531"] = "Aquí hay una\nnota…\fEl PUESTO GUARDA\nDE LA ZONA SAFARI\festá cerrado hasta\nnuevo aviso.",
  ["4e:557b"] = "CASA DEL GUARDA\nDE LA ZONA SAFARI",
  ["4e:5596"] = "El GUARDA está\nde viaje. Ésa es\fla razón por la\nque la ZONA SAFARI\vestá cerrada.",
  ["4e:55dd"] = "No ensuciar.\fPor favor, no\ntirar basura.",
  ["4e:56d3"] = "Si estás buscando\nPOKéMON, mira\fen las zonas de\nhierba alta.",
  ["4e:5713"] = "¡Ayyyy!",
  ["4e:571c"] = "Siendo tan fuerte,\ndebe de ser muy\vdivertido luchar.",
  ["4e:574e"] = "El CAMINO BICIS es\nun atajo a CIUDAD\vAZULONA.",
  ["4e:577c"] = "¡Uau…!",
  ["4e:5784"] = "Si no tienes una\nBICI, no podrás\fusar el atajo.",
  ["4e:57c8"] = "RUTA 18\fCIUDAD AZULONA -\nCIUDAD FUCSIA",
  ["4e:587f"] = "¡Eh, tú! Eres de\nJOHTO, ¿verdad?",
  ["4e:58a1"] = "¡Venga, golpea!",
  ["4e:58b2"] = "¡No seas chulo,\npunki de JOHTO!",
  ["4e:58d3"] = "¡Uau! ¡Qué BICI\nmás guay!",
  ["4e:58ef"] = "Pero tú no\npareces guay…",
  ["4e:590d"] = "Soy guay, pero\nestoy débil. Por\veso no lo parezco.\fDebería entrenar\nmucho más…",
  ["4e:5957"] = "¡Eh! ¿Un combate\nrapidito?",
  ["4e:597a"] = "¡Vaya! ¡Qué\nvitalidad!",
  ["4e:599c"] = "Montar sin manos\nen el CAMINO BICIS\ves muy guay.",
  ["4e:59d3"] = "¡Somos estrellas\nde la carretera!",
  ["4e:59f1"] = "¡Arrrg! ¡Chocar y\narder!",
  ["4e:5a0a"] = "¡Conducir de forma\nimprudente causa\faccidentes! ¡Ten\ncuidado!",
  ["4e:5aa6"] = "CAMINO BICIS\f¡Cuesta abajo\npor la costa!",
  ["4e:5b3a"] = "Este POLIWRATH es\nmi compañero.\fMe pregunto si\nalgún día\fevolucionará en\nuna rana POKéMON.",
  ["4e:5b88"] = "POLIWRATH: ¡Polii!",
  ["4e:5b9b"] = "Volví a perder en\nlas tragaperras.\fLas chicas también\njugamos a las\ftragaperras.\nPrueba tú también.",
  ["4e:5c00"] = "Últimamente han\naparecido GRIMER.\f¿Ves esa charca\nque hay delante de\fla casa? Ahí\nviven GRIMER.\f¿De dónde han\nvenido? Es un\vgrave problema…",
  ["4e:5c99"] = "¡Bravo! ¡Este\nGIMNASIO es\fgenial! ¡Es sólo\npara chicas!",
  ["4e:5cd2"] = "¿Te cuento\nun secreto?\fLa MANSIÓN AZULONA\ntiene una puerta\vtrasera secreta.",
  ["4e:5d12"] = "Hay un concurso\nde tragones\ven el restaurante.\fSólo verlo hace\nque me sienta\vlleno…",
  ["4e:5d7a"] = "El C. COMERCIAL\nde CIUDAD AZULONA\fdispone de los\nmejores artículos.\fSi no encuentras\nalgo aquí, no lo\fencontrarás en\nningún otro sitio.\f¡Vaya…! Parezco\nuna vendedora.",
  ["4e:5e18"] = "Me he mareado de\nir mirando al\fsuelo mientras\ncaminaba.",
  ["4e:5e52"] = "CIUDAD AZULONA\fLa ciudad de los\nsueños de arcoiris",
  ["4e:5e7b"] = "LÍDER DEL GIMNASIO\nPOKéMON DE\fCIUDAD AZULONA:\nERIKA\fLa princesa amante\nde la naturaleza",
  ["4e:5ebb"] = "¡Encuentra lo que\nnecesitas en el\fCENTRO COMERCIAL\nDE CIUDAD AZULONA!",
  ["4e:5ee6"] = "MANSIÓN AZULONA",
  ["4e:5ef7"] = "CASINO DE CIUDAD\nAZULONA: Zona de\vjuego para todos",
  ["4e:5f2a"] = "PISTAS ENTRENADOR\fPROTEC. ESP\nprotege a los\fPOKéMON de\nataques ESPECIALES\vcomo fuego y agua.\f¡Consigue los\nobjetos en el\fCENTRO COMERCIAL\nde CIUDAD AZULONA!",
  ["4e:6081"] = "¿Y este cartel?\fAlgunos\nentrenadores han\festado luchando en\nVÍA SUBTERRÁNEA.\fTras numerosas\nquejas de los\fvecinos, la VÍA\nSUBTERRÁNEA ha\fsido cerrada\nindefinidamente.\fPOLICÍA C. AZULONA",
  ["4e:614f"] = "Está cerrada…",
  ["4f:407f"] = "¿Has olvidado\nalgo?",
  ["4f:409d"] = "¡Kiaaa!",
  ["4f:40a6"] = "Antes de ser\nmaestra, solía\folvidarme de\nmuchas cosas.",
  ["4f:40e4"] = "Creo que si hace\nsol, los niños\fdeberían estar\njugando en el\fpatio en lugar\nde estar en clase.",
  ["4f:414c"] = "No quería\nperder…",
  ["4f:4163"] = "Es importante\nestudiar, pero\fhacer deporte\ntambién.",
  ["4f:419c"] = "Espera. Tengo que\nllamar a mamá.",
  ["4f:41be"] = "¡Lo siento, mamá!\n¡Me han vencido!",
  ["4f:41d9"] = "Mi madre se\npreocupa mucho por\fmí, tengo que\nllamarla siempre.",
  ["4f:421d"] = "Luchemos.\n¡No perderé!",
  ["4f:4238"] = "¡Me olvidé de\nhacer los deberes!",
  ["4f:4255"] = "¡Sayonara! Lo he\naprendido en la\vclase de japonés.",
  ["4f:428a"] = "Vamos a la TORRE\nRADIO de LAVANDA\fpara realizar unos\nestudios sociales.",
  ["4f:42cc"] = "¡Eres demasiado\nduro!",
  ["4f:42e3"] = "Estoy cansado de\ncaminar. Necesito\vun descanso.",
  ["4f:4313"] = "¡Mi asignatura\nfavorita es la\vgimnasia!",
  ["4f:432e"] = "¡Oh, no! ¿Cómo he\npodido perder?",
  ["4f:4349"] = "¡Si los POKéMON\nfueran una\fasignatura, yo\nsería el mejor!",
  ["4f:437c"] = "RUTA 15\fCIUDAD FUCSIA -\nPUEBLO LAVANDA",
  ["4f:4458"] = "Que sepas que\nme costó mucho\fatrapar a mis\nqueridos POKéMON.",
  ["4f:4495"] = "¡Auuuu!",
  ["4f:449e"] = "SQUIRTLE, CHARMAN-\nDER y BULBASAUR.\fCreo que es una\nbuena combinación.",
  ["4f:44e8"] = "Mi sueño es volar\ncon mi querido\vPOKéMON pájaro.",
  ["4f:4517"] = "Puedo soñar, pero\nnunca podré volar.",
  ["4f:453a"] = "¿Tienes POKéMON\nque conozcan la\fMO VUELO? ¿Sí?\n¡Qué envidia!",
  ["4f:457a"] = "¿Has luchado\ncon todos los\fentrenadores\nde GIMNASIO?",
  ["4f:45a0"] = "¡Oh! ¡Demasiado\nfuerte para mí!",
  ["4f:45bd"] = "Las MEDALLAS de\nKANTO te ayudarán\fen los combates\ncon el CABLE LINK.",
  ["4f:46a7"] = "¡Arrodíllate ante\nmi regio POKéMON!",
  ["4f:46c7"] = "¿Qué? ¡Te burlas\nde la realeza!",
  ["4f:46e8"] = "¿Acaso no quiere\nser rey todo\vel mundo?",
  ["4f:4714"] = "¡Jijiji! ¿Quieres\nluchar contra mi\vgrupo de PIKACHU?",
  ["4f:4747"] = "¡PI, PIKACHU!",
  ["4f:4754"] = "Parece que tienes\nmuchos POKéMON,\fpero PIKACHU es\nel mejor.",
  ["4f:4796"] = "La agilidad es\nla clave de los\vPOKéMON pájaro.",
  ["4f:47c2"] = "Me venciste con\ntu velocidad…",
  ["4f:47e0"] = "Tus POKéMON\nestán muy bien\ventrenados.",
  ["4f:4809"] = "Mira mis\nPOKéMON. Fíjate\fen su color y\nen su plumaje.",
  ["4f:484e"] = "¡Vaya! ¡No soy lo\nbastante bueno!",
  ["4f:4867"] = "Los POKéMON son\nfelices si los\vpones guapos.",
  ["4f:488b"] = "Debería ir al\nTÚNEL ROCA para\vconseguir un ONIX.",
  ["4f:48be"] = "He perdido…",
  ["4f:48c7"] = "Parece que las\nformas geológicas\vno cambian.\fPero sí que\ncambian, aunque\vpoco a poco.",
  ["4f:4921"] = "PISTAS ENTRENADOR\f¡Mira! Allí, a\nla izquierda\vdel poste.",
  ["4f:4960"] = "RUTA 13 HACIA EL\fNORTE AL PUENTE\nSILENCIO",
  ["4f:4982"] = "HACIA EL NORTE\nAL PUEBLO LAVANDA\fHACIA EL OESTE\nA CIUDAD FUCSIA",
  ["4f:4a69"] = "La paciencia es la\nclave para pescar\vy criar POKéMON.",
  ["4f:4a9a"] = "¡Guaaa!",
  ["4f:4aa3"] = "No tengo paciencia\npara la pesca…",
  ["4f:4ac2"] = "Me gusta pescar\nmientras escucho\fcanciones por\nla radio.",
  ["4f:4b0b"] = "¡Mi estúpida radio\nme ha distraído!",
  ["4f:4b2b"] = "¿Conoces las\nemisoras de\fradio de KANTO?\nTenemos muchas.",
  ["4f:4b74"] = "¿Qué es lo más\nimportante en\vnuestras vidas?",
  ["4f:4ba5"] = "¡La respuesta\nvendrá luego!",
  ["4f:4bc4"] = "Creo que la\nelectricidad es lo\fmás importante en\nnuestras vidas.\fSi no lo fuera, no\nse habría montado\ftanto follón\ncuando se estropeó\fla CENTRAL\nde ENERGÍA.",
  ["4f:4c6b"] = "¿Te acuerdas?",
  ["4f:4c7d"] = "Te acuerdas, ¿no?",
  ["4f:4c8f"] = "El tirón de la\nCAÑA cuando ha\fpicado un\nPOKéMON…\fÉsa es la mejor\nsensación para un\vpescador como yo.",
  ["4f:4cf7"] = "RUTA 12\fPUEBLO LAVANDA\nHACIA EL NORTE",
  ["4f:4d18"] = "COTO DE PESCA",
  ["4f:4de8"] = "No se puede hacer\ntrampa en POKéMON.\f¡Que quede bien\nclaro!",
  ["4f:4e25"] = "¿Qué? ¿Cómo ha\npodido ocurrir?",
  ["4f:4e40"] = "He luchado con\nhonor.\fNo me\navergüenzo.",
  ["4f:4e81"] = "Cuando llevo\npantalones cortos\fpor la hierba, me\npican las piernas.",
  ["4f:4ebf"] = "¡Ayyyy!\n¡Me han pisado!",
  ["4f:4ed8"] = "Voy a capturar\nmás POKéMON en\vla hierba.",
  ["4f:4f03"] = "…",
  ["4f:4f06"] = "…",
  ["4f:4f09"] = "…\fPerdí cuando tenía\nlos ojos cerrados.",
  ["4f:4f2f"] = "Ya veo…\fTodo lo que hay\nque ver de ti…",
  ["4f:4f5b"] = "No me imaginaba\ntu poder…",
  ["4f:4f7a"] = "Fuerza de\nconvicción…\fEres fuerte porque\nconfías en tus\vPOKéMON.",
  ["4f:4fc6"] = "RUTA 11",
  ["4f:5048"] = "Menudo\nedificio, ¿eh?\fEs la TORRE de\nRADIO de KANTO.",
  ["4f:5080"] = "KANTO tiene muchos\nprogramas buenos.",
  ["4f:50a2"] = "Viene gente de\ntodas partes a\frendir homenaje\na las almas de\flos POKéMON\nque han partido.",
  ["4f:50f2"] = "Para despertar a\nlos POKéMON,\fsintoniza FLAUTA\nPOKéMON.\f¡Todo entrenador\ndebería saberlo!",
  ["4f:513d"] = "PUEBLO LAVANDA\fEl noble pueblo\npúrpura",
  ["4f:5162"] = "EMISORA DE\nKANTO\f¡Tus programas\nfavoritos a\vcualquier hora!",
  ["4f:51a7"] = "CASA POKéMON\nDE VOLUNTARIOS DE\vPUEBLO LAVANDA",
  ["4f:51c6"] = "CEMENTERIO\fQue las almas de\nlos POKéMON\vdescansen en paz",
  ["4f:5308"] = "CIUDAD CARMÍN\nes el puerto\fmás importante\nde KANTO.\fEn él atracan\nlujosos\ftransatlánticos\nde todo el mundo.",
  ["4f:5362"] = "Mi POKéMON está\npreparando el\fterreno donde\nedificar.\fPero no tengo\ndinero para el\vproyecto…",
  ["4f:53bd"] = "MACHOP: ¡Machop\nmachop!",
  ["4f:53d5"] = "Un MACHOP gruñe\nmientras pisotea\vel suelo.",
  ["4f:540d"] = "En KANTO hay ocho\nGIMNASIOS.\fEse gran edificio\nes el GIMNASIO\fPOKéMON de CIUDAD\nCARMÍN.",
  ["4f:5457"] = "SNORLAX duerme\nplácidamente…",
  ["4f:5477"] = "El POKéGEAR está\ncerca del\vSNORLAX dormido.\f…\f¡SNORLAX se\ndespertó!",
  ["4f:54bb"] = "Los entrenadores\nexpertos se reúnen\ven KANTO.\fLos LÍDERES de\nGIMNASIO son\vmuy fuertes.\fNo serán fáciles\nde vencer.",
  ["4f:551e"] = "¿Has conseguido ya\nalguna MEDALLA de\vGIMNASIO de KANTO?\f¿A que los\nentrenadores\fde KANTO son\nmuy fuertes?",
  ["4f:557b"] = "Supongo que pronto\nhabrás conseguido\ftodas las MEDALLAS\nde KANTO.\fCuando tengas\nlas ocho MEDALLAS,\vdímelo.",
  ["4f:55e6"] = "¡Enhorabuena!\fTienes todas las\nMEDALLAS de KANTO.\fTe recompensaré\npor tu esfuerzo.",
  ["4f:563d"] = "Llevar distintos\ntipos de POKéMON\fte debería ayudar\nen el combate.\fSeguro que las\nMEDALLAS de KANTO\vte ayudarán.",
  ["4f:56ac"] = "CIUDAD CARMÍN\fEl puerto de los\nocasos exquisitos",
  ["4f:56da"] = "LÍDER DEL GIMNASIO\nPOKéMON DE LA\fCIUDAD CARMÍN:\nLT. SURGE\fEl Rayo\nAmericano",
  ["4f:571b"] = "CLUB DE FANS\nDE POKéMON\v¡Bienvenidos!",
  ["4f:5741"] = "CUEVA DIGLETT",
  ["4f:5751"] = "ENTRADA AL PUERTO\nCARMÍN",
  ["4f:5820"] = "La carretera está\ncortada hasta que\farreglen la\nCENTRAL ENERGÍA.",
  ["4f:5864"] = "VÍA SUBTERRÁNEA\fCIUDAD CELESTE -\nCIUDAD CARMÍN",
  ["4f:5923"] = "Aquí vive una niña\nque es experta en\fimitar a la\ngente.\fImita incluso a\nla gente con\fla que habla,\ny te confunde.",
  ["4f:59a3"] = "La COPIONA parecía\nmuy triste.\fHabía perdido\nsu POKé MUÑECO\vCLEFAIRY favorito.",
  ["4f:59f6"] = "¿Eres de\nJOHTO?\fSi funcionara el\nMAGNETOTRÉN, no\ftardarías nada en\nvolver a casa.",
  ["4f:5a44"] = "¿Eres de\nJOHTO?\fCon el MAGNETOTRÉN\nenseguida estarás\ven casa.",
  ["4f:5a94"] = "Iba al GIMNASIO\na luchar contra\ventrenadores…\fY acabé en el\nviejo GIMNASIO\fque hay\nal lado.\f¡Chico, qué\nvergüenza pasé!",
  ["4f:5b24"] = "Es SILPH S.A.,\nfamosa por sus\vartículos POKéMON.\fEn el pasado, el\nTEAM ROCKET quiso\fhacerse con esta\ncompañía por esa\vmisma razón.",
  ["4f:5b92"] = "¡Ñam… ñam…!\fDicen que en la\nCENTRAL de ENERGÍA\ftienen muchos\nproblemas.\f¡Ñam… ñam…!",
  ["4f:5be1"] = "¡Ñam… ñam…!\fDicen que hay\nproblemas en la\vCENTRAL ENERGÍA.\f¡Ñam… ñam…!\n¡Estoy lleno!",
  ["4f:5c3b"] = "Entrar por primera\nvez en un callejón\fme pone un\npoco nervioso.",
  ["4f:5c7b"] = "En CIUDAD VERDE\nhay un lugar\fllamado la CASA\ndel ENTRENADOR,\fdonde se reúne\ngente de todas\vpartes.",
  ["4f:5cdb"] = "Nuestra ciudad\nsalió en un\vprograma de radio.\fEstá bien oír\nalabanzas sobre tu\fciudad, pero\ntambién da un poco\vde vergüenza.",
  ["4f:5d4d"] = "CIUDAD AZAFRÁN\fLa brillante y\ndorada tierra del\vcomercio",
  ["4f:5d7c"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\vAZAFRÁN: SABRINA\fMaestra de los\nPOKéMON psíquicos",
  ["4f:5dbf"] = "¡Bienvenidos!\nDOJO-KARATE",
  ["4f:5de0"] = "EDIFICIO-OFICINAS\nSILPH S.A.",
  ["4f:5dfb"] = "CASA DEL\nSR. PSÍQUICO",
  ["4f:5e0f"] = "ESTACIÓN DEL\nMAGNETOTRÉN DE\vCIUDAD AZAFRÁN",
  ["4f:5f1e"] = "La carretera está\ncortada hasta que\farreglen la\nCENTRAL ENERGÍA.",
  ["4f:5f62"] = "VÍA SUBTERRÁNEA\fCIUDAD CELESTE -\nCIUDAD CARMÍN",
  ["4f:5f93"] = "¿Qué es esto?\fCasa en venta…\nNo vive nadie.",
  ["4f:60b0"] = "La CENTRAL de\nENERGÍA de KANTO\festá al final de\nla RUTA 9. Hubo\funa especie de\naccidente.",
  ["4f:610c"] = "¿Vas a atrapar\ntodos los tipos\vde POKéMON?\fParece un gran\ndesafío, pero\vserá divertido.",
  ["4f:6170"] = "El CABO Norte es\nideal para llevar\fa una chica.\n¡Les encanta!",
  ["4f:61b1"] = "SLOWBRO: ¿Slow?",
  ["4f:61c2"] = "¡Mi SLOWBRO y yo\nformamos un equipo\vimpresionante!",
  ["4f:61f1"] = "¡SLOWBRO, enséñame\ntu CONFUSIÓN!",
  ["4f:6213"] = "…",
  ["4f:6216"] = "Soy un gran\nseguidor de\fla LÍDER MISTY\nde CIUDAD CELESTE.",
  ["4f:623d"] = "Vi a ese tipo\nsospechoso de\fcamino al CABO de\nCIUDAD CELESTE.",
  ["4f:6271"] = "Antes había una\ncueva aquí que\ftenía POKéMON\nrealmente fuertes.",
  ["4f:62b6"] = "¡Caray!\fMi BUSCAOBJETOS\nresponde…",
  ["4f:62da"] = "CIUDAD CELESTE\fUna misteriosa\naura azulada la\vrodea",
  ["4f:630d"] = "LÍDER DEL GIMNASIO\nPOKéMON DE LA\fCIUDAD CELESTE:\nMISTY\fLa Sirena\nDistorsionada",
  ["4f:6349"] = "Aquí hay una\nnota…\fLa TIENDA DE BICIS\nse ha trasladado a\fCIUDAD TRIGAL, en\nJOHTO…",
  ["4f:6394"] = "Aquí hay una\nnota…\f¡Acaba con los\nladrones y haz que\fla ciudad sea más\ngrata y alegre!\fPOLICÍA C. CELESTE",
  ["4f:6403"] = "Hacia el\nCABO CELESTE",
  ["4f:6418"] = "Está cerrada…",
  ["50:4080"] = "He venido a\nexplorar el\vTÚNEL ROCA.",
  ["50:40a0"] = "¡Uau! Peligro.",
  ["50:40b4"] = "Hirieron a mis\nPOKéMON antes\fde entrar al\nTÚNEL ROCA.\fSerá mejor que los\nlleve ahora mismo\fa un CENTRO\nPOKéMON.",
  ["50:411a"] = "¿Has ido alguna\nvez de picnic?\f¡Es muy\ndivertido!",
  ["50:414f"] = "¡Ohhhh!",
  ["50:4157"] = "Hacemos dulces y\nlos repartimos\fentre todos. ¡Son\ndeliciosos!",
  ["50:419d"] = "¡Eh, tú!\n¡No tires basura!",
  ["50:41b5"] = "Sólo estaba\ndiciendo que…",
  ["50:41d1"] = "Perdón. No estabas\ntirando basura. Me\vhe equivocado.",
  ["50:4202"] = "La gente no\ndebería dejar la\vbasura por ahí.",
  ["50:422c"] = "¡Ohh…! Perdí…",
  ["50:423a"] = "Es importante\nahorrar energía,\fpues el entorno es\naún más vital.",
  ["50:4283"] = "Ella se desviará\npor MT. PLATEADO\vcuando venga…\fMT. PLATEADO está\nen JOHTO, ¿verdad?",
  ["50:42d2"] = "Estaba ocupado\ncantando…",
  ["50:42eb"] = "Los combates son\ncuestión de\vconcentración.",
  ["50:430d"] = "Te contaré un\nsecreto.\fPero primero,\n¡luchemos!",
  ["50:433b"] = "¡Caray!\nHe perdido…",
  ["50:4353"] = "La CENTRAL ENERGÍA\nestá al otro lado\vde un riachuelo.",
  ["50:437d"] = "RUTA 9\fCIUDAD CELESTE -\nTÚNEL ROCA",
  ["50:443b"] = "¡Eh, chico! ¡Un\nmiembro del TEAM\vROCKET ser yo!\fSer de otro país.\nEntrenador número\vuno, ¡yo ése!\fPensar hice. Si\ncortar energía,\f¡mucho pánico\naquí todos!\fMisión secreta\nes, ¡no contar\va ti!\fPero, si ganar a\nmí, un hombre\fsoy y secreto mío\na ti contar.\f¡Eh, chico!\n¡Lucha empezar!",
  ["50:4574"] = "¡Ayyyy! ¡No, no,\nno! ¡Creer no\vpuedo!\f¡Fuerte mucho\neres! ¡Rival\vpara ti no soy!",
  ["50:45cd"] = "Vale. Secreto\ncontar a ti.\fMAQUINARIA robar\nhice, en el GIM.\fde CIUDAD\nCELESTE guardé.\fEn agua meter.\nEn el agua estar,\fen el centro\ndel GIMNASIO.\f¡Chico, olvidar\na mí, no!\fTEAM ROCKET ganar\na ti seguro.\fAmigos míos\nvenir de JOHTO.\fSí, venganza\nhabrá.",
  ["50:46f3"] = "…\f¿Dices que TEAM\nROCKET adiós?\f¿Roto? ¿Eso\ndices?\f¡Oh, no! ¿Debo\nir por cuenta\vmía ahora?",
  ["50:48e7"] = "MISTY: ¡Eh!\n¿Por qué\fhas venido a\nmolestarnos ahora?\f¿Sabes cómo llaman\na la gente\vcomo tú?\f¡Pesados! Me has\noído bien, pesado.\f…\f¡Oh! Esas\nMEDALLAS… ¿Son\fde los GIMNASIOS\nde JOHTO?\fSi tienes ocho,\nserás muy bueno.\fDe acuerdo. Ven\nal GIMNASIO de\vCIUDAD CELESTE.\fMe enfrentaré a\nti encantada.\fSoy MISTY, la\nLÍDER del GIMNASIO\vde CIUDAD CELESTE.",
  ["50:4a2e"] = "¡Véncenos a los\nseis para ganar\fun fantástico\npremio!\f¿Lo conseguirás?",
  ["50:4a83"] = "¡Uau! Muy bien.",
  ["50:4a96"] = "Hice lo que pude.\nNo me arrepiento.",
  ["50:4ab9"] = "Ahora me toca a\nmí. ¡En guardia!",
  ["50:4ad6"] = "¿Cómo he\npodido perder?",
  ["50:4ae9"] = "Hice lo que pude.\nNo me arrepiento.",
  ["50:4b0c"] = "¡Soy el tercero!\nY no será fácil.",
  ["50:4b2a"] = "¡Au! ¡Se acabó!",
  ["50:4b3d"] = "Hice lo que pude.\nNo me arrepiento.",
  ["50:4b60"] = "¡Yo soy la cuarta!\n¿Cansado?",
  ["50:4b7a"] = "He perdido…",
  ["50:4b87"] = "Hice lo que pude.\nNo me arrepiento.",
  ["50:4baa"] = "Yo soy el quinto.\n¡Te machacaré!",
  ["50:4bc8"] = "¡Uau! Demasiado.",
  ["50:4bd9"] = "Hice lo que pude.\nNo me arrepiento.",
  ["50:4bfc"] = "Y por último yo,\npero te lo aviso,\v¡soy la mejor!",
  ["50:4c2c"] = "¿Estás bromeando?",
  ["50:4c3c"] = "Hice lo que pude.\nNo me arrepiento.",
  ["50:4c5f"] = "¡Mufufufu…!\fNo tengo nada que\nver con los otros\vseis entrenadores.\fPero he esperado a\nque estés cansado\fde tanto pelear\npara vencerte.",
  ["50:4ce2"] = "¿No estás\ncansado?",
  ["50:4cfb"] = "Lo siento… No\nharé más trampas.",
  ["50:4d1c"] = "Tuviste que\nluchar una\fvez más, pero\nganaste.\fComo te prometí,\nel premio es tuyo.",
  ["50:4d7e"] = "Pero después de\nverte luchar, me\fgustaría saber\ncómo me iría a mí.\fDéjame luchar\ncontra ti.",
  ["50:4dde"] = "¡Nunca había visto\nnada igual!",
  ["50:4e01"] = "¡Ha sido\nfantástico!\fTus POKéMON y tú\nsois realmente\vbuenos.",
  ["50:4e48"] = "CASA DEL MAR\nCASA DE BILL",
  ["50:4f79"] = "¡Ah! Hace un\ntiempo estupendo.",
  ["50:4f9c"] = "Hace sol, pero\nestoy mojado…",
  ["50:4fb8"] = "Cuando llueve,\nes difícil\vencenderlo…",
  ["50:4fe2"] = "¡Mmm…! No sé\nqué hacer…",
  ["50:5001"] = "Sabía que\nperdería…",
  ["50:5012"] = "Parecías fuerte.\fMe daba miedo\ndesafiarte…",
  ["50:5043"] = "¡Puedo correr\ncomo el viento!",
  ["50:505d"] = "¡He perdido!",
  ["50:506a"] = "Siempre llevo\npantalones cortos.\fÉsa es mi forma\nde vestir.",
  ["50:50a8"] = "¡Sube y echa\nun vistazo!",
  ["50:50c8"] = "¡Uau! ¡Eso quema!",
  ["50:50d9"] = "Soy el mejor\nCOMEFUEGOS de\vKANTO.\fPero no el mejor\nentrenador…",
  ["50:5124"] = "PLAZA MT. MOON\fSube las\nescaleras",
  ["50:51d5"] = "Las noticias dicen\nque ha pasado algo\ven la C. ENERGÍA.",
  ["50:520a"] = "¿Perdí? ¡Vaya\nnoticia!",
  ["50:5223"] = "Tengo que ir a la\nCENTRAL ENERGÍA.\f¿Está cerca del\nTÚNEL ROCA?",
  ["50:525b"] = "Presiento que\npuedo ganar.\f¡Veamos si\ntengo razón!",
  ["50:5293"] = "¡Uau! Eres\ndemasiado fuerte.",
  ["50:52ad"] = "Dicen que CLEFAIRY\naparece en el\fMT. MOON.\n¿Pero dónde?",
  ["50:52eb"] = "¡Umm…!\nYo…",
  ["50:52f3"] = "…",
  ["50:52f6"] = "…Creo que seguiré\nentrenándome…",
  ["50:5311"] = "PLAZA MT. MOON\fSube las\nescaleras",
  ["50:53ef"] = "Somos el grupo de\nentrenadores de la\fFEDERACIÓN POKéMON\nde KANTO.\f¡Te vamos a\narrollar!",
  ["50:543f"] = "¡Lo…, lo siento!",
  ["50:5449"] = "¡Viva la\nFEDERACIÓN\vPOKéMON de KANTO!",
  ["50:5475"] = "Los polis han\ncerrado la VÍA\fSUBTERRÁNEA. ¡Qué\nfastidio!",
  ["50:54b5"] = "¡Per…, perdóname!",
  ["50:54c4"] = "Destruido por\nun gamberro\vde JOHTO…",
  ["50:54e8"] = "Somos la\nFEDERACIÓN\fPOKéMON de KANTO.\n¡Adelante, tío!",
  ["50:551b"] = "¡Vaya! ¡Perdona!",
  ["50:552a"] = "Intentaremos no\nmolestar a nadie\va partir de ahora.",
  ["50:5557"] = "¿Cómo funciona\nel MAGNETOTRÉN?",
  ["50:557a"] = "Quiero ver el\nMAGNETOTRÉN…",
  ["50:55a0"] = "¡El poder de los\nimanes es inmenso!",
  ["50:55c4"] = "Necesitamos\nelectricidad.\fLa CENTRAL ENERGÍA\nnos suministra la\velectricidad.",
  ["50:5615"] = "¡No malgastes\nelectricidad!",
  ["50:562e"] = "La C. ENERGÍA, al\nnorte de LAVANDA,\fsuministra energía\nal MAGNETOTRÉN.",
  ["50:5675"] = "Está cerrada…",
  ["50:5682"] = "El cartel\nestá roto.\fEs imposible\nleerlo…",
  ["50:571c"] = "CENTRAL DE\nENERGÍA DE KANTO",
  ["50:5776"] = "¡Ja, ja, ja!",
  ["50:5780"] = "¡Aaaaaaachís!",
  ["50:5790"] = "¡La alergia me\nhace estornudar!\v¡AAACHÚS!",
  ["50:57bd"] = "Te gustan los\nPOKéMON, ¿verdad?\f¡A mí también!",
  ["50:57df"] = "Tengo que decir\nque son mi ruina.",
  ["50:57fe"] = "Mira lo que\nhas hecho a\vmis POKéMON.\fNo lo\nolvidaré…",
  ["50:5831"] = "RUTA 10\fCIUDAD CELESTE -\nPUEBLO LAVANDA",
  ["50:588f"] = "MESETA AÑIL\f¡El objetivo\nfinal de los\ventrenadores!\fEl CG de la\nLIGA POKéMON",
  ["51:400e"] = "Los marineros son\nmuy generosos.\fUno enseñó FUERZA\na mi POKéMON y\fahora puede mover\ngrandes rocas.",
  ["51:4067"] = "Hay una persona en\nCIUDAD ORQUÍDEA,\vcruzando el mar.\f¡Dicen que\npresume de sus\vraros POKéMON!",
  ["51:419a"] = "Gracias por\nayudarnos en el\vFARO…\fPero esto es\ndistinto. Déjame\vque me presente.\fSoy YASMINA, una\nLÍDER de GIMNASIO.\vUso el tipo acero.\f¿Sabes algo\ndel tipo acero?\fFue descubierto\nhace poco\vtiempo.\f¡Um…! ¡Veamos!",
  ["51:429c"] = "Eres mejor\nentrenador que yo,\ftanto en habilidad\ncomo en simpatía.\fDe acuerdo con las\nnormas de la LIGA,\fte concedo esta\nMEDALLA.",
  ["51:431b"] = "{PLAYER}\nrecibió la\vMEDALLA MINERAL.",
  ["51:4335"] = "La MEDALLA MINERAL\naumenta la DEFENSA\vde los POKéMON.\f¡Eh…! Toma\nesto también…",
  ["51:4386"] = "Usa esta MT\npara enseñar\vCOLA FÉRREA.",
  ["51:43b2"] = "¡Eh…! No sé\ncómo decirlo, pero\vbuena suerte…",
  ["51:43e3"] = "YASMINA usa el\ntipo acero recién\vdescubierto.\fNo sé mucho\nsobre ese tipo.",
  ["51:4432"] = "Ha sido increíble.\f¿El tipo acero,\neh?\f¡Ha sido un gran\ncombate de un\vtipo desconocido!",
  ["51:4489"] = "YASMINA, la LÍDER\ndel GIMNASIO, está\ven el FARO.\fHa estado cuidando\na un POKéMON\venfermo.\fUn buen entrenador\ndebe de ser\vcompasivo.",
  ["51:4583"] = "Cuando mis POKéMON\nenfermaron, el\fFARMACÉUTICO de\nCIUDAD IRIS me\vdio una medicina.",
  ["51:45d1"] = "RHYDON: ¡Rhydo!",
  ["51:4624"] = "De camino a CIUDAD\nORQUÍDEA, hay\fcuatro islas\ndesiertas.\f¡A los niños malos\nlos llevan a\flas islas como\ncastigo!",
  ["51:4692"] = "Cuando me meto en\nlíos, papá siempre\vse enfada.",
  ["51:472a"] = "¡CIUDAD OLIVO está\njunto al mar!\f¡Y si está junto\nal mar, tiene que\vhaber peces!\fLlevo 30 años\npescando aquí.\f¿Quieres mirar\nal mar y\vpescar?",
  ["51:47bc"] = "¡Ah, ja, ja!\n¡Ya tenemos un\vnuevo pescador!",
  ["51:47e8"] = "No sólo hay peces\nen el mar. Puedes\fencontrarlos allí\ndonde haya agua.",
  ["51:482d"] = "¿Quééé? ¿¡No te\ngusta pescar!?\v¡Incomprensible!",
  ["51:4860"] = "¿Qué tal va todo?\n¿Pica el grande?",
  ["51:48bd"] = "¡Ajá! ¡Tus POKéMON\nparecen muy\vdébiles!\fNo son capaces\nde mover\vrocas.\f¡Toma! ¡Usa esto\ny enséñales\vFUERZA!\fNecesitas la\nMEDALLA TRIGAL\fpara usar FUERZA\nfuera del combate.",
  ["51:4980"] = "¡En el mar sólo\npuedes confiar\ven ti mismo!\f¡Y yo estoy en\nplena forma!",
  ["51:49e0"] = "¿Vas a cruzar el\nmar? Pues escucha:\fhay torbellinos\nde camino hacia\vCIUDAD ORQUÍDEA.\fPara pasar los\ntorbellinos,\ftienes que conocer\nun movimiento más.",
  ["51:4aaa"] = "¿Tus POKéMON saben\nun movimiento para\fllevar personas\npor el agua?",
  ["51:4aec"] = "Mi BUTTERFREE ha\nestado con mi\vnovio.\fY me ha traído\nuna CARTA suya.\f¿Quieres saber\nlo que dice?\fVeamos… ¡No!\n¡Es un secreto!",
  ["51:4bb0"] = "¿De dónde has\ndicho que eras?\f¿De PUEBLO\nPRIMAVERA?\fEl PROF. ELM vive\npor allí, ¿no?\fHas recorrido un\nlargo camino.",
  ["51:4d04"] = "MUU-MUU está\nenferma…\fNecesita muchas\nBAYAS.",
  ["51:4d30"] = "¡Estamos dando de\ncomer a MUU-MUU!",
  ["51:4d46"] = "MUU-MUU: ¡Muu…!",
  ["51:4d56"] = "Está débil…",
  ["51:4d68"] = "MILTANK: ¡MUU!",
  ["51:4d77"] = "¿Dar una BAYA a\nMUU-MUU?",
  ["51:4d91"] = "{PLAYER} dio una\nBAYA a MUU-MUU.",
  ["51:4dad"] = "¡MUU-MUU está un\npoco mejor!",
  ["51:4dd1"] = "¡MUU-MUU está\nmucho mejor!",
  ["51:4df0"] = "¡MUU-MUU se ha\nrecuperado!",
  ["51:4e11"] = "{PLAYER} no tiene\nBAYAS…",
  ["51:4e24"] = "{PLAYER} no le\nda una BAYA.\fMUU-MUU parece\ntriste.",
  ["51:4f0d"] = "Mi MUU-MUU ya\nno me da\vleche.\fLa leche de esta\nGRANJA es famosa.\fCasi todos\nquieren probarla.\fSupongo que si\nle doy muchas\fBAYAS me dará\nmucha leche.",
  ["51:4fb7"] = "¿Te gusta mi\nLECHE MU-MU?\fEs mi orgullo y\nmi alegría, hijo.\f¡Dásela a los\nPOKéMON para\vrestaurar sus PS!\fTuya es por\nsólo 500¥.",
  ["51:5031"] = "¡Toma! ¡Bébetela\ny disfruta!",
  ["51:5050"] = "Lo siento, hijo.\n¡Si no hay dinero,\vno hay trato!",
  ["51:506f"] = "Hijo, tu MOCHILA\nestá llena.",
  ["51:508e"] = "¿No la quieres?\nVuelve otro día.",
  ["51:50b3"] = "Mejor que me vaya\na ordeñar.",
  ["51:50cd"] = "Nuestra leche\nllega hasta KANTO.\fAsí que si nuestra\nMUU-MUU no nos da\fleche, tendremos\nproblemas.",
  ["51:512d"] = "Has curado a\nnuestra MUU-MUU.\fYa vuelve a dar\nLECHE MU-MU.\fAquí tienes algo\nque te ayudará.",
  ["51:519e"] = "Esto es\nRONQUIDO.\fEs un movimiento\nraro que sólo\ffunciona cuando el\nPOKéMON duerme.\fMejor que pienses\ncómo vas a\vutilizarlo.",
  ["51:526c"] = "Dicen que ha\naparecido un\fGYARADOS rojo\nen el LAGO.\f¡Qué raro, porque\nen el lago no son\ffrecuentes ni los\nGYARADOS comunes!",
  ["51:52de"] = "¿Mi programa de\nradio favorito? La\vMÚSICA POKéMON.",
  ["51:530d"] = "He estado oyendo\nrisas en la\fradio… Es\nespeluznante.",
  ["51:545d"] = "Los POKéMON viven\ntodo tipo de\vexperiencias.\fYo también he\nvisto y sufrido\vmucho en mi vida.\fSoy más mayor, así\nque te enseñaré lo\vque quiero decir.\fHe estado con los\nPOKéMON desde\fantes de que tú\nnacieras.\fY no pierdo\nfácilmente.\f¡Yo, FREDO, el\nentrenador del\finvierno, te\nmostraré mi poder!",
  ["51:5583"] = "¡Ah! Me impresiona\ntu valor.\fCon tu gran\nvoluntad, sé que\fsuperarás todos\nlos obstáculos.\f¡Te mereces\nesta MEDALLA!",
  ["51:560b"] = "{PLAYER}\nrecibió la\vMEDALLA GLACIAR.",
  ["51:5625"] = "Esta MEDALLA sube\nlas habilidades\fESPECIALES de los\nPOKéMON.\fY tus POKéMON\nusarán TORBELLINO\fpara pasar los\ntorbellinos.\f¡Además, te voy\na hacer un regalo!",
  ["51:56bf"] = "Esta MT contiene\nVIENTO HIELO.\fCausa daño y baja\nla velocidad.\fDemuestra la\ndureza del\vinvierno.",
  ["51:5729"] = "La primavera llega\ncuando se derrite\fel hielo y la\nnieve.\fTú y tus POKéMON\npasaréis juntos\vmuchos años.\f¡Pasadlo\nbien!",
  ["51:57b1"] = "¡Congelaré a tus\nPOKéMON! ¡No\vpodrás hacer nada!",
  ["51:57e0"] = "Maldición. No\npude hacer nada.",
  ["51:57fd"] = "Hay un movimiento\nque se puede usar\fcuando el POKéMON\nestá congelado.",
  ["51:5835"] = "Este GIMNASIO\ntiene un suelo\fresbaladizo. ¿A\nque es divertido?\f¡Pero oye, aquí\nno estamos\vjugando!",
  ["51:588d"] = "¿Ves lo serios\nque somos?",
  ["51:58ad"] = "Este GIMNASIO es\ngenial. ¡Me\fencanta patinar\ncon mis POKéMON!",
  ["51:58df"] = "Conozco el secreto\nde FREDO.",
  ["51:58f6"] = "Te contaré el\nsecreto de FREDO.",
  ["51:5917"] = "El secreto del\npoder de FREDO…\fMedita todos los\ndías bajo una\fcascada para\nmejorar su cuerpo\vy su mente.",
  ["51:597e"] = "Para vencer a\nFREDO, el LÍDER\fdel GIM., piensa\nantes de patinar.",
  ["51:59c4"] = "¡No perderé ante\nti esquiando!",
  ["51:59e6"] = "Si no patinas con\nprecisión, no\flograrás nada en\neste GIMNASIO.",
  ["51:5a27"] = "¡Mira qué bien\nesquío!",
  ["51:5a44"] = "¡No! ¡He perdido!",
  ["51:5a5f"] = "No debería haber\npresumido sobre mi\vforma de esquiar.",
  ["51:5a8f"] = "FREDO es veterano.\nLleva entrenando\fPOKéMON desde\nhace 50 años.\fDicen que es bueno\ncongelando a sus\frivales con los\nataques de hielo.\f¡Eso quiere decir\nque deberías\fderretirle con tu\nardiente ambición!",
  ["51:5b45"] = "¡FREDO es bueno,\npero tú eres\vaún mejor!\f¡Ha sido un gran\ncombate que acortó\fdistancias entre\ngeneraciones!",
  ["51:5c32"] = "¿Qué pasa?\n¿Ha vuelto el\vTEAM ROCKET?\fHe visto hombres\nde negro en el\vLAGO DE LA FURIA.",
  ["51:5c83"] = "No permito que\nmis POKéMON\fevolucionen\ndemasiado pronto.\fAntes de dejarles\nevolucionar, les\fenseño algunos\nmovimientos.",
  ["51:5ce8"] = "Al evolucionar,\nlos POKéMON se\ffortalecen, pero\ntardan más en\vaprender ataques.",
  ["51:5d88"] = "MONTE MORTERO es\ncomo un laberinto.\fTen cuidado. No\nte pierdas.",
  ["52:406c"] = "Sin la MEDALLA\ndel GIMNASIO de\fCIUDAD IRIS, no se\nentra en la TORRE\fHOJALATA. ¡Vaya,\ntendrás que irte!",
  ["52:40cc"] = "Sin la MEDALLA\nde CIUDAD IRIS,\fno se entra en\nTORRE HOJALATA.\f¡Ah!\f¡La MEDALLA de\nla CIUDAD IRIS!\vPuedes pasar.",
  ["52:413f"] = "La TORRE HOJALATA\nse construyó como\fmorada para los\nPOKéMON voladores.",
  ["52:417d"] = "¡La TORRE HOJALATA\nse ha movido! ¡Se\fhabrá posado un\nPOKéMON arriba!",
  ["52:41b9"] = "Dos torres…\nDos POKéMON…\fPero cuando una\nse quemó, los dos\fPOKéMON huyeron\ny nunca volvieron.",
  ["52:4304"] = "Hola, soy BILL.\n¿Quién eres tú?\f¿Eh? {PLAYER}.\n¡Has llegado\vjusto a tiempo!",
  ["52:434e"] = "Ya he terminado de\najustar la CÁPSULA\vdel TIEMPO.\fSabes que puedes\ncambiar POKéMON,\v¿verdad?\fMi CÁPSULA del\nTIEMPO sirve para\fcambiar POKéMON\ncon el pasado.\fPero no podrás\nenviar nada que\fno existiera en\nel pasado.\fSi lo haces, el PC\ndel pasado podría\vestropearse.\fAsí que debes\neliminar cualquier\fcosa que no\nexistiera antes.\fEsto es, no envíes\nnuevos movimientos\fo nuevos POKéMON\na esta CÁPSULA.\fNo te preocupes.\nYa he acabado\vde ajustarla.\fMañana funcionarán\ntodas las CÁPSULAS\fdel TIEMPO de los\nCENTROS POKéMON.\fDebo volver pronto\na CIUDAD TRIGAL.\vMi familia espera.\f¡Hasta luego!",
  ["52:4581"] = "Las CHICAS KIMONO\nson unas geniales\fbailarinas, además\nde magníficas\vcon sus POKéMON.",
  ["52:45d6"] = "MORTI, el LÍDER\ndel GIMNASIO, es\vmuy bueno.\fY sus POKéMON\nson muy fuertes.",
  ["52:461c"] = "LAGO DE LA FURIA.\fUn montón de\nGYARADOS…\f¡Esto huele a\nconspiración!",
  ["52:46d3"] = "Sucedió cuando\nera joven.\fEl cielo se\noscureció de\frepente. Un enorme\nPOKéMON estaba\vtapando el sol.\fMe pregunto qué\nsería ese POKéMON,\fmezcla de pájaro\ny dragón.",
  ["52:4782"] = "¿Existe un POKéMON\ntan grande? Si\fexiste, debe de\nser muy fuerte.",
  ["52:48b8"] = "Tus POKéMON son\nencantadores.\v¿Cómo luchan?",
  ["52:48e9"] = "¡Oh! ¡Eres muy\nfuerte!",
  ["52:4903"] = "Me ha gustado el\ncombate. Espero\vvolver a verte.",
  ["52:4938"] = "Yo siempre bailo\ncon mis POKéMON.\fY también los\nentreno, claro.",
  ["52:4974"] = "¡Estuve cerca!\nPor poco te venzo.",
  ["52:4995"] = "El ritmo es muy\nimportante para\fla danza y para\nlos POKéMON.",
  ["52:49c9"] = "¿Te gusta\nmi pasador?\f¡Ah! ¿Un combate\nPOKéMON?",
  ["52:49f6"] = "No me queda ningún\nPOKéMON…",
  ["52:4a12"] = "Cada mes pongo\nuna flor nueva\ven mi pasador.",
  ["52:4a4a"] = "¡Oh! ¡Eres\ntan mono!\v¿Quieres luchar?",
  ["52:4a7f"] = "Eres más fuerte de\nlo que pareces.",
  ["52:4a9e"] = "He entrenado mucho\ny creía que tenía\fposibilidades,\npero no.",
  ["52:4ae6"] = "¿Te gusta como\nbailo? Y también\fsoy hábil con\nlos POKéMON.",
  ["52:4b14"] = "¡Oh! ¡Tú también\neres bueno!",
  ["52:4b32"] = "Sigo bailando\nporque hay gente\fa la que le gusta\nlo que hago.\fMis POKéMON\nme animan.",
  ["52:4b94"] = "Las CHICAS KIMONO\nno sólo bailan.\fTambién son\nextraordinarias\vcon los POKéMON.\fYo siempre las\ndesafío pero nunca\fles he hecho\nni un rasguño…",
  ["52:4c1b"] = "¡Chico! Si vences\na todas las CHICAS\fKIMONO, te daré\nun regalo.",
  ["52:4c5e"] = "Verte luchar ha\nsido como ver\vuna danza.\f¡Ha sido un\nextraño combate!\fMe gustaría darte\nesto. Adelante,\v¡tuyo es!",
  ["52:4cdf"] = "Es SURF.\fUn movimiento\nque permite nadar\va los POKéMON.",
  ["52:4d19"] = "Ojalá mis POKéMON\nfueran tan\felegantes como las\nCHICAS KIMONO…",
  ["52:4d4e"] = "RHYDON: ¡Rhydo,\nrhydo!",
  ["52:4d68"] = "Ese hombre siempre\nva con su RHYDON.\fDice que quiere un\nPOKéMON que baile\vy haga SURF.\f¿Intenta crear\nun POKéMON que\fhaga natación\nsincronizada?",
  ["52:4dee"] = "Las CHICAS KIMONO\nson tan guapas…\fPero tienen que\nentrenar mucho.\fY deben aprender\nlos distintos\fbailes antes\nde actuar.\fPero si te gusta\nalgo, todo\ves posible.",
  ["52:4ebd"] = "Es un elegante\npanel decorado\vcon flores.",
  ["52:4f8c"] = "Mi EEVEE\nevolucionó en\vESPEON.\fPero el EEVEE\nde mi amigo\fevolucionó en\nUMBREON.\fNo sé por qué. Los\ndos educamos a\fnuestros EEVEE de\nla misma forma…",
  ["52:5019"] = "Si usas REVIVIR,\nel POKéMON\fdebilitado se\nreanimará.",
  ["52:516b"] = "Me alegro de que\nhayas venido.\fEn CIUDAD IRIS,\nveneramos a los\vPOKéMON.\fDicen que a los\nentrenadores más\ffuertes se les\naparecerán los\fPOKéMON\nlegendarios.\fYo lo creo y he\nentrenado aquí\fen secreto toda\nmi vida.\fPor eso, ahora\nveo lo que otros\vno ven.\fUn poco más…\fUn poco más y\nen el futuro\fencontraré a\nlos POKéMON\vlegendarios.\f¡Y tú me vas a\nayudar a llegar\va ese nivel!",
  ["52:52f4"] = "Aún no soy lo\nbastante bueno…\fDe acuerdo. Esta\nMEDALLA es tuya.",
  ["52:532d"] = "{PLAYER}\nrecibió la\vMEDALLA NIEBLA.",
  ["52:5343"] = "Con la MEDALLA\nNIEBLA, te\fobedecerán todos\nlos POKéMON\vhasta el nivel 50.\fY los POKéMON\nque sepan SURF\fpodrán usarlo en\ncualquier momento.\fQuédate con\nesto también.",
  ["52:53d6"] = "Es BOLA SOMBRA.\nCausa daños y\fpuede reducir la\nDEFENSA ESPECIAL.\fÚsala si te\ngusta.",
  ["52:542f"] = "Entiendo…\fTu viaje te\nha llevado a\vtierras lejanas.\fY has presenciado\nmuchas más cosas\vque yo.\f¡Cómo te\nenvidio…!",
  ["52:54a7"] = "Pasé la primavera\ncon mis POKéMON.\fY el verano, otoño\ne invierno.\fLuego volvió la\nprimavera. Hemos\fvivido juntos\nmucho tiempo.",
  ["52:5527"] = "Viví victorias\ny derrotas.",
  ["52:554d"] = "¿De dónde vienen\nlos POKéMON?",
  ["52:5568"] = "¿Puedes causar\nalgún daño a\vnuestros POKéMON?",
  ["52:5591"] = "¡Ah! ¡Bien hecho!",
  ["52:55a1"] = "Sólo usamos\nPOKéMON fantasma.\f¡Los ataques\nnormales no les\vhacen daño!",
  ["52:55e5"] = "¡Ganaré!",
  ["52:55f3"] = "¡He… he perdido!",
  ["52:5602"] = "¡Ganará el que\nmás lo desee!",
  ["52:5628"] = "¿Atónito por el\nsuelo invisible?\f¡Si quieres una\npista, vénceme!",
  ["52:5669"] = "¿Có-Cómo?",
  ["52:5674"] = "Bien. Te contaré\nel secreto\fdel suelo\ninvisible.\f¡La ruta está\nenfrente de ti!",
  ["52:56d2"] = "Estos entrenadores\ntienen motivos\vsecretos.\fSi les ganas,\npodrían contarte\falgunos secretos\nsobre CIUDAD IRIS.",
  ["52:573c"] = "¡Uauu, {PLAYER}!\n¡Genial!\f¡Me escondí en\nel rincón\vmuerto de miedo!",
  ["52:58cc"] = "¡Ah! ¿Vas de\naventura con tus\vPOKéMON?\f¿Y qué es una\naventura sin\vun tesoro?\f¿Tengo razón\no no?",
  ["52:5945"] = "¡Bien! Entiendes\nel verdadero\fespíritu de\nla aventura.\f¡Me gusta!\nToma esto.",
  ["52:599e"] = "Por aquí hay\nmuchos objetos\fque no se ven\ntan fácilmente.\fUtiliza el\nBUSCAOBJETOS para\fsaber si hay algún\nobjeto cerca.\fÉste no indica el\nlugar exacto, así\fque tú tendrás\nque encontrarlo.\f¡Ah, sí! Dicen que\nhay muchos objetos\fen TORRE QUEMADA\nde CIUDAD IRIS.",
  ["52:5a95"] = "¡Oh! A cada uno lo\nsuyo, supongo…",
  ["52:5ab6"] = "HISTORIA de\nCIUDAD IRIS\f¿Quieres leerla?",
  ["52:5adc"] = "En CIUDAD IRIS\nhabía dos torres.\fCada una acogía a\nun fuerte POKéMON\vvolador.\fPero una de\nellas se quemó.\fY desde entonces\nno se ha visto a\fninguno de los\ndos POKéMON.\f¿Seguir leyendo?",
  ["52:5b92"] = "En CIUDAD IRIS\ntambién vivían\ftres POKéMON\nque corrían por\vtoda la ciudad.\fDicen que habían\nnacido del agua,\fdel fuego y del\nrayo.\fPero como no\npodían contener su\venorme fuerza…\fHuyeron hacia\nlos pastos.",
  ["53:40f3"] = "Soy DÉBORA, la\nmejor maestra\fde dragones\ndel mundo.\fNo pueden conmigo\nni los miembros\fdel ALTO MANDO de\nla LIGA POKéMON.\f¿Todavía quieres\nluchar conmigo?\fEstá bien.\n¡Luchemos!\f¡Como entrenadora,\nusaré todo mi\fpoder contra\ncualquier rival!",
  ["53:41cf"] = "¿He perdido?\fNo puedo creerlo.\nHa debido de haber\valgún error…",
  ["53:4207"] = "No lo\nadmitiré.\fHabré perdido,\npero aún no estás\fpreparado para la\nLIGA POKéMON.\fLo sé. Deberías\nenfrentarte al\fdesafío de los\nque usan dragones.\fDetrás de este\nGIMNASIO está la\vGUARIDA DRAGÓN.\fVe allí y tráeme\nel COLMILLO de\fDRAGÓN que hay\nen la GUARIDA.\fÉsa es la prueba\nque debes aceptar\fsi de verdad usas\ndragones.\fSi lo logras,\nte aceptaré\vcomo entrenador.\fHasta entonces, no\nte daré ninguna\vMEDALLA.",
  ["53:4391"] = "DÉBORA: ¿Cuál es\nel problema?\fEsta prueba no te\ncostará, salvo que\fhayas ganado\nde chiripa.",
  ["53:43f0"] = "DÉBORA: No has\nconseguido eso en\vla GUARIDA DRAGÓN.\fEstás haciendo\ntrampas…\fMe has\ndecepcionado.",
  ["53:4451"] = "DÉBORA: Me has\ndemostrado lo que\vvales.\fEsta MT es\npara ti.",
  ["53:44a7"] = "Esta MT contiene\nDRAGOALIENTO.\fNo, no tiene\nnada que ver\vcon mi aliento.\fSi no la quieres,\nno es necesario\vque la aceptes.",
  ["53:4525"] = "Así que has\nconseguido todas\vlas MEDALLAS.\fAhora debes\ndirigirte a la\fLIGA POKéMON\nde MESETA AÑIL.\f¿Sabes cómo llegar\nhasta allí?\fDesde aquí, ve a\nPUEBLO PRIMAVERA.\fLuego haz SURF\nhacia el Este. Es\vuna ruta difícil.\f¡Ni se te ocurra\nperder en la\vLIGA POKéMON!\f¡Si pierdes, me\nsentiré aún peor\fpor haber perdido\nante ti!",
  ["53:4651"] = "¿Tu primer combate\ncontra dragones?\f¡Te mostraré lo\nfuertes que son!",
  ["53:4696"] = "¡Qué decepción!",
  ["53:46a8"] = "¿Viste a LANCE, el\nmaestro de los\fdragones? No puede\nser cierto.",
  ["53:46e5"] = "¿Mis posibilidades\nde perder? ¡Ni el\vuno por ciento!",
  ["53:4711"] = "Es extraño.",
  ["53:471d"] = "Ahora sé cuál es\nmi punto débil.\f¡Gracias por\nenseñármelo!",
  ["53:4753"] = "Los dragones son\nPOKéMON sagrados.\fEstán llenos de\nenergía vital.\fSi no eres\nserio, no\fpodrás acabar\ncon ellos.",
  ["53:47c0"] = "¡Adelante!",
  ["53:47cc"] = "Los dragones son\ndébiles contra los\fmovimientos del\ntipo dragón.",
  ["53:47fa"] = "¡Hola, futuro\ncampeón!\f¡Ha sido un largo\nviaje, pero casi\fhemos acabado!\n¡Confía en mí!\fDÉBORA usa los\nmíticos y sagrados\fPOKéMON de tipo\ndragón.\fNo son fáciles\nde dañar.\fPero se supone\nque son débiles\fcontra los ataques\ndel tipo hielo.",
  ["53:48e8"] = "¡Genial! ¡Has\nvencido a DÉBORA!\fSólo te queda el\ndesafío de la\vLIGA POKéMON.\f¡Vas a convertirte\nen el CAMPEÓN\vPOKéMON!",
  ["53:4a3f"] = "No es como si\ntodos usáramos\vPOKéMON dragón.\fMi política es\nusar POKéMON más\ffuertes que los\nPOKéMON dragón.",
  ["53:4aa9"] = "Eres especial…",
  ["53:4abb"] = "¡Tú observa!\nMis POKéMON se\fharán aún más\nfuertes.\fSeremos un\nentrenador y un\fequipo POKéMON\nmás fuertes.",
  ["53:4b20"] = "DÉBORA nos ha\nentrenado a\fconciencia. No\npuedo perder.",
  ["53:4b69"] = "¡Arrrg!\n¡Qué disgusto!",
  ["53:4b83"] = "¡Uau…! ¡Tendré\nque replantearme\vmi entrenamiento!",
  ["53:4bad"] = "¡La piedra cayó\npor el agujero!",
  ["53:4c64"] = "DÉBORA y LANCE\nentrenaron aquí\fpara perfeccionar\nsus técnicas.",
  ["53:4ca4"] = "DRATINI: ¡Draa!",
  ["53:4d20"] = "No puedes comprar\nMÁX. REVIVIR. Pero\féste reanima\na un POKéMON\vdebilitado.\fAtención: No\nrestaura los PP o\fPUNTOS de PODER de\nlos movimientos.",
  ["53:4d9f"] = "MÁX. REPEL evita\nque se acerquen\vPOKéMON débiles.\fEs el repelente\nmás duradero\vde todos.",
  ["53:4e3b"] = "En el corazón de\nla remota MESETA\fAÑIL se celebra la\nLIGA POKéMON.\fDicen que allí se\nreúnen los mejores\fentrenadores de\ntodo el país.",
  ["53:4eb3"] = "Tenía un\nmovimiento que\fquería enseñar\na mi POKéMON.\fAsí que usé el\nQUITA-MOVIMIENTOS\vy eliminé una MO.",
  ["53:4fa7"] = "Parece que BLAINE,\ndel GIMNASIO de\fISLA CANELA, vive\nsolo en la cueva\vde ISLAS ESPUMA…",
  ["53:4ff1"] = "El volcán hizo\nerupción hace\vun año.",
  ["53:507c"] = "El volcán de ISLA\nCANELA ha entrado\ven erupción.\fY ha lanzado rocas\nque han cortado la\fRUTA 19 hasta\nnuevo aviso.\fMe pregunto si la\ngente de ISLA\fCANELA estará\nbien…",
  ["53:50fc"] = "Nadie en ISLA\nCANELA resultó\fherido por la\nerupción. ¡Bien!",
  ["53:51ba"] = "BLAINE: ¡Buaaa!\fMi GIMNASIO de\nISLA CANELA se ha\vquemado.\fEl volcán nos ha\ndejado sin casa a\fmis POKéMON\ncomefuego y a mí.\f¡Buaaaa!\fPero sigo haciendo\nmi trabajo de\fLÍDER de GIMNASIO\nen esta cueva.\fSi me vences,\nte daré una\vMEDALLA.\f¡Ja! Espero que\ntengas ANTIQUEMAR.",
  ["53:52b8"] = "BLAINE: Increíble.\nMe consumí…\f¡Has ganado la\nMEDALLA VOLCÁN!",
  ["53:52f5"] = "{PLAYER} recibió\nla MED. VOLCÁN.",
  ["53:530f"] = "BLAINE: Esta vez\nhe perdido, pero\fla próxima te\nganaré.\fCuando reconstruya\nmi GIMNASIO de I.\fCANELA, tendremos\nla revancha.",
  ["53:538e"] = "BLAINE: Mis\nPOKéMON de fuego\fserán más fuertes.\n¡Ya lo verás!",
  ["53:53cb"] = "¡Vaya!\f¿Eh…? ¿Ya\nha acabado?\f¡Lo siento, tío!\fEl GIMNASIO de\nISLA CANELA ya no\fexiste y no sabía\ndónde encontrarte.\fPero eres fuerte\nhasta sin mis\fconsejos. ¡Sabía\nque ganarías!",
  ["53:5477"] = "Los GIMNASIOS\nPOKéMON están allí\fdonde se encuentre\nsu LÍDER.\fNo es necesario\nun edificio.",
  ["53:5521"] = "Te has\nperdido…\fAquí he meditado.\nUn nuevo poder se\fha despertado\ndentro de mí.\fDéjame compartir\nmi poder con tus\fPOKéMON.\nToma esto, hijo.",
  ["53:55b4"] = "¿Lo ves? ¡Es PODER\nOCULTO!\fSaca el poder de\nlos POKéMON para\vatacar.\fRecuerda: su tipo\ny poder dependen\fdel POKéMON\nque lo usa.",
  ["53:5649"] = "Estoy meditando…",
  ["53:5704"] = "El LAGO DE LA\nFURIA es un cráter\fobra de violentos\nGYARADOS.\fEl cráter se llenó\nde agua de la\flluvia y se formó\nel LAGO.\fEsta historia la\ncontó por primera\fvez el tatarabuelo\nde mi abuelo.\fAntes se podían\npescar MAGIKARP\fen el lago,\npero…\fNo entiendo lo\nque ocurre ahora.",
  ["53:5823"] = "En el LAGO pasan\ncosas raras desde\fque llegaron esos\nhombres de negro.",
  ["53:5866"] = "La normalidad ha\nvuelto al LAGO DE\fLA FURIA. Vuelve a\nhaber MAGIKARP.\fQuizá se cumpla\nmi sueño de ver\fal MAGIKARP más\ngrande del mundo.\f¿Tienes una CAÑA?\nSi tienes una,\vayúdame por favor.",
  ["53:5914"] = "¡Ah, tienes un\nMAGIKARP! A ver\flo grande que es\nese bebé.",
  ["53:594d"] = "¡Uau! ¡Éste es\nimpresionante!\f¡Me quito el\nsombrero ante ti!\f¡Toma esto como\nrecuerdo!",
  ["53:5999"] = "Lo importante es\nel récord. ¡Piensa\fen él como una\nbonificación!",
  ["53:59d7"] = "¡Uau! ¡Éste es\nimpresionante!\fOjalá no tuviera\nque decirlo, pero\fhe visto uno más\ngrande antes.",
  ["53:5a32"] = "¿Qué? ¡Eso no es\nun MAGIKARP!",
  ["53:5a4f"] = "¿No tienes ninguno\nbueno para\fenseñármelo? Quizá\nla próxima vez.",
  ["53:5af5"] = "Últimamente sólo\npasaron por aquí\flos que iban al\nLAGO DE LA FURIA.",
  ["53:5b3b"] = "Ahora nadie\nva al LAGO\vDE LA FURIA.",
  ["53:5ca8"] = "¡Alto ahí,\nseñor!\fEl precio por\npasar es 1000¥.",
  ["53:5ce1"] = "¡Gracias, señor!",
  ["53:5cf2"] = "Entonces paga\nlo que tengas.",
  ["53:5d13"] = "¡Je, je! Nos\nestamos forrando.\fTodo el mundo\nquiere ver lo que\focurre en el LAGO\nDE LA FURIA.",
  ["53:5d6d"] = "Esos gamberros de\nnegro me echaron\vde mi puesto.\fSe dejaron\nesto.\fMe molesta.\n¿Podrías\vllevártelo?",
  ["53:5dff"] = "Usa esta puerta\npara no andar\vpor la hierba.",
  ["54:4005"] = "¿Coleccionas las\nMEDALLAS DE KANTO?",
  ["54:405a"] = "Dicen que hay\nun tipo sospechoso\vmerodeando.\fSi resulta ser\nel ladrón, le\vdetendré.",
  ["54:40c3"] = "Ya nos atracaron\nantes.",
  ["54:40e7"] = "DIGLETT: Dig, dig.",
  ["54:414d"] = "Mi marido vive\nfeliz con los\fPOKéMON que ha\nintercambiado.",
  ["54:418a"] = "Soy tan feliz…",
  ["54:419c"] = "KANGASKHAN: Kangas\nkangas.",
  ["54:41b5"] = "ZUBAT: Zuba zubaa.",
  ["54:4218"] = "La RUTA 9 va hacia\nel Este. La\fCENTRAL de ENERGÍA\nestá al final.",
  ["54:4257"] = "El MAGNETOTRÉN\nviaja a unos\n550 Km/h. Puede\nllevarte de\fKANTO a JOHTO en\npocos segundos.\fHace que sea muy\nfácil ir a JOHTO.",
  ["54:4453"] = "¡Uups! ¡Yo sentir!\nTú no hacer daño,\v¿de acuerdo?\fYo muy ocupado.\nNo tener tiempo\fpara hablar\ncontigo. No poder\vverme nadie.",
  ["54:44cc"] = "¡Oh, no! ¡Tú\nverme! ¡Yo cometer\vgran error!",
  ["54:44fd"] = "¡Oye! Tú olvidar\nque me has visto,\f¿vale? Tú ver, oír\ny saber nada, ¿de\facuerdo?\n¡Adiós, chico!\f¡Hasta la vista!",
  ["54:4568"] = "Lo siento, estaré\nfuera un tiempo.\fMISTY, LÍDER del\nGIMNASIO",
  ["54:459a"] = "Como MISTY ha\nsalido, nosotros\ftampoco estaremos.\nLos ENTRENADORES",
  ["54:45cc"] = "MISTY: Te estaba\nesperando,\vpesado.\fPuede que tengas\nmuchas MEDALLAS de\fJOHTO, pero será\nmejor que me tomes\ven serio.\f¡Mis POKéMON de\nagua son fuertes!",
  ["54:4664"] = "MISTY: Eres\nrealmente bueno…\fReconozco que eres\nun experto…\fAquí tienes la\nMEDALLA CASCADA.",
  ["54:46c0"] = "{PLAYER} recibió\nMEDALLA CASCADA.",
  ["54:46da"] = "MISTY: ¿Hay muchos\nentrenadores\ffuertes en JOHTO?\nComo tú, digo.\fUn día viajaré y\nlucharé contra\fentrenadores\nexpertos.",
  ["54:4762"] = "Siento haber\nestado fuera.\v¡A lo nuestro!",
  ["54:4790"] = "¡Me rindo! ¡Has\nganado!",
  ["54:47ae"] = "Estaré nadando\ntranquilamente.",
  ["54:47c8"] = "No te desanimes\npor mi elegante\vforma de nadar.",
  ["54:47f7"] = "¡Ooh! Has acabado\nconmigo…",
  ["54:4818"] = "No fardes tanto de\nhaberme vencido.\fMISTY acabará\ncontigo si te\vconfías demasiado.",
  ["54:486a"] = "¡Glup…!\f¡Soy el primero!\n¡Ven a por mí!",
  ["54:488c"] = "No puede ser…",
  ["54:489b"] = "MISTY ha mejorado\nmucho en los\vúltimos años.\f¡No bajes la\nguardia o acabarás\vmachacado!",
  ["54:48ff"] = "¡Hola, futuro\nCAMPEÓN!\fComo MISTY no\nestaba, salí\fa divertirme un\nrato. ¡Je, je, je!",
  ["54:4952"] = "¡Uauu! ¡Qué\nfuerte eres!\f¡Como siempre, ha\nsido un combate\vrealmente bueno!",
  ["54:4a25"] = "Encontrarás muchos\nentrenadores de\fcamino hacia\nCABO CELESTE.\fQuieren saber cómo\nson en comparación\fcon otros\nentrenadores.",
  ["54:4a9e"] = "MISTY es casi la\núnica persona de\fla ciudad capaz de\nvencer a los\fENTRENADORES de\nCABO CELESTE.",
  ["54:4b49"] = "¿Un CENTRO POKéMON\njunto a una cueva?\f¡Qué bien!\n",
  ["54:4b7e"] = "El DIRECTOR de la\nC. ENERGÍA busca\fa un entrenador\nPOKéMON fuerte.\fNecesita ayuda\npara recuperar\falgo que le\nrobaron.",
  ["54:4bf6"] = "Dicen que el TEAM\nROCKET se reunió\fen JOHTO, pero se\nvolvió a separar.\fNo tenía ni idea\nde eso.",
  ["54:4c64"] = "Cuando salgas,\nverás el tejado\fde un edificio\nmuy grande.\fEso es la CENTRAL\nde ENERGÍA.",
  ["54:4e31"] = "Entró un ladrón en\nla C. ENERGÍA…\f¿Adónde vamos a\nir a parar?",
  ["54:4e73"] = "Tengo noticias de\nCIUDAD CELESTE.\fParece que ha\nestado merodeando\fpor allí un hombre\nmuy sospechoso.",
  ["54:4ed0"] = "¿Puedo pedirte\nayuda?",
  ["54:4ef3"] = "Tendremos que\nreforzar nuestra\vseguridad.",
  ["54:4f20"] = "Alguien ha robado\nuna pieza que\fnecesitamos para\nel generador.\f¡Sin ella, el\nnuevo generador no\vsirve para nada!",
  ["54:4f89"] = "El generador ya\nfunciona y está\fgenerando mucha\nelectricidad.",
  ["54:4fca"] = "Esta CENTRAL de\nENERGÍA había\fsido abandonada\nhace mucho tiempo.\fVolvimos a ponerla\nen funcionamiento\fpara poder usar\nel MAGNETOTRÉN.",
  ["54:5040"] = "¡El generador\nya funciona!",
  ["54:505f"] = "El DIRECTOR de la\nCENTRAL ENERGÍA\vestá ahí delante.\fPero está triste y\nenfadado porque\falguien ha\nestropeado el\vgenerador…",
  ["54:50d0"] = "El DIRECTOR está\ncontento porque\fel generador ya\nestá arreglado.",
  ["54:5113"] = "El MAGNETOTRÉN\nconsume mucha\velectricidad.\fNo se puede mover\nsi el nuevo\fgenerador no\nfunciona.",
  ["54:5176"] = "¡Muy bien!\nEl MAGNETOTRÉN\fpuede volver a\nfuncionar.",
  ["54:51b5"] = "DIRECTOR: ¡Me voy\na enfadar con\valguien!\f¿Quién ha roto mi\ngenerador?\f¡Con el tiempo que\nle he dedicado!\f¡Como lo atrape,\nva a saber lo\fque es mi\nELECTROCAÑÓN!",
  ["54:5259"] = "DIRECTOR: ¡Nunca\nle perdonaré!\fAunque el culpable\nllore y suplique\fperdón, ¡le\nmachacaré!\f¡Ja, ja, ja!",
  ["54:52bf"] = "DIRECTOR: ¡Sí!\f¡Ésa es la pieza\nque le faltaba a\fmi generador! ¿La\nencontraste tú?",
  ["54:5315"] = "¡Yuju! ¡Gracias!\f¡Toma esta MT\ncomo recompensa!",
  ["54:5345"] = "DIRECTOR: La MT07\nes mi ELECTRO-\fCAÑÓN. ¡Es muy\npotente!\fAunque presenta\nel inconveniente\fde no ser muy\nprecisa.",
  ["54:53c6"] = "DIRECTOR: ¡Mi\nquerido generador!\f¡Sigue generando\nelectricidad!",
  ["54:5612"] = "¿Conoces a BILL?\nEs mi nieto.\fEstá en JOHTO\ntrabajando con\flos PC. Yo le\ncuido la casa.",
  ["54:5676"] = "Si tienes ese\nPOKéMON, ¿me\vdejas verlo?",
  ["54:56a4"] = "¿Me lo dejas ver?\n¡Qué amable eres!",
  ["54:56c8"] = "¿No lo tienes?\n¡Qué pena…!",
  ["54:56ea"] = "¡Ah! ¿es ése\n{STRBUF}?\f¡Qué mono!\nEres muy\vsimpático.",
  ["54:5725"] = "¡Gracias!\fToma esto como\nagradecimiento.",
  ["54:5752"] = "Vuelve cuando\nquieras.",
  ["54:576e"] = "Gracias por\nmostrarme tantos\fPOKéMON\nbonitos.\fMe he divertido\nmucho. Me alegro\fde haber vivido\ntantos años.",
  ["54:57d5"] = "¿Mmm?\fÉse no es el\nPOKéMON del\vque me hablaron.",
  ["54:5804"] = "Mi nieto BILL me\ndijo que había un\fPOKéMON con una\nlengua muy larga.",
  ["54:5843"] = "Mi nieto mencionó\na un POKéMON verde\fy redondo al que\nle crecen hojas en\vla cabeza.",
  ["54:5897"] = "¿Conoces a un\nPOKéMON de mar que\ftiene una esfera\nroja en el cuerpo?\fYa sabes, ése\nque tiene forma\vde estrella.\fDicen que sale\npor la noche.\fMe encantaría\nverlo.",
  ["54:5942"] = "BILL me habló de\nun POKéMON que\fes muy fiel a su\nentrenador.\fSe supone que\nRUGE bien.",
  ["54:599b"] = "He oído hablar de\nun POKéMON que\vtiene seis colas.\fMe gustaría\nabrazar a un\vPOKéMON así.",
  ["54:59f5"] = "¿Conoces a ese\nPOKéMON tan\vpopular?\fEl POKéMON de\ncuerpo amarillo\vy mejillas rojas.\fMe gustaría\nverlo antes\fde que\nevolucione.",
  ["55:4013"] = "¿Tus POKéMON saben\nmovimientos MO?\fSe pueden usar\nestos movimientos\faunque el POKéMON\nesté debilitado.",
  ["55:4067"] = "En el PC de BILL\nse almacenan 20\vPOKéMON por CAJA.",
  ["55:4092"] = "¿Sabes algo sobre\nlos BONGURI?\fAbre uno, vacíalo\ny rellénalo con\fun aparato\nespecial.\fAsí podrás atrapar\nPOKéMON.\fAntes de que se\ninventaran las\fPOKé BALL, todos\nusaban BONGURI.",
  ["55:41ed"] = "Todos los SLOWPOKE\ndel pueblo\vhan desaparecido.\fQuizá el guardián\ndel ENCINAR esté\venfadado…\fPuede ser un mal\npresagio. Mejor\vno salir.",
  ["55:4276"] = "Los SLOWPOKE han\nvuelto…\fPero mi APRENDIZ\nno ha vuelto del\vENCINAR.\f¿Dónde demonios\nestá ese vago?",
  ["55:42ec"] = "¿Expulsaste al\nTEAM ROCKET y\ffuiste solo al\nENCINAR?\f¡Qué valiente! Me\ngustas. Entrena\vcon nosotros.",
  ["55:4359"] = "¿Adónde han ido\nlos SLOWPOKE?\f¿Están jugando\nfuera?",
  ["55:439e"] = "Lo siento. Olvidé\ndarte las gracias.\fÉste es el CARBÓN\nque he fabricado.\fA los POKéMON de\nfuego les gustará\vllevarlo.",
  ["55:440c"] = "Los SLOWPOKE han\nvuelto, hasta\vFARFETCH'D.\f¡Eres el mejor,\ntío!",
  ["55:445e"] = "FARFETCH'D: ¡Farf!",
  ["55:44c6"] = "Aquí no hay SÚPER\nBALL. Tendrás que\fconformarte con\nlas POKé BALL.\f¡Ojalá me pudiera\nfabricar CÉSAR\valguna BALL!",
  ["55:452f"] = "Mejor una SÚPER\nBALL para capturar\fPOKéMON que una\nPOKé BALL.\fPero a veces,\nlas de CÉSAR\vson mejores.",
  ["55:47ee"] = "¿Quién eres?\f{PLAYER},\n¿quieres que haga\valguna BALL?\fLo siento, pero\ndeberás esperar.\f¿Conoces al TEAM\nROCKET? ¡Bah!\fNo importa. Yo\nte lo contaré.\fSe trata de una\nbanda malvada que\fusa POKéMON para\nel trabajo sucio.\fSe supone que se\ndisolvieron hace\vtres años.\f¡Pero están en el\nPOZO cortando\fCOLAS de SLOWPOKE\npara venderlas!\f¡Así que voy a\nir allí a darles\vuna lección!\f¡Resistid,\nSLOWPOKE!\v¡CÉSAR os ayudará!",
  ["55:4990"] = "CÉSAR: ¡{PLAYER}!\fTe has portado\ncomo un auténtico\vhéroe en el POZO.\f¡Tienes estilo!\fSería un honor\nhacer alguna BALL\fpara un entrenador\ncomo tú.\fAhora sólo tengo\nésta. Tuya es.",
  ["55:4a44"] = "CÉSAR: Fabrico\nlas BALL de\vlos BONGURI.\fRecógelos de\nlos árboles\vy traémelos.\fLos usaré para\nhacer las BALL.",
  ["55:4ab1"] = "CÉSAR: ¿Tienes\nun BONGURI?\f¡Vale! Te haré\nuna BALL.",
  ["55:4af4"] = "CÉSAR: Tardaré un\ndía en fabricar\funa BALL. Vuelve\nmañana a por ella.",
  ["55:4b37"] = "CÉSAR: ¡Oh…!\n¡Qué decepción!",
  ["55:4b53"] = "CÉSAR: ¡Estoy\ntrabajando! ¡Vete!",
  ["55:4b76"] = "CÉSAR: ¡{PLAYER}!\nAcabo de terminar\vtu BALL. Tuya es.",
  ["55:4ba5"] = "CÉSAR: Ha salido\nmuy bien.\fIntenta capturar\nPOKéMON con ella.",
  ["55:4bde"] = "Los SLOWPOKE se\nhan ido…\f¿Se los ha llevado\nla gente mala?",
  ["55:4c1a"] = "El abuelo se fue.\nEstoy tan sola…",
  ["55:4c38"] = "¡El SLOWPOKE\nque me regaló mi\fpadre ha vuelto!\n¡Y su COLA\vvuelve a crecer!",
  ["55:4c7e"] = "Papá trabaja en\nSILPH y estudia\vlas POKé BALL.\fTengo que quedarme\nen casa con el\vabuelo y SLOWPOKE.",
  ["55:4cdb"] = "SLOWPOKE: ¡Mmm!\n(Bostezo).",
  ["55:4cee"] = "¿Un joven\nPROF. OAK?",
  ["55:4d03"] = "Es una estatua\ndel guardián\vdel encinar.",
  ["55:4e83"] = "¡Soy ANTÓN!\nSoy invencible\fcon los\nPOKéMON bicho.\f¡Mis estudios me\nvan a convertir en\funa autoridad de\nlos POKéMON bicho!\fTe enseñaré lo\nque he aprendido.",
  ["55:4f26"] = "¡Uauu, increíble!\n¡Eres un experto\ven POKéMON!\fMi investigación\naún no ha acabado.\fVale, tú ganas.\nToma esta MEDALLA.",
  ["55:4f8c"] = "{PLAYER}\nrecibió la\vMEDALLA COLMENA.",
  ["55:4fa3"] = "¿Conoces las\nventajas de la\vMEDALLA COLMENA?\fSi la tienes, los\nPOKéMON hasta N.30\vte obedecerán.\fY los POKéMON\nque sepan CORTE\fpodrán usarlo\nfuera del combate.\fMira, también te\ndaré esto.",
  ["55:5060"] = "MT49 contiene\nCORTEFURIA.\fSi no fallas, se\nhace cada vez\vmás fuerte.\fCuanto más dure\nel combate, más\vfuerte será.\f¿No es genial?\n¡Lo descubrí yo!",
  ["55:50fe"] = "Los POKéMON bicho\nson muy complejos.\fQuedan muchos\nmisterios por\vresolver.\fEstudia a fondo\ntus favoritos.",
  ["55:515e"] = "Los POKéMON bicho\nevolucionan pronto\fy se hacen fuertes\nmucho antes.",
  ["55:519d"] = "¡No se trata sólo\nde evolucionar!",
  ["55:51b9"] = "Los POKéMON se\nhacen más fuertes\vsi evolucionan.",
  ["55:51e7"] = "¡Los POKéMON bicho\nson buenos y muy\ffuertes! ¡Te lo\ndemostraré!",
  ["55:521a"] = "Has demostrado lo\nfuerte que eres…",
  ["55:5239"] = "Son geniales,\npero la mayoría de\flas chicas odian\nlos POKéMON bicho.\fNo sé por qué…",
  ["55:527e"] = "¿Has salvado a los\nSLOWPOKE? ¡Uauu!\v¡Eres muy fuerte!\f¡Pero mis\nPOKéMON\fentrenados también\nson muy fuertes!",
  ["55:52da"] = "¡Urrggg!",
  ["55:52e4"] = "Supongo que\ndebería enseñarles\vmejores ataques…",
  ["55:530f"] = "AMY: ¿Vas a\ndesafiar al LÍDER?\v¡Ni lo sueñes!",
  ["55:5341"] = "AMY-MAY: ¡Oh,\ndoble bondad!",
  ["55:5362"] = "AMY: ¡Eres\nmuy fuerte!",
  ["55:537d"] = "MAY: ¿Quieres ver\nal LÍDER?\f¡Pues nosotras\nvamos primero!",
  ["55:53ae"] = "AMY-MAY: ¡Oh,\ndoble bondad!",
  ["55:53cf"] = "MAY: Han perdido\nnuestros POKéMON.\v¡Qué lástima!",
  ["55:53fc"] = "¡Hola, valiente!\fANTÓN es joven,\npero conoce muy\fbien a los POKéMON\nbicho.\fY sin mis consejos\nte resultaría aún\vmás duro.\fVeamos… A los\nPOKéMON bicho no\vles va el fuego.\fY los ataques de\ntipo volador son\vmuy efectivos.",
  ["55:54bf"] = "¡Eso es! Ha sido\nun gran encuentro\fentre jóvenes\ncon talento.\fCon gente como tú,\n¡el futuro de los\fPOKéMON será\nmaravilloso!",
  ["56:400f"] = "Cuando atrapas un\nPOKéMON, puede\vestar débil.\fPero éste crecerá\ny se hará más\vfuerte.\fEs importante\ntratar a los\fPOKéMON con\nmucho cariño.",
  ["56:4090"] = "Los POKéMON pueden\nir equipados con\fobjetos como\nPOCIÓN y ANTÍDOTO.\fPero parece que\nno saben usar los\fobjetos hechos\npor el hombre.",
  ["56:41e0"] = "¡Soy PEGASO, líder\ndel GIMNASIO de\vCIUDAD MALVA!\fDicen que una\nsacudida eléctrica\fpuede acabar con\nlas alas de los\vPOKéMON voladores.\f¡No permitiré\nque hablen así\vde ellos!\f¡Yo te enseñaré el\nauténtico poder de\flos magníficos\npájaros POKéMON!",
  ["56:42b7"] = "¡Maldición! Los\nqueridos POKéMON\vde mi padre…\f¡Muy bien!\nToma esto.\fEs la MEDALLA\nCÉFIRO oficial de\vla LIGA POKéMON.",
  ["56:431c"] = "{PLAYER} recibió\nla MEDALLA CÉFIRO.",
  ["56:4335"] = "La MEDALLA CÉFIRO\nmejora el ataque\vde los POKéMON.\fY permite que\nlos POKéMON\fusen DESTELLO, si\nlo tienen.\fToma, también\nte daré esto.",
  ["56:43b5"] = "Al usar una MT, el\nPOKéMON aprenderá\finmediatamente un\nnuevo movimiento.\fPiensa antes de\nactuar, ya que las\fMT sólo se pueden\nusar una vez.\fMT31 contiene\nBOFETÓN-LODO.\fReduce la\nprecisión del\fenemigo y causa\ngrandes daños.\fEs decir, es tanto\ndefensiva como\vofensiva.",
  ["56:44a2"] = "Encontrarás\nGIMNASIOS POKéMON\fen las ciudades\ny en los pueblos.\fDeberías probar\ntus habilidades en\vestos GIMNASIOS.\f¡Yo seguiré\nentrenándome para\fser el maestro de\nlos pájaros!",
  ["56:453a"] = "¡La clave está en\ntener valor!\fÉstos entrenan\nnoche y día para\fconvertirse en\nmaestros POKéMON.\f¡Adelante!",
  ["56:459c"] = "¡Aaah!",
  ["56:45a4"] = "¡La destreza de\nPEGASO es real!\f¡No te confíes\npor haberme\vvencido!",
  ["56:45ec"] = "¡Demuéstrame que\neres lo bastante\vbueno para PEGASO!",
  ["56:4620"] = "¡No puede\nser cierto!",
  ["56:4634"] = "¡Qué patético!\nHe perdido contra\vun novato…",
  ["56:4666"] = "¡Hola! ¡No soy\nentrenador pero te\vpuedo aconsejar!\f¡Créeme!\nSi confías, tus\fsueños de triunfo\npodrían cumplirse.\f¿Confías? Pues\nescucha.\fEl tipo planta es\ndébil contra el\ftipo volador.\n¡No lo olvides!",
  ["56:4735"] = "¡Bonita batalla!\n¡Sigue así y\vserás el CAMPEÓN!",
  ["56:48a8"] = "¡Soy yo, PRIMO!\f¡Fantásticos son\nlos POKéMON!\f¡A ti yo te\nenseñaré a ser un\ventrenador mejor!\f¿Quieres saber\ncómo ser un\vganador?",
  ["56:492a"] = "¡Bien! ¡A ti yo\nte enseñaré!\f¡En combate, los\nprimeros POKéMON\vsalen antes!\f¡Quizá sea más\nfácil si cambias\vel orden!\f¿Quieres que te\ncuente más cosas?",
  ["56:49be"] = "¿Quieres saber\ncómo educar bien\va los POKéMON?",
  ["56:49e8"] = "¡Bien! ¡A ti yo\nte enseñaré!\fSi un POKéMON\nsale al combate,\faunque brevemente,\ngana puntos EXP.\f¡Pon arriba los\nPOKéMON débiles,\fy cámbialos rápido\nen el combate!\f¡Así se harán\nfuertes los\vPOKéMON débiles!",
  ["56:4a9e"] = "¡Oh! ¡Un alumno\nlisto eres! ¡Nada\vmás quieres saber!\f¡Bueno en POKéMON\ndebes de ser!",
  ["56:4aed"] = "Estoy tomando\napuntes de lo que\vdice el profesor.\fY debería copiar\ntambién lo escrito\ven la pizarra.",
  ["56:4b47"] = "He cambiado a mis\nmejores POKéMON\vcon mi compañero.",
  ["56:4b74"] = "¡El POKéMON que\nhe conseguido va\vequipado con algo!",
  ["56:4ba6"] = "Si un POKéMON va\nequipado con una\fBAYA, se curará él\nsolo en combate.\fLos POKéMON pueden\nir equipados con\vmuchos objetos…\fEs muy duro\ntomar apuntes…",
  ["56:4c1f"] = "La pizarra indica\ncómo cambian de\festado los POKéMON\nen combate.",
  ["56:4c6b"] = "Si un POKéMON\nes envenenado,\vperderá PS.\fEl envenenamiento\ncontinúa tras el\fcombate y al\ncaminar seguirá\vperdiendo PS.\fPara curarlo,\nusa ANTÍDOTO.",
  ["56:4ced"] = "La parálisis baja\nla velocidad y\fpuede impedir el\nmovimiento.\fPermanece tras el\ncombate, así que\vusa ANTIPARALIZ.",
  ["56:4d4f"] = "Si tu POKéMON\nse queda dormido\fno podrá realizar\nningún movimiento.\fUn POKéMON dormido\nno se despierta\vtras el combate.\fDespiértalo con\nDESPERTAR.",
  ["56:4dc2"] = "Las quemaduras\nconsumen PS,\freducen el poder\ndel ataque\fy permanecen\ntras el combate.\fUsa ANTIQUEMAR\ncomo cura.",
  ["56:4e38"] = "Si tu POKéMON está\ncongelado, no\vpodrá hacer nada.\fSeguirá congelado\ntras el combate.\fDescongélalo con\nANTIHIELO.",
  ["56:4ea3"] = "Es el cuaderno de\neste niño…\fCaptura POKéMON\nusando POKé BALL.\fTu equipo puede\ntener hasta seis.\f¿Seguir leyendo?",
  ["56:4f04"] = "Antes de lanzar la\nPOKé BALL, debes\vdebilitarlo.\fAtrapar un\nPOKéMON quemado\fo envenenado es\nmucho más fácil.\f¿Seguir leyendo?",
  ["56:4f74"] = "Algunos ataques\ncausan confusión.\fUn POKéMON confuso\npuede atacarse a\vsí mismo.\fRetirarlo del\ncombate, eliminará\vsu confusión.\f¿Seguir leyendo?",
  ["56:4ff4"] = "Quienes atrapan\nPOKéMON y los usan\fpara luchar son\nentrenadores.\fSu misión es ir\na los GIMNASIOS\fy vencer a otros\nentrenadores.\fLa hoja siguiente\nestá… ¡vacía!\fNiño: ¡Eh, eh…!\fNo he escrito\nnada más…",
  ["56:5167"] = "Ella usa los\nnombres de sus\vcomidas favoritas.\fQuiero decir,\ncomo motes para\vsus POKéMON.",
  ["56:51cb"] = "¡A mi PIDGEY le\nllamo FRESITA!",
  ["56:51e9"] = "FRESITA: ¡Pidgey!",
  ["56:52c2"] = "¡{PLAYER}, cuánto\ntiempo sin verte!\fEl PROF. ELM te\nestá buscando.\fQuiere pedirte\notro favor.\f¿Puedes llevar el\nHUEVO POKéMON?",
  ["56:5332"] = "Hemos descubierto\nque los POKéMON\fsalen del HUEVO\ncuando crecen.\fPara que el HUEVO\nse abra, debe de\festar con otros\nPOKéMON activos.\f{PLAYER}, sólo\npodemos confíar\ven ti.\fLlama al PROF. ELM\ncuando se abra el\vHUEVO, por favor.",
  ["56:5400"] = "¡Oh, no! No puedes\nllevar más\vPOKéMON.\fEsperaré aquí a\nque le hagas\vsitio al HUEVO.",
  ["56:545f"] = "Pero…\nEl PROF. ELM\vpreguntó por ti.",
  ["56:547f"] = "{PLAYER},\n¿quieres el HUEVO?",
  ["56:549a"] = "El sistema de\nalmacenamiento del\fPC es de un chico\nllamado BILL.",
  ["56:54cd"] = "Fue hace unos\ntres años.\fEl TEAM ROCKET\nquería hacer daño\va los POKéMON.\fPero prevaleció la\njusticia y un niño\vacabó con ellos.",
  ["56:5549"] = "Los POKéMON son\nlistos y no\fobedecen a quien\nno respetan.\fSin las MEDALLAS\nnecesarias, harán\flo que ellos\nquieran.",
  ["56:5628"] = "Los POKéMON que\nse intercambian\vcrecen rápido.\fPero si no tienes\nla MEDALLA\fadecuada, podrían\ndesobedecerte.",
  ["56:56c7"] = "RUINAS ALFA\fCentro Turístico\n¡Mírame y Tócame!\f¡Intenta mover las\npiezas de piedra!",
  ["56:5712"] = "¿Estás estudiando\nlas RUINAS?\fEres un científico\nen potencia.",
  ["56:574e"] = "Hay dibujos en las\npiezas de piedra.\fIntenté moverlas.\nMe pregunto\vqué serán.",
  ["56:5814"] = "Éste es un buen\nsitio para pescar.\f¿Has visto a\ngente pescando?\v¿Y tú?\f¿Quieres una\nde mis CAÑAS?",
  ["56:5879"] = "Eso está\nbien.\f¡Ahora ya eres\nun pescador!",
  ["56:58ac"] = "¡Pescar es genial!\fSi ves agua, ya\nsea el mar o un\frío, utiliza\ntu CAÑA.",
  ["56:58fd"] = "¡Vaya! Me has\ndecepcionado…",
  ["56:591e"] = "Hola, jovencito.\n¿Qué? ¿Pican?",
  ["56:5943"] = "¿Cómo equipar\na mi POKéMON?\fQuizá con un\nobjeto que aumente\vsu ATAQUE…",
  ["56:5a70"] = "¡Perdona, chaval!\n¿Puedes hacerme\vun favor?\f¿Puedes darle este\nPOKéMON con CARTA\va mi amigo?\fEstá en la\nRUTA 31.",
  ["56:5adb"] = "¿Lo harás? Genial.\n¡Gracias, chaval!\fMi amigo es un\nchico gordinflón\fque siempre está\ndurmiendo.\f¡Le reconocerás\nenseguida!",
  ["56:5b4b"] = "{PLAYER} recibió\nPOKéMON con CARTA.",
  ["56:5b69"] = "Puedes leerla,\n¡pero no la\vpierdas! ¡RUTA 31!\fAh, sí. Un extraño\nárbol bloqueaba\vel camino.\f¿Lo habrán\nretirado ya?",
  ["56:5be9"] = "No puedes llevar\notro POKéMON…",
  ["56:5c07"] = "¡Oh…! Entonces,\nno importa…",
  ["56:5c1e"] = "¡Gracias, chaval!\n¡Muchas gracias\fpor habérselo\nllevado!\f¡Toma esto por\nlas molestias!",
  ["56:5c6c"] = "¿A que mi amigo\nestaba durmiendo?\vTe lo dije.",
  ["56:5c9d"] = "Un extraño árbol\nbloquea el camino.\fSi le hablas,\nse mueve.\fDicen que se\nvolvió loco cuando\falguien lo mojó\ncon una REGADERA.",
  ["56:5d2d"] = "Me gusta la Nana\nPOKéMON que ponen\ven la radio.",
  ["56:5ef2"] = "Hoy es {STRBUF}.\nEso significa que\fhoy es el Concurso\nCaptura de Bichos.\fLas reglas son\nsencillas.\fUsa uno de tus\nPOKéMON y captura\fun POKéMON bicho\npara ganar.\f¿Te gustaría\nintentarlo?",
  ["56:5fa4"] = "Aquí tienes las\nPARQUE BALL para\vel Concurso.",
  ["56:5fce"] = "{PLAYER} recibió\n20 PARQUE BALL.",
  ["56:5fe9"] = "Aquél que consiga\nel POKéMON bicho\fmás fuerte será\nel ganador.\fTienes 20\nminutos.\fSi te quedas sin\nPARQUE BALL, has\vperdido.\fPuedes quedarte\nel último POKéMON\vque captures.\f¡Sal y captura\nel POKéMON\fbicho más fuerte\nque encuentres!",
  ["56:60cd"] = "¡Oh, oh…!\fTienes más de\nun POKéMON.\fTendrás que usar\na {STRBUF},\fel primer POKéMON\nde tu equipo.\f¿Te parece\nbien?",
  ["56:613e"] = "Bien, guardaremos\nlos otros POKéMON\vmientras compites.",
  ["56:6172"] = "Los POKéMON de\n{PLAYER} se quedan\vcon el AYUDANTE.",
  ["56:619e"] = "Elige el POKéMON\nque usarás en\fel Concurso y\nluego ven a verme.",
  ["56:61e3"] = "Muy bien.\nEsperamos verte\vpronto por aquí.",
  ["56:620f"] = "¡Oh, oh…!\nEl primer POKéMON\fde tu equipo no\npuede luchar.\fSustitúyelo por\nel POKéMON que\fquieras usar y\nluego ven a verme.",
  ["56:6283"] = "¡Oh, oh…!\nTu equipo y\ftu CAJA del PC\nestán llenos.\fNo tienes sitio\npara guardar el\vPOKéMON bicho.\fHaz sitio en\ntu equipo o en\fla CAJA del PC y\nluego ven a verme.",
  ["56:6326"] = "¡Oh, oh…! Tienes\nun HUEVO como\fprimer POKéMON\nde tu equipo.\fSustitúyelo por\nel POKéMON que\fquieras usar y\nluego ven a verme.",
  ["56:63a1"] = "Aún te quedan\n{STRBUF} minuto(s).\f¿Quieres terminar\nahora?",
  ["56:63e2"] = "Bien. Espera en\nla Puerta Norte a\fque se anuncien\nlos ganadores.",
  ["56:642a"] = "Vale. Vuelve fuera\ny termina\vel juego.",
  ["56:6456"] = "El Concurso ha\nacabado. Esperamos\fvolveros a ver\naquí pronto.",
  ["56:649b"] = "En el PARQUE se\nsuelen celebrar\fmuchos Concursos.\nDeberías probar.",
  ["56:64df"] = "¿Cuándo será el\npróximo Concurso\vCaptura de Bichos?",
  ["56:6515"] = "El Concurso de\nCaptura de Bichos\fes los martes,\njueves y sábados.\fNo sólo ganas\nun premio por\fparticipar, sino\nque también puedes\fquedarte con un\nPOKéMON bicho.",
  ["56:660d"] = "¿No te imaginas\nquién podría\fhacer algo así?\n¿Y por qué?",
  ["56:6648"] = "¿Has visto ese\nextraño árbol en\vel camino?\fEso explica por\nqué vienen menos\fpersonas a visitar\nlas RUINAS ALFA.",
  ["56:69c0"] = "Hoy es {STRBUF}.\nEso significa que\fhoy es el Concurso\nCaptura de Bichos.\fLas reglas son\nsencillas.\fUsa uno de tus\nPOKéMON y captura\fun POKéMON bicho\npara ganar.\f¿Te gustaría\nintentarlo?",
  ["56:6a70"] = "Aquí tienes las\nPARQUE BALL para\vel Concurso.",
  ["56:6a9a"] = "{PLAYER} recibió\n20 PARQUE BALL.",
  ["56:6ab5"] = "Aquél que consiga\nel POKéMON bicho\fmás fuerte será\nel ganador.\fTienes 20\nminutos.\fSi te quedas sin\nPARQUE BALL, estás\vperdido.\fPuedes quedarte\nel último POKéMON\vque captures.\f¡Sal y captura\nel POKéMON\fbicho más fuerte\nque encuentres!",
  ["56:6b99"] = "¡Oh, oh…!\fTienes más de\nun POKéMON.\fTendrás que usar\na {STRBUF},\fel primer POKéMON\nde tu equipo.\f¿Te parece\nbien?",
  ["56:6c0a"] = "Bien, guardaremos\nlos otros POKéMON\vmientras compites.",
  ["56:6c3e"] = "Los POKéMON de\n{PLAYER} se quedan\vcon el AYUDANTE.",
  ["56:6c6a"] = "Elige el POKéMON\nque usarás en\fel Concurso y\nluego ven a verme.",
  ["56:6caf"] = "Muy bien.\nEsperamos verte\vpronto por aquí.",
  ["56:6cdb"] = "¡Oh, oh…!\nEl primer POKéMON\fde tu equipo no\npuede luchar.\fSustitúyelo por\nel POKéMON que\fquieras usar y\nluego ven a verme.",
  ["56:6d4f"] = "¡Oh, oh…!\nTu equipo y\ftu CAJA del PC\nestán llenos.\fNo tienes sitio\npara guardar el\vPOKéMON bicho.\fHaz sitio en\ntu equipo o en\fla CAJA del PC y\nluego ven a verme.",
  ["56:6df2"] = "¡Oh, oh…! Tienes\nun HUEVO como\fprimer POKéMON\nde tu equipo.\fSustitúyelo por\nel POKéMON que\fquieras usar y\nluego ven a verme.",
  ["56:6e6d"] = "Aún te quedan {STRBUF}\nminutos.\f¿Quieres terminar\nahora?",
  ["56:6eac"] = "Bien. Por favor,\nespera aquí\fa que se anuncien\nlos ganadores.",
  ["56:6ee7"] = "Bien. Por favor,\nvuelve fuera y\vtermina.",
  ["56:6f12"] = "El Concurso ha\nacabado. Esperamos\fvolveros a ver\naquí pronto.",
  ["56:6f57"] = "Algunos POKéMON\nsólo aparecen en\vel PARQUE.",
  ["56:6f80"] = "RAFA: ¡Uau! Me\nhas vencido. Eres\vbastante bueno.",
  ["56:6fab"] = "RAFA: La suerte\ncuenta mucho.\fNunca se sabe\nqué POKéMON\vva a aparecer.",
  ["56:6ff6"] = "SAM: Te envidio.\nEsta vez no\vlo he conseguido.",
  ["56:7027"] = "SAM: ¿Has usado\nPOKéMON grandes?",
  ["56:7049"] = "NANO: ¡Eso es!\nVoy a entrenar\fmejor a mis\nPOKéMON.",
  ["56:707d"] = "NANO: Quizá ganes\nmás puntos por\fun POKéMON de\nun color inusual.",
  ["56:70c1"] = "GUILLE: ¿Eres el\nganador? ¿Qué\vhas atrapado?",
  ["56:70f1"] = "GUILLE: Me alegra\nhaber atrapado\fel POKéMON\nque quería.",
  ["56:7135"] = "TINO: Enhorabuena.\n¡Te has ganado mi\vrespeto!",
  ["56:7163"] = "TINO: He atrapado\nun SCYTHER,\vpero he perdido.",
  ["56:7197"] = "BENITO: El POKéMON\nque has atrapado…\ves impresionante.",
  ["56:71c4"] = "BENITO: Es más\nfácil ganar con\fun POKéMON bicho\nde nivel alto.\fPero creo que\ntambién cuentan\votros aspectos.",
  ["56:7232"] = "CINDY: ¿Ganaste?\n¡Qué bien!\f¿Te apetece buscar\nPOKéMON bicho\vconmigo?",
  ["56:727f"] = "CINDY: ¡Adoro\nlos POKéMON bicho!",
  ["56:729f"] = "KAI: ¡No…!\nNo me puedo creer\vque haya perdido.",
  ["56:72d0"] = "KAI: ¡Dicen que\nalguien ha ganado\vcon un CATERPIE!",
  ["56:7302"] = "SAMUEL: La próxima\nvez ganaré yo.",
  ["56:7327"] = "SAMUEL: Vaya,\ncreí que obtendría\vmás puntos…",
  ["56:7356"] = "KOLDO: ¿Me das\nalgún consejo?\fQuiero estudiar\ntu estilo.",
  ["56:7396"] = "KOLDO: He\nestudiado mucho,\fpero eso no vale\npara ganar.",
  ["56:74dd"] = "¡Vaya…! Tu MOCHILA\nestá llena.\fGuardaremos\ntu premio, pero\vsólo hoy.\fHaz sitio en ella\ny ven a verme.",
  ["56:754c"] = "¿{PLAYER}?\fAquí tienes el\npremio que te\vguardábamos.",
  ["57:4122"] = "¡Hola! Soy BLANCA.\f¡Todos jugaban a\nPOKéMON, así\vque yo también!\f¡Los POKéMON son\nmuy monos!\f¿Quieres luchar?\n¡Te lo advierto!\v¡Soy muy buena!",
  ["57:41a5"] = "¡Ayy…!\f¡Uaaaaaaa!\n¡Eres malo!\f¡No deberías ser\ntan serio! ¡Sí,\vtú, niño, tú!",
  ["57:41f5"] = "¡Uaaaaa!\f¡Uaaaaa!\f¡Buaa, buaa…!\n¡Eres malo!",
  ["57:4223"] = "¡Sniff…!\f¿Qué quieres?\n¿Una MEDALLA?\f¡Ah, sí! Se me\nolvidaba. Toma la\vMEDALLA PLANICIE.",
  ["57:4278"] = "{PLAYER}\nrecibió la\vMEDALLA PLANICIE.",
  ["57:4290"] = "Con MED. PLANICIE\nlos POKéMON\fpodrán usar FUERZA\nfuera del combate.\fAdemás, aumentará\nla VELOCIDAD de\vtus POKéMON.\f¡Ah, toma esto\ntambién!",
  ["57:4307"] = "¡Es ATRACCIÓN!\nUtiliza todo el\fencanto de un\nPOKéMON.\f¿No es perfecto\npara una monada\vcomo yo?",
  ["57:4365"] = "¡Ah, ha estado\nmuy bien!\f¡Vuelve cuando\nquieras! ¡Adiós!",
  ["57:43a0"] = "¡No creas que será\nfácil vencerme!",
  ["57:43bb"] = "¡Vaya…! Pensaba\nque eras débil…",
  ["57:43db"] = "En el mundo de los\nPOKéMON, ¿quién\fes más fuerte: el\nmacho o la hembra?",
  ["57:441b"] = "Prefiero un\nPOKéMON mono a\vun POKéMON fuerte.\f¡Mis POKéMON son\nmonos y fuertes!",
  ["57:4469"] = "¡Oh, no, no, no!",
  ["57:447a"] = "Intento vencer a\nBLANCA, pero…\ves deprimente.\f¡De acuerdo! ¡Si\npierdo, volveré\fa intentarlo\notra vez!",
  ["57:44de"] = "¡Oh, no! Has hecho\nllorar a BLANCA.\f¡No te preocupes!\nPronto dejará de\fllorar. Siempre\nllora si pierde.",
  ["57:4537"] = "¡Eres muy\ngracioso! ¡Me\fgustas! ¡Pero\nno me rendiré!",
  ["57:457e"] = "Veamos… ¡Uups!\n¿Ya está?",
  ["57:4599"] = "¡Uau! ¡Debes de\nser muy bueno para\fhaberme ganado!\n¡Adelante!",
  ["57:45c8"] = "¡Hazlo lo mejor\nque puedas o\vacabaré contigo!",
  ["57:45f7"] = "¡No! ¡Oh, MEOWTH,\nlo siento mucho!",
  ["57:4615"] = "Le había enseñado\na MEOWTH todo tipo\vde ataques…",
  ["57:4644"] = "¡Hola, futuro\ncampeón!\fEste GIMNASIO es\npara entrenadores\fque usan POKéMON\nde tipo normal.\fTe recomiendo usar\nlos POKéMON de\vtipo lucha.",
  ["57:46b1"] = "¿Has ganado?\n¡Genial! Yo estaba\focupado mirando\na las chicas.",
  ["57:4791"] = "(Suspiro…)\nMe trasladé aquí,\fpero no vendo mis\nBICIS. ¿Por qué?\f¿Montarías en una\nBICI para hacerme\vpublicidad?",
  ["57:4802"] = "¿De verdad? ¡Bien!\fDime tu nombre y\nnúmero de teléfono\fy te prestaré\nuna BICI.",
  ["57:4852"] = "{PLAYER} tomó\nprestada una BICI.",
  ["57:4869"] = "¡Mis BICIS son de\ngran calidad!\fPuedes usarlas en\ncualquier lugar.",
  ["57:48a2"] = "(Suspiro…)\n¡Oh, por el amor\vde Dios…!",
  ["57:48f7"] = "¡Es una BICI\nnovísima!",
  ["57:49ad"] = "Si tratas bien a\ntus POKéMON,\fellos te\nquerrán.\f¿Eh? Déjame ver\ntu {STRBUF}…",
  ["57:4a06"] = "¡Parece muy feliz!\nTe debe de\vquerer mucho.",
  ["57:4a36"] = "Me parece que\nconfía mucho\ven ti.",
  ["57:4a64"] = "Es cariñoso\ncontigo. Parece\vfeliz.",
  ["57:4a98"] = "Es bastante mono.",
  ["57:4aa9"] = "Deberías tratarlo\nmejor. No está\vacostumbrado a ti.",
  ["57:4adb"] = "Da la impresión de\nque no le gustas.\vParece malvado.",
  ["57:4b0e"] = "No dejo de perder\nen los combates y\fmis POKéMON acaban\ndesmayándose…\fQuizá sea ésa la\nrazón por la que\vno les gusto…",
  ["57:4b71"] = "¡Si uso un objeto\ncon mi POKéMON,\vse pone contento!",
  ["57:4c7e"] = "BILL: ¡Hola,\n{PLAYER}! Haznos\fun favor y acepta\neste EEVEE.\fApareció cuando\najustaba la\vCÁPSULA de TIEMPO.\fAlguien tiene que\ncuidarlo y a mí\vno me gusta salir.\f¿Puedo confiar en\nti para jugar con\vél, {PLAYER}?",
  ["57:4d49"] = "BILL: ¡Lo sabía!\n¡Ahí te lo dejo,\fhéroe! ¡Eres\ngenial, tío!\fVale, confío en\ntí. Cuídalo\vbien.",
  ["57:4db5"] = "¡{PLAYER}\nrecibió\va EEVEE!",
  ["57:4dc8"] = "BILL: ELM dice que\nEEVEE evoluciona\fen formas nuevas\ny desconocidas.",
  ["57:4e09"] = "No, espera. No\npuedes llevar\vmás POKéMON.",
  ["57:4e34"] = "¡Oh…! ¿Qué\nhacer ahora?",
  ["57:4e49"] = "BILL: Solía\nexperimentar con\vun TELETRANSPORTE.\fDebería\nprofundizar más.",
  ["57:4e93"] = "¡Oh! ¿Coleccionas\nPOKéMON? Mi hijo\fBILL es un\nexperto.\fPero ha tenido\nque ir al CENTRO\fPOKéMON de\nCIUDAD IRIS.",
  ["57:4efa"] = "Qué alegría me\nda volver a ver\va mi hijo.",
  ["57:4f1d"] = "¿Eres entrenador?\fTengo un número\nde teléfono que\vte será útil.",
  ["57:4f58"] = "{PLAYER} grabó\nel número de BILL.",
  ["57:4f72"] = "Mi hermano creó\nel sistema de\falmacenamiento de\nPOKéMON del PC.\fTe iba a dar el\nteléfono de\vBILL…",
  ["57:4fc5"] = "No puedes grabar\nningún número más.",
  ["57:4fe8"] = "Mi hermano BILL\ncreó el sistema\fde almacenamiento\nde los POKéMON.",
  ["57:50d7"] = "El tren no ha\nllegado…\f¡Tengo una idea!\n¡Llevaré a cuestas\va los pasajeros!\fAunque no creo\nque funcione.",
  ["57:512e"] = "Pronto saldremos\npara C. AZAFRÁN.\f¿Quiere\nsubir?",
  ["57:5164"] = "Por favor, ¿puedo\nver su PASE?\fVale. Pase por\naquí, señor.",
  ["57:51a0"] = "Lo siento, pero\nno tiene PASE.",
  ["57:51c3"] = "Siempre a su\nservicio.",
  ["57:51de"] = "Hemos llegado a\nCIUDAD TRIGAL.\fSiempre a su\nservicio.",
  ["57:5217"] = "Soy el PRESIDENTE.\fMi sueño era crear\nun tren que fuera\fmás rápido que\ncualquier POKéMON.\fHace que JOHTO\nesté mucho más\vcerca de KANTO.",
  ["57:5311"] = "¡Oh! ¡Eres mejor\nque BLANCA!\f¿Conoces ese árbol\nque se mueve?\fSi lo mojas con\nuna REGADERA,\vataca.\fPero como tienes\nalgunas MEDALLAS,\vno te pasará nada.",
  ["57:53b6"] = "Lalala lalalala.\n¡Échale mucha\vagua, cariño!",
  ["57:53e9"] = "¡Cuando regué ese\nárbol que se movía\fen la RUTA 36, dio\nun salto!\fCreo que se trata\nde un POKéMON.\fPero sólo alguien\ncomo nuestra LÍDER\fde GIM., BLANCA,\npodría vencerle.",
  ["57:5485"] = "¿Conoces ese árbol\nque se mueve?\fSi lo riegas,\n¡da un salto\vde sorpresa!",
  ["57:5513"] = "El COLISEO del\npiso de arriba del\fCENTRO POKéMON es\npara conectarse.\fLos récords de los\ncombates están en\fla pared. No puedo\npermitirme perder.",
  ["57:5597"] = "Me pregunto\ncuántos tipos de\fPOKéMON hay en\nel mundo.\fHace tres años, el\nPROF. OAK dijo que\fhabía 150 tipos\ndistintos.",
  ["57:5614"] = "Un POKéMON de\nnivel superior no\vsiempre gana.\fAún así, su tipo\npuede tener alguna\vdesventaja.\fNo creo que haya\nun único POKéMON\fque sea el más\nfuerte.",
  ["57:56fe"] = "Un día estaba\nluchando y mis\fPOKéMON no se\npodían mover.\fSus movimientos no\ntenían ningún\fPUNTO de PODER,\no PP.",
  ["57:576f"] = "A veces, un\nPOKéMON sano\fno puede usar\nsus movimientos.\fSi ocurre esto,\ncúralo en el\fCENTRO POKéMON,\no usa un objeto.",
  ["57:5a38"] = "Bienvenido al\nCENTRO COMERCIAL\vde CIUDAD TRIGAL\n",
  ["57:5a5c"] = "El CENTRO\nCOMERCIAL tiene\vbuenos artículos.\fPero algunos\nobjetos sólo se\fconsiguen en\nel CASINO.",
  ["57:5abf"] = "¡Me encanta\nir de compras!",
  ["57:5adf"] = "Mamá es experta\nen gangas.\fSiempre compra\ncosas a precios\vmás bajos.",
  ["57:5b25"] = "PB INFORMACIÓN\fP1 TIENDA DE\n   ENTRENADORES\fP2 ARTÍCULOS DE\n   COMBATE\fP3 BOTIQUÍN\fP4 TIENDA DE MT\fP5 ÚLTIMO PISO",
  ["57:5cb7"] = "El POKéGEAR puede\nalmacenar hasta\vdiez números.\fEs difícil decidir\nqué numeros debes\vguardar.",
  ["57:5d0d"] = "Conseguí mi ABRA\nen el CASINO.\fAhora es mi mejor\ncompañero.",
  ["57:5d49"] = "Este CENTRO\nCOMERCIAL indica\fque CIUDAD TRIGAL\nes muy grande.\fSu gama de\nproductos no\vtiene rival.",
  ["57:5dba"] = "Tu Compañero\nde Viaje\fP1 TIENDA DE\n   ENTRENADORES",
  ["57:5e5e"] = "¡Estoy muy\ninquieto!\fUso VELOCIDAD X\npara acelerar\va mis POKéMON.",
  ["57:5ea7"] = "¡Eh! ¿Utilizas\nESPECIAL X cuando\vluchas?\f¡Es increíble!\n¡Aumenta las\fcaracterísticas\nESPECIALES!",
  ["57:5f09"] = "Para los amantes\nde la victoria\fP2 COLECCIÓN\n   DE COMBATE",
  ["57:5f9d"] = "Me encantan los\nPOKéMON fuertes.\fLes doy PROTEÍNAS\npara mejorar su\vATAQUE.",
  ["57:5fe7"] = "El HIERRO mejora\nsu DEFENSA.",
  ["57:6009"] = "Algunos POKéMON\nsólo evolucionan\fal intercambiarlos\ncon el Game Link.\fPor ejemplo:\nMACHOKE, KADABRA,\fHAUNTER y\nGRAVELER.\fDicen que hay\notros también.",
  ["57:60a2"] = "¡Curamos a\ntus POKéMON!\fP3 BOTIQUÍN",
  ["57:61d8"] = "Hola. ¡Oh, tus\nPOKéMON…!",
  ["57:61ef"] = "Están muy unidos\na ti.\fEste movimiento\nsería perfecto\vpara vosotros.",
  ["57:623b"] = "¡Son adorables!\fEnséñales unas\nbuenas MT.",
  ["57:626d"] = "Parece malvado.\n¿Qué te parece\vesta MT para él?",
  ["57:6297"] = "Seguro que hay\nMT que serían\fperfectas para\ntus POKéMON.",
  ["57:62d6"] = "REGALO MISTERIOSO.\fCon un simple\nbeep, recibes\fun regalo. Búscalo\nen el menú.",
  ["57:630e"] = "La opción REGALO\nMISTERIOSO es para\vGame Boy Color.",
  ["57:6342"] = "Los domingos viene\nuna señora a\vexaminar POKéMON.\f¡Regala\nhasta las MT!",
  ["57:6388"] = "No puedes cambiar\nel nombre de un\fPOKéMON que has\nintercambiado.\fEl nombre refleja\nlos sentimientos\fdel entrenador\noriginal.",
  ["57:63f9"] = "Personaliza a tus\nPOKéMON\fP4 TIENDA DE MT",
  ["57:6560"] = "¡Una máquina\nexpendedora!",
  ["57:6584"] = "¡Clang! ¡Salió\nuna lata de\v{STRBUF}!",
  ["57:65a7"] = "¡Uups! No tienes\nbastante dinero.",
  ["57:65c0"] = "No hay sitio\npara nada más.",
  ["57:65e0"] = "¿Escuchas el CANAL\nde la SUERTE?\fSi quieres ganar,\ncambia POKéMON\fcon mucha gente\npara conseguir\vmuchos números ID.",
  ["57:665f"] = "Si estás cansado,\nprueba las bebidas\vde las máquinas.\fA tus POKéMON\nles gustarán.",
  ["57:66af"] = "¡Tómate un\nrespiro!\fP5 ÚLTIMO PISO",
  ["57:6ab5"] = "¡Bienvenido!\f¡Aquí cambiamos\ntus fichas por\vpremios fabulosos!",
  ["57:6af0"] = "¿Qué premio\nquieres?",
  ["57:6b0d"] = "{STRBUF}.\n¿De acuerdo?",
  ["57:6b22"] = "¡Aquí tienes!",
  ["57:6b30"] = "¡Vaya! ¡Necesitas\nmás fichas!",
  ["57:6b4d"] = "Lo siento. No\ntienes más sitio.",
  ["57:6b6e"] = "Vale. ¡Guarda tus\nfichas y vuelve\vcuando quieras!",
  ["57:6b9a"] = "¡Vaya! No tienes\nun MONEDERO.",
  ["57:6bba"] = "Yo siempre juego\nen esta máquina.\fGano más fichas\nque en otras.",
  ["57:6c03"] = "Me encanta esta\nnueva tragaperras.\fEs más difícil\nque las de\vCIUDAD AZULONA.",
  ["57:6c59"] = "Vivir es un juego,\ny yo jugaré hasta\vque no pueda más.",
  ["57:6c90"] = "Las cartas…\fLas prefiero a las\ntragaperras porque\fson más fáciles\nde acertar.\fPero se gana\nmucho menos.",
  ["57:6cfc"] = "¡No pararé hasta\nque gane!",
  ["57:6d16"] = "Enseñé VENTISCA a\nmi POKéMON.\fHa sido difícil\nganar bastantes\ffichas pero ha\nmerecido la pena.",
  ["57:6d72"] = "No gané en las\ntragaperras y\flo perdí todo en\nlas cartas…\fMe enfadé tanto\nque tiré mi\fMONEDERO al\nSUBTERRÁNEO.",
  ["57:6f2c"] = "El ENCINAR es muy\ngrande. ¡Cuidado!\vNo te pierdas.",
  ["57:6f5c"] = "El ENCINAR está\nvigilado por su\vguardián.\f¡No hagas\nnada malo!",
  ["57:6ffe"] = "¿Estás completando\nuna POKéDEX?\fSería duro si los\nPOKéMON no\faparecieran.\nPrueba esta MT.",
  ["57:7057"] = "Es DULCE AROMA.\fÚsala siempre que\naparezcan POKéMON.\fAtraerá a los\nPOKéMON.",
  ["57:70a2"] = "BUTTERFREE: ¡Frii!",
  ["57:70b6"] = "¿Has visto el\nsantuario en honor\vdel guardián?\fProtege el\nBOSQUE desde\vantaño.\fCreo que debe\nde ser un POKéMON\vdel tipo planta.",
  ["57:71b8"] = "El abuelo te\nestaba buscando.",
  ["59:400b"] = "Soy el GURÚ\nPESCADOR, el mayor\fde los HERMANOS\nPESCADORES.\f¿Conoces al\nPESCADOR DAVID?\fPesca en la\nRUTA 44.\fMe contó un truco\nsorprendente\vpor teléfono.\fGracias a él,\natrapé muchos\fPOKéMON raros.\n¡Menudo día aquél!",
  ["59:40fa"] = "Es una foto de\ngente pescando…\fLo están pasando\nmuy bien…",
  ["59:4177"] = "Hay un POKéMON\ndormido delante de\vla CUEVA DIGLETT.\f¡El momento ideal\npara atraparlo!\f¿Pero cómo\ndespertarlo?",
  ["59:41ef"] = "Antes había un\nPOKéMON durmiendo\fdelante de la\nCUEVA de DIGLETT.\fPero parece que\nha desaparecido.",
  ["59:4255"] = "El FERRY es un\nbuen lugar para\fconocer y luchar\ncon entrenadores.",
  ["59:4292"] = "Tienes algunas\nMEDALLAS que no\vhabía visto nunca.\f¡Claro! Las has\nganado en JOHTO.",
  ["59:43d8"] = "Soy el PRESIDENTE\ndel CLUB de FANS\vde POKéMON.\fHe curado a más\nde 150 POKéMON.\fSoy muy exigente\ncuando se trata de\vPOKéMON.\f¿Has venido\npara saber\vde mis POKéMON?",
  ["59:4468"] = "¡Muy bien!\n¡Pues escucha!\fMi… preferido\nes RAPIDASH…\fEs… gracioso…\ncariñoso… veloz\ve increíble…\v¿No crees…? Es\vsorprendente…\vsimpático…\v¡Y lo quiero!\fSi lo abrazas…\ncuando duerme…\ves tan cálido…\vy mimoso… Es\vespectacular…\vencantador…\v¡Uuups! ¡Mira qué\vhora es! ¡Hablo\vdemasiado!",
  ["59:4594"] = "¡Gracias por\nescucharme!\v¡Toma esto!",
  ["59:45c9"] = "Es un CARAMELORARO\nque fortalece a\vlos POKéMON.\fPrefiero que mis\nPOKéMON luchen\fpara fortalecerse.\n¡Así que toma!",
  ["59:4637"] = "¡Hola, {PLAYER}!\f¿Has vuelto para\nsaber más cosas\vsobre mis POKéMON?\f¿No? Pues tengo\nmás historias…",
  ["59:468f"] = "¡Qué pena…!\f¡Vuelve cuando\nquieras!",
  ["59:46c4"] = "Al PRESIDENTE\nle encanta hablar\fcuando se trata de\nPOKéMON…",
  ["59:46f7"] = "Me encanta el\nmodo en que\fCLEFAIRY mueve el\ndedo para usar\fMETRÓNOMO. ¡Es\ntan adorable!",
  ["59:4756"] = "Me gusta CLEFAIRY,\npero jamás podría\fatrapar uno.\nPor eso me\fconformo con este\nPOKé MUÑECO\vque he encontrado.",
  ["59:47b1"] = "¡Ah, entiendo! La\nniña que perdió el\fPOKé MUÑECO\nestá triste…\fVale. ¿Podrías\ndevolverle este\fPOKé MUÑECO a\nesa pobre niña?\fUn día me haré\namigo de un\fCLEFAIRY real.\n¡No te preocupes!",
  ["59:4861"] = "{PLAYER} recibió\nPOKé MUÑECO.",
  ["59:4875"] = "¡Ya verás! Voy\na hacerme amigo\fde un auténtico\nCLEFAIRY.",
  ["59:48af"] = "Tu MOCHILA está\nrepleta.",
  ["59:48ca"] = "¡Mira mi precioso\nBAYLEEF!\f¡Lleva una hoja\ntan mona!",
  ["59:4908"] = "¡Es un CLEFAIRY!\n¿Verdad?\f¡No! Es un\nPOKé MUÑECO\vCLEFAIRY.",
  ["59:4940"] = "BAYLEEF: ¡Li liif!",
  ["59:4953"] = "Escuchemos\natentamente a\vlos entrenadores.",
  ["59:4980"] = "Si alguno alardea,\nhazlo tú también.",
  ["59:4a17"] = "¿Has oído hablar\ndel MAGNETOTRÉN?\fEs un tren que\nva hasta CIUDAD\vTRIGAL, en JOHTO.",
  ["59:4a6d"] = "Quiero ir a CIUDAD\nAZAFRÁN para ver\vel MAGNETOTRÉN.",
  ["59:4ae2"] = "El TEAM ROCKET ya\nno está en KANTO.\fEso hace que\nme sienta mejor.",
  ["59:4b21"] = "Estoy pensando en\nir a comprar a\vCIUDAD AZAFRÁN.",
  ["59:4b8b"] = "Durante años,\nDIGLETT ha estado\fexcavando un gran\ntúnel.\fEl túnel lleva a\nuna ciudad lejana.",
  ["59:4c99"] = "SURGE: ¡Oye,\nchaval!\fLo reconozco.\nPuede que no seas\ftan listo como\npara retirarte,\f¡pero eres\nvaliente!\f¡En cuanto a\nlos POKéMON\feléctricos, soy\nel número uno!\fNunca he perdido\nen combate.\f¡Acabaré contigo,\ntal y como hice\fcon mis enemigos\nen la guerra!",
  ["59:4d8a"] = "SURGE: ¡Arrrgh!\n¡Eres muy fuerte!\f¡Muy bien! ¡Toma\nla MEDALLA TRUENO!",
  ["59:4dc9"] = "{PLAYER} recibió\nla MEDALLA TRUENO.",
  ["59:4de3"] = "SURGE: La MEDALLA\nTRUENO aumenta la\fvelocidad de los\nPOKéMON.\fTe la mereces por\nhaberme vencido.\fLlévala con\norgullo, ¿me oyes?",
  ["59:4e55"] = "SURGE: ¡Hola,\nchaval! ¿Aún\fluchando y\nresoplando?\f¡Mis POKéMON y yo\nseguimos en ello!",
  ["59:4ea8"] = "¿Vienes a derrotar\nal LT. SURGE?\f¡No, si yo\npuedo impedirlo!",
  ["59:4ede"] = "¡Cuánto siento\nhaberle fallado,\vLT. SURGE!",
  ["59:4f02"] = "Cuando aún estaba\nen el ejército, el\fLT. SURGE me salvó\nla vida.",
  ["59:4f3a"] = "El LT. SURGE\nreconoció mi\fpotencial con\nlos POKéMON\veléctricos.\f¿Crees que puedes\nvencerme?",
  ["59:4f89"] = "¡Ooh! ¡Increíble!",
  ["59:4f9d"] = "Si funcionaran las\ntrampas del\fGIMNASIO, no lo\nhabrías logrado.",
  ["59:4fd9"] = "¡Voy a acabar\ncontigo! ¡Vas\va echar chispas!",
  ["59:500c"] = "¡Vaya! Me has\nvencido…",
  ["59:5028"] = "No te relajes\npor haberme\fvencido… LT.\nSURGE es fuerte.",
  ["59:5069"] = "¡Hola, futuro\nCAMPEÓN!\fEsta vez no\ntendrás tanta\vsuerte.\fEl LT. SURGE es\nmuy prudente. Ha\fpuesto trampas por\ntodo el GIMNASIO.\fPero (risas),\nlas trampas no\vestán activadas.\fTe será fácil\nencontrar al\vLT. SURGE.",
  ["59:5131"] = "¡Vaya combate más\nelectrizante!\f¡Me has puesto\nmuy nervioso!",
  ["59:5170"] = "¡Bah! Aquí sólo\nhay basura.",
  ["59:5250"] = "¡Bienvenido a\nCIUDAD AZAFRÁN,\fhogar del\nMAGNETOTRÉN!\fEso es lo que\nsuelo decir, pero\fel MAGNETOTRÉN no\nfunciona ahora.\fNo recibe\nelectricidad\fporque hay un\nproblema en la\fCENTRAL de\nENERGÍA.",
  ["59:531d"] = "El MAGNETOTRÉN\nes lo más\ffamoso de\nCIUDAD AZAFRÁN.",
  ["59:53bb"] = "¡Hola!\fROJO lleva fuera\nmucho tiempo.\fTampoco ha\nllamado, así que\fno sé dónde está,\nni lo que ha\vestado haciendo.\fDicen que si no\nhay noticias es\fque todo va bien,\npero estoy\vpreocupada por él.",
  ["59:547c"] = "Me preocupa que\nROJO esté herido o\fenfermo, pero es\nun chico. Estoy\forgullosa de que\nesté haciendo\flo que quiere.",
  ["59:54e3"] = "Tienen programas\nque no se emiten\ven JOHTO…",
  ["59:554b"] = "{PLAYER} jugó\na la N64.\fMejor irse. No hay\ntiempo que perder.",
  ["59:5582"] = "Parece que nadie\nlo ha usado en\vmucho tiempo…",
  ["59:562b"] = "DALIA: ¡Hola! Mi\nhermano es LÍDER\fdel GIMNASIO de\nCIUDAD VERDE.\fPero sale tanto de\nla ciudad que trae\fproblemas a los\nentrenadores.",
  ["59:56b1"] = "DALIA: ¡Llegas\na tiempo! Iba a\vtomar un té.\f¿Quieres\ntomarte uno?\fTus POKéMON están\nun poco sucios.\f¿Quieres que\nlimpie a uno?",
  ["59:573f"] = "DALIA: ¿Qué\nPOKéMON limpio?",
  ["59:5761"] = "DALIA: Vale, haré\nque mejore su\vaspecto enseguida.",
  ["59:5791"] = "{STRBUF}\nparece contento.",
  ["59:57a5"] = "DALIA: ¡Ya está!\n¡Listo!\f¿Qué? ¿Tiene buen\naspecto o no?\f¡Qué POKéMON\nmás mono!",
  ["59:57f5"] = "DALIA: Siempre\ntomo té a esta\fhora. Ven cuando\nquieras.",
  ["59:582f"] = "DALIA: ¿No quieres\nque te limpie un\fPOKéMON? Vale, tan\nsólo tomaremos té.",
  ["59:5872"] = "DALIA: Lo siento.\nNo puedo\vlimpiar un HUEVO.",
  ["59:5922"] = "OAK: ¡Ah, {PLAYER}!\nMe alegro de\fque hayas venido\nhasta KANTO.\f¿Qué opinas de los\nentrenadores que\fhay por aquí? Son\nfuertes, ¿verdad?",
  ["59:599d"] = "¿Qué tal va tu\nPOKéDEX?\fVeamos…",
  ["59:59c3"] = "Si pasas por aquí,\nespero que vengas\va visitarme.",
  ["59:59f7"] = "OAK: ¡Uau!\n¡Excelente!\fHas conseguido las\nMEDALLAS de todos\flos GIMNASIOS de\nKANTO. ¡Muy bien!\fSabía que\neras bueno.\f¿Sabes qué,\n{PLAYER}? Arreglaré\ftodo para que\npuedas ir a MONTE\vPLATEADO.\fMONTE PLATEADO es\nuna gran montaña\fllena de\nPOKéMON salvajes.\fEs muy peligroso\npara un entrenador\fnormal, así que\nestá prohibido ir.\fPero en tu caso,\n{PLAYER}, haremos\vuna excepción.\fSube hasta la\nMESETA AÑIL. Desde\fallí puedes llegar\na MONTE PLATEADO.",
  ["59:5b9d"] = "OAK: ¿Cómo? ¿No\nhas conseguido las\vMEDALLAS DE KANTO?\fLos LÍDERES de los\nGIMNASIOS de KANTO\fson tan fuertes\ncomo los de JOHTO.\fTe aconsejo que\nte enfrentes a\vellos.",
  ["59:5c37"] = "OAK: ¿Quieres\nconseguir las\vMEDALLAS DE KANTO?\fNo será fácil,\npero la\fexperiencia\ntambién cuenta.\fVen a verme cuando\nlas tengas todas.\vTe haré un regalo.\f¡Sigue así,\n{PLAYER}!",
  ["59:5cf6"] = "El programa de\nla HORA POKéMON\fdel PROF. OAK\nno se emite aquí,\ven KANTO.\f¡Qué pena! ¡Me\ngustaría oírlo!",
  ["59:5d54"] = "Gracias a tu\ntrabajo en la\fPOKéDEX, la\ninvestigación del\vPROF. ha avanzado.",
  ["59:5da2"] = "No se lo digas a\nnadie, pero la\fHORA DE OAK\nno es en directo.",
  ["59:5de5"] = "Pulsa START para\nacceder al MENÚ.",
  ["59:5e04"] = "La opción GUARDAR\nestá en el MENÚ.\fUtilízala con\nfrecuencia.",
  ["59:5e40"] = "Aquí dentro no\nhay nada…",
  ["59:5e59"] = "Hay un nuevo\ne-mail en el PC.\f…\fPROF. OAK,\n¿cómo van sus\vinvestigaciones?\fYo no paro\nde estudiar.\fDicen que\n{PLAYER} se está\vhaciendo famoso.\fMe alegra mucho\noirlo.\fELM, desde PUEBLO\nPRIMAVERA.",
  ["5a:400f"] = "¡NIDORAN, agítate!",
  ["5a:4020"] = "NIDORAN: ¡Nidoo!",
  ["5a:40cb"] = "BROCK: ¡Uau! No\ntodos los días\fnos desafía\nalguien de JOHTO.\fSoy BROCK, LÍDER\ndel GIM. de C.\fPLATEADA y experto\nen POKéMON roca.\fMis POKéMON son\ninsensibles a la\fmayoría de ataques\nfísicos. Te será\fmuy difícil\nhacerles daño.\f¡Venga!",
  ["5a:41b6"] = "BROCK: Mi dura\ndefensa no soportó\flos ataques de\ntus POKéMON…\fEres más fuerte de\nlo que pensaba…\fToma. Coge\nesta MEDALLA.",
  ["5a:4238"] = "{PLAYER} recibió\nla MEDALLA ROCA.",
  ["5a:4252"] = "BROCK: Gracias,\n{PLAYER}. Me gustó\fluchar contigo,\naunque estoy un\vpoco triste.\fLa MEDALLA ROCA\nhará que tus\fPOKéMON sean aún\nmás fuertes.",
  ["5a:42d5"] = "BROCK: El mundo es\nenorme. Hay muchos\fentrenadores tan\nfuertes como tú.\fEspera y verás.\nYo también me voy\fa hacer más\nfuerte.",
  ["5a:435d"] = "Los entrenadores\nde este GIMNASIO\vusan POKéMON roca.\fLos de roca tienen\nmayor DEFENSA.\fLos combates\npueden durar mucho\ftiempo. ¿Estás\npreparado?",
  ["5a:43ec"] = "Tengo que ganar\nestos combates…",
  ["5a:440a"] = "¡Eh, tú! ¡Chico\nde JOHTO! BROCK\fes muy duro. Te\ncastigará si no\fle tomas en\nserio.",
  ["5a:4469"] = "¡Eh, futuro\nCAMPEÓN! Eres\frealmente temible.\n¿Vas a enfrentarte\fa los LÍDERES DE\nGIMNASIO de KANTO?\fSon fuertes y\nentregados, igual\fque los LÍDERES de\nGIMNASIO de JOHTO.",
  ["5a:4502"] = "¡Hola, futuro\nCAMPEÓN! Este\fGIMNASIO no te\nha costado mucho.\fTu forma de atacar\nha sido realmente\fincreíble. Lo\ndigo en serio.",
  ["5a:45d3"] = "¡Hola! ¡Mira mi\nGYARADOS!\fProcede de un\nMAGIKARP. No me\fpuedo creer lo\nfuerte que es.",
  ["5a:4635"] = "Había una vez\nun anciano muy\fraro que vendía\nMAGIKARP.\fDecía que\nlos MAGIKARP del\fLAGO DE LA FURIA\neran excelentes.",
  ["5a:46fc"] = "¡Sí! Ya no hay\nGIMNASIO en la\fISLA CANELA. Me\nquedé de piedra.\f¿Sí? Estoy al\nteléfono. ¡Fuera!",
  ["5a:4758"] = "JIGGLYPUFF: Puff,\npuff.",
  ["5a:4770"] = "Casi todos los\nPOKéMON se duermen\fal oír cantar a\nJIGGLYPUFF.\fCuando un POKéMON\nestá dormido sólo\fse pueden usar\nciertos ataques.",
  ["5a:485a"] = "Me gusta dormirme\ncon la radio en…\v¡Zzzz…!",
  ["5a:4a24"] = "En la LIGA\nPOKéMON, serás\fpuesto a prueba\npor el ALTO MANDO.\fDeberás vencerlos\na todos. ¡Si\fpierdes, volverás\na empezar!",
  ["5a:4aa1"] = "Espera.\f¿Te vas a\nenfrentar ahora\fal desafío de la\nLIGA POKéMON?\fPues yo no\nlo creo.\fMis POKéMON\nestán muy bien\fentrenados y van a\nacabar contigo.\f¡{PLAYER}!\n¡Te desafío!",
  ["5a:4b41"] = "…\fVale. He perdido.",
  ["5a:4b50"] = "¡Maldición…!\nSigo sin ganar…\fYo… Tengo que\npensar más en mis\vPOKéMON…\f¡Umm! ¡Procura\nno perder!",
  ["5a:4ba9"] = "…\f¡Uau…!\nCon ayuda de mis\fcompañeros, ¡voy a\nser el CAMPEÓN!",
  ["5a:4be1"] = "¿Qué? ¿Vas a\ndesafiar al ALTO\fMANDO? ¿Seguro que\nestás preparado?\fSi necesitas\nentrenarte más, mi\fABRA te puede\nayudar.\fABRA te puede\nTELETRANSPORTAR.\f¿Te gustaría\nvolver a casa?",
  ["5a:4c93"] = "Vale. Concéntrate\nen la imagen\vde tu casa…",
  ["5a:4cbd"] = "Vale, vale. ¡Que\ntengas suerte!",
  ["5a:4cdf"] = "ABRA: Aabra…",
  ["5a:4ddd"] = "Bienvenido a la\nLIGA POKéMON.\fPermíteme que me\npresente. Me llamo\vMENTO.\fMe he entrenado\npor todo el mundo\fpara mejorar a mis\nPOKéMON psíquicos.\fY, por fin, me han\naceptado en el\vALTO MANDO.\f¡Sólo puedo seguir\nmejorando!\f¡Es imposible\nque pierda!",
  ["5a:4ed8"] = "No… Esto es…\nincreíble…",
  ["5a:4ef0"] = "Aunque haya\nperdido, no\fcambiaré mis\nplanes.\f¡Seguiré luchando\nhasta ser el mejor\fde todos los\nentrenadores!\fY ahora {PLAYER},\nexperimenta toda\fla fuerza del\nALTO MANDO.",
  ["5a:503f"] = "¡Ja, ja, ja!\fSoy KOGA, del ALTO\nMANDO. Vivo en las\fsombras, como un\nninja.\f¡Te confundiré y\nte destruiré con\vmi estilo!\fConfusión, sueño,\nveneno…\f¡Prepárate para\nser víctima de\vmis técnicas!\f¡Ja, ja, ja!\fLos POKéMON no\nutilizan sólo\fla fuerza bruta.\n¡Ya lo verás!",
  ["5a:5155"] = "¡Ah! ¡Has\ndemostrado\vtu valor!",
  ["5a:5176"] = "He probado\ncontigo todo\vlo que sé.\fPero he fallado.\nDebería\ventrenarme más.\f¡Entra en la\nsala siguiente,\fy demuestra tus\nhabilidades!",
  ["5a:52aa"] = "Soy BRUNO, del\nALTO MANDO.\fEntreno siempre al\nmáximo porque\fconfío en nuestro\npotencial.\fPor eso somos\ntan fuertes.\f¿Resistirás\nnuestro poder?\f¿Mmm? No veo que\ntengas miedo.\fPareces decidido.\n¡Perfecto!\f¿Listo, {PLAYER}?\n¡Te doblegarás\fante nuestro\ninmenso poder!\f¡Ja, ja!",
  ["5a:53cf"] = "¿Qué? ¿Cómo hemos\npodido perder?",
  ["5a:53e8"] = "Como he perdido,\nno tengo derecho\va decir nada…\f¡Enfréntate al\nsiguiente desafío!",
  ["5a:54d3"] = "Soy KAREN, del\nALTO MANDO.\f¿Eres {PLAYER}?\n¡Qué gracia!\fMe gustan los\nPOKéMON de tipo\vsiniestro.\fSu naturaleza tan\nfuerte y salvaje\fme parece muy\natractiva.\f¿Crees que podrás\ndetenerlos? ¡A ver\vque tal lo haces!\f¡Vamos allá!",
  ["5a:55a4"] = "Eres bueno…\nMe gusta eso\ven un entrenador.",
  ["5a:55d5"] = "POKéMON fuertes.\fPOKéMON débiles.\fÉsa es la visión\negoísta que tiene\vtodo el mundo.\fSi un entrenador\nes bueno, debería\fser capaz de ganar\ncon sus favoritos.\fMe gusta tu\nestilo. Sabes\vlo que importa.\fAdelante. El\nCAMPEÓN te espera.",
  ["5a:5816"] = "LANCE: Te estaba\nesperando.\f¡{PLAYER}!\fSabía que con tus\nhabilidades serías\fcapaz de llegar\nhasta mí.\fNo es necesario\ndecir nada más.\fLucharemos para\nsaber quién es el\fmás fuerte de\nlos dos.\fComo entrenador\nmás poderoso y\fCAMPEÓN de la LIGA\nPOKéMON…\f¡Yo, LANCE, el\nmaestro de los\fdragones, acepto\ntu desafío!",
  ["5a:5953"] = "Se acabó…\fPero es\nextraño.\fNo estoy enfadado\npor perder. De\fhecho, estoy\ncontento.\fEstoy contento por\nhaber presenciado\fel nacimiento de\nun nuevo CAMPEÓN.",
  ["5a:59e1"] = "¡Uauu…!\fTe has vuelto muy\npoderoso,\v{PLAYER}.\fTus POKéMON han\nrespondido bien a\ftu fuerza y\ndecisión.\fComo entrenador,\nseguirás creciendo\ffuerte con\ntus POKéMON.",
  ["5a:5a8c"] = "ROSA: ¡Oh, no!\n¡Todo ha acabado!\fPROF. OAK, si no\nfuera tan lento.",
  ["5a:5aca"] = "PROF. OAK: ¡Ah,\n{PLAYER}! ¡Cuánto\ftiempo sin\nverte!\fPareces más\nmaduro.\f¡Tu victoria en\nla LIGA ha sido\vfantástica!\fY todo gracias a\ntu dedicación,\fconfianza y amor\npor los POKéMON.\fTus POKéMON son\ngeniales.\fConfían en ti\ncomo entrenador\fy no se rinden\nnunca.\f¡Enhorabuena,\n{PLAYER}!",
  ["5a:5bf6"] = "ROSA: ¡Vamos a\nentrevistar al\vnuevo CAMPEÓN!",
  ["5a:5c26"] = "LANCE: Aquí va a\nempezar a haber\vmucho ruido…\f{PLAYER}, ¿puedes\nvenir conmigo?",
  ["5a:5c70"] = "ROSA: ¡Espera!\n¡No hemos hecho\vla entrevista!",
  ["5a:5d51"] = "LANCE: Ha pasado\nmucho tiempo desde\fla última vez que\nvine aquí.\fAquí rendimos\nhomenaje a los\fCAMPEONES de la\nLIGA, eternamente.\fY admitimos\na sus valientes\vPOKéMON.\fHoy hemos\npresenciado el\fnacimiento de un\nnuevo CAMPEÓN\fde la LIGA. Un\nentrenador\fcompasivo,\nque confía en\vsus POKéMON.\fUn entrenador que\nha ganado gracias\fa su constancia y\ndeterminación.\f¡Un nuevo CAMPEÓN\nde la LIGA que\fha demostrado\nsu grandeza!\f{PLAYER}, permíteme\nregistrarte a ti y\fa tus compañeros\ncomo CAMPEONES.",
  ["5b:41b3"] = "El barco va a\nzarpar. Por favor,\vsuba a bordo.",
  ["5b:41de"] = "Lo siento. No\npuedes embarcar.",
  ["5b:41fa"] = "Bienvenido al\nFERRY S.S. AQUA.\f¿Vas a embarcar\nhoy?",
  ["5b:4238"] = "¿Puedo ver tu\nTICKET BARCO?",
  ["5b:4259"] = "Siempre a su\nservicio.",
  ["5b:4274"] = "{PLAYER} enseña\nel TICKET BARCO.\fMuy bien.\n¡Gracias, señor!",
  ["5b:42a9"] = "{PLAYER} intentó\nenseñar el TICKET\vBARCO…\f¡Pero no lo tiene!\f¡Lo siento!\nSólo puedes subir\fsi tienes un\nTICKET BARCO.",
  ["5b:4310"] = "El FERRY zarpará\nel próximo lunes.",
  ["5b:4336"] = "El FERRY zarpará\nel viernes.",
  ["5b:435c"] = "Aquí es fácil\natrapar SHELLDER.\fEn otros sitios\nson raros.",
  ["5b:439d"] = "¿Cuántas CAÑAS\ntienes?\fLas distintas\nCAÑAS sirven para\fatrapar distintos\nPOKéMON.",
  ["5b:43de"] = "¡El S.S. AQUA usa\npropulsores para\vsurcar las olas!",
  ["5b:440a"] = "En KANTO hay\nmuchos POKéMON.\f¡Ojalá pudiera ir!",
  ["5b:443f"] = "No queremos que te\ncaigas al mar\fy por eso no\npuedes entrar.",
  ["5b:466e"] = "El barco va a\nzarpar. Por favor,\vsuba a bordo.",
  ["5b:4699"] = "Lo siento. No\npuedes embarcar.",
  ["5b:46b5"] = "Bienvenido al\nFERRY S.S. AQUA.\f¿Vas a embarcar\nhoy?",
  ["5b:46f3"] = "¿Puedo ver tu\nTICKET BARCO?",
  ["5b:4714"] = "Siempre a su\nservicio.",
  ["5b:472f"] = "{PLAYER} enseña\nel TICKET BARCO.\fMuy bien.\n¡Gracias, señor!",
  ["5b:4764"] = "{PLAYER} intentó\nenseñar el TICKET\vBARCO…\f¡Pero no lo tiene!\f¡Lo siento!\nSólo puedes subir\fsi tienes un\nTICKET BARCO.",
  ["5b:47cb"] = "El FERRY zarpará\nel miércoles.",
  ["5b:47f2"] = "El FERRY zarpará\nel domingo.",
  ["5b:4818"] = "¿Vienes de\nJOHTO?\fDicen que allí\nviven muchos\vPOKéMON raros.",
  ["5b:49ad"] = "El FERRY S.S. AQUA\nse dirige a\vCIUDAD CARMÍN.\fDaremos un\naviso cuando\vlleguemos.",
  ["5b:4a0d"] = "El FERRY S.S. AQUA\nse dirige a\vCIUDAD OLIVO.\fDaremos un\naviso cuando\vlleguemos.",
  ["5b:4a6b"] = "Éste es tu\ncamarote.\fSi están heridos\ntus POKéMON,\féchate una\nsiestecita.\fEso los curará.",
  ["5b:4ac1"] = "Es tu camarote.\fPuedes curar a tus\nPOKéMON durmiendo\vuna siesta.\fEl barco llegará\na su destino\vmientras duermes.",
  ["5b:4b32"] = "Los pasajeros son\nentrenadores.\fEstán deseando\nluchar en sus\vcamarotes.",
  ["5b:4b84"] = "¡Uau!\fDisculpa, hijo.\n¡Tenía prisa!\f¡Mi nieta ha\ndesaparecido!\fEs muy pequeña.\nSi la ves, por\ffavor, avísame.\n",
  ["5b:4c04"] = "El FERRY S.S. AQUA\nha llegado a\vCIUDAD OLIVO.",
  ["5b:4c35"] = "El FERRY S.S. AQUA\nha llegado a\vCIUDAD CARMÍN.",
  ["5b:4dba"] = "Voy a KANTO a\nponerme a prueba.",
  ["5b:4de0"] = "¡Quería ganar!",
  ["5b:4df2"] = "Los entrenadores\nde JOHTO pueden\fluchar contra los\nLÍDERES de KANTO.",
  ["5b:4e2a"] = "¡Me entreno para\nser la CAMPEONA!",
  ["5b:4e4c"] = "¿En qué somos\ntan diferentes?",
  ["5b:4e6e"] = "¡Te ganaré un\ndía de éstos!",
  ["5b:4e8d"] = "¿Conoces a LILA?\nEs una DJ muy\vbuena de KANTO.",
  ["5b:4eb8"] = "¡Yaaaa!",
  ["5b:4ec2"] = "LILA es buena pero\nROSA es la mejor.\f¡Me encantaría\nescuchar las\vemisoras de JOHTO!",
  ["5b:4f0e"] = "¿Estás solo?\n¡Pues luchemos!",
  ["5b:4f30"] = "¡Es demasiado!\n",
  ["5b:4f4b"] = "Me pregunto si en\nKANTO habrá\fmontañas que valga\nla pena escalar.",
  ["5b:4f89"] = "Sí, es verdad,\nsoy un marinero.\f¡No hacía\nnada malo!\fComo el camarote\nestaba vacío, me\veché un sueñecito.\f¡Ah! ¡Olvídalo!\n¡Luchemos!",
  ["5b:500e"] = "¡Lo siento! ¡Todo\nes culpa mía!",
  ["5b:5028"] = "Los marineros\nhacemos mucho\ftrabajo físico.\n¡Es agotador!",
  ["5b:5068"] = "¡Oh, no! He\nperdido algo\vmuy importante.",
  ["5b:509a"] = "No… No lo\nencuentro…",
  ["5b:50ae"] = "Me rindo. Hijo, no\ntienes por qué\fbuscarlo.\n¡Olvídalo!",
  ["5b:50ec"] = "¡Yujuu!\n¡Qué suerte!",
  ["5b:50fc"] = "¡Qué mala suerte!\n¡He perdido!",
  ["5b:5112"] = "He encontrado una\nmoneda muy bonita.\fAlguien debe de\nhaberla perdido…",
  ["5b:5270"] = "¡Voy a KANTO para\nactuar en un\fespectáculo de\ncomefuegos!",
  ["5b:52a4"] = "La débil llama\npierde fuerza.",
  ["5b:52be"] = "El fuego es débil\ncontra el agua.\fNo te importa,\n¿verdad?",
  ["5b:52fa"] = "¡Voy a ver a mi\nabuela para que me\fatrape unos\ncuantos bichos!",
  ["5b:5329"] = "¡Ooh! ¡Uau!\n¡Qué duro eres!",
  ["5b:5347"] = "Encontrarás muchos\nPOKéMON en los\várboles de JOHTO.",
  ["5b:5379"] = "Intento olvidar a\nmis enemigos.\v¡Luchemos!",
  ["5b:53a4"] = "Estoy desolada…",
  ["5b:53b5"] = "Lo mejor para\ncurar las penas\fes hacer un\nviaje en barco.\fPero los viajes\nen FERRY son\fdemasiado\ncortos.",
  ["5b:5418"] = "Voy a una audición\nde mis canciones\fen la EMISORA de\nCIUDAD TRIGAL.",
  ["5b:5456"] = "¡Uauu!\n¡Distorsión total!",
  ["5b:5470"] = "Hablando de la\nEMISORA, ¿cuál es\fnº de la suerte\nde esta semana?",
  ["5b:54af"] = "¡Una buena cama!\nA dormir…",
  ["5b:54cc"] = "¡Ah! Me siento\ncomo nuevo.",
  ["5b:54e9"] = "El FERRY S.S. AQUA\nha llegado a\vCIUDAD OLIVO.",
  ["5b:551a"] = "El FERRY S.S. AQUA\nha llegado a\vCIUDAD CARMÍN.",
  ["5b:570e"] = "¡Ah! Gracias por\nvenir.\fEstoy agotado\nde entretener\va esa niña.",
  ["5b:5760"] = "¿Te gusta viajar\nen el S.S. AQUA?\fPrácticamente\nvuela por encima\vde las olas.",
  ["5b:57aa"] = "Hola, hijo…\nNo encuentro\va mi nieta.\fSi está en el\nbarco, no hay\fproblema. Pero,\n¿y si se ha\vcaído al mar?\fEs muy revoltosa.\nPodría estar\fmolestando. Estoy\npreocupado…",
  ["5b:585a"] = "{PLAYER}, ¿verdad?\nMe han dicho que\fhas entretenido a\nmi nieta.\fQuiero darte\nlas gracias.",
  ["5b:58b2"] = "¡Me gustaría que\ntuvieras esto!",
  ["5b:58d5"] = "Estamos viajando\npor todo el mundo.",
  ["5b:58f7"] = "CAPITÁN, venga,\njuegue conmigo.\f¡Me aburro! Quiero\njugar más.",
  ["5b:5936"] = "¡Hola! ¿Quieres\njugar conmigo?\f¿Qué…?\f¿Que mi abuelo\nestá preocupado?\f¡Debería irme!\f¡Tengo que buscar\nal abuelo!",
  ["5b:599b"] = "¡Hola, abuelo!\nEstaba jugando\fcon el CAPITÁN y\neste chico.",
  ["5b:59dd"] = "¡Me he divertido\nmucho jugando!",
  ["5b:59f9"] = "¡Hola, hijo!\n¿Quieres luchar?",
  ["5b:5a1c"] = "¡Eres fuerte!",
  ["5b:5a2b"] = "¿Viajas\nsolo?\f¿Tu madre no está\npreocupada?",
  ["5b:5a5e"] = "¿Crees que soy\nuna nena?\v¡No es justo!",
  ["5b:5a84"] = "¡Oh! ¡Perdimos!",
  ["5b:5a92"] = "¡No deberías\nllamar nenas a\vlas chicas!",
  ["5b:5ab9"] = "¡No soy una nena!\f¡Y no deberías\nllamar así a\funa dama!",
  ["5b:5aea"] = "¡Oh! ¡Perdimos!",
  ["5b:5af8"] = "A veces, los niños\nson más listos que\vlos adultos.",
  ["5b:5b25"] = "¡Ssh! ¡Mi cerebro\nestá captando\vseñales de radio!",
  ["5b:5b51"] = "¡Escucho\nalgo…!",
  ["5b:5b67"] = "Entiendo. Puedes\noír la radio de\vJOHTO en el FERRY.",
  ["5b:5b9e"] = "¿Qué opinas? Mis\nPOKéMON son\vbonitos, ¿verdad?",
  ["5b:5bce"] = "¡Oh, no! ¡Mis\npreciosos POKéMON!",
  ["5b:5bec"] = "¡Debo ir a la\nPELUQUERÍA POKéMON\fpara ponerlos\nguapos!",
  ["5b:5c1f"] = "Me voy de compras\nal C. COMERCIAL\vy luego…",
  ["5b:5c4d"] = "¿Qué es lo que\niba a hacer?",
  ["5b:5c66"] = "¡Ah, sí! Tengo que\nir a buscar a mis\fPOKéMON a la\nGUARDERÍA.",
  ["5b:5c97"] = "¿Qué tipos de\nPOKé BALL llevas\vcontigo?",
  ["5b:5cc4"] = "¡Espera! ¡Detente!\n¡No, por favor!",
  ["5b:5cdf"] = "Deberías usar las\nBALL adecuadas\fpara cada\nsituación.",
  ["5b:5d15"] = "El FERRY S.S. AQUA\nha llegado a\vCIUDAD CARMÍN.",
  ["5b:5f4b"] = "¡Eh! ¿Podrías\nbuscar a mi\vcompañero?\f¡Está haciendo de\nlas suyas en algún\fsitio! ¡El muy\nvago!\fMe gustaría ir a\nbuscarle, pero\vestoy de servicio.",
  ["5b:5fd7"] = "¡Oh…!\fEl CAPITÁN se\npondrá furioso…",
  ["5b:5ffe"] = "¡Gracias, chico!\n¡Le he echado una\fbuena bronca y se\nha tranquilizado!",
  ["5b:603d"] = "¿Una niña pequeña?\fPuede que la haya\nvisto por aquí.",
  ["5b:606d"] = "El comedor está\nahí delante.\fLas escaleras del\nfondo conducen al\fcamarote del\nCAPITÁN.",
  ["5b:60bd"] = "No hay nada mejor\nque un combate\fen mi tiempo\nlibre.",
  ["5b:60ea"] = "¡Gane o pierda, se\nacabó el descanso!",
  ["5b:6108"] = "Supongo que no\nganaré si no me\vlo tomo en serio.",
  ["5b:6133"] = "Me aburro tanto.\n¿Quieres luchar?",
  ["5b:6151"] = "¡Uau! ¡Eres\ndemasiado fuerte!",
  ["5b:6169"] = "AZAFRÁN…\nAZULONA…\fDicen que hay\nmuchas ciudades\vgrandes en KANTO.",
  ["5b:61a7"] = "¡Urrf…!\n¡Estoy mareado!",
  ["5b:61ba"] = "No me puedo\nmover…",
  ["5b:61d2"] = "No vuelvo a ir en\nbarco. La próxima\fvez viajaré en el\nMAGNETOTRÉN.",
  ["5b:6210"] = "¡Aquí es donde\ntrabajamos!",
  ["5b:6230"] = "He perdido en mi\npropio campo…",
  ["5b:624a"] = "Llevamos a muchos\npasajeros desde\fCIUDAD CARMÍN a\nCIUDAD OLIVO.",
  ["5b:628c"] = "¡Aunque estemos en\nel mar, no puedo\vpescar!\f¡Qué aburrido!\n¡Luchemos!",
  ["5b:62d8"] = "Ya… Ya no\nme aburro…",
  ["5b:62f2"] = "Voy a pescar en\nlos muelles de\vCIUDAD CARMÍN.",
  ["5b:6317"] = "¡Fortalezco mis\npiernas nadando\fen la estela\ndel barco!",
  ["5b:6355"] = "¡Bailemos el Rock\nand Roll!",
  ["5b:636e"] = "No pude encontrar\nal REY del KARATE\ven JOHTO.\fDicen que se está\nentrenando en\valguna cueva.",
  ["5b:63c9"] = "¡Soy marinero!\fPero entreno\nPOKéMON para\vser el CAMPEÓN.",
  ["5b:640c"] = "Me falta\nentrenamiento…",
  ["5b:642f"] = "¡Ocho MEDALLAS!\nEso demuestra que\fhas vencido a los\nLÍDERES de GIM.\f¡No me extraña que\nseas tan bueno!",
  ["5b:6486"] = "¡No toques a\nmis alumnos!",
  ["5b:64a9"] = "¡Aaah!",
  ["5b:64b1"] = "Vamos de excursión\na las RUINAS de\flas afueras de\nCIUDAD MALVA.",
  ["5b:64e4"] = "¿Conoces las\nRUINAS ALFA?",
  ["5b:6504"] = "¡Aarg!",
  ["5b:650d"] = "Las radios captan\nseñales extrañas\ven las RUINAS.",
  ["5b:653f"] = "En las RUINAS\nALFA hay unas\fextrañas piezas\nde piedra.",
  ["5b:6576"] = "¡Estoy agotado!",
  ["5b:6586"] = "He leído que hay\ncuatro piezas de\vpiedra como ésas.",
  ["5b:667f"] = "El FERRY S.S. AQUA\nnavega hasta KANTO\flos lunes y\nlos viernes.",
  ["5b:66ed"] = "El FERRY sale\nsiempre los\fmiércoles y\nlos domingos.",
  ["5b:680b"] = "PLAZA MT. MOON\nNo tirar basura",
  ["5b:6882"] = "Cuando el sol se\npone, CLEFAIRY\vsale a jugar.",
  ["5b:693b"] = "¡Shaoooh!",
  ["5c:400f"] = "Esperaba comprar\nalgunos souvenirs\fen la ZONA SAFARI,\npero está cerrada.",
  ["5c:4050"] = "La nieta del\nGUARDA de la ZONA\fSAFARI vive en la\nciudad.",
  ["5c:424f"] = "¡Fufufufu…!\fLo siento\nmucho…\f¡Sólo bromeaba!\f¡Soy la auténtica!\fSoy SACHIKO, del\nGIMNASIO FUCSIA.\v¡La original!",
  ["5c:42bb"] = "SACHIKO: Eres un\ntipo duro. ¡Y, sin\vduda, has ganado!\fAquí tienes la\nMEDALLA ALMA.",
  ["5c:4305"] = "{PLAYER} recibió\nla MEDALLA ALMA.",
  ["5c:431c"] = "SACHIKO: ¡Eres tan\nfuerte! ¡Tengo un\vregalo para ti!\fEs TÓXICO, un\npotente veneno que\fva agotando los\nPS de la víctima.",
  ["5c:438e"] = "SACHIKO: Voy a\nesforzarme por\fmejorar mis\nhabilidades.\f¡Quiero llegar a\nser mejor que mi\vpadre y que tú!",
  ["5c:4400"] = "¡Fufufu! ¡Soy\nSACHIKO, la LÍDER\vdel GIMNASIO!\f¡No, no soy yo!\n¡Qué tonto eres!",
  ["5c:4440"] = "Te he engañado…",
  ["5c:4453"] = "¿Cómo reconocerás\na la auténtica\vLÍDER?",
  ["5c:4480"] = "¡Te he engañado!\n¡Ja ja ja!",
  ["5c:4495"] = "¡Oh…! He perdido…\nNo eres débil…",
  ["5c:44b3"] = "¿Qué? ¿Mi disfraz\nno era perfecto?",
  ["5c:44d5"] = "¡Soy SACHIKO!\f¿Cómo has sabido\nque no era yo?\f¡Luchemos!",
  ["5c:450b"] = "¡Maldición!\n¡Quería ganar!",
  ["5c:4526"] = "Debes de estar\ncansado.",
  ["5c:4542"] = "¡Uajajaja!\fAcertaste, chaval.\n¡Yo soy SACHIKO!",
  ["5c:456a"] = "¿A que era bueno\nmi disfraz?",
  ["5c:458b"] = "¡Eh, chico!\n¿No era bueno\vmi disfraz?",
  ["5c:45ba"] = "¡Hola, futuro\nCAMPEÓN!\fEcha un vistazo a\ntu alrededor.\fTodos los\nentrenadores se\vparecen a SACHIKO.\f¿Cuál será la\nauténtica SACHIKO?",
  ["5c:4646"] = "¡Qué bien luchas,\nentrenador\vde JOHTO!",
  ["5c:46e4"] = "Mi abuelo está en\ncasa de mi hermano\fBILL, en CABO\nCELESTE.",
  ["5c:471a"] = "He visto a unos\nlentos y raros\fPOKéMON en el\nCAMINO DE BICIS.",
  ["5c:47b5"] = "¡Anda! Tienes un\nnuevo tipo de\vPOKéDEX.\f¿Te la ha dado\nel PROF. OAK?",
  ["5c:47fd"] = "Me sorprendió\nmucho el GIMNASIO.\fHabía tres chicas\nque parecían\vidénticas.",
  ["5c:484f"] = "¡Soy SACHIKO!\nAbracadabra…",
  ["5c:486f"] = "¿Has visto? ¡Ahora\nsoy como ella!",
  ["5c:4907"] = "Mi abuelo es el\nGUARDA de la ZONA\vSAFARI.\fAl menos lo era…\fDecidió irse de\nvacaciones y se\ffue al extranjero\nél solo.\fAsí fue como dejó\nde ocuparse de\vla ZONA SAFARI.",
  ["5c:49b2"] = "Mucha gente se\nenfadó cuando\fcerraron la ZONA\nSAFARI, pero el\vabuelo es terco.",
  ["5c:4a0b"] = "Es una foto de un\nanciano sonriente\frodeado de\nPOKéMON.",
  ["5c:4a47"] = "Es una foto de una\nextensa pradera\fllena de POKéMON\nraros jugando.",
  ["5c:4ac2"] = "¿Estás trabajando\nen una POKéDEX?\fEs muy importante.\n¡No te rindas!",
  ["5c:4b31"] = "Los entrenadores\nambiciosos escalan\fel MT. PLATEADO a\npesar del peligro.\fCon sus fieles\nPOKéMON, sentirán\fque pueden ir a\ncualquier lado…",
  ["5c:4c13"] = "¡Pues vaya!\nMe encontraste.\fPor favor, no se\nlo digas a nadie.\fTe daré esto si\nme guardas el\vsecreto. ¿Vale?",
  ["5c:4c81"] = "Es muy duro\nser famoso.\fTodo el mundo\nme persigue.\fSólo quiero que me\ndejen en paz…",
  ["5c:4ce3"] = "FEAROW: ¡Fearow!",
  ["5c:4fa4"] = "Bienvenido al\nCOLISEO DEL\vCLUB CABLE.\fAquí puedes luchar\ncontra un amigo.\f¿Quieres\nluchar?",
  ["5c:4ffe"] = "Bienvenido al\nCENTRO DE CAMBIO\vDEL CLUB CABLE.\fAquí puedes\ncambiar POKéMON\vcon un amigo.\f¿Quieres cambiar\nPOKéMON?",
  ["5c:5068"] = "Bienvenido a la\nCÁPSULA DEL TIEMPO\vDEL CLUB CABLE.\fPuedes viajar al\npasado y cambiar\vtus POKéMON.\f¿Quieres viajar al\npasado?",
  ["5c:50e2"] = "Tu amigo no\nestá preparado.",
  ["5c:50fd"] = "Antes de conectar\nlas consolas,\vguarda el juego.",
  ["5c:5130"] = "Espera, por favor.",
  ["5c:513e"] = "La conexión se ha\ninterrumpido por\vinactividad.\fHabla con tu\namigo y vuelve\vcuando quieras.",
  ["5c:519a"] = "Vuelve algún día.",
  ["5c:51f2"] = "No puedes\nconectarte con\vel pasado aquí.",
  ["5c:5213"] = "Tu amigo eligió\nuna sala distinta.",
  ["5c:5238"] = "Entra, por favor.",
  ["5c:5258"] = "Perdona. No\npuedes llevar a\v{STRBUF}.",
  ["5c:5275"] = "No puedes llevar a\n{STRBUF} con\v{STRBUF}.",
  ["5c:529c"] = "No puedes llevarte\na {STRBUF}\vcon la CARTA.",
  ["5c:52cd"] = "Lo siento. Estamos\narreglando la\vCÁPSULA DE TIEMPO.",
  ["5c:52fc"] = "Lo siento. Estamos\najustando la\vMÁQUINA DE CAMBIO.",
  ["5c:532c"] = "Lo siento. Estamos\najustando la\vMÁQUINA DE LUCHA.",
  ["5c:535d"] = "¡Hola! Tú eres\n{PLAYER}, ¿no?\f¿Quieres recoger\nlo que tengo\vpara ti?",
  ["5c:5391"] = "¡Aquí tienes!",
  ["5c:539f"] = "Esperamos poder\nayudarte de nuevo.",
  ["5c:53bc"] = "¡Oh! No tienes\nespacio para esto.\fPara en cualquier\nCENTRO POKéMON\fdel país y podrás\nrecogerlo.",
  ["5c:541a"] = "¿No? Es muy\nextraño…",
  ["5c:553d"] = "Tu amigo está\npreparado.",
  ["5c:55be"] = "Tu amigo está\npreparado.",
  ["5d:401f"] = "Al norte de\nPUEBLO LAVANDA\festá el TÚNEL\nROCA. Crúzalo\fpara llegar a\nla CENTRAL\vde ENERGÍA.",
  ["5d:4072"] = "Hay un programa\nde radio que\fpone música de\nPOKé FLAUTA.\fNecesitas una\nTARJETA EXPN para\vsintonizarlo.",
  ["5d:40db"] = "La EMISORA no\npuede transmitir\fporque la CENTRAL\nde ENERGÍA no\vfunciona.",
  ["5d:411e"] = "El DIRECTOR de\nla EMISORA estaba\vmuy contento.\fDijo que han\nvuelto a emitir\fporque la CENTRAL\nde ENERGÍA ya\vfunciona.",
  ["5d:4222"] = "El SR. FUJI vive\naquí, pero ahora\vno está en casa.\fDebe de estar en\nel CEMENTERIO.",
  ["5d:4271"] = "Algunas personas\nson tan crueles\fque abandonan a\nsus POKéMON.\fEl abuelo recoge a\nlos POKéMON que\fno tienen hogar\ny los cuida.",
  ["5d:42e7"] = "PSYDUCK: ¿Psyay?",
  ["5d:42fa"] = "NIDORINO: ¡Nido!",
  ["5d:430b"] = "PIDGEY: ¡Pijji!",
  ["5d:437e"] = "El PUEBLO LAVANDA\nes un pequeño y\fapacible lugar,\nal pie de las\vmontañas.\fDesde que se\nconstruyó la TORRE\fde RADIO, acude\nalgo más de gente.",
  ["5d:445a"] = "Si vas a explorar\nuna cueva, debes\fllevar siempre\nREPELENTE.\fAunque me gusta la\nexploración, aún\fno he explorado\ntodas las cuevas.",
  ["5d:44dd"] = "He oído hablar de\nun artesano que\ffabrica POKé BALL\na medida en PUEBLO\fAZALEA, en JOHTO.\n¡Yo quiero una!",
  ["5d:4586"] = "SR. FUJI: ¡Hola!\f¡Mmm…! Parece que\nestás educando a\ftus POKéMON con\nmucho cariño.\fLos amantes de los\nPOKéMON vienen a\frendir homenaje a\nPOKéMON muertos.\fPor favor, muestra\ntu condolencia por\flas almas POKéMON\nque han partido.\fSeguro que eso\nles hará felices.",
  ["5d:4680"] = "Creo que aquí hay\notras tumbas de\vPOKéMON.\fHay muchas cámaras\nen las que sólo\fpuede entrar\nel SR. FUJI.",
  ["5d:46e4"] = "He venido con mi\nmadre a visitar\flas tumbas de los\nPOKéMON…",
  ["5d:470e"] = "A los POKéMON que\nvivían conmigo…\flos quería como a\nmis nietos…",
  ["5d:47f2"] = "¡Bienvenido!\nMira por donde\fquieras en este\npiso.",
  ["5d:482d"] = "Lo siento, pero\nsólo puedes dar\funa vuelta por la\nplanta baja.\fDesde que una\nbanda criminal\fasaltó la TORRE de\nRADIO, tuvimos\fque incrementar\nnuestra seguridad.",
  ["5d:48c3"] = "En la TORRE de\nRADIO hay mucha\fgente que trabaja\nduramente.\fSeguro que están\nhaciendo todo lo\fposible por emitir\nbuenos programas.",
  ["5d:492e"] = "¡Oh, no, no, no!\fNo hemos emitido\ndesde que cerró la\fCENTRAL de\nENERGÍA.\fSi no emitimos, de\nnada servirá el\fesfuerzo realizado\npor la emisora.\f¡Me arruinaré!",
  ["5d:49d4"] = "¿Eres tú\n{PLAYER}? ¿El que\farregló la CENTRAL\nde ENERGÍA?\fGracias a ti, no\nperdí mi empleo.\f¡Sin duda, tú eres\nmi salvador!\fToma esto como\nagradecimiento.",
  ["5d:4a74"] = "Con eso podrás\nsintonizar los\fprogramas de\nradio de KANTO.\f¡Jajajaja!",
  ["5d:4ac6"] = "¡Oye, tío!\f¡Soy el DIRECTOR\nde MÚSICA!\f¡Vaya! Tu POKéGEAR\nno sintoniza mis\fprogramas de\nmúsica. ¡Qué pena!\fSi consigues una\nTARJETA EXPN, los\fpodrás oír. ¡Hazte\ncon una!",
  ["5d:4b83"] = "¡Oye, tío!\f¡Soy el DIRECTOR\nde MÚSICA!\fSoy el encargado\nde las fantásticas\fmelodías que se\nemiten aquí.\fNo seas anticuado.\n¡Atrapa la música\vde las ondas!",
  ["5d:4c26"] = "PB RECEPCIÓN\nP1 VENTAS\vP2 PERSONAL\vP3 PRODUCCIÓN\vP4 DESPACHO DEL\v   DIRECTOR",
  ["5d:4c70"] = "Anima a los POKé-\nMON con la melodía\fde la POKé FLAUTA\ndel CANAL 20",
  ["5d:4d5c"] = "¿Has estado en\nPUEBLO LAVANDA?\fHay una TORRE\nde RADIO muy alta.",
  ["5d:4df2"] = "Soy el hermano\npequeño del GURÚ\vPESCADOR.\fVeo que te gusta\npescar. ¡No\ftengo ninguna\nduda!\fSé que tengo\nrazón.",
  ["5d:4e72"] = "Sí, sí. ¡Justo lo\nque pensaba!\f¡Aquí tienes!\nToma esto. Es\vuna SÚPER CAÑA.",
  ["5d:4ebf"] = "Intenta pescar\nallí donde veas\vagua.\fRecuerda: puedes\ncapturar POKéMON\fdiferentes usando\ndistintas CAÑAS.",
  ["5d:4f2f"] = "¿Eh? ¿Me engañan\nmis ojos?",
  ["5d:4ff8"] = "¡Estoy alucinado!\fVino un chico\nde tu edad, de\fpelo largo y\nmirada penetrante.\f¡Y me obligó a\ndarle mis\vqueridos POKéMON!\fTodavía me queda\nuno, ¿pero qué\vhago si vuelve?\fPareces fuerte.\n¿Podrías cuidar\fde mi POKéMON\nun rato?",
  ["5d:50e2"] = "¡Oh, gracias!\f¡Cuídale bien,\npor favor!",
  ["5d:5110"] = "{PLAYER} recibió\nun POKéMON.",
  ["5d:5124"] = "No puedes llevar\nmás POKéMON.",
  ["5d:513e"] = "¡Oh, no…!\n¿Y qué hago\vsi vuelve?",
  ["5d:5165"] = "¡Hola! ¿Cómo está\nmi POKéMON?\fCreo que ya\npasó el peligro.\v¿Me lo devuelves?",
  ["5d:51a6"] = "¡Gracias!",
  ["5d:51b2"] = "¡Oye! ¡No llevas\na mi POKéMON\vcontigo!",
  ["5d:51d8"] = "Mi POKéMON te\nha tomado cariño.\f¡Vale! ¡Quédatelo,\npero prométeme\fque serás bueno\ncon él!",
  ["5d:5234"] = "¡Oh, no, no…!\nEs como si me\vhubieran robado.",
  ["5d:5261"] = "Para los POKéMON,\nla felicidad es\festar con quien\nlos quiere.",
  ["5d:53ee"] = "¡UAUUUU!\f¡Has llegado\nhasta aquí!\f¡Que sepas que\nsoy muy fuerte!\f¡Mis POKéMON\naplastarán piedras\vy romperán huesos!\f¡Atento!",
  ["5d:5464"] = "ANÍBAL: ¡Urgg!\n¡Urgg…!\f¡Oooarrg!",
  ["5d:547f"] = "¿Qué? Ahora tienes\nmiedo, ¿no?\f¿Qué? ¿No tiene\nnada que ver con\flos POKéMON?\n¡Es cierto!\fVenga.\n¡Luchemos!",
  ["5d:54eb"] = "¿Qué? ¿Cómo?\n¿He perdido?\f¡Muy bien!\n¡Te mereces la\vMEDALLA TORMENTA!",
  ["5d:552a"] = "{PLAYER}\nrecibió la\vMEDALLA TORMENTA.",
  ["5d:5542"] = "Con MED. TORMENTA,\nte obedecerán los\fPOKéMON hasta\nel nivel 70.\fY permitirá a\ntus POKéMON usar\fVUELO cuando no\nestén luchando.\f¡Toma esto\ntambién!",
  ["5d:55cf"] = "Se trata de\nPUÑODINÁMICO.\f¡No siempre golpea\npero cuando lo\fhace produce\nconfusión!",
  ["5d:5625"] = "¡UAJAJAA! ¡Ha sido\nmuy divertido!\f¡Pero una derrota\nes una derrota!\f¡Desde ahora, voy\na entrenar 24\vhoras al día!",
  ["5d:568c"] = "A mis POKéMON y\na mí nos une una\vgran amistad.\f¡Nuestro vínculo\nnunca se romperá!",
  ["5d:56de"] = "¡No puede ser!",
  ["5d:56ef"] = "¡Parece que tú y\ntus POKéMON estáis\vmuy unidos!",
  ["5d:5723"] = "¡Los expertos en\nartes marciales no\vtememos a nada!",
  ["5d:5745"] = "¡Es increíble!",
  ["5d:5756"] = "Los POKéMON de\nlucha temen a los\vpsíquicos…",
  ["5d:577f"] = "Las palabras no\nsirven. ¡Deja que\vhablen tus puños!",
  ["5d:57b2"] = "…",
  ["5d:57b5"] = "¡He perdido!\n¡No sé qué decir!",
  ["5d:57ce"] = "¡Mis furiosos\npuños destrozarán\va tus POKéMON!",
  ["5d:57f7"] = "¡Me has aplastado!",
  ["5d:5809"] = "¡Mis POKéMON han\nperdido! Has\vherido mi orgullo.",
  ["5d:58dd"] = "¿Conoces al\nPOKéMANÍACO?\fSiempre está\npresumiendo de sus\vraros POKéMON.",
  ["5d:5923"] = "Los entrenadores\nde este GIMNASIO\vson muy peleones.\fSi me quedo, puede\nque vengan\va por mí.\fÉste es mi\nconsejo: el LÍDER\fdel GIMNASIO usa\nPOKéMON de lucha.\fPara confundirle\nutiliza POKéMON\vpsíquicos.\fDebilita a sus\nPOKéMON antes de\fque puedan usar\nla fuerza física.",
  ["5d:5a2a"] = "¡{PLAYER}! ¡Has\nganado! ¡Con sólo\vmirarte, lo sé!",
  ["5d:5ac9"] = "Parece que tus\nPOKéMON están\fbien. ¿Hay algo\nque te preocupa?\f…\f¿El POKéMON del\nFARO tiene\vproblemas?\f¡Entendido!\fEsto debería\nayudarte.",
  ["5d:5b52"] = "{PLAYER}\nrecibió la\vPOCIÓN SECRETA.",
  ["5d:5b6c"] = "Mi POCIÓN SECRETA\nes muy potente.\fSólo la doy en\ncasos de urgencia.",
  ["5d:5bf5"] = "Tienes unos\nPOKéMON\vmagníficos.\f¿Quieres una foto\nde recuerdo?",
  ["5d:5c3e"] = "¡Vale! ¡Sonríe!",
  ["5d:5c52"] = "¡Oh! ¡Qué mal!\nPensaba que sería\fun maravilloso\nrecuerdo…",
  ["5d:5cb8"] = "¿Vienes de\nCIUDAD OLIVO?\f¿Te acuerdas de\nlas cuatro islas\vdel camino?\fDicen que en\nellas se esconde\funa criatura\nmítica marina.",
  ["5d:5d3b"] = "Dicen que sólo\npuedes verla si\ftienes un ALA\nPLATEADA.\fDebe de tener la\nmisma esencia que\vla criatura.",
  ["5d:5da5"] = "Los torbellinos\nque rodean las\fislas deben de\nser obra de esa\vcriatura.",
  ["5e:4011"] = "¡Hola! ¡Bienvenido\nal CENTRO\fCOMERCIAL de\nCIUDAD AZULONA!\fEl directorio\nestá en la pared.",
  ["5e:4057"] = "Este C. COMERCIAL\npertenece a la\fmisma cadena que\nel de TRIGAL.\fLos dos fueron\nrenovados al\vmismo tiempo.",
  ["5e:40cb"] = "Es la primera vez\nque vengo.\fEs muy grande…\fMe da miedo\nperderme.",
  ["5e:410c"] = "PB: INFORMACIÓN\fP1: TIENDA DE\n    ENTRENADORES\fP2: TIENDA DE MT\fP3: REGALOS\fP4: FARMACIA\fP5: MÁQUINAS\n    EXPENDEDORAS",
  ["5e:41ed"] = "Hace poco que soy\nentrenador. Mi\fhijo me animó a\nserlo.\fEstoy impresionado\npor la cantidad de\fobjetos útiles\nque hay.",
  ["5e:4262"] = "A mi padre le está\ncostando aprender\flos nombres de los\nobjetos y cómo se\fsupone que debe\nutilizarlos…",
  ["5e:42c0"] = "¡Objetos de máxima\ncalidad para\ventrenadores!\fP1: TIENDA DE\n    ENTRENADORES",
  ["5e:4377"] = "No sé en qué\nPOKéMON debería\futilizar esta\nMT…",
  ["5e:43aa"] = "¡Oh, oh! Cambié\nmis POKéMON sin\fquitarles la\nMEJORA.",
  ["5e:43eb"] = "¡Sí! ¡Ya tengo\nun PORYGON!\fSe me dan muy mal\nlas tragaperras.\f¡Jamás ganaría\nbastantes fichas!\f¿Ehh…?\f¡El PORYGON que he\ncambiado se ha\fconvertido en otro\nPOKéMON!",
  ["5e:4485"] = "En la TIENDA DE MT\nhay ataques raros.",
  ["5e:44a9"] = "P2: TIENDA DE MT\f¡Fortalece a tus\nPOKéMON!",
  ["5e:4545"] = "He venido a por\nuna CARTA SURF\vpara mi novia.",
  ["5e:4579"] = "Éste es el único\nlugar en el que\fencontrarás\nCARTAS AMOR.",
  ["5e:45b0"] = "¡Dilo con un\nregalo!\fP3: REGALOS",
  ["5e:4647"] = "Quiero comprar\nobjetos que\faumenten las\nhabilidades de\fmis POKéMON. ¡Pero\nno tengo dinero!",
  ["5e:4696"] = "Quiero MÁS PP,\npara aumentar los\fPP de los ataques.\n¡Pero no se vende!",
  ["5e:46da"] = "Si usas objetos en\ntus POKéMON, se\vpondrán contentos.\fSin embargo, odian\nalgunos objetos.",
  ["5e:4724"] = "P4: FARMACIA",
  ["5e:486c"] = "¡Una máquina\nexpendedora!",
  ["5e:4890"] = "¡Clang!\fSalió\n{STRBUF}.",
  ["5e:48aa"] = "¡Uups, no tienes\nbastante dinero!",
  ["5e:48c3"] = "No hay sitio\npara nada más…",
  ["5e:48e3"] = "Una máquina\nexpendedora con\funa ruleta de\npremios…\fNunca verás\nnada igual.",
  ["5e:492c"] = "¡Auu! ¡Aquí no\nhay juegos!\f¡Quería jugar…!",
  ["5e:495a"] = "ÚLTIMO PISO\nEXPENDEDORAS",
  ["5e:4a32"] = "Mis queridos\nPOKéMON me hacen\fcompañía, así que\nnunca estoy sola.\fMEOWTH hasta trae\ndinero a casa.",
  ["5e:4a8c"] = "MEOWTH: ¡Meow!",
  ["5e:4a9b"] = "CLEFAIRY: ¡Clef\ncleff!",
  ["5e:4ab2"] = "NIDORAN: ¡Nido\nnido!",
  ["5e:4ac7"] = "DESPACHO DEL JEFE\nDE MANSIÓN AZULONA",
  ["5e:4b55"] = "{PLAYER} encendió\nel PC.\f…\fAlguien estaba\nescribiendo\vun e-mail.\fEspero que\nvengas a KANTO.\fTe sorprenderás de\ncuánto han\fcambiado las\ncosas por aquí.\fTambién verás\nmuchos POKéMON\fque no son nativos\nde JOHTO.\fAl PRODUCTOR\f…",
  ["5e:4c48"] = "SALA DE REUNIONES\nDE GAME FREAK",
  ["5e:4cea"] = "¡Hola!\f¡Soy el DISEÑADOR\nDEL JUEGO!\fTe costará\ncompletar tu\fPOKéDEX, pero\n¡no te rindas!",
  ["5e:4d41"] = "¡Uau! ¡Excelente!\n¡Has completado tu\vPOKéDEX!\f¡Enhorabuena!",
  ["5e:4d7c"] = "…",
  ["5e:4d7f"] = "El ARTISTA GRÁFICO\nte imprimirá un\vDIPLOMA.\fDeberías presumir\nde ello.",
  ["5e:4dd0"] = "Soy el ARTISTA\nGRÁFICO.\f¡Te he dibujado!",
  ["5e:4df4"] = "Soy el ARTISTA\nGRÁFICO.\f¿Has completado\ntu POKéDEX?\f¿Quieres imprimir\ntu DIPLOMA?",
  ["5e:4e4c"] = "Avísame si quieres\nque te imprima tu\vDIPLOMA.",
  ["5e:4eb1"] = "¿Quién? ¿Yo? Soy\nel PROGRAMADOR.\f¡Juega a las\ntragaperras!",
  ["5e:4ee6"] = "¿A que las GEMELAS\nson adorables?\fY YASMINA también\nes muy guapa.\f¡Me encantan!",
  ["5e:4f27"] = "SALA DE DESARROLLO\nDE GAME FREAK",
  ["5e:4f44"] = "Es un dibujo\ndetallado de\vuna chica guapa.",
  ["5e:4f6e"] = "Es el programa\ndel juego. ¡No lo\ftoques! ¡Podrías\nestropearlo!",
  ["5e:4fb2"] = "Está lleno de\nmaterial de\freferencia: hasta\nun POKé MUÑECO.",
  ["5e:50ad"] = "Te contaré una\nhistoria de miedo.",
  ["5e:50d0"] = "Pero no te dará\ntanto miedo si\vaún es de día.\fVuelve cuando\nanochezca, ¿vale?",
  ["5e:5129"] = "Érase una vez un\nniño pequeño al\fque le regalaron\nuna BICICLETA…\fQuería probarla\nenseguida…\fSe lo estaba\npasando tan bien\fque olvidó que\nanochecía…\fDe vuelta a casa,\nen plena noche,\f¡la bici empezó\na frenarse!\f¡Cada vez era más\ndifícil pedalear!\fY cuando dejó de\npedalear, ¡la bici\fempezó a moverse\nhacia atrás!\fEra como si la\nbici estuviera\fmaldita y él fuera\na desaparecer.\f…\f…\f(¡CHILLIDO!)\f¡Y el niño siguió\nsubiendo por el\vCAMINO de BICIS!\f¡Ba-dum!\n¡Ba-dum ba-dum!\fPor haberme\nescuchado, ¡aquí\vtienes esta MT03!",
  ["5e:5339"] = "MT03 es MALDICIÓN.\fEs un terrible\nataque que reduce\fpoco a poco los\nPS de la víctima.",
  ["5e:53b4"] = "ERIKA es experta\nen POKéMON planta.\fSi no tienes\ncuidado, acabará\vcontigo.",
  ["5e:5405"] = "El TEAM ROCKET\nestá escondido\fen el sótano del\nCASINO.\fEspera. Eso fue\nhace tres años.",
  ["5e:5571"] = "¡Bienvenido!\fAl lado puedes\ncambiar tus\ffichas por\npremios fabulosos.",
  ["5e:55b6"] = "Todas las\ntragaperras son de\vúltima generación.",
  ["5e:55e3"] = "Quiero jugar en\nesta máquina.\fAyer me desplumó,\nasí que hoy\fsoltará el\ndinero.",
  ["5e:5636"] = "Creo que esta\nmáquina soltará\vel dinero…\fLas posibilidades\nvarían según\vla máquina.",
  ["5e:567d"] = "¡Bien!\f¡Las fichas no\ndejan de salir!\f¿Qué, chico?\n¿Quieres jugar?\f¡Compartiré la\nsuerte contigo!",
  ["5e:56e6"] = "¡Bien!\f¡Me gusta hacer\nfavores a la\vgente!",
  ["5e:572b"] = "¡Eh! No tienes\nningún MONEDERO.\f¿Y cómo te voy a\ndar las fichas,\vchico?",
  ["5e:577a"] = "¡Eh! Tu MONEDERO\nestá lleno, chico.\fTú también debes\nde estar de\vsuerte.",
  ["5e:57c6"] = "¡Eh! ¡Futuro\nCAMPEÓN!\f¿Tú también juegas\na las tragaperras?\fQuiero conseguir\nbastantes fichas\vpara un POKéMON.\fPero aún no tengo\nbastantes…",
  ["5e:584e"] = "¡Mmm…! Los impares\nson mejores para\fla línea PIKACHU.\n¿Qué hago?",
  ["5e:5894"] = "¡Eh!\fDebajo de este\npóster…\f¡No hay nada!",
  ["5e:58c2"] = "¡Eh!\fDebajo de este\npóster…\f¡No hay nada!",
  ["5e:58f0"] = "Aquí hay un\nencendedor.",
  ["5e:5908"] = "¡Un refresco!\fAlguien se lo\nhabrá dejado…\f¿Uh? ¡Está vacío!",
  ["5e:5c59"] = "Yo quería a\nMR.MIME, pero me\ffaltaban 100\nfichas…",
  ["5e:5c8a"] = "¡Uauu…!\fDebo permanecer\ntranquilo…\fNo puedo perder\nla cabeza o\vperderé todo…",
  ["5e:5cdf"] = "¡Bienvenido!\f¡Aquí te cambiamos\ntus fichas por\vpremios fabulosos!",
  ["5e:5d15"] = "¿Qué premio\nquieres?",
  ["5e:5d32"] = "De acuerdo,\n¿{STRBUF}?",
  ["5e:5d4e"] = "¡Aquí tienes!",
  ["5e:5d5c"] = "No tienes\nbastantes fichas.",
  ["5e:5d79"] = "No tienes espacio\nsuficiente.",
  ["5e:5d93"] = "¡Vuelve cuando\ntengas fichas!",
  ["5e:5db5"] = "¡Vaya! No tienes\nun MONEDERO.",
  ["5e:5ec9"] = "ERIKA: Hola…\nBonito día,\f¿verdad? Se está\ntan bien…\fPodría hasta\ndormirme…\fMe llamo ERIKA.\nSoy la LÍDER\fdel GIMNASIO de\nCIUDAD AZULONA.\f¿Cómo? ¿Vienes\nde JOHTO?\v¡Qué bien…!\f¡Oh! Lo siento,\nno me di cuenta\fde que querías\ndesafiarme.\fMuy bien, pero\nno perderé.",
  ["5e:5fdf"] = "ERIKA: ¡Oh! Admito\nque he perdido…\fEres realmente\nbueno…\fTe daré la MEDALLA\nARCOIRIS…",
  ["5e:6037"] = "{PLAYER} recibió\nMEDALLA ARCOIRIS.",
  ["5e:6051"] = "ERIKA: Ha sido un\ncombate genial.\fMe has inspirado.\nAcepta esta MT\vcomo regalo.\fEs GIGA-DRENADO.\fEs un fantástico\nataque que drena\fla mitad del daño\nproducido para\vcurar al POKéMON.\fÚsalo si\nquieres…",
  ["5e:6130"] = "ERIKA: La derrota\ndeja mal sabor\vde boca…\fPero saber que\nhay entrenadores\fmás fuertes me\nanima a mejorar…",
  ["5e:619d"] = "¡Alto! ¡Aquí sólo\npueden entrar\vlas chicas!",
  ["5e:61c1"] = "¡Oh, maldición!",
  ["5e:61cd"] = "No es que no nos\ngusten los chicos.\fPero hay ciertos\ntemas de los que\fsólo pueden hablar\nlas chicas.",
  ["5e:622f"] = "¡Oh! ¿Un combate?\nMe da un poco de\vmiedo, pero bueno.",
  ["5e:625b"] = "¡Oh! ¿Se acabó?",
  ["5e:626a"] = "¡Uauu! ¡Tienes\nmuchas MEDALLAS!\f¡No me extraña\nhaber perdido!",
  ["5e:62a1"] = "¿Estabas mirando\nestas flores o\va mí?",
  ["5e:62ce"] = "¡Qué rabia!",
  ["5e:62dd"] = "¿Cómo voy a hacer\npara llegar a ser\ftan elegante\ncomo ERIKA?",
  ["5e:630e"] = "¡Te enseñaremos\nlos movimientos\fPOKéMON que nos\nenseñó ERIKA!",
  ["5e:633e"] = "Hemos perdido…",
  ["5e:634c"] = "¡ERIKA te lo\nhará pagar!",
  ["5e:636d"] = "¡Vamos a proteger\na ERIKA!",
  ["5e:638b"] = "No ganamos…",
  ["5e:639c"] = "¡ERIKA es mucho,\nmucho más fuerte!",
  ["5e:64ba"] = "¡Hola!\fEstamos celebrando\nun concurso\vde tragones.\fPerdona. Ahora no\npodemos atenderte.",
  ["5e:6505"] = "¡Ñam, ñam…!",
  ["5e:6516"] = "¡No me hables!\f¡Me vas a\ndesconcentrar!",
  ["5e:6546"] = "¡Glup…! ¡Ñam…!",
  ["5e:6554"] = "¡Mejor cantidad\nque calidad!\f¡Si estoy lleno,\nestoy feliz!",
  ["5e:658a"] = "¡Ñam, ñam…!",
  ["5e:6599"] = "La comida de aquí\nes buena, pero\fen CIUDAD TRIGAL\nes aún mejor.",
  ["5e:65dd"] = "¡Ñam… Ñam…!",
  ["5e:65ee"] = "Aquí nadie te va\na dar un MONEDERO.\fMejor que lo\nbusques en JOHTO.",
  ["5e:6630"] = "¡Ñam… ñam…!\f¡Sigo comiendo!",
  ["5e:6654"] = "¡Más, JEFE!",
  ["5e:6661"] = "¡Concurso de\ntragones! ¡Sin\ftiempo! ¡Una lucha\nsin fin! ¡El mayor\ftragón podrá\ncomer gratis!",
  ["5e:66c3"] = "{PLAYER} encontró\n{STRBUF}.",
  ["5e:66d5"] = "Pero {PLAYER} no\ntiene espacio…",
  ["5e:6757"] = "Si bajas por el\nCAMINO BICIS,\fllegarás a\nCIUDAD FUCSIA.",
  ["5e:67e6"] = "Aquí empieza el\nCAMINO BICIS.\fEs todo cuesta\nabajo. Es muy\vemocionante.\fEs una sensación\nque no se\fexperimenta en\nbarco o en tren.",
  ["5e:6874"] = "¡Eh! ¡Alto!\fNo puedes pasar\npor el CAMINO\fBICIS si no vas\nen BICICLETA.",
  ["5e:690a"] = "¿Has oído lo del\naccidente de la\vCENTRAL ENERGÍA?\fSe encuentra al\nEste, cerca de\vPUEBLO LAVANDA.",
  ["5e:6970"] = "Me tomo muy en\nserio mi trabajo\vde GUARDA.\f¡Eh! Tienes una\nPOKéDEX.\fVale. Puedes\npasar.",
  ["5e:6a0a"] = "CAMINO BICIS\nA partir de aquí,\ves cuesta arriba.",
  ["5e:6a2b"] = "¡Alto! ¿No tienes\nuna BICI?\fAquí empieza el\nCAMINO BICIS.\fNecesitas una\nBICI para seguir.",
  ["5f:4057"] = "AZUL: Bien. Por\nfin aquí, ¿no?\fEn ISLA CANELA no\nestaba de humor,\fpero ahora estoy\nlisto para luchar.\f…\f¿Dices que has\nganado en todos\flos GIMNASIOS de\nJOHTO?\f¡Bah! Pues los\nGIMNASIOS de JOHTO\fdeben de ser\npatéticos.\fPero, ¡no más\npalabras!\fSabré si eres\nbueno o no\fluchando contra\nti, ahora mismo.\f¿Preparado, chico?",
  ["5f:4188"] = "AZUL: ¿Qué?\f¿Cómo diablos he\nperdido?\f…\f¡Está bien…!\nToma, aquí tienes\vla MEDALLA TIERRA.",
  ["5f:41e9"] = "{PLAYER} recibió\nla MEDALLA TIERRA.",
  ["5f:4201"] = "AZUL: …\fDe acuerdo, me he\nequivocado. Tenías\frazón. Eres un\nbuen entrenador.\fPero algún día\nte derrotaré.\f¡No lo\nolvides!",
  ["5f:4285"] = "AZUL: Escucha.\fSerá mejor que no\npierdas hasta que\fyo te derrote.\n¿Entendido?",
  ["5f:42c8"] = "¡Hola, futuro\nCAMPEÓN! ¿Qué\ftal te va?\nParece que estás\vde suerte.\fEl LÍDER DEL\nGIMNASIO luchó\fcontra el CAMPEÓN\nhace 3 años.\f¡Es un tipo duro!\f¡Debes esforzarte\nal máximo!",
  ["5f:437a"] = "Tío, eres\nrealmente duro…\f¡Qué batalla más\nemocionante!\fMe ha hecho\nllorar.",
  ["5f:442e"] = "¿Dedicas mucho\ntiempo a pensar\fen nombres para\ntus POKéMON?\fEs más divertido\nintercambiarlos\fsi les pones\nbuenos motes.",
  ["5f:44a5"] = "Son SPEARY, un\nSPEAROW, y RATTEY,\vun RATTATA.",
  ["5f:44d8"] = "SPEARY: ¡Spea!",
  ["5f:44ea"] = "RATTEY: ¡Ratii!",
  ["5f:4559"] = "Bienvenido a la\nCASA DEL\fENTRENADOR, el\nlugar más popular\vde CIUDAD VERDE.\fEs sólo para\nentrenadores.\fPuedes luchar\ncontra los mejores\fentrenadores en el\npiso de abajo.",
  ["5f:45ff"] = "La CIUDAD VERDE\nes la más cercana\va la MESETA AÑIL.\fConstruyeron este\nlugar debido al\fgran número de\nentrenadores que\fpasaban de camino\na la MESETA AÑIL.",
  ["5f:468f"] = "Aquí abajo tienen\nlugar combates\vde entrenamiento.\fMe encantaría ver\nlo bien que lucha\fun entrenador de\nJOHTO.",
  ["5f:46f7"] = "Creo que no puedes\nser el CAMPEÓN\fsi no luchas\ncon toda la gente\fque te encuentres\npor ahí.\fEl CAMPEÓN de\nPALETA viajó por\flas ciudades y\npueblos de KANTO.",
  ["5f:47a3"] = "¡Ah…! Estoy\ndescansando de los\vcombates POKéMON.",
  ["5f:47ce"] = "Los combates de\nentrenamiento se\fcelebran en HALL\nDE ENTRENAMIENTO.\fLos entrenadores\nmás hábiles están\vinvitados.",
  ["5f:4837"] = "No existen reglas\nsobre los combates\fde prueba. Al\nigual que en los\fcombates reales,\naquí vale todo.",
  ["5f:489b"] = "¿Qué es esto?\n¿Una estrategia?\fEsta letra se\nparece a las\fhuellas de ONIX…\n¡Es ilegible…!",
  ["5f:49fa"] = "Bienvenido al HALL\nDE ENTRENAMIENTO.\fPuedes luchar\ncon un entrenador\vcada día.",
  ["5f:4a44"] = "{STRBUF}\nserá hoy tu rival.",
  ["5f:4a61"] = "¿Quieres\nluchar?",
  ["5f:4a7c"] = "Entra, por\nfavor.\fPuedes empezar\nahora mismo.",
  ["5f:4ab0"] = "Lo siento. Sólo\npueden entrar\faquéllos que van\na luchar.",
  ["5f:4af7"] = "Lo siento, señor.\nÉsta es la segunda\fvez que viene hoy.\nSólo se puede\fentrar una vez\nal día.",
  ["5f:4b57"] = "He perdido…\n¡Qué pena…!",
  ["5f:4b66"] = "He viajado hasta\naquí sólo para\vluchar contra ti.",
  ["5f:4bd3"] = "El LÍDER de este\nGIMNASIO es\vgenial.",
  ["5f:4bf9"] = "¿Has estado en\nISLA CANELA?\fEs una isla muy\nal sur de aquí.",
  ["5f:4c8c"] = "¿Dónde estará el\nLÍDER del GIMNASIO\fde CIUDAD VERDE?\nQuería desafiarle.",
  ["5f:4cd4"] = "No hay ningún\nENTRENADOR en\fel GIMNASIO de\nCIUDAD VERDE.\fEl LÍDER dice que\nsu política es\fganar sin tener\nsubordinados.",
  ["5f:4d4a"] = "Dicen que el\nGIMNASIO de ISLA\fCANELA está\ndestruido.\fMe pregunto que\nhabrá sido de\vBLAINE, su LÍDER.",
  ["5f:4da7"] = "Mi sueño es ser\nLÍDER de GIMNASIO.",
  ["5f:4e44"] = "¡Hola! Me alegro\nde verte.\fEres la primera\nvisita que recibo\fdesde hace\nmucho tiempo.\f¡Estoy muy\ncontento! Te voy\fa hacer un\npequeño regalo.",
  ["5f:4ec4"] = "Es una PEPITA.\fNo puedo darte\npepitas de la\fsabiduría,\n¡sólo esto!",
  ["5f:4f34"] = "¿Eres {PLAYER}?\fSoy el AYUDANTE\ndel PROF. OAK.\fNo sabía que\nestabas aquí.\fEl LAB. del PROF.\nOAK está cerca de\vPUEBLO PALETA.",
  ["5f:5008"] = "Sólo pueden pasar\nlos entrenadores\fque demuestren\nsu valía.",
  ["5f:503e"] = "No tienes todas\nlas MEDALLAS\vde JOHTO.\fLo siento, pero no\npuedo dejarte\vpasar.",
  ["5f:5093"] = "¡Oh! ¡Las ocho\nMEDALLAS de JOHTO!\f¡Le ruego que\npase, señor!",
  ["5f:50d0"] = "Este camino lleva\na MT.PLATEADO.\fDonde verás a unos\nPOKéMON fuertes\vy terribles.",
  ["5f:5116"] = "Vas a la LIGA\nPOKéMON, ¿verdad?\fEl ALTO MANDO es\ntan fuerte que da\fmiedo. ¡Están\nesperándote!",
  ["60:43f7"] = "ELM: ¡{PLAYER}!\n¡Eres tú!\fQuería pedirte\nun favor.\fConozco a un tal\nSR. POKéMON,\vque siempre está\fdescubriendo\ncosas nuevas\fy presumiendo\nde ellas.\fAcabo de recibir\nun e-mail suyo\fdiciendo que esta\nvez va en serio.\fMe intriga, pero\nestamos ocupados\festudiando a los\nPOKéMON.\f¿Podrías indagar\npor nosotros?\fTe daré un POKéMON\npara que te\vacompañe.\fTodos son POKéMON\nraros que acabamos\vde encontrar.\fVenga. ¡Elige uno!",
  ["60:4590"] = "Si aparece un\nPOKéMON salvaje,\fhaz que tu POKéMON\nluche contra él.",
  ["60:45c2"] = "ELM: ¡Espera!\n¿Adónde vas?",
  ["60:45e3"] = "ELM: ¿Quieres a\nCYNDAQUIL, el\vPOKéMON de fuego?",
  ["60:460e"] = "ELM: ¿Quieres a\nTOTODILE, el\vPOKéMON de agua?",
  ["60:463a"] = "ELM: ¿Quieres a\nCHIKORITA, el\vPOKéMON planta?",
  ["60:4668"] = "ELM: Piénsalo\ncon cuidado.\fTu compañero es\nimportante.",
  ["60:46a2"] = "ELM: ¡Yo también\ncreo que es un\vPOKéMON genial!",
  ["60:46c8"] = "¡{PLAYER}\nrecibió a\v{STRBUF}!",
  ["60:46db"] = "El SR. POKéMON\nvive cerca de\vCIUDAD CEREZO.\fEstá casi en\nlínea recta.",
  ["60:472f"] = "Si hieren a tu\nPOKéMON, cúralo\vcon esta máquina.",
  ["60:476c"] = "Éste es mi número\nde teléfono.\fLlámame si surge\nalgo.",
  ["60:47a9"] = "{PLAYER} anotó\nel número de ELM.",
  ["60:47c3"] = "El SR. POKéMON va\na todas partes y\vencuentra rarezas.\f¡Qué pena que\nsean tan raros\vy tan inútiles!\f¡{PLAYER},\nconfío en ti!",
  ["60:4835"] = "Contiene un\nPOKéMON atrapado\vpor el PROF. ELM.",
  ["60:485d"] = "Me pregunto qué\nserá esto.",
  ["60:4877"] = "¿Curar a\ntus POKéMON?",
  ["60:4883"] = "ELM: {PLAYER},\n¡qué horror…!\f¡Ah, sí! ¿Cuál\nera el gran\fdescubrimiento del\nSR. POKéMON?",
  ["60:48c8"] = "{PLAYER} le dio el\nHUEVO MISTERIOSO\val PROF. ELM.",
  ["60:48ef"] = "ELM: ¿Esto?",
  ["60:48fb"] = "Pero… ¿Es un\nHUEVO de POKéMON?\fSi lo es, ¡vaya\ndescubrimiento!",
  ["60:4936"] = "ELM: ¿¡Qué!?\f¿El PROF. OAK te\ndio una POKéDEX?\f{PLAYER}, ¿es eso\ncierto? ¡Mm…,\vincreíble!\fOAK no suele\nequivocarse al\fjuzgar a un\nentrenador.\f¡Oh, {PLAYER}!\nPuede que tengas\flo necesario para\nser un CAMPEÓN.\fAdemás, pareces\nllevarte bien con\vlos POKéMON.\fDeberías aceptar\nel desafío de un\vGIMNASIO POKéMON.\fEl GIMNASIO más\ncercano es el de\vCIUDAD MALVA.",
  ["60:4a85"] = "{PLAYER}. El\ncamino hacia la\fgloria será\nlargo.\fAntes de irte, no\nolvides hablar\vcon tu madre.",
  ["60:4af2"] = "ELM: ¡No te\nrindas! Si sé algo\fsobre ese HUEVO,\nte llamaré.",
  ["60:4b33"] = "ELM: ¿{PLAYER}?\n¿No has visto a\vmi ayudante?\fTe esperaba con\nel HUEVO en el\fCENTRO POKéMON\nde CIUDAD MALVA.\fSi no lo has\nvisto, búscalo\vahí.",
  ["60:4bd1"] = "ELM: ¿Alguna\nnovedad?",
  ["60:4bf6"] = "¿{PLAYER}? Creía\nque el huevo se\vhabía abierto.\f¿Dónde está el\nPOKéMON?",
  ["60:4c28"] = "ELM: ¡Qué buen\naspecto, {PLAYER}!",
  ["60:4c41"] = "¿Qué?\n¿¡Ese POKéMON!?",
  ["60:4c55"] = "¡El HUEVO se\nabrió! Los POKéMON\vdeben nacer así.\fQuizá no todos\nlos POKéMON.\f¡Uauu! Aún nos\nqueda mucho por\vaprender.",
  ["60:4cd2"] = "¡Gracias, {PLAYER}!\nNos estás ayudando\fa descubrir los\nmisterios POKéMON.\f¡Recibe esto\ncomo prueba\vde nuestra estima!",
  ["60:4d43"] = "Eso es una\nPIEDRAETERNA.\fAlgunos POKéMON\nevolucionan al\falcanzar ciertos\nniveles.\fSi un POKéMON\nva equipado con la\fPIEDRAETERNA,\nno evolucionará.\fDásela al POKéMON\n\nque no quieras que\vevolucione.",
  ["60:4ded"] = "ELM: {PLAYER},\nsi surge algo,\vte llamaré.",
  ["60:4e1b"] = "(Suspiro…). El\nPOKéMON robado.\fMe pregunto\ncómo estará.\fDicen que los\nPOKéMON educados\fpor malas personas\nse vuelven malos.",
  ["60:4e86"] = "ELM: ¡{PLAYER}!\nGracias a ti,\fmis estudios\nvan fenomenal.\fToma esto como\nprueba de mi\vestima.",
  ["60:4ee7"] = "¡La MASTER BALL\nes la mejor!\f¡Es la BALL\ndefinitiva! Atrapa\fcualquier tipo\nde POKéMON.\fSólo la tienen\nlos auténticos\finvestigadores\nde POKéMON.\f¡Toma, {PLAYER}!\n¡Creo que a ti\fte ayudará más\nque a mí!",
  ["60:4fa4"] = "ELM: ¡{PLAYER}!\n¿Qué tal?\fTe he llamado\nporque tengo\valgo para ti.\fEs un TICKET\nde BARCO.\fAhora podrás\natrapar POKéMON\ven KANTO.",
  ["60:5020"] = "El barco zarpa de\nCIUDAD OLIVO.\fPero eso ya lo\nsabías, {PLAYER}.\fHas viajado por\ntodas partes con\vtus POKéMON.\f¡Dale recuerdos\nal PROF. OAK\ven KANTO!",
  ["60:50e9"] = "{PLAYER}, toma\nesto por las\vmolestias.",
  ["60:5116"] = "Sólo somos dos,\nasí que siempre\vestamos ocupados.",
  ["60:5146"] = "Oimos un ruido\nmuy fuerte…\fY cuando salimos\na mirar, alguien\fnos robó un\nPOKéMON.\f¡Es horrible\nque alguien\vhiciera eso!\f(Suspiro…) El\nPOKéMON robado.\fMe pregunto cómo\nestará.\fDicen que los\nPOKéMON educados\fpor malas personas\nse vuelven malos.",
  ["60:5229"] = "¡{PLAYER}!\f¡Usa esto para\nllenar tu POKéDEX!",
  ["60:524b"] = "Atrapa POKéMON\npara completar\vtu POKéDEX.\fAtrapa POKéMON\nsalvajes usando\vlas POKé BALL.",
  ["60:52a1"] = "Dicen que han\nrobado un POKéMON.\fY acabo de recibir\ncierta información\vdel PROF. ELM.\fParece que fue un\njoven pelirrojo,\vde pelo largo.\f¿Qué?\f¿Que tú te has\nenfrentado a un\ventrenador así?\f¿Y sabes cómo\nse llama?",
  ["60:5371"] = "¡Bien! Así que su\nnombre es {RIVAL}.\f¡Gracias por tu\ncolaboración!",
  ["60:53ae"] = "La ventana está\nabierta.\fEntra una\nsuave brisa.",
  ["60:53e2"] = "¡Entró por\naquí!",
  ["60:53fd"] = "{PLAYER} abrió\nun libro.\fPista de viaje 1:\fPulsa START para\nabrir el MENÚ.",
  ["60:543b"] = "{PLAYER} abrió\nun libro.\fPista de viaje 2:\f¡Graba tu viaje\ncon GUARDAR!",
  ["60:5477"] = "{PLAYER} abrió\nun libro.\fPista de viaje 3:\fAbre tu MOCHILA y\npulsa SELECT para\vmover objetos.",
  ["60:54c6"] = "{PLAYER} abrió\nun libro.\fPista de viaje 4:\fMira los ataques\nde tus POKéMON.\fPulsa A para\ncambiar de ataque.",
  ["60:5521"] = "Dentro está el\nenvoltorio del\ftentempié que se\ntomó el PROF. ELM.",
  ["60:5719"] = "¡Ah, {PLAYER}…!\nNuestro vecino,\fel PROF. ELM, te\nestaba buscando.\fDijo que quería\nque le hicieras\vun favor.\f¡Ah! ¡Casi se me\nolvida! Ya han\ftraído tu POKéGEAR\ndel taller.\f¡Aquí tienes!",
  ["60:57d2"] = "El POKéMON GEAR o\nsólo POKéGEAR.\fEs básico si\nquieres ser un\vbuen entrenador.\f¡Ah! Falta el día\nde la semana.\f¡No olvides\nponerlo!",
  ["60:5857"] = "¿Es horario\nde verano?",
  ["60:5878"] = "Vuelve a casa\npara cambiar de\vhora el reloj.\fPor cierto,\n¿sabes cómo usar\vel TELÉFONO?",
  ["60:58e0"] = "¿Recuerdas que\nhay que encender\fel POKéGEAR\ny elegir el\vTELÉFONO?",
  ["60:591c"] = "Te leeré las\ninstrucciones.\fEnciende el\nPOKéGEAR y elige\vel TELÉFONO.",
  ["60:5965"] = "Los números están\nen la memoria.\fElige el nombre\nque quieras.\f¿No te parece\nestupendo?",
  ["60:59ca"] = "El PROF. ELM te\nestá esperando.\f¡Date prisa!",
  ["60:59fa"] = "¿Qué quería\nel PROF. ELM?\f…\fParece muy\ndíficil.\fDeberías estar\norgulloso de\fque la gente\nconfíe en ti.",
  ["60:5a6c"] = "¡Vamos, {PLAYER}!\f¡Cuentas con\ntoda mi ayuda!",
  ["60:5a92"] = "¡La especialidad\nde mi madre!\f¡HAMBURGUESA\nVOLCÁN CANELA!",
  ["60:5abc"] = "El fregadero está\nimpecable. A mamá\vle gusta limpio.",
  ["60:5ae9"] = "Veamos qué hay\nen la nevera…\f¡AGUA FRESCA y una\nsabrosa LIMONADA!",
  ["60:5b28"] = "Una peli en TV:\ndos niños suben\fa un tren bajo un\ncielo estrellado.\f¡Mejor que yo\ntambién me vaya!",
  ["60:5c5c"] = "¡La HORA POKéMON\ndel PROF. OAK!\f¡Sintonízanos la\npróxima vez!",
  ["60:5c8d"] = "¡EL CANAL POKéMON!",
  ["60:5c9c"] = "¡Soy la DJ ROSA,\nla presentadora!",
  ["60:5cbc"] = "¡POKéMON!\nCANAL POKéMON…",
  ["60:5d64"] = "PIKACHU es un\nPOKéMON\vevolucionado.\fLos hallazgos del\nPROF. ELM me\vsorprendieron.\fEs famoso por\nsus estudios\fsobre la evolución\nde los POKéMON.\f(Suspiro…).\fMe gustaría ser\nuna investigadora\vcomo él…",
  ["60:5e09"] = "¡La HORA POKéMON\ndel PROF. OAK!\f¡Sintonízanos la\npróxima vez!",
  ["60:5e3a"] = "¡EL CANAL POKéMON!",
  ["60:5e49"] = "¡Soy la DJ ROSA,\nla presentadora!",
  ["60:5e69"] = "¡POKéMON!\nCANAL POKéMON…",
  ["60:5eb8"] = "¡Hola, {PLAYER}!\nMi marido siempre\festá muy ocupado.\n¡Ojalá esté bien!\fCuando estudia\na los POKéMON,\fse olvida hasta\nde comer.",
  ["60:5f2c"] = "¡Cuando sea mayor,\nayudaré a mi\vpadre!\f¡Voy a ser un\ngran profesor\vPOKéMON!",
  ["60:5fdc"] = "Los POKéMON.\n¿De dónde vienen?\f¿Adónde van?\f¿Por qué no ha\npresenciado nadie\fel nacimiento de\nun POKéMON?\f¡Quiero saber!\n¡Quiero dedicar mi\fvida al estudio de\nlos POKéMON!\f…\fSon algunos\npapeles del\vPROF. ELM.",
  ["60:610b"] = "Tus POKéMON\nparecen cansados.\fDeberías dejarlos\ndescansar un poco.",
  ["60:6149"] = "¡Vaya! ¡Tus\nPOKéMON tienen\vbuen aspecto!\f¡Sigue así!",
  ["60:61b7"] = "Aquí hay algo\nescrito.\f¿Quieres leerlo?",
  ["60:61e0"] = "A mis hermanos y\nhermanas:\fNos orgullece\nayudar a los\fentrenadores\nPOKéMON.\fCuando habléis con\nlos entrenadores,\vdadles algo útil.\fBesos,\nLUNA\f¿Seguir leyendo?",
  ["60:6277"] = "Lunes, LUNA\nRUTA 40\fMartes, MARTA\nRUTA 29\fMiércoles, MIGUEL\nLAGO DE LA FURIA\fJueves, JOSUÉ\nRUTA 36\fViernes, VICKI\nRUTA 32\fSábado, SABINO\nCIUDAD ENDRINO\fDomingo, DOMINGO\nRUTA 37",
  ["60:6384"] = "¿A dónde vas con\nlos POKéMON?\f¿A la LIGA\nPOKéMON?\f¿Son tus POKéMON\nlo bastante\ffieles como para\npemitirte ganar?\fDéjame ver…",
  ["60:63e9"] = "¡Ah! Tus POKéMON\nconfían mucho\ven ti.\fDa gusto ver a un\nbuen entrenador.\fToma. Un regalo\npara el viaje.",
  ["60:644d"] = "MT37 contiene\nTORMENTA ARENA.\fEste movimiento\ndaña a ambos\vcombatientes.\fEs para entrenado-\nres avanzados.\fÚsala si te\natreves. ¡Suerte!",
  ["60:64dd"] = "Si no confían\nmás en ti,\ftendrás problemas\npara ganar.\fLa confianza es el\nvínculo entre los\fPOKéMON y sus\nentrenadores.",
  ["60:657f"] = "No puedes cruzar\nsetos.\fPero puedes saltar\npor encima de\vellos para atajar.",
  ["60:65cb"] = "Más adelante\naparecen muchos\ftipos de\nPOKéMON.\fSi quieres hacerte\ncon todos, tendrás\fque buscar por\ntodas partes.",
  ["61:400d"] = "¡Hola!\fEl REY del KARATE,\nel maestro del\fDOJO-KARATE, está\nentrenando en una\vcueva de JOHTO.",
  ["61:4061"] = "¡Lo que tenga que\nser será!",
  ["61:4081"] = "¡Enemigos por\ntodas partes!",
  ["61:4180"] = "SABRINA: Sabía\nque vendrías…\fHace tres años\ntuve una visión\vde tu llegada.\fTú lo que quieres\nes mi MEDALLA.\fNo me gusta\nluchar, pero mi\fdeber como LÍDER\nes conceder\fMEDALLAS a todo\naquel que se las\vmerezca.\fComo eso es lo que\nquieres, mira mis\vpoderes psíquicos.",
  ["61:4295"] = "SABRINA: Tu\npoder…\fsupera con creces\nlo que esperaba…\fQuizá no se pueda\npredecir del todo\flo que nos espera\nen el futuro…\fVale, tú ganas.\nTe has ganado la\vMEDALLA PANTANO.",
  ["61:4336"] = "{PLAYER} recibió\nMEDALLA PANTANO.",
  ["61:434e"] = "SABRINA: La\nMEDALLA PANTANO\fmuestra tus\npoderes ocultos.\fAunque no supe\npredecir tu poder\fcon exactitud,\nsabía que valías\vmucho.\f¡Te convertirás en\nun amado y alabado\vCAMPEÓN!",
  ["61:440d"] = "SABRINA: Tu amor\npor tus POKéMON\fsupera mi poder\npsíquico…\fCreo que el poder\ndel amor es un\ftipo de poder\npsíquico…",
  ["61:448a"] = "¡El poder de todos\nlos que venciste\vestá en mí!",
  ["61:44bc"] = "Fuerte…\nMuy fuerte…",
  ["61:44d5"] = "¿De dónde proviene\ntu poder?",
  ["61:44f8"] = "El poder psíquico\nes el poder de tu\valma.",
  ["61:4522"] = "¡Tu alma tiene más\npoder que la mía!",
  ["61:4547"] = "Has fortalecido tu\nalma, no sólo tus\vhabilidades.",
  ["61:457e"] = "¡Fufufufu…!\nLo veo claramente.\f¡Puedo leer\ntu alma!",
  ["61:45b5"] = "A pesar de leerte\nel pensamiento,\vhe perdido…",
  ["61:45d7"] = "¡Maldición! Olvidé\nque predije mi\vderrota contra ti.",
  ["61:460d"] = "El DOJO-KARATE era\nel GIMNASIO\vde esta ciudad.",
  ["61:4643"] = "¡Eres bueno…!",
  ["61:4654"] = "El REY del KARATE,\nel maestro del\fDOJO-KARATE, acaba\nde ser machacado\vpor SABRINA.",
  ["61:46a2"] = "¡Hola, futuro\nCAMPEÓN!\fUn entrenador tan\nhabilidoso como tú\fno necesita que le\ndigan cómo luchar\fcontra POKéMON\npsíquicos, ¿no?\f¡Espero mucho\nde ti!\f¡Buena suerte!",
  ["61:4741"] = "¡Otro combate\nfantástico!",
  ["61:486d"] = "En PUEBLO LAVANDA\nhay una gran TORRE\vde RADIO.",
  ["61:4894"] = "Quiero ser más\nfuerte, pero aún\vsoy muy mala…\f¿Podrías enseñarme\ncómo algún día?",
  ["61:493b"] = "Hay una enorme\nCENTRAL de ENERGÍA\fal norte de PUEBLO\nLAVANDA.",
  ["61:496e"] = "Acabo de cruzar\nel TÚNEL ROCA.\fPasaba algo en\nla CENTRAL de\vENERGÍA.",
  ["61:49c9"] = "Las cuevas suelen\nderrumbarse.\fÚltimamente han\ndesaparecido\fvarias cuevas,\ncomo la de\vCIUDAD CELESTE.\fPara un MONTAÑERO\nprofesional, eso\ves obvio.",
  ["61:4a60"] = "La OFICINA CENTRAL\nde SILPH S.A. y\fla ESTACIÓN del\nMAGNETOTRÉN son\flos lugares más\nvistos de AZAFRÁN.",
  ["61:4b33"] = "…\f…\f…\f¡Lo conseguí!\f¡Tú lo quisiste!",
  ["61:4b56"] = "MT29 es PSÍQUICO.\fPuede reducir\nlas HABILIDADES\fESPECIALES del\nblanco.",
  ["61:4c45"] = "Lo siento, pero el\nMAGNETOTRÉN no\vfunciona ahora.",
  ["61:4c79"] = "Pronto saldremos\nhacia CIUDAD\vTRIGAL.\f¿Quiere\nsubir?",
  ["61:4cb3"] = "Por favor, ¿puedo\nver su PASE?\fVale. Pase por\naquí, señor.",
  ["61:4cef"] = "Lo siento, pero\nno tiene un PASE.",
  ["61:4d11"] = "¡Vuelve siempre\nque quieras!",
  ["61:4d2c"] = "Hemos llegado a\nCIUDAD AZAFRÁN.\fSiempre a\nsu servicio.",
  ["61:4d63"] = "El MAGNETOTRÉN es\nun tren ultra-\fmoderno, accionado\npor electricidad\fe imanes. Su\nvelocidad es\vincreíble.\fSin embargo,\nsi no hay\velectricidad…",
  ["61:4dfa"] = "¡Caramba…!\f¡Cuántas veces he\nido de KANTO a\fJOHTO y de JOHTO\na KANTO!",
  ["61:4e44"] = "Antes de que se\nconstruyera la\fESTACIÓN, ahí\nhabía una casa.\fY en ella vivía\nuna niña\vllamada COPIONA.",
  ["61:4eb9"] = "Hola. ¿Tienes un\nPASE? Yo sí. Toda\fla gente de CIUDAD\nAZAFRÁN que usa el\fMAGNETOTRÉN tiene\nun PASE.",
  ["61:4f9c"] = "Bienvenido a la\nOFICINA CENTRAL\vde SILPH S.A.",
  ["61:4fcf"] = "Al piso de arriba\nsólo pueden subir\vlos empleados.\fPero como has\nvenido desde tan\flejos, toma este\npequeño recuerdo.",
  ["61:5041"] = "Es lo último de\nSILPH S.A. Aún\fno se encuentra\na la venta.",
  ["61:50cd"] = "A mi hija le gusta\nimitar a la gente.\fY por eso la\nllaman la\vCOPIONA.",
  ["61:512e"] = "Mi hija es muy\nintrovertida…\fTiene muy\npocos amigos.",
  ["61:516c"] = "Acaba de perder\nel POKé MUÑECO que\fle regaló un niño\nhace tres años.\fDesde entonces,\nimita a la gente\vmucho mejor…",
  ["61:51e4"] = "BLISSEY: ¡Bliisii!",
  ["61:52f1"] = "{PLAYER}: ¿Te gusta\nPOKéMON?\f{PLAYER}: No, yo\nsólo preguntaba.\f{PLAYER}: ¿Eh?\n¡Eres muy rara!",
  ["61:533f"] = "COPIONA: ¿Cómo?\n¿Que no imite?\f¡Pero si es mi\nhobby favorito!",
  ["61:537b"] = "{PLAYER}: ¡Hola!\nDicen que has\fperdido tu POKé\nMUÑECO favorito.\f{PLAYER}: Si lo\nencuentro, ¿me\vdarás un PASE?\f{PLAYER}: Iré\na buscarlo.\f¿Crees que lo\nperdiste en\vCIUDAD CARMÍN?",
  ["61:542d"] = "COPIONA: ¿Perdona?\f¿No tendría que\ndecirte yo lo\vque debes hacer?\fEstoy preocupada.\n¿Y si alguien\vlo encuentra?",
  ["61:5496"] = "COPIONA: ¡Sí! ¡Ése\nes mi POKé MUÑECO\vCLEFAIRY!\f¿Ves el descosido\nque tiene en la\fpata derecha?\n¡Ésa es la prueba!",
  ["61:54f9"] = "Está bien. ¡Aquí\ntienes el PASE del\fMAGNETOTRÉN que\nte prometí!",
  ["61:552b"] = "COPIONA: Ése es\nel PASE para el\vMAGNETOTRÉN.\fLa empresa de\nferrocarriles me\flo dio cuando\nderribaron nuestra\fcasa para edificar\nla ESTACIÓN.",
  ["61:55af"] = "{PLAYER}: ¡Hola!\nMuchas gracias por\vel PASE de tren.\f{PLAYER}: ¿Perdona?\f{PLAYER}: ¿Tanto\nte divierte imitar\vtodo lo que hago?",
  ["61:560c"] = "COPIONA: ¿Apuestas\nalgo? ¡Es genial!",
  ["61:562d"] = "DODRIO: ¡Dodrii!",
  ["61:5640"] = "ESPEJITO, ESPEJITO\n¿QUIÉN ES EL MÁS\fGUAPO DE\nTODOS?",
  ["61:567b"] = "¡Qué POKéMON\nmás raro!\fEs un muñeco…",
  ["61:5702"] = "Muchas ciudades de\nJOHTO están llenas\fde historia. ¡Cómo\nme gustaría ir!",
  ["61:5766"] = "Eres de JOHTO,\n¿verdad?\f¿Qué opinas de\nKANTO? Es bonito,\v¿no crees?",
  ["61:57ff"] = "¡Aaaayy!\fSiento que una\nsiniestra sombra\fse cierne\nsobre ti.\f¡Toma esto para\nprotegerte!",
  ["61:5851"] = "Corrías un peligro\nmortal, pero ahora\vestás protegido.",
  ["61:5888"] = "A mi abuela le\ngusta protegerse\fcontra supuestos\nmalos espíritus.\fPerdona si te\nha asustado.",
  ["62:402c"] = "¡Se han quedado\nsin POKé BALL!\f¿Cuándo\nconseguirán más?",
  ["62:406b"] = "¡Tengo POKé BALL\nde reserva! ¡Puedo\vatrapar POKéMON!",
  ["62:4098"] = "Cuando iba por la\nhierba, un POKéMON\fbicho envenenó\na mis POKéMON.\fYo seguí andando,\npero mi POKéMON\vse debilitó.\fDeberías llevar un\nANTÍDOTO contigo.",
  ["62:4182"] = "¡Es genial! Puedo\nguardar a todos\flos POKéMON que\nquiera, ¡y gratis!",
  ["62:41c0"] = "Ese PC puede ser\nusado por todo\ventrenador.",
  ["62:41e9"] = "El CENTRO de\nCOMUNICACIONES de\farriba está recién\nconstruido.\fPero aún no está\nterminado.",
  ["62:423e"] = "El CENTRO de\nCOMUNICACIONES de\farriba está recién\nconstruido.\f¡Yo ya he cambiado\nPOKéMON en él!",
  ["62:42e2"] = "¿Quieres saber lo\nbueno que eres\fcomo entrenador\nPOKéMON?\fPues vete a los\nGIMNASIOS POKéMON\fde JOHTO y gana\nmuchas MEDALLAS.",
  ["62:435d"] = "¡Cuando sea mayor,\nvoy a ser un LÍDER\vde GIMNASIO!\f¡Hago luchar a mis\nPOKéMON con los\fde mi amigo para\nfortalecerlos!",
  ["62:4405"] = "¡Cuando era niño,\nera un brillante\ventrenador!\fÉste es mi\nconsejo: ¡Atrapa\vmuchos POKéMON!\f¡Y trátalos con\nmucho cariño!",
  ["62:44bb"] = "Luchando, los\nPOKéMON ganan\fexperiencia y se\ntransforman.",
  ["62:44f4"] = "¿Se transforman?\f¡Alucinaría si\nlo viera!",
  ["62:457a"] = "Los POKéMON\ncomen BAYAS.\fMi POKéMON se\ncuró comiendo\vuna BAYA.\fToma. ¡Te daré\nuna!",
  ["62:45e4"] = "Busca BAYAS\nen los árboles.\fSon muy fáciles\nde encontrar.",
  ["62:4755"] = "¡Hola! Debes de\nser {PLAYER}.\fEl PROF. ELM dijo\nque vendrías.",
  ["62:4797"] = "Esto es lo que\nquiero que\fexamine el\nPROF. ELM.",
  ["62:47c1"] = "{PLAYER} recibió\nun HUEVO MIST.",
  ["62:47da"] = "Conozco a una\npareja que tiene\funa GUARDERÍA\nPOKéMON.\fEllos me dieron\nese HUEVO.\fComo me intrigaba,\nle mandé una carta\val PROF. ELM.\fEl PROF. ELM es la\nmáxima autoridad\fen evolución de\nlos POKéMON.",
  ["62:4881"] = "Hasta el PROF. OAK\nlo reconoce.",
  ["62:48a6"] = "Si tengo razón,\nel PROF. ELM lo\vsabrá.",
  ["62:48dc"] = "¿Vas a ir a ver\nal PROF. ELM?\fToma. Tus POKéMON\ndeberían descansar\vun poco.",
  ["62:4923"] = "¡Confío\nen ti!",
  ["62:4939"] = "¡La vida es\ngenial! ¡Siempre\fquedan cosas por\ndescubrir!",
  ["62:4974"] = "OAK: ¡Así que tú\neres {PLAYER}!\f¡Yo soy OAK!\n¡Un científico\vPOKéMON!\fEstaba visitando a\nmi viejo amigo el\vSR. POKéMON.\fY como me dijo que\ntenías algo para\fel PROF. ELM,\ndecidí esperarte.\f¡Oh! ¿Qué es esto?\n¡Un POKéMON raro!\fVeamos…\f¡Mmm, ya veo!\fAhora entiendo por\nqué el PROF. ELM\fte confió un\nPOKéMON.\fPara científicos\ncomo el PROF. ELM\fy yo, los POKéMON\nson amigos.\fSabía que\ntratarías a tus\fPOKéMON con\nmucho cariño.\f¡Ah!\fPareces ser de\nconfianza.\f¿Te gustaría\nayudarme?\fMira. Ésta es la\núltima versión de\vla POKéDEX.\fRegistra los datos\nde los POKéMON\fque has atrapado\no que has visto.\f¡Es una moderna\nenciclopedia!",
  ["62:4bbb"] = "¡{PLAYER} recibió\nla POKéDEX!",
  ["62:4bcd"] = "Busca muchos\ntipos de POKéMON\fy completa esa\nPOKéDEX.\fAhora tengo\nque irme.\fMe esperan en\nCIUDAD TRIGAL para\fpresentar mi\nprograma de radio.\f¡{PLAYER}, cuento\ncontigo!",
  ["62:4c65"] = "¿Mmm? ¡Esa ESCAMA!\n¿De qué es? ¿De\vun GYARADOS rojo?\f¡Es muy rara!\nQuiero tenerla…\f{PLAYER}, ¿quieres\nintercambiarla?\fYo te ofrezco\nREPARTIR EXP.\fMe lo dio\nel PROF. OAK.",
  ["62:4cfc"] = "Es una pena.\nEs realmente\vraro.",
  ["62:4d32"] = "Lleno de revistas\nextranjeras.\fNi siquiera puedo\nleer los títulos.",
  ["62:4d73"] = "Es un ordenador\nenorme. ¡Mmm!\vEstá estropeado.",
  ["62:4d9b"] = "¡Un montón de\nmonedas extrañas!\fQuizá sean de\notro país…",
  ["62:4e29"] = "¡Hola, chico!\n¿Has visitado la\vTORRE BELLSPROUT?",
  ["62:4e4f"] = "Estoy demasiado\nlejos. ¡Mejor que\vllame a casa!",
  ["64:558c"] = "",
  ["64:558e"] = "Soy el ENCARGADO\nde la GUARDERÍA.\f¿Quieres que\ncuide un POKéMON?",
  ["64:55bd"] = "Soy el ENCARGADO\nde la GUARDERÍA.\f¿Sabes algo sobre\nlos HUEVOS?\fMi mujer y yo\nestábamos cuidando\vunos POKéMON.\f¡Y de pronto\nvimos un HUEVO!\f¿No te parece\nincreíble?\f¿Quieres que te\ncuide un POKéMON?",
  ["64:566a"] = "Soy la ENCARGADA\nde la GUARDERÍA.\f¿Quieres que te\ncuide un POKéMON?",
  ["64:56a0"] = "Soy la ENCARGADA\nde la GUARDERÍA.\f¿Sabes algo sobre\nlos HUEVOS?\fMi marido y yo\nestábamos cuidando\vunos POKéMON.\f¡Y de pronto\nvimos un HUEVO!\f¿No te parece\nincreíble?\f¿Quieres que te\ncuide un POKéMON?",
  ["64:575e"] = "¿Cuál quieres\nque cuide?",
  ["64:577c"] = "¿Oh? Pero sólo\ntienes un POKéMON.",
  ["64:579d"] = "Perdona, pero no\nacepto HUEVOS.",
  ["64:57bf"] = "Quita la CARTA y\nvuelve a verme.",
  ["64:57e4"] = "Si me lo das,\n¿con quién vas\va combatir?",
  ["64:5815"] = "Vale. Cuidaré de\ntu {STRBUF}.",
  ["64:5830"] = "Vuelve a por él\nmás tarde.",
  ["64:5849"] = "¿Somos geniales o\nno? ¿Quieres ver a\vtu {STRBUF}?",
  ["64:587b"] = "Tu {STRBUF}\nha crecido mucho.\fEn cuanto a nivel,\nha subido {NUM}.\fRecuperar a tu\nPOKéMON te\vcostará {NUM}¥.",
  ["64:58e9"] = "¡Perfecto! ¡Aquí\nestá tu POKéMON!",
  ["64:5904"] = "{PLAYER} recogió\na {STRBUF}.",
  ["64:5917"] = "¿Ya de vuelta?\nTu {STRBUF}\fdebería pasar más\ntiempo aquí. Pero\frecoger ahora\na tu POKéMON, te\vcostará 100¥.",
  ["64:5987"] = "No tienes espacio\nsuficiente.",
  ["64:59a1"] = "No tienes\nbastante dinero.",
  ["64:59be"] = "No hay problema.",
  ["64:59ce"] = "Vuelve cuando\nquieras.",
  ["64:59db"] = "Aún no…",
  ["64:59e5"] = "¡Ah, eres tú!\fEstábamos cuidando\nde tus POKéMON y\f¡menuda sorpresa\nnos hemos llevado!\f¡Tus POKéMON han\ntenido un HUEVO!\fNo sabemos cómo ha\nllegado ahí, pero\fes de tus POKéMON.\n¿Lo quieres?",
  ["64:5a8a"] = "¡{PLAYER} recibió\nel HUEVO!",
  ["64:5a9f"] = "Cuídalo\nbien.",
  ["64:5ab6"] = "Cuidaré de él.\n¡Gracias!",
  ["64:5ad7"] = "No tienes sitio en\ntu equipo. Vuelve\ven otro momento.",
  ["65:4751"] = "¿Qué?\f",
  ["65:4759"] = "",
  ["65:475b"] = "¡{STRBUF}\nsalió del\vHUEVO!",
  ["65:4778"] = "¿Quieres darle\nun mote a\v{STRBUF}?",
  ["65:4793"] = "Es el {STRBUF}\nque dejé con\fla ENCARGADA de\nla GUARDERÍA.",
  ["65:47c4"] = "Es el {STRBUF}\nque dejé con el\fENCARGADO de\nla GUARDERÍA.",
  ["65:47f4"] = "Está rebosante\nde energía.",
  ["65:480f"] = "No está interesado\nen {STRBUF}.",
  ["65:482d"] = "Está interesado\nen {STRBUF}.",
  ["65:484c"] = "Es agradable con\n{STRBUF}.",
  ["65:4866"] = "Muestra interés\npor {STRBUF}.",
  ["65:4883"] = "Aquí no hay\nninguna CARTA.",
  ["65:4899"] = "La CARTA fue\nenviada.",
  ["65:48b9"] = "¡MOCHILA llena!",
  ["65:48cc"] = "Perderás el\nmensaje de\vla CARTA. ¿Vale?",
  ["65:48f1"] = "Ya lleva\nun objeto.",
  ["65:4911"] = "Un HUEVO no puede\nllevar CARTAS.",
  ["65:492d"] = "La CARTA fue\nsacada del BUZÓN.",
  ["65:4993"] = "Hay un POKéMON que\nlleva una CARTA.\fPor favor, quita\nla CARTA.",
  ["65:544a"] = "Primero quita\nla CARTA.",
  ["65:54fd"] = "¿O prefieres\nborrar el mensaje?",
  ["65:5522"] = "Quitada CARTA de\n{STRBUF}.",
  ["65:553d"] = "No hay bastante\nespacio para\vquitar la CARTA.",
  ["65:5561"] = "¿Enviar la\nCARTA a tu PC?",
  ["65:5584"] = "El BUZÓN de tu\nPC está lleno.",
  ["65:559f"] = "La CARTA fue\nenviada a tu PC.",
  ["65:5c61"] = "¿Cuántos?",
  ["65:5c6c"] = "{NUM} unidad/es\nde {STRBUF}\vserán {NUM}¥.",
  ["65:5c8c"] = "Hola, hijo.\fVendo hierbas\nmedicinales.\fSon buenas, pero\nun poco amargas.\fQuizá tus POKéMON\nno las quieran.\f¡Je, je, je…!",
  ["65:5d07"] = "¿Cuántos?",
  ["65:5d12"] = "{NUM} unidad/es\nde {STRBUF}\vserán {NUM}¥.",
  ["65:5d32"] = "Gracias, hijo.\n¡Je, je, je…!",
  ["65:5d4e"] = "¡Oh! Tu MOCHILA\nestá llena, hijo.",
  ["65:5d6c"] = "¡Je, je…! No\ntienes ese dinero.",
  ["65:5d8e"] = "Vuelve otra vez.\n¡Je, je, je…!",
  ["65:5dab"] = "¡Oye! ¿Quieres ver\nunas gangas?\fVendo objetos que\nnadie posee, pero\fsólo un objeto de\ncada tipo.",
  ["65:5e14"] = "{STRBUF}\ncuesta {NUM}¥.\v¿Lo quieres?",
  ["65:5e31"] = "Gracias.",
  ["65:5e3a"] = "¡Oh! Tu MOCHILA\nestá a tope.",
  ["65:5e5b"] = "Eso ya lo has\ncomprado. No me\vquedan más.",
  ["65:5e8c"] = "¡Oh! No tienes\nsuficiente dinero.",
  ["65:5eaa"] = "Vuelve en otra\nocasión.",
  ["65:5ec3"] = "¿Qué quieres?\n¿Alguna medicina?",
  ["65:5ee2"] = "¿Cuántos?",
  ["65:5eed"] = "{NUM} unidad/es\nde {STRBUF}\vserán {NUM}¥.",
  ["65:5f0f"] = "¡Muchas gracias!",
  ["65:5f1d"] = "No te queda\nsitio.",
  ["65:5f3c"] = "¿Eh? No tienes\nbastante dinero.",
  ["65:5f5a"] = "De acuerdo.\nHasta luego.",
  ["65:5f76"] = "No tienes nada\npara vender.",
  ["65:5f97"] = "¿Cuántos?",
  ["65:5fa2"] = "Puedo pagarte\n{NUM}¥.\f¿Te parece bien?",
  ["65:5fc6"] = "¡Bienvenido!\n¿Qué deseas?",
  ["65:5fe4"] = "Aquí tienes.\n¡Gracias!",
  ["65:5ffe"] = "No tienes\nbastante dinero.",
  ["65:601b"] = "No puedes llevar\nmás objetos.",
  ["65:603b"] = "Lo siento. No te\npuedo comprar eso.",
  ["65:605d"] = "¡Vuelve cuando\nquieras!",
  ["65:6071"] = "¿Puedo ayudarte\nen algo más?",
  ["65:6092"] = "Recibiste {NUM} ¥\npor {STRBUF}.",
}